INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38250, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "たくさんの中から、とくにこれを、と、いうときに使うことば。", "primary_collocate": null, "pronunciation": "とりわけ", "ipa": "toɾiwake", "syllable_count": 4, "sentences": [{"text": "私は野菜が好きですが、とりわけトマトが大好きです。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "わたしはやさいがすきですが、とりわけトマトがだいすきです。", "sentence_source": "generated"}, {"text": "日本の料理はどれもおいしいが、とりわけ寿司が好きだ。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "にほんのりょうりはどれもおいしいが、とりわけすしがすきだ。", "sentence_source": "generated"}, {"text": "今日は寒いですが、とりわけ風が冷たいです。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "きょうはさむいですが、とりわけかぜがつめたいです。", "sentence_source": "generated"}, {"text": "動物が好きで、とりわけ犬をよく見に行く。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "どうぶつがすきで、とりわけいぬをよくみにいく。", "sentence_source": "generated"}, {"text": "授業の中で、とりわけ音楽の時間が楽しみだ。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "じゅぎょうのなかで、とりわけおんがくのじかんがたのしみだ。", "sentence_source": "generated"}, {"text": "兄はスポーツが得意で、とりわけサッカーが上手だ。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "あにはスポーツがとくいで、とりわけサッカーがじょうずだ。", "sentence_source": "generated"}, {"text": "この町は桜が有名だが、とりわけ川沿いの道がきれいだ。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "このまちはさくらがゆうめいだが、とりわけかわぞいのみちがきれいだ。", "sentence_source": "generated"}, {"text": "今月は忙しかったが、とりわけ最後の一週間が大変だった。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "こんげつはいそがしかったが、とりわけさいごのいっしゅうかんがたいへんだった。", "sentence_source": "generated"}, {"text": "彼女の絵はどれも素敵だが、とりわけ海の絵が気に入っている。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "かのじょのえはどれもすてきだが、とりわけうみのえがきにいっている。", "sentence_source": "generated"}, {"text": "夏休みの思い出の中で、とりわけ祖母の家で過ごした日が忘れられない。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "なつやすみのおもいでのなかで、とりわけそぼのいえですごしたひがわすれられない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "とりわけ", "label": "副詞形"}, {"form": "取り分け", "label": "漢字表記"}], "register": "neutral", "sense_fingerprint": "たくさんの中から特にこれと選び出して言う語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cadf245-b057-4a4f-80e4-458d2df7fe35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38250, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "とりわけ", "is_correct": true, "explanation": "「野菜が好きですが、〜トマトが大好き」で、野菜の中から特にトマトを取り立てる意味に合う。"}, {"text": "ふと", "is_correct": false, "explanation": "思いつきで急にという意味で、好みを取り立てる文には合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "たまたまの意味で、好みの強調とは合わない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "深く眠るさまを表し、好みを取り立てる文には意味が合わない。"}], "explanations": {"とりわけ": "「野菜が好きですが、〜トマトが大好き」で、野菜の中から特にトマトを取り立てる意味に合う。", "ふと": "思いつきで急にという意味で、好みを取り立てる文には合わない。", "偶然": "たまたまの意味で、好みの強調とは合わない。", "ぐっすり": "深く眠るさまを表し、好みを取り立てる文には意味が合わない。"}, "sentence_index": 0, "correct_answer": "とりわけ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方になり、とりわけ店の明かりがついた。", "explanation": "ここは〈突然〉の意味。「とりわけ」は取り立てる語で、急な変化は表さないので合わない。"}, {"text": "お客さんが来て、とりわけ、お茶を出した。", "explanation": "ここは〈ついでに〉の意味。「とりわけ」は付け足しの語ではないので合わない。"}, {"text": "寝る前に、とりわけ、電気を消した。", "explanation": "ここは〈最後に〉の意味（順序）。「とりわけ」は順序を示さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38250, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "とりわけ", "is_correct": true, "explanation": "「桜が有名だが、〜川沿いの道がきれいだ」で、桜の名所の中から特に川沿いの道を取り立てる意味。"}, {"text": "ぜひ", "is_correct": false, "explanation": "強い願いを表す語で、取り立てる意味には合わない。"}, {"text": "じっくり", "is_correct": false, "explanation": "時間をかけて丁寧にという意味で、ここでは意味が通らない。"}, {"text": "ほぼ", "is_correct": false, "explanation": "おおよそ・だいたいという意味で、取り立てる意味とは異なる。"}], "explanations": {"とりわけ": "「桜が有名だが、〜川沿いの道がきれいだ」で、桜の名所の中から特に川沿いの道を取り立てる意味。", "ぜひ": "強い願いを表す語で、取り立てる意味には合わない。", "じっくり": "時間をかけて丁寧にという意味で、ここでは意味が通らない。", "ほぼ": "おおよそ・だいたいという意味で、取り立てる意味とは異なる。"}, "sentence_index": 6, "correct_answer": "とりわけ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "いろいろ調べたが、とりわけ、この店は閉まっていた。", "explanation": "ここは〈結局〉の意味（結論）。「とりわけ」は結論を示す用法では使わないので合わない。"}, {"text": "とりわけ、材料を用意します。", "explanation": "ここは〈まず〉の意味（順序）。「とりわけ」は順序を示さないので合わない。"}, {"text": "実は、とりわけ、私も同じ経験がある。", "explanation": "ここは〈実は〉の意味（打ち明け）。「とりわけ」は打ち明ける用法では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38250, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は雨が多いですが、とりわけな日曜日は晴れやすいです。", "corrected_sentence": "週末は雨が多いですが、とりわけ日曜日は晴れやすいです。", "error_description": "「とりわけ」は副詞なので、形容動詞の語尾「な」は付けられない。「とりわけ日曜日は」が正しい形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38250, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この動物園は見どころが多いが、とりわけで夜の散歩ツアーは人気が高い。", "corrected_sentence": "この動物園は見どころが多いが、とりわけ夜の散歩ツアーは人気が高い。", "error_description": "「とりわけ」は副詞なので、助動詞「で」を付けて断定の形にはできない。「とりわけ夜の」が正しい形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
