INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38251, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "数ある中でも、特に。とりわけ。", "primary_collocate": null, "pronunciation": "とりわけ", "ipa": "toɾiwake", "syllable_count": 4, "sentences": [{"text": "しかし、産業革命以降の急激な人間活動、とりわけ化石燃料の大量消費と森林破壊は、この循環に深刻な破綻をもたらした。", "target_word": "とりわけ", "complexity_tier": "T4", "furigana": "しかし、さんぎょうかくめいいこうのきゅうげきなにんげんかつどう、とりわけかせきねんりょうのたいりょうしょうひとしんりんはかいは、このじゅんかんにしんこくなはたんをもたらした。", "sentence_source": "mined"}, {"text": "私は果物が好きだが、とりわけ桃には目がない。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "わたしはくだものがすきだが、とりわけももにはめがない。", "sentence_source": "generated"}, {"text": "今年の夏は暑く、とりわけ八月は記録的な猛暑だった。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "ことしのなつはあつく、とりわけはちがつはきろくてきなもうしょだった。", "sentence_source": "generated"}, {"text": "京都には名所が多いが、とりわけ秋の紅葉は見事だ。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "きょうとにはめいしょがおおいが、とりわけあきのこうようはみごとだ。", "sentence_source": "generated"}, {"text": "彼は運動全般が得意で、とりわけ水泳では県大会で優勝した。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "かれはうんどうぜんぱんがとくいで、とりわけすいえいではけんたいかいでゆうしょうした。", "sentence_source": "generated"}, {"text": "この地域では、とりわけ高齢者の医療が大きな課題になっている。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "このちいきでは、とりわけこうれいしゃのいりょうがおおきなかだいになっている。", "sentence_source": "generated"}, {"text": "新入社員は皆まじめだが、とりわけ佐藤さんの熱意は目立っていた。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "しんにゅうしゃいんはみなまじめだが、とりわけさとうさんのねついはめだっていた。", "sentence_source": "generated"}, {"text": "昨日の会議では、とりわけ費用の問題が長く議論された。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "きのうのかいぎでは、とりわけひようのもんだいがながくぎろんされた。", "sentence_source": "generated"}, {"text": "寒い日が続いており、とりわけ朝晩の冷え込みが厳しい。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "さむいひがつづいており、とりわけあさばんのひえこみがきびしい。", "sentence_source": "generated"}, {"text": "この小説は文章が美しく、とりわけ最後の場面が心に残る。", "target_word": "とりわけ", "complexity_tier": "T3", "furigana": "このしょうせつはぶんしょうがうつくしく、とりわけさいごのばめんがこころにのこる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "とりわけ", "label": "副詞形"}, {"form": "取り分け", "label": "漢字表記"}], "register": "formal", "sense_fingerprint": "多くの中から特に取り立てて示す副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cadf245-b057-4a4f-80e4-458d2df7fe35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38251, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "とりわけ", "is_correct": true, "explanation": "「人間活動、〜、化石燃料の大量消費と森林破壊」の中から特に取り立てる意味に合う。"}, {"text": "ようやく", "is_correct": false, "explanation": "長い時間を経て実現するさまを表し、列挙の中の強調としては合わない。"}, {"text": "ふと", "is_correct": false, "explanation": "思いつきで急にという意味で、ここでは文の意味が通らない。"}, {"text": "きっと", "is_correct": false, "explanation": "確実にそうなるという推量で、列挙の強調には合わない。"}], "explanations": {"とりわけ": "「人間活動、〜、化石燃料の大量消費と森林破壊」の中から特に取り立てる意味に合う。", "ようやく": "長い時間を経て実現するさまを表し、列挙の中の強調としては合わない。", "ふと": "思いつきで急にという意味で、ここでは文の意味が通らない。", "きっと": "確実にそうなるという推量で、列挙の強調には合わない。"}, "sentence_index": 0, "correct_answer": "とりわけ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓の外が急に暗くなり、とりわけ雨が降り出した。", "explanation": "ここは〈突然〉の意味。「とりわけ」は取り立てる語で、急な出来事を表さないので合わない。"}, {"text": "テストは難しかったが、とりわけ、先生は笑って許してくれた。", "explanation": "ここは〈結果的に〉の意味。「とりわけ」は結果を示す語ではないので合わない。"}, {"text": "今日は休みだが、とりわけ仕事に行かなければならない。", "explanation": "ここは〈それでも〉の意味（逆接）。「とりわけ」は逆接の接続には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38251, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "とりわけ", "is_correct": true, "explanation": "「皆まじめだが、〜佐藤さんの熱意は目立っていた」で、特に一人を取り立てる意味に合う。"}, {"text": "さっそく", "is_correct": false, "explanation": "すぐに行うさまを表し、取り立てる意味にはならず不自然。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "深く眠るさまを表し、ここでは意味が通らない。"}, {"text": "少しも", "is_correct": false, "explanation": "否定と結びつく副詞で、「目立っていた」とは合わない。"}], "explanations": {"とりわけ": "「皆まじめだが、〜佐藤さんの熱意は目立っていた」で、特に一人を取り立てる意味に合う。", "さっそく": "すぐに行うさまを表し、取り立てる意味にはならず不自然。", "ぐっすり": "深く眠るさまを表し、ここでは意味が通らない。", "少しも": "否定と結びつく副詞で、「目立っていた」とは合わない。"}, "sentence_index": 6, "correct_answer": "とりわけ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長い冬が過ぎ、とりわけ春が来た。", "explanation": "ここは〈ついに〉の意味。「とりわけ」は取り立てる語で、待ち望んだ変化の到来は表さないので合わない。"}, {"text": "いろいろ試したが、とりわけ、誰も返事をくれなかった。", "explanation": "ここは〈結局〉の意味（結論）。「とりわけ」は結論を示す用法では使わないので合わない。"}, {"text": "会議は長引いたが、とりわけ、まだ終わっていない。", "explanation": "ここは〈まだ〉の意味。「とりわけ」は継続や状態を示す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38251, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏は暑いが、とりわけに七月は湿気が多い。", "corrected_sentence": "夏は暑いが、とりわけ七月は湿気が多い。", "error_description": "「とりわけ」は副詞なので助詞「に」は付けられない。「とりわけ七月は」が正しい形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38251, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父の話はどれも面白いが、とりわけの戦争の体験談は心に残る。", "corrected_sentence": "祖父の話はどれも面白いが、とりわけ戦争の体験談は心に残る。", "error_description": "「とりわけ」は副詞なので、名詞の前に「の」を付けて連体修飾にはできない。「とりわけ戦争の体験談」が正しい形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38252, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「都会へ送る」の目的語として農産を示す正しい格助詞。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す「に」で、「農産に都会へ送って」は送る対象を表せず不自然。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段の「で」で、送る対象を表す形にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は後ろに名詞が続く必要があり、「農産の都会へ」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「都会へ送る」の目的語として農産を示す正しい格助詞。", "に": "位置や相手を示す「に」で、「農産に都会へ送って」は送る対象を表せず不自然。", "で": "場所や手段の「で」で、送る対象を表す形にならない。", "の": "連体修飾の「の」は後ろに名詞が続く必要があり、「農産の都会へ」は成り立たない。"}, "error_tags": {"に": "位置・相手を示す助詞", "で": "場所・手段を示す助詞", "の": "連体修飾の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38252, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「農産の展示会」の「の」。農産を展示会を修飾する名詞として結ぶ連体修飾の助詞。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」にすると「農産を展示会では」となり、農産が働きかけを受ける対象にならず不自然。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す「に」にすると「農産に展示会では」となり、展示会を修飾できず成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段の「で」にすると「農産で展示会では」となり、農産と展示会をつなげられず不自然。"}], "correct_answer": "の", "explanations": {"の": "「農産の展示会」の「の」。農産を展示会を修飾する名詞として結ぶ連体修飾の助詞。", "を": "目的語の「を」にすると「農産を展示会では」となり、農産が働きかけを受ける対象にならず不自然。", "に": "位置や相手を示す「に」にすると「農産に展示会では」となり、展示会を修飾できず成り立たない。", "で": "場所や手段の「で」にすると「農産で展示会では」となり、農産と展示会をつなげられず不自然。"}, "error_tags": {"を": "目的語を示す助詞", "に": "位置・相手を示す助詞", "で": "場所・手段を示す助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38252, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "畑でとれた食べ物のことです。", "primary_collocate": null, "pronunciation": "のうさん", "ipa": "noːsaɴ", "syllable_count": 4, "sentences": [{"text": "この地域は農産が豊かで、秋になると市場に新鮮な野菜がたくさん並ぶ。", "target_word": "農産", "complexity_tier": "T3", "furigana": "この地域[ちいき]は農産[のうさん]が豊[ゆた]かで、秋[あき]になると市場[しじょう]に新鮮[しんせん]な野菜[やさい]がたくさん並[なら]ぶ。", "sentence_source": "generated"}, {"text": "北の村では農産を都会へ送って、家族の生活を支えている。", "target_word": "農産", "complexity_tier": "T3", "furigana": "北[きた]の村[むら]では農産[のうさん]を都会[とかい]へ送[おく]って、家族[かぞく]の生活[せいかつ]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "台風で畑がだめになり、今年は農産が例年よりずっと少なかった。", "target_word": "農産", "complexity_tier": "T3", "furigana": "台風[たいふう]で畑[はたけ]がだめになり、今年[ことし]は農産[のうさん]が例年[れいねん]よりずっと少[すく]なかった。", "sentence_source": "generated"}, {"text": "農産の種類が多いので、この道の駅は一日中にぎわっている。", "target_word": "農産", "complexity_tier": "T3", "furigana": "農産[のうさん]の種類[しゅるい]が多[おお]いので、この道[みち]の駅[えき]は一日中[いちにちじゅう]にぎわっている。", "sentence_source": "generated"}, {"text": "雨が少ない年は、農産の値段が上がりやすい。", "target_word": "農産", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]ない年[とし]は、農産[のうさん]の値段[ねだん]が上[あ]がりやすい。", "sentence_source": "generated"}, {"text": "祖父は自分の畑でとれた農産を近所の人に配っている。", "target_word": "農産", "complexity_tier": "T3", "furigana": "祖父[そふ]は自分[じぶん]の畑[はたけ]でとれた農産[のうさん]を近所[きんじょ]の人[ひと]に配[くば]っている。", "sentence_source": "generated"}, {"text": "この島は土地がやせているため、農産は期待したほど多く採れない。", "target_word": "農産", "complexity_tier": "T3", "furigana": "この島[しま]は土地[とち]がやせているため、農産[のうさん]は期待[きたい]したほど多[おお]く採[と]れない。", "sentence_source": "generated"}, {"text": "農産の展示会では、大きなかぼちゃやさつまいもが注目を集めた。", "target_word": "農産", "complexity_tier": "T3", "furigana": "農産[のうさん]の展示会[てんじかい]では、大[おお]きなかぼちゃやさつまいもが注目[ちゅうもく]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "町の農産を使った料理が、観光客に人気だ。", "target_word": "農産", "complexity_tier": "T3", "furigana": "町[まち]の農産[のうさん]を使[つか]った料理[りょうり]が、観光客[かんこうきゃく]に人気[にんき]だ。", "sentence_source": "generated"}, {"text": "海の近くの町なので、魚はとれるが農産は少ない。", "target_word": "農産", "complexity_tier": "T3", "furigana": "海[うみ]の近[ちか]くの町[まち]なので、魚[さかな]はとれるが農産[のうさん]は少[すく]ない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農産", "label": "基本形"}], "register": "標準（常体）", "sense_fingerprint": "畑で作られる野菜や穀物などの食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e1bbe0-3c9d-4fe0-b0b7-7f30482dfc7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38252, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "農産", "is_correct": true, "explanation": "畑でとれた食べ物を指し、「豊か」で市場に野菜が並ぶ文脈に合う。"}, {"text": "農薬", "is_correct": false, "explanation": "作物を害虫から守る薬剤のことで、「豊か」や市場に並ぶ話とは結びつかない。"}, {"text": "農具", "is_correct": false, "explanation": "畑仕事に使う道具のことで、「豊か」で市場に野菜が並ぶ内容とは合わない。"}, {"text": "種苗", "is_correct": false, "explanation": "植えつけ用の種や苗のことで、秋に市場に並ぶ収穫物の話とずれる。"}], "explanations": {"農産": "畑でとれた食べ物を指し、「豊か」で市場に野菜が並ぶ文脈に合う。", "農薬": "作物を害虫から守る薬剤のことで、「豊か」や市場に並ぶ話とは結びつかない。", "農具": "畑仕事に使う道具のことで、「豊か」で市場に野菜が並ぶ内容とは合わない。", "種苗": "植えつけ用の種や苗のことで、秋に市場に並ぶ収穫物の話とずれる。"}, "sentence_index": 0, "correct_answer": "農産"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は毎朝、農産を手伝って畑に出ている。", "explanation": "ここは〈農業〉の意味。農産は収穫される食べ物で、手伝う対象の仕事にはならない。"}, {"text": "畑に農産をまいて、害虫を追い払った。", "explanation": "ここは〈農薬〉の意味。農産はまく薬剤ではなく食べ物なので、この言い方はしない。"}, {"text": "港では農産を獲って、大きな船で運んでいる。", "explanation": "ここは〈水産〉の意味。農産は畑の作物で、海でとる魚や貝には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38252, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "農産", "is_correct": true, "explanation": "畑でとれた食べ物を指し、土地がやせて多く採れないという文脈に合う。"}, {"text": "肥料", "is_correct": false, "explanation": "土に与える資材で、採れる食べ物ではないので「多く採れない」とは言えない。"}, {"text": "土壌", "is_correct": false, "explanation": "土地そのものを指し、採れるものではないので文が成り立たない。"}, {"text": "農具", "is_correct": false, "explanation": "畑仕事の道具で、採れる食べ物ではないので文に合わない。"}], "explanations": {"農産": "畑でとれた食べ物を指し、土地がやせて多く採れないという文脈に合う。", "肥料": "土に与える資材で、採れる食べ物ではないので「多く採れない」とは言えない。", "土壌": "土地そのものを指し、採れるものではないので文が成り立たない。", "農具": "畑仕事の道具で、採れる食べ物ではないので文に合わない。"}, "sentence_index": 6, "correct_answer": "農産"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は農産を営んで、今も毎朝畑に出ている。", "explanation": "ここは〈農家〉の意味。農産は食べ物で、人の暮らしや仕事を指す「営む」とは合わない。"}, {"text": "父は毎朝、農産を耕して、畑の草を取っている。", "explanation": "ここは〈農地〉の意味。農産は食べ物で、耕す対象の土地ではないので「耕す」とは合わない。"}, {"text": "この町の農産は、毎年村の祭りを開いている。", "explanation": "ここは〈農家〉（人）の意味。農産は物なので、祭りを開く主体にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38252, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この地域では農産を豊富で、秋には市場に新鮮な野菜が並ぶ。", "corrected_sentence": "この地域では農産が豊富で、秋には市場に新鮮な野菜が並ぶ。", "error_description": "助詞の誤り。「豊富だ」の主語は「が」で示すので、「農産を」は「農産が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38252, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の上の村では、農産に多く採れる。", "corrected_sentence": "山の上の村では、農産が多く採れる。", "error_description": "助詞の誤り。「採れる」の主語は「農産」なので「が」が正しい。「に」は場所や相手を示すため合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38253, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」で、農産が後ろの「輸出」を修飾する正しい形。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」にすると、後ろに主語の「輸出が」が続き文が不自然になる。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す「に」で、「農産に輸出」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」で、「農産で輸出」は不自然。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」で、農産が後ろの「輸出」を修飾する正しい形。", "を": "目的語の「を」にすると、後ろに主語の「輸出が」が続き文が不自然になる。", "に": "位置や相手を示す「に」で、「農産に輸出」は意味が通らない。", "で": "手段や場所の「で」で、「農産で輸出」は不自然。"}, "error_tags": {"を": "目的語を示す助詞", "に": "位置・相手を示す助詞", "で": "手段・場所を示す助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38253, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「売る」の目的語として農産を示す正しい格助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」にすると「農産が売る店が」となり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」で、「農産へ売る」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」で、「農産と売る店」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「売る」の目的語として農産を示す正しい格助詞。", "が": "主語の「が」にすると「農産が売る店が」となり、文が成り立たない。", "へ": "方向の「へ」で、「農産へ売る」は意味が通らない。", "と": "並列や相手を示す「と」で、「農産と売る店」は不自然。"}, "error_tags": {"が": "主語を示す助詞", "へ": "方向を示す助詞", "と": "並列・相手を示す助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38253, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "農業で生産される物。野菜や米など。", "primary_collocate": null, "pronunciation": "のうさん", "ipa": "noːsaɴ", "syllable_count": 4, "sentences": [{"text": "この県は米や野菜など、農産の生産量が全国で上位だ。", "target_word": "農産", "complexity_tier": "T3", "furigana": "この県[けん]は米[こめ]や野菜[やさい]など、農産[のうさん]の生産量[せいさんりょう]が全国[ぜんこく]で上位[じょうい]だ。", "sentence_source": "generated"}, {"text": "農産の輸出が増えて、農家の収入も上がってきた。", "target_word": "農産", "complexity_tier": "T3", "furigana": "農産[のうさん]の輸出[ゆしゅつ]が増[ふ]えて、農家[のうか]の収入[しゅうにゅう]も上[あ]がってきた。", "sentence_source": "generated"}, {"text": "農産は天気の影響を受けやすいので、価格が安定しない。", "target_word": "農産", "complexity_tier": "T3", "furigana": "農産[のうさん]は天気[てんき]の影響[えいきょう]を受[う]けやすいので、価格[かかく]が安定[あんてい]しない。", "sentence_source": "generated"}, {"text": "市は地元の農産を学校給食に使う取り組みを始めた。", "target_word": "農産", "complexity_tier": "T3", "furigana": "市[し]は地元[じもと]の農産[のうさん]を学校給食[がっこうきゅうしょく]に使[つか]う取[と]り組[く]みを始[はじ]めた。", "sentence_source": "generated"}, {"text": "農産の加工工場ができて、町に新しい仕事が生まれた。", "target_word": "農産", "complexity_tier": "T3", "furigana": "農産[のうさん]の加工工場[かこうこうじょう]ができて、町[まち]に新[あたら]しい仕事[しごと]が生[う]まれた。", "sentence_source": "generated"}, {"text": "外国との取引では、農産の安全基準が厳しく決められている。", "target_word": "農産", "complexity_tier": "T3", "furigana": "外国[がいこく]との取引[とりひき]では、農産[のうさん]の安全基準[あんぜんきじゅん]が厳[きび]しく決[き]められている。", "sentence_source": "generated"}, {"text": "米は日本を代表する農産の一つだ。", "target_word": "農産", "complexity_tier": "T3", "furigana": "米[こめ]は日本[にほん]を代表[だいひょう]する農産[のうさん]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "農産を売る店が駅前に増えて、買い物客が集まっている。", "target_word": "農産", "complexity_tier": "T3", "furigana": "農産[のうさん]を売[う]る店[みせ]が駅前[えきまえ]に増[ふ]えて、買[か]い物客[ものきゃく]が集[あつ]まっている。", "sentence_source": "generated"}, {"text": "今年は暑さのせいで、農産の出来がよくなかった。", "target_word": "農産", "complexity_tier": "T3", "furigana": "今年[ことし]は暑[あつ]さのせいで、農産[のうさん]の出来[でき]がよくなかった。", "sentence_source": "generated"}, {"text": "この国は工業よりも農産が経済の中心になっている。", "target_word": "農産", "complexity_tier": "T3", "furigana": "この国[くに]は工業[こうぎょう]よりも農産[のうさん]が経済[けいざい]の中心[ちゅうしん]になっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農産", "label": "基本形"}], "register": "標準（常体）", "sense_fingerprint": "農業によって生産される産物。野菜・米など", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e1bbe0-3c9d-4fe0-b0b7-7f30482dfc7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38253, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "農産", "is_correct": true, "explanation": "米や野菜を含む生産物を指し、生産量の対象として正しい。"}, {"text": "農家", "is_correct": false, "explanation": "農業を営む人や家を指し、生産量の対象にはならない。"}, {"text": "農地", "is_correct": false, "explanation": "畑そのものを指す土地の語で、生産量の対象にはならない。"}, {"text": "農閑期", "is_correct": false, "explanation": "農作業が少ない時期のことで、生産量とは結びつかない。"}], "explanations": {"農産": "米や野菜を含む生産物を指し、生産量の対象として正しい。", "農家": "農業を営む人や家を指し、生産量の対象にはならない。", "農地": "畑そのものを指す土地の語で、生産量の対象にはならない。", "農閑期": "農作業が少ない時期のことで、生産量とは結びつかない。"}, "sentence_index": 0, "correct_answer": "農産"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市は地元の農産を担い手として育てる計画を立てた。", "explanation": "ここは〈農業〉（担い手）の意味。農産は食べ物で、人のように担い手として育てる対象ではない。"}, {"text": "市は地元の農産を広げて、新しい畑を作る計画だ。", "explanation": "ここは〈農地〉の意味。農産は広げるものではなく、広がるのは畑そのものなので合わない。"}, {"text": "市は地元の農産を雇って、畑の仕事を任せた。", "explanation": "ここは〈農家〉の意味。農産は人ではないので、雇ったり仕事を任せたりできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38253, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "農産", "is_correct": true, "explanation": "米と並べて農業の生産物の一つを示す語で、代表する産物の意味に合う。"}, {"text": "農薬", "is_correct": false, "explanation": "害虫を防ぐ薬剤で、米のような代表的な産物とは言えない。"}, {"text": "工芸品", "is_correct": false, "explanation": "手仕事で作る工芸の品で、米と並ぶ代表的な農産とは言えない。"}, {"text": "肥料", "is_correct": false, "explanation": "作物に与える材料で、米と並ぶ代表的な産物にはならない。"}], "explanations": {"農産": "米と並べて農業の生産物の一つを示す語で、代表する産物の意味に合う。", "農薬": "害虫を防ぐ薬剤で、米のような代表的な産物とは言えない。", "工芸品": "手仕事で作る工芸の品で、米と並ぶ代表的な農産とは言えない。", "肥料": "作物に与える材料で、米と並ぶ代表的な産物にはならない。"}, "sentence_index": 6, "correct_answer": "農産"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この町は漁師が多く、港では農産が毎朝水揚げされている。", "explanation": "ここは〈水産〉の意味。水揚げするのは海産物で、畑でとれる農産とは合わない。"}, {"text": "この国は害虫の被害を防ぐため、農産の使用量を毎年増やしている。", "explanation": "ここは〈農薬〉の意味。農産は使う薬剤ではなく食べ物なので、使用量という言い方はしない。"}, {"text": "この国は鉱業が衰えて、農産を掘り出す仕事が増えている。", "explanation": "ここは〈鉱業〉の意味。掘り出すのは鉱物で、畑でとれる農産は掘るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38253, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この国では、農産を輸出がこの数年で大きく伸びた。", "corrected_sentence": "この国では、農産の輸出がこの数年で大きく伸びた。", "error_description": "助詞の誤り。「輸出」を修飾するので「農産の」と連体修飾の「の」が必要。「を」は目的語を示し、後ろの「輸出が伸びた」と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38253, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年は農産を収穫が多く、市場に野菜が安く並んだ。", "corrected_sentence": "今年は農産の収穫が多く、市場に野菜が安く並んだ。", "error_description": "助詞の誤り。「農産の収穫」は「の」で「収穫」を修飾する。「を」は目的語で、後ろの「収穫が多い」と続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd57213f-6007-4df9-bf96-242b9c5934c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38254, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "簡潔", "is_correct": true, "explanation": "むだがなく短くまとまっている意味で、冗長の反対語として辞書に挙がる。"}, {"text": "豊富", "is_correct": false, "explanation": "量が多い点では近いが、冗長の反対語ではない。"}, {"text": "迅速", "is_correct": false, "explanation": "速さを表す語で、冗長とは反対の関係にない。"}, {"text": "活発", "is_correct": false, "explanation": "動きが盛んなことを表し、冗長の反対語ではない。"}], "correct_answer": "簡潔", "explanations": {"簡潔": "むだがなく短くまとまっている意味で、冗長の反対語として辞書に挙がる。", "豊富": "量が多い点では近いが、冗長の反対語ではない。", "迅速": "速さを表す語で、冗長とは反対の関係にない。", "活発": "動きが盛んなことを表し、冗長の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38254, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "簡潔", "is_correct": true, "explanation": "むだがなく短くまとまっている意味で、冗長の反対語として辞書に挙がる。"}, {"text": "緻密", "is_correct": false, "explanation": "細かく行き届いている意味で、冗長の反対語ではない。"}, {"text": "大胆", "is_correct": false, "explanation": "思い切りがよい意味で、冗長とは反対の関係にない。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深い意味で、冗長の反対語ではない。"}], "correct_answer": "簡潔", "explanations": {"簡潔": "むだがなく短くまとまっている意味で、冗長の反対語として辞書に挙がる。", "緻密": "細かく行き届いている意味で、冗長の反対語ではない。", "大胆": "思い切りがよい意味で、冗長とは反対の関係にない。", "慎重": "注意深い意味で、冗長の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38254, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "必要なものよりも多くあること。", "primary_collocate": null, "pronunciation": "じょうちょう", "ipa": "dʑoːtɕoː", "syllable_count": 4, "sentences": [{"text": "この資料は同じ説明が何度も出てくるので、冗長だと言われました。", "target_word": "冗長", "complexity_tier": "T3", "furigana": "この資料[しりょう]は同[おな]じ説明[せつめい]が何度[なんど]も出[で]てくるので、冗長[じょうちょう]だと言[い]われました。", "sentence_source": "generated"}, {"text": "冗長な部分を削ったら、レポートが三ページに収まりました。", "target_word": "冗長な", "complexity_tier": "T3", "furigana": "冗長[じょうちょう]な部分[ぶぶん]を削[けず]ったら、レポートが三[さん]ページに収[おさ]まりました。", "sentence_source": "generated"}, {"text": "彼のあいさつは冗長で、最後まで聞くのがつらかった。", "target_word": "冗長で", "complexity_tier": "T3", "furigana": "彼[かれ]のあいさつは冗長[じょうちょう]で、最後[さいご]まで聞[き]くのがつらかった。", "sentence_source": "generated"}, {"text": "同じ内容を二回書くのは冗長なので、一回にまとめましょう。", "target_word": "冗長な", "complexity_tier": "T3", "furigana": "同[おな]じ内容[ないよう]を二回[にかい]書[か]くのは冗長[じょうちょう]なので、一回[いっかい]にまとめましょう。", "sentence_source": "generated"}, {"text": "この設計は冗長で、部品の数が必要以上に多い。", "target_word": "冗長で", "complexity_tier": "T3", "furigana": "この設計[せっけい]は冗長[じょうちょう]で、部品[ぶひん]の数[かず]が必要[ひつよう]以上[いじょう]に多[おお]い。", "sentence_source": "generated"}, {"text": "冗長な言い方をやめて、短く答えてください。", "target_word": "冗長な", "complexity_tier": "T3", "furigana": "冗長[じょうちょう]な言[い]い方[かた]をやめて、短[みじか]く答[こた]えてください。", "sentence_source": "generated"}, {"text": "メールが冗長にならないよう、要点だけ書いた。", "target_word": "冗長に", "complexity_tier": "T3", "furigana": "メールが冗長[じょうちょう]にならないよう、要点[ようてん]だけ書[か]いた。", "sentence_source": "generated"}, {"text": "説明が冗長だったため、聞き手は途中で飽きてしまった。", "target_word": "冗長だった", "complexity_tier": "T3", "furigana": "説明[せつめい]が冗長[じょうちょう]だったため、聞[き]き手[て]は途中[とちゅう]で飽[あ]きてしまった。", "sentence_source": "generated"}, {"text": "冗長な表現を減らすと、文章が読みやすくなります。", "target_word": "冗長な", "complexity_tier": "T3", "furigana": "冗長[じょうちょう]な表現[ひょうげん]を減[へ]らすと、文章[ぶんしょう]が読[よ]みやすくなります。", "sentence_source": "generated"}, {"text": "この規則は冗長なので、半分に減らしても問題ありません。", "target_word": "冗長な", "complexity_tier": "T3", "furigana": "この規則[きそく]は冗長[じょうちょう]なので、半分[はんぶん]に減[へ]らしても問題[もんだい]ありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "冗長だ", "label": "終止形"}, {"form": "冗長な", "label": "連体形"}, {"form": "冗長で", "label": "連用形（で）"}, {"form": "冗長に", "label": "連用形（に）"}, {"form": "冗長だった", "label": "過去形"}], "register": "書き言葉", "sense_fingerprint": "必要な量より多くて余分なこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '725786b7-83d1-4185-8797-adecf4153e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38254, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冗長", "is_correct": true, "explanation": "同じ説明が繰り返されることを指摘する語として文脈に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "人の性格を表す語で、説明の内容には使えない。"}, {"text": "頑丈", "is_correct": false, "explanation": "丈夫さを表す語で、説明の繰り返しとは関係がない。"}, {"text": "鮮明", "is_correct": false, "explanation": "はっきりしている様子を表し、繰り返しを指摘する文脈に合わない。"}], "explanations": {"冗長": "同じ説明が繰り返されることを指摘する語として文脈に合う。", "陽気": "人の性格を表す語で、説明の内容には使えない。", "頑丈": "丈夫さを表す語で、説明の繰り返しとは関係がない。", "鮮明": "はっきりしている様子を表し、繰り返しを指摘する文脈に合わない。"}, "sentence_index": 0, "correct_answer": "冗長"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の笑顔は冗長で、どこか不自然だった。", "explanation": "ここは〈大げさ〉の意味。冗長は量や構成が多すぎることを言うので、表情の印象には使わない。"}, {"text": "彼の話は短すぎて、冗長にしか聞こえなかった。", "explanation": "「短すぎて」と「冗長」（余分に多い）が矛盾し、この文脈では義項が成り立たない。"}, {"text": "冗長な髪を切って、さっぱりした。", "explanation": "ここは〈長い〉の意味。冗長は量が多すぎることで、髪の長さを言う語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38254, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冗長に", "is_correct": true, "explanation": "「冗長にならない」の形で、メールの書き方を指す文脈に合う。"}, {"text": "繊細に", "is_correct": false, "explanation": "「繊細にならない」は文脈に合わず、メールの長さを表さない。"}, {"text": "豪華に", "is_correct": false, "explanation": "「豪華にならない」は文脈に合わず、メールの書き方とは関係がない。"}, {"text": "乱暴に", "is_correct": false, "explanation": "「乱暴にならない」は文脈に合わず、メールの長さを表さない。"}], "explanations": {"冗長に": "「冗長にならない」の形で、メールの書き方を指す文脈に合う。", "繊細に": "「繊細にならない」は文脈に合わず、メールの長さを表さない。", "豪華に": "「豪華にならない」は文脈に合わず、メールの書き方とは関係がない。", "乱暴に": "「乱暴にならない」は文脈に合わず、メールの長さを表さない。"}, "sentence_index": 6, "correct_answer": "冗長に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冗長な食材は足りなかったので、急いで買いに行った。", "explanation": "「冗長」は余分な量を表し、「足りなかった」と矛盾するので、この文脈では誤り。"}, {"text": "彼は冗長な足取りで、ゆっくり歩いた。", "explanation": "ここは〈のろい〉の意味。冗長は量や構成が多すぎることで、歩く速さには使わない。"}, {"text": "冗長に寒さに、震えが止まらなかった。", "explanation": "「冗長に」は名詞の前に置けず、「寒さに」と続けても形が崩れる。意味ではなく形の誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38254, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この資料は内容が多く、冗長に言われた。", "corrected_sentence": "この資料は内容が多く、冗長だと言われた。", "error_description": "誤り：「冗長に」。正しくは「冗長だと」。断定の「冗長だ」に引用の「と」を付けて「言われた」に続ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "冗長な", "is_correct": true, "explanation": "連体形で、後ろの名詞「部分」を修飾する形に合う。"}, {"text": "冗長だ", "is_correct": false, "explanation": "終止形で、名詞を直接修飾できない。"}, {"text": "冗長で", "is_correct": false, "explanation": "連用形の「で」は名詞を修飾できず、文の形が崩れる。"}, {"text": "冗長に", "is_correct": false, "explanation": "連用形の「に」は動詞を修飾する形で、名詞の前には入らない。"}], "correct_form": "冗長な", "base_form": "冗長だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"冗長な": "連体形で、後ろの名詞「部分」を修飾する形に合う。", "冗長だ": "終止形で、名詞を直接修飾できない。", "冗長で": "連用形の「で」は名詞を修飾できず、文の形が崩れる。", "冗長に": "連用形の「に」は動詞を修飾する形で、名詞の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38254, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "説明が冗長なったので、聞き手は途中で飽きた。", "corrected_sentence": "説明が冗長になったので、聞き手は途中で飽きた。", "error_description": "誤り：「冗長なった」。「なる」には形容動詞の連用形「に」を用い、正しくは「冗長になった」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "冗長だった", "is_correct": true, "explanation": "過去の断定形で、「説明が〜だったため」の形に合う。"}, {"text": "冗長な", "is_correct": false, "explanation": "連体形は「説明が」の述語として続かず、文の形が崩れる。"}, {"text": "冗長なら", "is_correct": false, "explanation": "仮定の形は「ため」の前で原因を述べる文に合わない。"}, {"text": "冗長だろう", "is_correct": false, "explanation": "推量の形になり、実際に聞き手が飽きた事実と合わない。"}], "correct_form": "冗長だった", "base_form": "冗長だ", "form_label": "過去形", "sentence_index": 7, "explanations": {"冗長だった": "過去の断定形で、「説明が〜だったため」の形に合う。", "冗長な": "連体形は「説明が」の述語として続かず、文の形が崩れる。", "冗長なら": "仮定の形は「ため」の前で原因を述べる文に合わない。", "冗長だろう": "推量の形になり、実際に聞き手が飽きた事実と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38255, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "簡潔", "is_correct": true, "explanation": "むだがなく短くまとまっている意味で、冗長の反対語として辞書に挙がる。"}, {"text": "豊富", "is_correct": false, "explanation": "量が多い点では近いが、冗長の反対語ではない。"}, {"text": "迅速", "is_correct": false, "explanation": "速さを表す語で、冗長とは反対の関係にない。"}, {"text": "活発", "is_correct": false, "explanation": "動きが盛んなことを表し、冗長の反対語ではない。"}], "correct_answer": "簡潔", "explanations": {"簡潔": "むだがなく短くまとまっている意味で、冗長の反対語として辞書に挙がる。", "豊富": "量が多い点では近いが、冗長の反対語ではない。", "迅速": "速さを表す語で、冗長とは反対の関係にない。", "活発": "動きが盛んなことを表し、冗長の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
