INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38255, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "必要以上に長かったり、多かったりすること。むだな部分があること。", "primary_collocate": null, "pronunciation": "じょうちょう", "ipa": "dʑoːtɕoː", "syllable_count": 4, "sentences": [{"text": "冗長な会議が続いて、夕方まで終わらなかった。", "target_word": "冗長な", "complexity_tier": "T3", "furigana": "冗長[じょうちょう]な会議[かいぎ]が続[つづ]いて、夕方[ゆうがた]まで終[お]わらなかった。", "sentence_source": "generated"}, {"text": "彼の話は冗長で、結論までに三十分もかかった。", "target_word": "冗長で", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は冗長[じょうちょう]で、結論[けつろん]までに三十分[さんじゅっぷん]もかかった。", "sentence_source": "generated"}, {"text": "この小説は前半が冗長で、物語がなかなか進まない。", "target_word": "冗長で", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は前半[ぜんはん]が冗長[じょうちょう]で、物語[ものがたり]がなかなか進[すす]まない。", "sentence_source": "generated"}, {"text": "冗長な手順を省いて、作業を速くした。", "target_word": "冗長な", "complexity_tier": "T3", "furigana": "冗長[じょうちょう]な手順[てじゅん]を省[はぶ]いて、作業[さぎょう]を速[はや]くした。", "sentence_source": "generated"}, {"text": "無駄が多く冗長なプログラムを、短く書き直した。", "target_word": "冗長な", "complexity_tier": "T3", "furigana": "無駄[むだ]が多[おお]く冗長[じょうちょう]なプログラムを、短[みじか]く書[か]き直[なお]した。", "sentence_source": "generated"}, {"text": "先生の説明は冗長だが、とても丁寧だ。", "target_word": "冗長だ", "complexity_tier": "T3", "furigana": "先生[せんせい]の説明[せつめい]は冗長[じょうちょう]だが、とても丁寧[ていねい]だ。", "sentence_source": "generated"}, {"text": "契約書の文章が冗長で、大事な点が見つけにくい。", "target_word": "冗長で", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]の文章[ぶんしょう]が冗長[じょうちょう]で、大事[だいじ]な点[てん]が見[み]つけにくい。", "sentence_source": "generated"}, {"text": "冗長な映画だったので、途中で眠ってしまった。", "target_word": "冗長な", "complexity_tier": "T3", "furigana": "冗長[じょうちょう]な映画[えいが]だったので、途中[とちゅう]で眠[ねむ]ってしまった。", "sentence_source": "generated"}, {"text": "手紙が冗長にならないように、短くまとめた。", "target_word": "冗長に", "complexity_tier": "T3", "furigana": "手紙[てがみ]が冗長[じょうちょう]にならないように、短[みじか]くまとめた。", "sentence_source": "generated"}, {"text": "冗長な前置きはいいので、すぐ本題に入ってください。", "target_word": "冗長な", "complexity_tier": "T3", "furigana": "冗長[じょうちょう]な前置[まえお]きはいいので、すぐ本題[ほんだい]に入[はい]ってください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "冗長だ", "label": "終止形"}, {"form": "冗長な", "label": "連体形"}, {"form": "冗長で", "label": "連用形（で）"}, {"form": "冗長に", "label": "連用形（に）"}, {"form": "冗長だった", "label": "過去形"}], "register": "書き言葉", "sense_fingerprint": "長すぎてむだな部分があること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '725786b7-83d1-4185-8797-adecf4153e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38255, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冗長な", "is_correct": true, "explanation": "長すぎてむだな会議という意味で、夕方まで終わらなかった文脈に合う。"}, {"text": "陽気な", "is_correct": false, "explanation": "人の性格を表す語で、会議の長さを表さない。"}, {"text": "頑丈な", "is_correct": false, "explanation": "丈夫さを表す語で、会議の進み方とは関係がない。"}, {"text": "鮮明な", "is_correct": false, "explanation": "はっきりしている様子を表し、長引いた会議の文脈に合わない。"}], "explanations": {"冗長な": "長すぎてむだな会議という意味で、夕方まで終わらなかった文脈に合う。", "陽気な": "人の性格を表す語で、会議の長さを表さない。", "頑丈な": "丈夫さを表す語で、会議の進み方とは関係がない。", "鮮明な": "はっきりしている様子を表し、長引いた会議の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "冗長な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その機械は冗長な音を立てて、動いていた。", "explanation": "ここは〈騒がしい〉の意味。冗長は必要以上の長さや多さを言う語で、音の大きさには使わない。"}, {"text": "彼は冗長に笑って、場を和ませた。", "explanation": "ここは〈大げさ〉の意味。冗長は話や手順がむだに長いことに使い、笑い方には使わない。"}, {"text": "冗長な声で、友人の名前を呼んだ。", "explanation": "ここは〈大きい〉の意味。声の大きさには冗長を使わず、大声と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38255, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冗長で", "is_correct": true, "explanation": "「文章が冗長で、要点が見つけにくい」の述語として文脈に合う。"}, {"text": "繊細で", "is_correct": false, "explanation": "細やかさを表す語で、文章の読みにくさの原因として合わない。"}, {"text": "豪華で", "is_correct": false, "explanation": "華やかさを表す語で、要点が見つけにくい文脈と合わない。"}, {"text": "陽気で", "is_correct": false, "explanation": "明るさを表す語で、文章の読みにくさとは関係がない。"}], "explanations": {"冗長で": "「文章が冗長で、要点が見つけにくい」の述語として文脈に合う。", "繊細で": "細やかさを表す語で、文章の読みにくさの原因として合わない。", "豪華で": "華やかさを表す語で、要点が見つけにくい文脈と合わない。", "陽気で": "明るさを表す語で、文章の読みにくさとは関係がない。"}, "sentence_index": 6, "correct_answer": "冗長で"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冗長な小包が届いて、びっくりした。", "explanation": "ここは〈大きい〉の意味。冗長は長さや多さがむだなことを言い、荷物の大きさには使わない。"}, {"text": "冗長な味のスープを飲んだ。", "explanation": "ここは〈濃い〉の意味。味の濃さには冗長を使わず、濃いと言う。"}, {"text": "冗長な口出しはやめてください。", "explanation": "ここは〈余計〉の意味。冗長は文章などの余分さに使い、人の行動には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38255, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冗長の打ち合わせが続き、夕方まで終わらなかった。", "corrected_sentence": "冗長な打ち合わせが続き、夕方まで終わらなかった。", "error_description": "誤り：「冗長の」。正しくは「冗長な」。冗長は形状詞なので、名詞を修飾するときは「な」を付ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "冗長で", "is_correct": true, "explanation": "連用形の「で」で、「話は冗長で、〜かかった」と後ろに続ける形に合う。"}, {"text": "冗長だ", "is_correct": false, "explanation": "終止形は文を言い切るため、後ろの「結論までに〜かかった」と続かない。"}, {"text": "冗長な", "is_correct": false, "explanation": "連体形は名詞を修飾するため、「話は」の述語にならない。"}, {"text": "冗長に", "is_correct": false, "explanation": "連用形の「に」は動詞を修飾する形で、「話は」の述語にならない。"}], "correct_form": "冗長で", "base_form": "冗長だ", "form_label": "連用形（で）", "sentence_index": 1, "explanations": {"冗長で": "連用形の「で」で、「話は冗長で、〜かかった」と後ろに続ける形に合う。", "冗長だ": "終止形は文を言い切るため、後ろの「結論までに〜かかった」と続かない。", "冗長な": "連体形は名詞を修飾するため、「話は」の述語にならない。", "冗長に": "連用形の「に」は動詞を修飾する形で、「話は」の述語にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38255, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "報告書の文章が冗長に、要点がわかりにくい。", "corrected_sentence": "報告書の文章が冗長で、要点がわかりにくい。", "error_description": "誤り：「冗長に」。正しくは「冗長で」。後ろに状態を並べる文なので、連用形「で」で続ける。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "冗長な", "is_correct": true, "explanation": "連体形で、後ろの名詞「映画」を修飾する形に合う。"}, {"text": "冗長に", "is_correct": false, "explanation": "連用形の「に」は動詞を修飾するため、「映画」を修飾できない。"}, {"text": "冗長なら", "is_correct": false, "explanation": "仮定の形は名詞を修飾できず、文の形が崩れる。"}, {"text": "冗長だろう", "is_correct": false, "explanation": "推量の形は名詞を修飾できず、「映画」に続かない。"}], "correct_form": "冗長な", "base_form": "冗長だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"冗長な": "連体形で、後ろの名詞「映画」を修飾する形に合う。", "冗長に": "連用形の「に」は動詞を修飾するため、「映画」を修飾できない。", "冗長なら": "仮定の形は名詞を修飾できず、文の形が崩れる。", "冗長だろう": "推量の形は名詞を修飾できず、「映画」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38256, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "が", "is_correct": false, "explanation": "「防衛が予算を発表した」では防衛が発表する主語になり、防衛と予算を結べない。"}, {"text": "の", "is_correct": true, "explanation": "「防衛」と「予算」を結び、防衛のための予算という意味を作る連体修飾の「の」。"}, {"text": "を", "is_correct": false, "explanation": "「予算を」は発表の目的語として文中にすでにある。防衛と予算の間に入れると「防衛を予算を」となり不自然。"}, {"text": "で", "is_correct": false, "explanation": "「防衛で予算」は手段や場所を表すが、防衛と予算の関係としては意味が通らない。"}], "correct_answer": "の", "explanations": {"が": "「防衛が予算を発表した」では防衛が発表する主語になり、防衛と予算を結べない。", "の": "「防衛」と「予算」を結び、防衛のための予算という意味を作る連体修飾の「の」。", "を": "「予算を」は発表の目的語として文中にすでにある。防衛と予算の間に入れると「防衛を予算を」となり不自然。", "で": "「防衛で予算」は手段や場所を表すが、防衛と予算の関係としては意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段・場所"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "攻撃", "is_correct": true, "explanation": "防衛の対義語。守る側に対して攻める側を表すので、国境を守る文脈と反対の関係になる。"}, {"text": "製造", "is_correct": false, "explanation": "ものを作ること。守ることの反対語ではない。"}, {"text": "教育", "is_correct": false, "explanation": "人を教え育てること。防衛の対義語ではない。"}, {"text": "旅行", "is_correct": false, "explanation": "別の土地へ出かけること。防衛とは対義の関係にない。"}], "correct_answer": "攻撃", "explanations": {"攻撃": "防衛の対義語。守る側に対して攻める側を表すので、国境を守る文脈と反対の関係になる。", "製造": "ものを作ること。守ることの反対語ではない。", "教育": "人を教え育てること。防衛の対義語ではない。", "旅行": "別の土地へ出かけること。防衛とは対義の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38256, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "から", "is_correct": false, "explanation": "「防衛から大切にする」では起点の関係になり、大切にする対象として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「防衛と大切にする」では並列の関係にならず、大切にする対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「防衛へ大切にする」では方向を表すが、大切にする対象を示せない。"}, {"text": "も", "is_correct": true, "explanation": "「防衛も大切にする」で、攻撃に加えて守りも重んじるという意味を作る「も」。"}], "correct_answer": "も", "explanations": {"から": "「防衛から大切にする」では起点の関係になり、大切にする対象として成り立たない。", "と": "「防衛と大切にする」では並列の関係にならず、大切にする対象を示せない。", "へ": "「防衛へ大切にする」では方向を表すが、大切にする対象を示せない。", "も": "「防衛も大切にする」で、攻撃に加えて守りも重んじるという意味を作る「も」。"}, "error_tags": {"から": "起点", "と": "並列", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "栽培", "is_correct": false, "explanation": "植物を育てること。防衛の反対語ではない。"}, {"text": "攻撃", "is_correct": true, "explanation": "防衛の対義語。守る側に対して攻める側を表すので、防衛の反対の関係にあたる。"}, {"text": "観光", "is_correct": false, "explanation": "名所などを見て回ること。防衛の対義語ではない。"}, {"text": "養殖", "is_correct": false, "explanation": "魚や貝を人の手で育てること。防衛とは対義の関係にない。"}], "correct_answer": "攻撃", "explanations": {"栽培": "植物を育てること。防衛の反対語ではない。", "攻撃": "防衛の対義語。守る側に対して攻める側を表すので、防衛の反対の関係にあたる。", "観光": "名所などを見て回ること。防衛の対義語ではない。", "養殖": "魚や貝を人の手で育てること。防衛とは対義の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38256, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "外からの攻撃や侵入に備えて、国や地位などを守ること。", "primary_collocate": null, "pronunciation": "ぼうえい", "ipa": "boːeː", "syllable_count": 4, "sentences": [{"text": "この国は、海や空の防衛に力を入れている。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "この国[くに]は、海[うみ]や空[そら]の防衛[ぼうえい]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "政府は来年の防衛の予算を発表した。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "政府[せいふ]は来年[らいねん]の防衛[ぼうえい]の予算[よさん]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "この城は、敵から町を防衛するために築かれた。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "この城[しろ]は、敵[てき]から町[まち]を防衛[ぼうえい]するために築[きず]かれた。", "sentence_source": "generated"}, {"text": "兵士たちは、最後まで国境を防衛した。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは、最後[さいご]まで国境[こっきょう]を防衛[ぼうえい]した。", "sentence_source": "generated"}, {"text": "彼は今年もチャンピオンの座を防衛した。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "彼[かれ]は今年[ことし]もチャンピオンの座[ざ]を防衛[ぼうえい]した。", "sentence_source": "generated"}, {"text": "相手が攻めてきたときだけ防衛する、という考え方もある。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "相手[あいて]が攻[せ]めてきたときだけ防衛[ぼうえい]する、という考[かんが]え方[かた]もある。", "sentence_source": "generated"}, {"text": "自衛官は、国の防衛を仕事にしている人たちだ。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "自衛官[じえいかん]は、国[くに]の防衛[ぼうえい]を仕事[しごと]にしている人[ひと]たちだ。", "sentence_source": "generated"}, {"text": "攻撃ばかり考えず、防衛も大切にしなければ勝てない。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "攻撃[こうげき]ばかり考[かんが]えず、防衛[ぼうえい]も大切[たいせつ]にしなければ勝[か]てない。", "sentence_source": "generated"}, {"text": "その島には、外国からの攻撃に備えて、防衛のための基地が置かれている。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "その島[しま]には、外国[がいこく]からの攻撃[こうげき]に備[そな]えて、防衛[ぼうえい]のための基地[きち]が置[お]かれている。", "sentence_source": "generated"}, {"text": "防衛の仕事をする大臣は、毎朝ニュースを確認するそうだ。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "防衛[ぼうえい]の仕事[しごと]をする大臣[だいじん]は、毎朝[まいあさ]ニュースを確認[かくにん]するそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "防衛", "label": "基本形"}, {"form": "防衛する", "label": "終止形"}, {"form": "防衛した", "label": "過去形"}, {"form": "防衛し", "label": "連用形"}], "register": "formal", "sense_fingerprint": "外からの攻撃や侵入に備えて、国や地位などを守ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e5da86-1411-4fd5-9f5f-e54c321bb1e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38256, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結婚", "is_correct": false, "explanation": "夫婦になることを表す語で、海や空を対象にすると意味が通らない。"}, {"text": "防衛", "is_correct": true, "explanation": "外からの攻撃や侵入に備えて守ること。海や空の守りに力を入れるという文脈に合う。"}, {"text": "読書", "is_correct": false, "explanation": "本を読むこと。海や空を対象にすると文が成り立たない。"}, {"text": "集金", "is_correct": false, "explanation": "お金を集めること。海や空の集金に力を入れるという文は成り立たない。"}], "explanations": {"結婚": "夫婦になることを表す語で、海や空を対象にすると意味が通らない。", "防衛": "外からの攻撃や侵入に備えて守ること。海や空の守りに力を入れるという文脈に合う。", "読書": "本を読むこと。海や空を対象にすると文が成り立たない。", "集金": "お金を集めること。海や空の集金に力を入れるという文は成り立たない。"}, "sentence_index": 0, "correct_answer": "防衛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪をひかないよう、毎日うがいをして防衛している。", "explanation": "ここは〈予防〉の意味。病気を防ぐ場合は〈予防〉を使い、防衛は外からの攻撃や侵入に備えて守ることなので合わない。"}, {"text": "台風が近づいているので、町の防衛のために避難の準備をした。", "explanation": "ここは〈防災〉の意味。台風などの自然災害への備えは〈防災〉で言い、防衛は敵の攻撃や侵入に備える意味で使うので合わない。"}, {"text": "道で弱っていた子猫を防衛して、家に連れて帰った。", "explanation": "ここは〈保護〉の意味。弱った動物を助けて守る場合は〈保護〉を使い、防衛は国や地位などを攻撃から守る意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38256, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "登山", "is_correct": false, "explanation": "山に登ること。国の仕事を登山とするのは文脈に合わない。"}, {"text": "防衛", "is_correct": true, "explanation": "外からの攻撃や侵入に備えて国を守ること。自衛官の仕事として合う。"}, {"text": "製菓", "is_correct": false, "explanation": "菓子を作ること。国の仕事を製菓とするのは意味が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "気晴らしに歩くこと。仕事の内容としては文が成り立たない。"}], "explanations": {"登山": "山に登ること。国の仕事を登山とするのは文脈に合わない。", "防衛": "外からの攻撃や侵入に備えて国を守ること。自衛官の仕事として合う。", "製菓": "菓子を作ること。国の仕事を製菓とするのは意味が通らない。", "散歩": "気晴らしに歩くこと。仕事の内容としては文が成り立たない。"}, "sentence_index": 6, "correct_answer": "防衛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "砂漠では、水の蒸発を防衛するため、布で水筒を覆った。", "explanation": "ここは〈防止〉の意味。水が蒸発するような自然の現象を抑える場合は〈防止〉を使い、防衛は敵の攻撃や危険から国や地位を守る場面に使うので合わない。"}, {"text": "放射線から作業員を防衛するため、厚い服を着せた。", "explanation": "ここは〈防護〉の意味。放射線や有害な物質から人を守る場合は〈防護〉を使い、防衛は敵の攻撃や国土を守る場面に使うので合わない。"}, {"text": "祭りの屋台は、火事の延焼を防衛するために間隔があけてある。", "explanation": "ここは〈防火〉の意味。火が燃え広がるのを防ぐ場合は〈防火〉を使い、防衛は敵の攻撃や国土を守る場面に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38256, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この砦は、敵から村に防衛するために築かれた。", "corrected_sentence": "この砦は、敵から村を防衛するために築かれた。", "error_description": "「防衛する」は目的語に「を」を取る他動詞。「村に」は誤りで、正しくは「村を防衛する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38256, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町は、兵士たちによって防衛られた。", "corrected_sentence": "この町は、兵士たちによって防衛された。", "error_description": "「防衛する」は「する」動詞なので、受身は「防衛される」→過去形「防衛された」。「防衛られた」は一段動詞の受身の形を誤って付けた活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38257, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "攻撃", "is_correct": true, "explanation": "攻め込むこと。守る行為の対義語として類語辞典に挙がる。"}, {"text": "準備", "is_correct": false, "explanation": "前もって整えること。防衛に先立つ行為で、対義語ではない。"}, {"text": "翻訳", "is_correct": false, "explanation": "言葉を別の言語に訳す意味で、防衛の対義語ではない。"}, {"text": "休息", "is_correct": false, "explanation": "体を休める意味で、防衛とは関係がない。"}], "correct_answer": "攻撃", "explanations": {"攻撃": "攻め込むこと。守る行為の対義語として類語辞典に挙がる。", "準備": "前もって整えること。防衛に先立つ行為で、対義語ではない。", "翻訳": "言葉を別の言語に訳す意味で、防衛の対義語ではない。", "休息": "体を休める意味で、防衛とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38257, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "攻撃", "is_correct": true, "explanation": "攻め込むこと。守る行為の対義語として類語辞典に挙がる。"}, {"text": "訓練", "is_correct": false, "explanation": "技能を身につけるために繰り返し行うこと。防衛の対義語ではない。"}, {"text": "交換", "is_correct": false, "explanation": "物をやりとりする意味で、防衛の対義語ではない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解き散らす意味で、防衛とは対になる関係ではない。"}], "correct_answer": "攻撃", "explanations": {"攻撃": "攻め込むこと。守る行為の対義語として類語辞典に挙がる。", "訓練": "技能を身につけるために繰り返し行うこと。防衛の対義語ではない。", "交換": "物をやりとりする意味で、防衛の対義語ではない。", "解散": "集まりを解き散らす意味で、防衛とは対になる関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38257, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "攻撃や危険から守ること。また、そのための手段や行為。", "primary_collocate": null, "pronunciation": "ぼうえい", "ipa": "boːeː", "syllable_count": 4, "sentences": [{"text": "みんなの町を、しっかり防衛します。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "みんなの町[まち]を、しっかり防衛[ぼうえい]します。", "sentence_source": "mined"}, {"text": "国を防衛するために、兵士たちは毎日訓練をしています。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "国[くに]を防衛[ぼうえい]するために、兵士[へいし]たちは毎日[まいにち]訓練[くんれん]をしています。", "sentence_source": "generated"}, {"text": "相手の攻撃が強かったので、チームは防衛に集中した。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "相手[あいて]の攻撃[こうげき]が強[つよ]かったので、チームは防衛[ぼうえい]に集中[しゅうちゅう]した。", "sentence_source": "generated"}, {"text": "小さな動物は、敵が近づくと防衛のために毛を逆立てる。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "小[ちい]さな動物[どうぶつ]は、敵[てき]が近[ちか]づくと防衛[ぼうえい]のために毛[け]を逆立[さかだ]てる。", "sentence_source": "generated"}, {"text": "城の防衛は難しく、敵に門を破られてしまった。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "城[しろ]の防衛[ぼうえい]は難[むずか]しく、敵[てき]に門[もん]を破[やぶ]られてしまった。", "sentence_source": "generated"}, {"text": "攻めるより防衛のほうが得意な選手が、試合を支えた。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "攻[せ]めるより防衛[ぼうえい]のほうが得意[とくい]な選手[せんしゅ]が、試合[しあい]を支[ささ]えた。", "sentence_source": "generated"}, {"text": "国境の防衛について、大臣が国会で説明した。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "国境[こっきょう]の防衛[ぼうえい]について、大臣[だいじん]が国会[こっかい]で説明[せつめい]した。", "sentence_source": "generated"}, {"text": "自分の家を防衛するため、住民たちは夜も見回りをした。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "自分[じぶん]の家[いえ]を防衛[ぼうえい]するため、住民[じゅうみん]たちは夜[よる]も見回[みまわ]りをした。", "sentence_source": "generated"}, {"text": "彼は防衛の手段として、大きな声で助けを呼んだ。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "彼[かれ]は防衛[ぼうえい]の手段[しゅだん]として、大[おお]きな声[こえ]で助[たす]けを呼[よ]んだ。", "sentence_source": "generated"}, {"text": "王は都を防衛する計画を、将軍たちと話し合った。", "target_word": "防衛", "complexity_tier": "T3", "furigana": "王[おう]は都[みやこ]を防衛[ぼうえい]する計画[けいかく]を、将軍[しょうぐん]たちと話[はな]し合[あ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "防衛", "label": "基本形"}, {"form": "防衛する", "label": "する動詞の終止形"}, {"form": "防衛した", "label": "過去形"}, {"form": "防衛して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "攻撃や危険から守る行為・手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 逆立てる (Zipf 1.27)']::text[], '7b3b14ba-f350-4b70-835c-74054ef8b390') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38257, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "防衛", "is_correct": true, "explanation": "「町を守る」という意味になり、文脈に合う。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解き散らす意味で、「町を解散する」は守る文脈と合わない。"}, {"text": "交換", "is_correct": false, "explanation": "物をやりとりする意味で、町には続かない。"}, {"text": "参加", "is_correct": false, "explanation": "加わる意味で、「町を参加する」とは言えない。"}], "explanations": {"防衛": "「町を守る」という意味になり、文脈に合う。", "解散": "集まりを解き散らす意味で、「町を解散する」は守る文脈と合わない。", "交換": "物をやりとりする意味で、町には続かない。", "参加": "加わる意味で、「町を参加する」とは言えない。"}, "sentence_index": 0, "correct_answer": "防衛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この番組は来週の夜、テレビで防衛されます。", "explanation": "ここは〈放映〉（テレビで流すこと）の意味。防衛は守ることなので、番組を流す場面には合わない。"}, {"text": "試合の最後まで、ファンは大きな声で防衛を続けた。", "explanation": "ここは〈声援〉（大きな声で励ますこと）の意味。防衛は守ることで、応援の意味では使わないので合わない。"}, {"text": "壊れた机を防衛して、きれいに直した。", "explanation": "ここは〈修理〉（壊れたものを直すこと）の意味。防衛は守ることで、直す意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38257, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防衛", "is_correct": true, "explanation": "国境の守りを指し、文脈に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "言葉を別の言語に訳す意味で、「国境の翻訳」では意味が通らない。"}, {"text": "採点", "is_correct": false, "explanation": "点数を付ける意味で、「国境の採点」とは続かない。"}, {"text": "予約", "is_correct": false, "explanation": "前もって取っておく意味で、「国境の予約」では文脈に合わない。"}], "explanations": {"防衛": "国境の守りを指し、文脈に合う。", "翻訳": "言葉を別の言語に訳す意味で、「国境の翻訳」では意味が通らない。", "採点": "点数を付ける意味で、「国境の採点」とは続かない。", "予約": "前もって取っておく意味で、「国境の予約」では文脈に合わない。"}, "sentence_index": 6, "correct_answer": "防衛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "相手の攻撃を受けたが、チームはすぐに防衛して点を返した。", "explanation": "ここは〈反撃〉（攻められて攻め返すこと）の意味。防衛は守ることで、攻め返す意味では使わない。"}, {"text": "会社は新しい提案を防衛して、その場で断った。", "explanation": "ここは〈拒否〉（受け入れずに断ること）の意味。防衛は守る行為で、断る意味では使わない。"}, {"text": "お客さんは席につくと、防衛を注文した。", "explanation": "ここは〈注文〉（品物を頼むこと）の意味。防衛は守ることで、頼む意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38257, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "敵の攻撃から町に防衛する。", "corrected_sentence": "敵の攻撃から町を防衛する。", "error_description": "「防衛する」は目的語に「を」をとる。「町に」は格助詞の誤りで、正しくは「町を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38257, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "チームの防衛を崩れて、失点が続いた。", "corrected_sentence": "チームの防衛が崩れて、失点が続いた。", "error_description": "「崩れる」は自動詞なので、主語には「が」を使う。「防衛を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
