INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38260, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "到着点を示す「に」で、「地区に救援物資が届いた」の形になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」を続けると主語が二つ並び、届く動作の主語として不自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では「地区を救援物資が届いた」となり、文が成り立たない。"}, {"text": "ながら", "is_correct": false, "explanation": "「ながら」は動詞に付く接続で、名詞の「地区」の後には続かず成り立たない。"}], "correct_answer": "に", "explanations": {"に": "到着点を示す「に」で、「地区に救援物資が届いた」の形になる。", "が": "「が」を続けると主語が二つ並び、届く動作の主語として不自然。", "を": "目的語の「を」では「地区を救援物資が届いた」となり、文が成り立たない。", "ながら": "「ながら」は動詞に付く接続で、名詞の「地区」の後には続かず成り立たない。"}, "error_tags": {"が": "主語", "を": "対象", "ながら": "接続"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38260, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある場所の中で、決められた範囲のところです。", "primary_collocate": null, "pronunciation": "ちく", "ipa": "tɕiku", "syllable_count": 2, "sentences": [{"text": "この地区は大雨のとき、川があふれる危険があるので避難の指示が出た。", "target_word": "地区", "complexity_tier": "T4", "furigana": "この地区[ちく]は大雨[おおあめ]のとき、川[かわ]があふれる危険[きけん]があるので避難[ひなん]の指示[しじ]が出[で]た。", "sentence_source": "generated"}, {"text": "工事は市の南側の地区だけで行われる。", "target_word": "地区", "complexity_tier": "T3", "furigana": "工事[こうじ]は市[し]の南側[みなみがわ]の地区[ちく]だけで行[おこな]われる。", "sentence_source": "generated"}, {"text": "火事を防ぐため、この地区では木の家を新しく建てられない。", "target_word": "地区", "complexity_tier": "T3", "furigana": "火事[かじ]を防[ふせ]ぐため、この地区[ちく]では木[き]の家[いえ]を新[あたら]しく建[た]てられない。", "sentence_source": "generated"}, {"text": "来月から、対象の地区に住む人には無料で検査券が配られる。", "target_word": "地区", "complexity_tier": "T4", "furigana": "来月[らいげつ]から、対象[たいしょう]の地区[ちく]に住[す]む人[ひと]には無料[むりょう]で検査券[けんさけん]が配[くば]られる。", "sentence_source": "generated"}, {"text": "この学校は、決められた地区の子どもだけが入ることができる。", "target_word": "地区", "complexity_tier": "T3", "furigana": "この学校[がっこう]は、決[き]められた地区[ちく]の子[こ]どもだけが入[はい]ることができる。", "sentence_source": "generated"}, {"text": "新しいごみの出し方は、まずこの地区で試すことになった。", "target_word": "地区", "complexity_tier": "T3", "furigana": "新[あたら]しいごみの出[だ]し方[かた]は、まずこの地区[ちく]で試[ため]すことになった。", "sentence_source": "generated"}, {"text": "祭りの間、この地区は車の進入が禁止される。", "target_word": "地区", "complexity_tier": "T3", "furigana": "祭[まつ]りの間[あいだ]、この地区[ちく]は車[くるま]の進入[しんにゅう]が禁止[きんし]される。", "sentence_source": "generated"}, {"text": "地震のあと、被害が大きかった地区に救援物資が届いた。", "target_word": "地区", "complexity_tier": "T4", "furigana": "地震[じしん]のあと、被害[ひがい]が大[おお]きかった地区[ちく]に救援[きゅうえん]物資[ぶっし]が届[とど]いた。", "sentence_source": "generated"}, {"text": "選挙の投票所は、住んでいる地区ごとに決まっている。", "target_word": "地区", "complexity_tier": "T3", "furigana": "選挙[せんきょ]の投票所[とうひょうじょ]は、住[す]んでいる地区[ちく]ごとに決[き]まっている。", "sentence_source": "generated"}, {"text": "古い建物を守るため、この地区には景観を保つ決まりがある。", "target_word": "地区", "complexity_tier": "T4", "furigana": "古[ふる]い建物[たてもの]を守[まも]るため、この地区[ちく]には景観[けいかん]を保[たも]つ決[き]まりがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地区", "label": "基本形"}], "register": "neutral written (plain form)", "sense_fingerprint": "行政や対策のために線を引いて決められた、一定の範囲の区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411dfe7-5f42-41f9-bd10-5cac4844963d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38260, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地区", "is_correct": true, "explanation": "「決まった範囲の場所」を指し、大雨で川があふれる危険がある地域の避難指示の文に合う。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は大雨による避難指示の主語にならず、文が成り立たない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は避難指示の主語にならず、文の意味が通らない。"}, {"text": "試合", "is_correct": false, "explanation": "試合は避難指示の主語にならず、文の意味が通らない。"}], "explanations": {"地区": "「決まった範囲の場所」を指し、大雨で川があふれる危険がある地域の避難指示の文に合う。", "宿題": "宿題は大雨による避難指示の主語にならず、文が成り立たない。", "料理": "料理は避難指示の主語にならず、文の意味が通らない。", "試合": "試合は避難指示の主語にならず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "地区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この地区を開けて、部屋に入った。", "explanation": "ここは〈扉〉の意味。地区は範囲を指す語で、開けるものではない。"}, {"text": "この地区に座って、映画を見た。", "explanation": "ここは〈座席〉の意味。地区は範囲を指す語で、座る場所としては使わない。"}, {"text": "彼女は指輪を、指の地区にはめた。", "explanation": "ここは〈身体の部分〉の意味。地区は地域の範囲を指す語なので、身体の一部には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38260, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地区", "is_correct": true, "explanation": "「決まった範囲の場所」を指し、祭りの間に車の進入が禁止される地域の文に合う。"}, {"text": "手帳", "is_correct": false, "explanation": "手帳は車の進入の主語にならず、文が成り立たない。"}, {"text": "花火", "is_correct": false, "explanation": "花火は車の進入禁止の主語にならず、文の意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は車の進入禁止の主語にならず、文の意味が通らない。"}], "explanations": {"地区": "「決まった範囲の場所」を指し、祭りの間に車の進入が禁止される地域の文に合う。", "手帳": "手帳は車の進入の主語にならず、文が成り立たない。", "花火": "花火は車の進入禁止の主語にならず、文の意味が通らない。", "天気": "天気は車の進入禁止の主語にならず、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "地区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "腕を上げると、この地区が痛む。", "explanation": "ここは〈身体の部分〉の意味。地区は地域の範囲を指す語で、体の一部が痛むという文には使わない。"}, {"text": "この地区には挿絵がたくさん載っている。", "explanation": "ここは〈本〉の意味。地区は地域の範囲を指すので、挿絵が載る本の意味では使わない。"}, {"text": "手帳の代わりに、この地区に予定を書いた。", "explanation": "ここは〈紙面〉の意味。地区は範囲を指す語で、予定を書き込む紙面の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38260, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この地区を大雨の日に、避難の指示が出た。", "corrected_sentence": "この地区は大雨の日に、避難の指示が出た。", "error_description": "地区を主題として示すには「は」を使う。目的語の「を」は、出た（自動詞）に合わず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38260, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地区を、春になると観光客でにぎわう。", "corrected_sentence": "この地区は、春になると観光客でにぎわう。", "error_description": "「にぎわう」は目的語を取らない自動詞なので、「を」は誤り。主題の「は」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38261, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「地区に」の「に」。古い寺や店が並んでいる場所を示すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「並ぶ」は目的語を取らないので、「を」は誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示すが、ここは並んでいる場所を示すので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「地区のは」は助詞が続かず、並んでいる場所を示せない。"}], "correct_answer": "に", "explanations": {"に": "「地区に」の「に」。古い寺や店が並んでいる場所を示すので正しい。", "を": "「並ぶ」は目的語を取らないので、「を」は誤り。", "へ": "「へ」は移動の方向を示すが、ここは並んでいる場所を示すので合わない。", "の": "「地区のは」は助詞が続かず、並んでいる場所を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38261, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「地区に住んでいた」の「に」。住む場所を示すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「住む」は「を」を取らず、場所は「に」で示すので誤り。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すが、ここは住んでいた場所を示すので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示すが、「住んでいた」の場所には使わない。"}], "correct_answer": "に", "explanations": {"に": "「地区に住んでいた」の「に」。住む場所を示すので正しい。", "を": "「住む」は「を」を取らず、場所は「に」で示すので誤り。", "と": "「と」は並列や共同を示すが、ここは住んでいた場所を示すので合わない。", "へ": "「へ」は移動の方向を示すが、「住んでいた」の場所には使わない。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38261, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人や建物が集まっている、地図上の区切られた場所。", "primary_collocate": null, "pronunciation": "ちく", "ipa": "tɕiku", "syllable_count": 2, "sentences": [{"text": "駅の北側は商店が多く集まる地区だ。", "target_word": "地区", "complexity_tier": "T3", "furigana": "駅[えき]の北側[きたがわ]は商店[しょうてん]が多[おお]く集[あつ]まる地区[ちく]だ。", "sentence_source": "generated"}, {"text": "この地区には古い寺や小さな店が並んでいて、散歩に向いている。", "target_word": "地区", "complexity_tier": "T3", "furigana": "この地区[ちく]には古[ふる]い寺[てら]や小[ちい]さな店[みせ]が並[なら]んでいて、散歩[さんぽ]に向[む]いている。", "sentence_source": "generated"}, {"text": "私は駅から遠い静かな地区に引っ越した。", "target_word": "地区", "complexity_tier": "T3", "furigana": "私[わたし]は駅[えき]から遠[とお]い静[しず]かな地区[ちく]に引[ひ]っ越[こ]した。", "sentence_source": "generated"}, {"text": "工場が多い地区では、朝から大きなトラックが通る。", "target_word": "地区", "complexity_tier": "T3", "furigana": "工場[こうじょう]が多[おお]い地区[ちく]では、朝[あさ]から大[おお]きなトラックが通[とお]る。", "sentence_source": "generated"}, {"text": "地図で見ると、この地区だけに高いビルが集まっている。", "target_word": "地区", "complexity_tier": "T3", "furigana": "地図[ちず]で見[み]ると、この地区[ちく]だけに高[たか]いビルが集[あつ]まっている。", "sentence_source": "generated"}, {"text": "観光客は、港に近い地区で食事をすることが多い。", "target_word": "地区", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]は、港[みなと]に近[ちか]い地区[ちく]で食事[しょくじ]をすることが多[おお]い。", "sentence_source": "generated"}, {"text": "大学がある地区は、若い人が多くて夜もにぎやかだ。", "target_word": "地区", "complexity_tier": "T3", "furigana": "大学[だいがく]がある地区[ちく]は、若[わか]い人[ひと]が多[おお]くて夜[よる]もにぎやかだ。", "sentence_source": "generated"}, {"text": "昔、この地区には腕のよい職人が多く住んでいた。", "target_word": "地区", "complexity_tier": "T3", "furigana": "昔[むかし]、この地区[ちく]には腕[うで]のよい職人[しょくにん]が多[おお]く住[す]んでいた。", "sentence_source": "generated"}, {"text": "隣の地区へ行くには、橋を渡らなければならない。", "target_word": "地区", "complexity_tier": "T3", "furigana": "隣[となり]の地区[ちく]へ行[い]くには、橋[はし]を渡[わた]らなければならない。", "sentence_source": "generated"}, {"text": "川の東にある地区は、新しい家が次々に建っている。", "target_word": "地区", "complexity_tier": "T3", "furigana": "川[かわ]の東[ひがし]にある地区[ちく]は、新[あたら]しい家[いえ]が次々[つぎつぎ]に建[た]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地区", "label": "基本形"}], "register": "neutral written (plain form)", "sense_fingerprint": "店・家・工場など人や建物が集まる、地図で見て分かるまとまりの場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411dfe7-5f42-41f9-bd10-5cac4844963d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38261, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地区", "is_correct": true, "explanation": "「商店が多く集まる、地図上で区切られた場所」の意味で、文に合う。"}, {"text": "季節", "is_correct": false, "explanation": "「商店が多く集まる季節」は時期を指すので、場所の話をしている文には合わない。"}, {"text": "言語", "is_correct": false, "explanation": "「商店が多く集まる言語」は意味が通らず、場所を表す語ではない。"}, {"text": "料理", "is_correct": false, "explanation": "「商店が多く集まる料理」は食べ物を指すので、文の場所の意味に合わない。"}], "explanations": {"地区": "「商店が多く集まる、地図上で区切られた場所」の意味で、文に合う。", "季節": "「商店が多く集まる季節」は時期を指すので、場所の話をしている文には合わない。", "言語": "「商店が多く集まる言語」は意味が通らず、場所を表す語ではない。", "料理": "「商店が多く集まる料理」は食べ物を指すので、文の場所の意味に合わない。"}, "sentence_index": 0, "correct_answer": "地区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は全部書き終えた地区を、時間内に先生へ提出した。", "explanation": "ここは〈答案〉の意味。答案は提出するものだが、地区は地図上の場所なので提出の対象にならない。"}, {"text": "ベトナムは日本と文化の結びつきが深い地区だ。", "explanation": "ここは〈国〉の意味。国は独立した国家を指すが、地区は町や地域の一部の範囲なので、ベトナムという国には合わない。"}, {"text": "彼女は英語とフランス語の地区を流ちょうに話せる。", "explanation": "ここは〈言語〉の意味。地区は場所を表す語で、流ちょうに話す対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38261, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地区", "is_correct": true, "explanation": "「大学がある、地図上で区切られた場所」の意味で、文に合う。"}, {"text": "小説", "is_correct": false, "explanation": "「大学がある小説」は意味が通らず、場所を表す語ではない。"}, {"text": "天候", "is_correct": false, "explanation": "「大学がある天候」は意味が通らず、場所の話をしている文に合わない。"}, {"text": "病気", "is_correct": false, "explanation": "「大学がある病気」は意味が通らず、場所を表す語ではない。"}], "explanations": {"地区": "「大学がある、地図上で区切られた場所」の意味で、文に合う。", "小説": "「大学がある小説」は意味が通らず、場所を表す語ではない。", "天候": "「大学がある天候」は意味が通らず、場所の話をしている文に合わない。", "病気": "「大学がある病気」は意味が通らず、場所を表す語ではない。"}, "sentence_index": 6, "correct_answer": "地区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合を見終えた後、彼は地区を三行にまとめた。", "explanation": "ここは〈感想〉の意味。感想は三行にまとめるものだが、地区は場所なので、まとめる対象にはならない。"}, {"text": "東京は日本全体の人口の半分が住む地区だ。", "explanation": "ここは〈地域〉の意味。地域は広い範囲にも使えるが、地区は町の一部のような小さな範囲なので、日本の人口の半分が住む東京には合わない。"}, {"text": "この駐車場の地区に、白い線が引かれている。", "explanation": "ここは〈区画〉の意味。駐車場の一台分の枠は区画と言い、地区は町の広い区域なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38261, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は昔からこの地区を住んでいる。", "corrected_sentence": "祖母は昔からこの地区に住んでいる。", "error_description": "「住む」は場所を表す「に」を取る。「を」は誤りで、正しくは「この地区に住んでいる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38261, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は去年、大学の近くの地区で引っ越した。", "corrected_sentence": "姉は去年、大学の近くの地区に引っ越した。", "error_description": "引っ越し先を表すには「に」を使う。「で」は場所での動作を表すので誤り。正しくは「地区に引っ越した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
