INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38262, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が住んでいること。", "primary_collocate": null, "pronunciation": "きょじゅう", "ipa": "kʲodʑɯː", "syllable_count": 3, "sentences": [{"text": "兄は東京に居住しています。", "target_word": "居住", "complexity_tier": "T2", "furigana": "兄[あに]は東京[とうきょう]に居住[きょじゅう]しています。", "sentence_source": "generated"}, {"text": "ここでは居住できません。", "target_word": "居住", "complexity_tier": "T3", "furigana": "ここでは居住[きょじゅう]できません。", "sentence_source": "generated"}, {"text": "家族と居住する場所を決めた。", "target_word": "居住", "complexity_tier": "T3", "furigana": "家族[かぞく]と居住[きょじゅう]する場所[ばしょ]を決[き]めた。", "sentence_source": "generated"}, {"text": "居住する人は多くない。", "target_word": "居住", "complexity_tier": "T3", "furigana": "居住[きょじゅう]する人[ひと]は多[おお]くない。", "sentence_source": "generated"}, {"text": "この地域は居住に適している。", "target_word": "居住", "complexity_tier": "T4", "furigana": "この地域[ちいき]は居住[きょじゅう]に適[てき]している。", "sentence_source": "generated"}, {"text": "居住が禁止されている地域だ。", "target_word": "居住", "complexity_tier": "T4", "furigana": "居住[きょじゅう]が禁止[きんし]されている地域[ちいき]だ。", "sentence_source": "generated"}, {"text": "一年間、海外に居住した。", "target_word": "居住", "complexity_tier": "T3", "furigana": "一年間[いちねんかん]、海外[かいがい]に居住[きょじゅう]した。", "sentence_source": "generated"}, {"text": "居住の許可をもらうために、役所へ行った。", "target_word": "居住", "complexity_tier": "T4", "furigana": "居住[きょじゅう]の許可[きょか]をもらうために、役所[やくしょ]へ行[い]った。", "sentence_source": "generated"}, {"text": "私は今、この町に居住している。", "target_word": "居住", "complexity_tier": "T3", "furigana": "私[わたし]は今[いま]、この町[まち]に居住[きょじゅう]している。", "sentence_source": "generated"}, {"text": "居住して三年がたちます。", "target_word": "居住", "complexity_tier": "T3", "furigana": "居住[きょじゅう]して三年[さんねん]がたちます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "居住する", "label": "活用"}, {"form": "居住者", "label": "派生"}, {"form": "居住地", "label": "派生"}, {"form": "居住区", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 人がある場所に住んでいること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a6e59f-ea65-43a2-8a55-7ec9fc7d85ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38262, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "居住", "is_correct": true, "explanation": "「東京に居住しています」は、住んでいるという意味で自然に合う。"}, {"text": "故障", "is_correct": false, "explanation": "形は合うが、兄が東京に故障するという意味は合わない。"}, {"text": "沸騰", "is_correct": false, "explanation": "形は合うが、兄が東京に沸騰するという意味は合わない。"}, {"text": "逮捕", "is_correct": false, "explanation": "形は合うが、兄が東京に逮捕するという意味は合わない。"}], "explanations": {"居住": "「東京に居住しています」は、住んでいるという意味で自然に合う。", "故障": "形は合うが、兄が東京に故障するという意味は合わない。", "沸騰": "形は合うが、兄が東京に沸騰するという意味は合わない。", "逮捕": "形は合うが、兄が東京に逮捕するという意味は合わない。"}, "sentence_index": 0, "correct_answer": "居住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、居住を磨いてから出かける。", "explanation": "「居住」は磨く物ではなく、住むことを表す語なので誤り。"}, {"text": "居住が大声で笑いながら歩いてきた。", "explanation": "「居住」は人や生き物ではないので、笑う主語として使うのは誤り。"}, {"text": "机の上に居住を置いて、部屋を出た。", "explanation": "「居住」は物ではなく状態を表すので、置く対象として使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38262, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "居住", "is_correct": true, "explanation": "「海外に居住した」は、住んだという意味で自然に合う。"}, {"text": "沸騰", "is_correct": false, "explanation": "形は合うが、一年間海外に沸騰するという意味は合わない。"}, {"text": "故障", "is_correct": false, "explanation": "形は合うが、一年間海外に故障するという意味は合わない。"}, {"text": "爆発", "is_correct": false, "explanation": "形は合うが、一年間海外に爆発するという意味は合わない。"}], "explanations": {"居住": "「海外に居住した」は、住んだという意味で自然に合う。", "沸騰": "形は合うが、一年間海外に沸騰するという意味は合わない。", "故障": "形は合うが、一年間海外に故障するという意味は合わない。", "爆発": "形は合うが、一年間海外に爆発するという意味は合わない。"}, "sentence_index": 6, "correct_answer": "居住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "居住をたたんで、かばんにしまった。", "explanation": "「居住」は折りたためる物ではなく、住むことを表す語なので誤り。"}, {"text": "居住が空から降ってきて、道が濡れた。", "explanation": "「居住」は降る物ではなく状態を表すので、主語として使うのは誤り。"}, {"text": "弟は居住を読んで、宿題を終えた。", "explanation": "「居住」は読む本や文章ではないので、読む対象として使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38262, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "叔父は九州を居住している。", "corrected_sentence": "叔父は九州に居住している。", "error_description": "居住する場所を示す助詞は「を」ではなく「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38262, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は山の近くを居住して五年になる。", "corrected_sentence": "彼は山の近くに居住して五年になる。", "error_description": "居住する場所を示す助詞は「を」ではなく「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38263, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "居住する場所を示す「に」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「京都を居住している」は場所の示し方として誤り。"}, {"text": "と", "is_correct": false, "explanation": "「京都と居住している」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「京都の居住している」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "居住する場所を示す「に」が合う。", "を": "「京都を居住している」は場所の示し方として誤り。", "と": "「京都と居住している」は文として成り立たない。", "の": "「京都の居住している」は文として成り立たない。"}, "error_tags": {"を": "object_marker_misuse", "と": "companion_misuse", "の": "possessive_misuse"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退去", "is_correct": true, "explanation": "居住は住むこと、退去は住まいを出ることで対になる。"}, {"text": "在住", "is_correct": false, "explanation": "在住は住んでいることで、居住に近く対義ではない。"}, {"text": "入居", "is_correct": false, "explanation": "入居は住み始めることで、対義ではない。"}, {"text": "定住", "is_correct": false, "explanation": "定住は一か所に住み続けることで、対義ではない。"}], "correct_answer": "退去", "explanations": {"退去": "居住は住むこと、退去は住まいを出ることで対になる。", "在住": "在住は住んでいることで、居住に近く対義ではない。", "入居": "入居は住み始めることで、対義ではない。", "定住": "定住は一か所に住み続けることで、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38263, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退去", "is_correct": true, "explanation": "居住は住むこと、退去は住まいを出ることで対になる。"}, {"text": "滞在", "is_correct": false, "explanation": "滞在は一時的にとどまることで、対義ではない。"}, {"text": "永住", "is_correct": false, "explanation": "永住はずっと住むことで、対義ではない。"}, {"text": "同居", "is_correct": false, "explanation": "同居は一緒に住むことで、対義ではない。"}], "correct_answer": "退去", "explanations": {"退去": "居住は住むこと、退去は住まいを出ることで対になる。", "滞在": "滞在は一時的にとどまることで、対義ではない。", "永住": "永住はずっと住むことで、対義ではない。", "同居": "同居は一緒に住むことで、対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38263, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある場所に住んでいること。", "primary_collocate": null, "pronunciation": "きょじゅう", "ipa": "kʲodʑɯː", "syllable_count": 3, "sentences": [{"text": "ミニマリストの思想に基づき、必要な要素だけを残すことで、居住者はより穏やかな日常を送ることができます。", "target_word": "居住", "complexity_tier": "T6", "furigana": "ミニマリストの思想[しそう]に基[もと]づき、必要[ひつよう]な要素[ようそ]だけを残[のこ]すことで、居住者[きょじゅうしゃ]はより穏[おだ]やかな日常[にちじょう]を送[おく]ることができます。", "sentence_source": "mined"}, {"text": "祖父は京都に居住している。", "target_word": "居住", "complexity_tier": "T3", "furigana": "祖父[そふ]は京都[きょうと]に居住[きょじゅう]している。", "sentence_source": "generated"}, {"text": "居住の自由は憲法で守られている。", "target_word": "居住", "complexity_tier": "T4", "furigana": "居住[きょじゅう]の自由[じゆう]は憲法[けんぽう]で守[まも]られている。", "sentence_source": "generated"}, {"text": "この建物には誰も居住していません。", "target_word": "居住", "complexity_tier": "T3", "furigana": "この建物[たてもの]には誰[だれ]も居住[きょじゅう]していません。", "sentence_source": "generated"}, {"text": "居住を始めたら、届けを出してください。", "target_word": "居住", "complexity_tier": "T4", "furigana": "居住[きょじゅう]を始[はじ]めたら、届[とど]けを出[だ]してください。", "sentence_source": "generated"}, {"text": "外国に居住して十年になる。", "target_word": "居住", "complexity_tier": "T3", "furigana": "外国[がいこく]に居住[きょじゅう]して十年[じゅうねん]になる。", "sentence_source": "generated"}, {"text": "ここなら安心して居住できる。", "target_word": "居住", "complexity_tier": "T3", "furigana": "ここなら安心[あんしん]して居住[きょじゅう]できる。", "sentence_source": "generated"}, {"text": "居住が認められる期間は短い。", "target_word": "居住", "complexity_tier": "T4", "furigana": "居住[きょじゅう]が認[みと]められる期間[きかん]は短[みじか]い。", "sentence_source": "generated"}, {"text": "山の近くに居住する人が増えた。", "target_word": "居住", "complexity_tier": "T3", "furigana": "山[やま]の近[ちか]くに居住[きょじゅう]する人[ひと]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "居住の条件を教えてください。", "target_word": "居住", "complexity_tier": "T3", "furigana": "居住[きょじゅう]の条件[じょうけん]を教[おし]えてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "居住する", "label": "活用"}, {"form": "居住者", "label": "派生"}, {"form": "居住地", "label": "派生"}, {"form": "居住区", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | ある場所に住んでいる状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a6e59f-ea65-43a2-8a55-7ec9fc7d85ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38263, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "居住", "is_correct": true, "explanation": "「居住者」で、住んでいる人という意味が文脈に合う。"}, {"text": "死亡", "is_correct": false, "explanation": "形は合うが、死亡者が穏やかな日常を送るという意味は合わない。"}, {"text": "欠席", "is_correct": false, "explanation": "形は合うが、欠席者が穏やかな日常を送るという意味は合わない。"}, {"text": "逮捕", "is_correct": false, "explanation": "形は合うが、逮捕者が穏やかな日常を送るという意味は合わない。"}], "explanations": {"居住": "「居住者」で、住んでいる人という意味が文脈に合う。", "死亡": "形は合うが、死亡者が穏やかな日常を送るという意味は合わない。", "欠席": "形は合うが、欠席者が穏やかな日常を送るという意味は合わない。", "逮捕": "形は合うが、逮捕者が穏やかな日常を送るという意味は合わない。"}, "sentence_index": 0, "correct_answer": "居住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夜、友だちと居住を食べに行った。", "explanation": "「居住」は住むことを表す語で、食べ物として使うのは誤り。"}, {"text": "彼は居住を急いで、駅まで走った。", "explanation": "「居住」は急ぐ対象ではなく、住んでいる状態を表すので誤り。"}, {"text": "雨で居住が濡れたので、傘を差した。", "explanation": "「居住」は濡れる物ではなく、状態を表す語なので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38263, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "居住", "is_correct": true, "explanation": "「安心して居住できる」は、住めるという意味で自然に合う。"}, {"text": "沸騰", "is_correct": false, "explanation": "形は合うが、安心して沸騰できるという意味は合わない。"}, {"text": "故障", "is_correct": false, "explanation": "形は合うが、安心して故障できるという意味は合わない。"}, {"text": "爆発", "is_correct": false, "explanation": "形は合うが、安心して爆発できるという意味は合わない。"}], "explanations": {"居住": "「安心して居住できる」は、住めるという意味で自然に合う。", "沸騰": "形は合うが、安心して沸騰できるという意味は合わない。", "故障": "形は合うが、安心して故障できるという意味は合わない。", "爆発": "形は合うが、安心して爆発できるという意味は合わない。"}, "sentence_index": 6, "correct_answer": "居住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "居住を飲んだら、体が温まった。", "explanation": "「居住」は飲み物ではなく、住むことを表す語なので誤り。"}, {"text": "山の上を居住が速く走っていた。", "explanation": "「居住」は走る主体ではないので、主語として使うのは誤り。"}, {"text": "居住の色が赤くて、とてもきれいだ。", "explanation": "「居住」は色を持つ物ではなく、状態を表すので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
