INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38264, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不満", "is_correct": true, "explanation": "「満足」の反対語で、望みがかなわず、足りないと感じる気持ちを表す。"}, {"text": "感動", "is_correct": false, "explanation": "心を強く動かされる気持ちで、満足の反対語ではない。"}, {"text": "安心", "is_correct": false, "explanation": "不安がない気持ちで、満足と似た場面で使うが、反対語ではない。"}, {"text": "疑問", "is_correct": false, "explanation": "わからず問いが残る状態で、満足の反対語とはされない。"}], "correct_answer": "不満", "explanations": {"不満": "「満足」の反対語で、望みがかなわず、足りないと感じる気持ちを表す。", "感動": "心を強く動かされる気持ちで、満足の反対語ではない。", "安心": "不安がない気持ちで、満足と似た場面で使うが、反対語ではない。", "疑問": "わからず問いが残る状態で、満足の反対語とはされない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38264, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「成績に満足」の「に」。満足する対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「満足」は目的語に「を」を取らないので、「成績を満足せず」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では「成績と満足せず」となり、満足の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「成績へ満足」となり、満足する対象を表せない。"}], "correct_answer": "に", "explanations": {"に": "「成績に満足」の「に」。満足する対象を示す。", "を": "「満足」は目的語に「を」を取らないので、「成績を満足せず」は成り立たない。", "と": "並列の「と」では「成績と満足せず」となり、満足の対象を示せない。", "へ": "方向の「へ」では「成績へ満足」となり、満足する対象を表せない。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不満", "is_correct": true, "explanation": "「満足」の反対語で、望みがかなわず、足りないと感じる気持ちを表す。"}, {"text": "感謝", "is_correct": false, "explanation": "ありがたいと思う気持ちで、満足の反対語ではない。"}, {"text": "緊張", "is_correct": false, "explanation": "体や心が張りつめた状態で、満足の反対語ではない。"}, {"text": "驚き", "is_correct": false, "explanation": "予想外のことに心が動く気持ちで、満足の反対語ではない。"}], "correct_answer": "不満", "explanations": {"不満": "「満足」の反対語で、望みがかなわず、足りないと感じる気持ちを表す。", "感謝": "ありがたいと思う気持ちで、満足の反対語ではない。", "緊張": "体や心が張りつめた状態で、満足の反対語ではない。", "驚き": "予想外のことに心が動く気持ちで、満足の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38264, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の気持ちが足りていること。", "primary_collocate": null, "pronunciation": "まんぞく", "ipa": "maɴdzoku", "syllable_count": 4, "sentences": [{"text": "昼ご飯をたくさん食べて、すっかり満足した。", "target_word": "満足", "complexity_tier": "T2", "furigana": "昼[ひる]ご飯[はん]をたくさん食[た]べて、すっかり満足[まんぞく]した。", "sentence_source": "generated"}, {"text": "彼女は小さな部屋でも満足して暮らしている。", "target_word": "満足", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は小[ちい]さな部屋[へや]でも満足[まんぞく]して暮[く]らしている。", "sentence_source": "generated"}, {"text": "子どもは好きな絵本を読んでもらい、満足した顔で眠った。", "target_word": "満足", "complexity_tier": "T3", "furigana": "子[こ]どもは好[す]きな絵本[えほん]を読[よ]んでもらい、満足[まんぞく]した顔[かお]で眠[ねむ]った。", "sentence_source": "generated"}, {"text": "今の生活に満足しているから、引っ越す気はない。", "target_word": "満足", "complexity_tier": "T3", "furigana": "今[いま]の生活[せいかつ]に満足[まんぞく]しているから、引[ひ]っ越[こ]す気[き]はない。", "sentence_source": "generated"}, {"text": "一度勝っただけで満足してはいけない。", "target_word": "満足", "complexity_tier": "T3", "furigana": "一度[いちど]勝[か]っただけで満足[まんぞく]してはいけない。", "sentence_source": "generated"}, {"text": "祖父は庭の花を見るだけで満足そうだった。", "target_word": "満足", "complexity_tier": "T3", "furigana": "祖父[そふ]は庭[にわ]の花[はな]を見[み]るだけで満足[まんぞく]そうだった。", "sentence_source": "generated"}, {"text": "甘いものを少し食べたら、それで満足した。", "target_word": "満足", "complexity_tier": "T3", "furigana": "甘[あま]いものを少[すこ]し食[た]べたら、それで満足[まんぞく]した。", "sentence_source": "generated"}, {"text": "彼は今の成績に満足せず、毎日遅くまで練習している。", "target_word": "満足", "complexity_tier": "T3", "furigana": "彼[かれ]は今[いま]の成績[せいせき]に満足[まんぞく]せず、毎日[まいにち]遅[おそ]くまで練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "私は毎朝コーヒーを飲めば満足だ。", "target_word": "満足", "complexity_tier": "T2", "furigana": "私[わたし]は毎朝[まいあさ]コーヒーを飲[の]めば満足[まんぞく]だ。", "sentence_source": "generated"}, {"text": "好きな歌を歌い終えて、心から満足した。", "target_word": "満足", "complexity_tier": "T3", "furigana": "好[す]きな歌[うた]を歌[うた]い終[お]えて、心[こころ]から満足[まんぞく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "満足する", "label": "辞書形"}, {"form": "満足した", "label": "過去形"}, {"form": "満足して", "label": "て形"}, {"form": "満足しない", "label": "否定形"}], "register": "neutral written (plain form)", "sense_fingerprint": "これで十分だと自分の心が感じて、それ以上を求めない気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411dfe7-5f42-41f9-bd10-5cac4844963d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38264, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "満足", "is_correct": true, "explanation": "「すっかり満足した」は、食べて満ち足りた気持ちを表すので文に合う。"}, {"text": "停電", "is_correct": false, "explanation": "「すっかり停電した」は食後の気持ちとして意味をなさず、文に合わない。"}, {"text": "寝坊", "is_correct": false, "explanation": "「すっかり寝坊した」は食事の内容と結びつかず、意味が通らない。"}, {"text": "遅刻", "is_correct": false, "explanation": "「すっかり遅刻した」は食事と関係がなく、文の意味に合わない。"}], "explanations": {"満足": "「すっかり満足した」は、食べて満ち足りた気持ちを表すので文に合う。", "停電": "「すっかり停電した」は食後の気持ちとして意味をなさず、文に合わない。", "寝坊": "「すっかり寝坊した」は食事の内容と結びつかず、意味が通らない。", "遅刻": "「すっかり遅刻した」は食事と関係がなく、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "満足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ようやく宿題が満足した。", "explanation": "ここは〈完了〉の意味。宿題は気持ちを持たないので、満足の対象にならない。"}, {"text": "必要な物資が満足しているので、注文はいらない。", "explanation": "ここは〈充足〉の意味。物資は気持ちを持たないので、足りていることを表す語は充足を使う。"}, {"text": "壊れた冷蔵庫が、ついに満足した。", "explanation": "ここは〈修理〉の意味。冷蔵庫は気持ちを持たないので、満足の主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38264, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "満足", "is_correct": true, "explanation": "「それで満足した」は、少しの甘いものでよいと感じた気持ちを表すので文に合う。"}, {"text": "急用", "is_correct": false, "explanation": "「それで急用した」は意味をなさない。"}, {"text": "方針", "is_correct": false, "explanation": "「それで方針した」は動詞として不自然で、文に合わない。"}, {"text": "感情", "is_correct": false, "explanation": "「それで感情した」は意味をなさず、気持ちを表す動詞としても使えない。"}], "explanations": {"満足": "「それで満足した」は、少しの甘いものでよいと感じた気持ちを表すので文に合う。", "急用": "「それで急用した」は意味をなさない。", "方針": "「それで方針した」は動詞として不自然で、文に合わない。", "感情": "「それで感情した」は意味をなさず、気持ちを表す動詞としても使えない。"}, "sentence_index": 6, "correct_answer": "満足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "目標の合格が満足して、みんなで喜んだ。", "explanation": "ここは〈達成〉の意味。合格は満足する主体ではなく、目標を達成するものなので合わない。"}, {"text": "病気が満足して、医者も喜んだ。", "explanation": "ここは〈完治〉の意味。病気は気持ちを持たないので、満足は合わない。"}, {"text": "ぐっすり満足した。", "explanation": "ここは〈熟睡〉の意味。眠りの深さを表す語で、満足の気持ちを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
