INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38265, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "自分の望みや条件が十分にかなえられて、不満がない状態。", "primary_collocate": null, "pronunciation": "まんぞく", "ipa": "maɴdzoku", "syllable_count": 4, "sentences": [{"text": "この店のサービスに満足したお客さんは、また来てくれる。", "target_word": "満足", "complexity_tier": "T3", "furigana": "この店[みせ]のサービスに満足[まんぞく]したお客[きゃく]さんは、また来[き]てくれる。", "sentence_source": "generated"}, {"text": "希望どおりの部屋が見つからず、満足できないまま探すのをやめた。", "target_word": "満足", "complexity_tier": "T3", "furigana": "希望[きぼう]どおりの部屋[へや]が見[み]つからず、満足[まんぞく]できないまま探[さが]すのをやめた。", "sentence_source": "generated"}, {"text": "新しいスマホの性能に満足している。", "target_word": "満足", "complexity_tier": "T3", "furigana": "新[あたら]しいスマホの性能[せいのう]に満足[まんぞく]している。", "sentence_source": "generated"}, {"text": "客の要求を満足させるのは簡単ではない。", "target_word": "満足", "complexity_tier": "T3", "furigana": "客[きゃく]の要求[ようきゅう]を満足[まんぞく]させるのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "検査の結果に満足できなかったので、もう一度調べてもらった。", "target_word": "満足", "complexity_tier": "T3", "furigana": "検査[けんさ]の結果[けっか]に満足[まんぞく]できなかったので、もう一度[いちど]調[しら]べてもらった。", "sentence_source": "generated"}, {"text": "品質に満足しなければ、代金は返します。", "target_word": "満足", "complexity_tier": "T3", "furigana": "品質[ひんしつ]に満足[まんぞく]しなければ、代金[だいきん]は返[かえ]します。", "sentence_source": "generated"}, {"text": "全員が満足する答えを出すのは難しい。", "target_word": "満足", "complexity_tier": "T3", "furigana": "全員[ぜんいん]が満足[まんぞく]する答[こた]えを出[だ]すのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "アンケートでは、八割の人が料金に満足していると答えた。", "target_word": "満足", "complexity_tier": "T4", "furigana": "アンケートでは、八割[はちわり]の人[ひと]が料金[りょうきん]に満足[まんぞく]していると答[こた]えた。", "sentence_source": "generated"}, {"text": "説明を聞いても満足できず、私は質問を続けた。", "target_word": "満足", "complexity_tier": "T3", "furigana": "説明[せつめい]を聞[き]いても満足[まんぞく]できず、私[わたし]は質問[しつもん]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "旅行の内容にとても満足して、友達にも勧めた。", "target_word": "満足", "complexity_tier": "T3", "furigana": "旅行[りょこう]の内容[ないよう]にとても満足[まんぞく]して、友達[ともだち]にも勧[すす]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "満足する", "label": "辞書形"}, {"form": "満足した", "label": "過去形"}, {"form": "満足できない", "label": "可能否定形"}, {"form": "満足させる", "label": "使役形"}], "register": "neutral written (plain form)", "sense_fingerprint": "希望・要求・基準が十分に満たされ、文句や不満が残らないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411dfe7-5f42-41f9-bd10-5cac4844963d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38265, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "満足", "is_correct": true, "explanation": "「サービスに満足したお客さん」は、サービスが期待を満たしたという意味で文に合う。"}, {"text": "停電", "is_correct": false, "explanation": "「サービスに停電した」は意味をなさず、文に合わない。"}, {"text": "遅刻", "is_correct": false, "explanation": "「サービスに遅刻した」は意味が通らず、文に合わない。"}, {"text": "疲労", "is_correct": false, "explanation": "「サービスに疲労した」は意味が通らず、文に合わない。"}], "explanations": {"満足": "「サービスに満足したお客さん」は、サービスが期待を満たしたという意味で文に合う。", "停電": "「サービスに停電した」は意味をなさず、文に合わない。", "遅刻": "「サービスに遅刻した」は意味が通らず、文に合わない。", "疲労": "「サービスに疲労した」は意味が通らず、文に合わない。"}, "sentence_index": 0, "correct_answer": "満足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工事が予定どおりに満足した。", "explanation": "ここは〈完了〉の意味。工事は気持ちを持たないので、満足の主語にならない。"}, {"text": "在庫が満足しているので、注文はいらない。", "explanation": "ここは〈充足〉の意味。在庫が足りていることは充足を使い、満足は人の気持ちに使う。"}, {"text": "雨漏りがようやく満足した。", "explanation": "ここは〈止まる〉の意味。雨漏りは気持ちを持たないので、満足は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38265, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "満足", "is_correct": true, "explanation": "「全員が満足する答え」は、全員の要求を満たす答えという意味で文に合う。"}, {"text": "宣言", "is_correct": false, "explanation": "「宣言する答え」は意味が通らず、文に合わない。"}, {"text": "反省", "is_correct": false, "explanation": "反省は自分を省みる行為で、答えを修飾するのは不自然で合わない。"}, {"text": "解散", "is_correct": false, "explanation": "「解散する答え」は意味をなさず、文に合わない。"}], "explanations": {"満足": "「全員が満足する答え」は、全員の要求を満たす答えという意味で文に合う。", "宣言": "「宣言する答え」は意味が通らず、文に合わない。", "反省": "反省は自分を省みる行為で、答えを修飾するのは不自然で合わない。", "解散": "「解散する答え」は意味をなさず、文に合わない。"}, "sentence_index": 6, "correct_answer": "満足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "目標の満足で、部員が喜んだ。", "explanation": "ここは〈達成〉の意味。目標は満足するものではなく、達成するものなので合わない。"}, {"text": "病気が満足して、医者も喜んだ。", "explanation": "ここは〈完治〉の意味。病気は気持ちを持たないので、満足は合わない。"}, {"text": "ついに荷物が届いて、部屋の掃除が満足した。", "explanation": "ここは〈完了〉の意味。掃除は気持ちを持たないので、満足の主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38265, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいパソコンの性能を満足している。", "corrected_sentence": "新しいパソコンの性能に満足している。", "error_description": "「満足している」は「に」を取る。「を」は誤りで、正しくは「性能に満足している」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38265, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "どの店にも満足できないず、結局この店に決めた。", "corrected_sentence": "どの店にも満足できず、結局この店に決めた。", "error_description": "「満足できず」が正しい。「満足できないず」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38266, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減少", "is_correct": true, "explanation": "数量や程度が増えることの対義語で、この文脈の「水量が増大する」の反対の意味にあたる。"}, {"text": "維持", "is_correct": false, "explanation": "同じ状態を保つ意味で、増減の対義語ではない。"}, {"text": "安定", "is_correct": false, "explanation": "変動が少ない状態を指し、増大の対義語として辞書に並ぶ語ではない。"}, {"text": "固定", "is_correct": false, "explanation": "動かないように定めることで、数量の増減を表す語ではない。"}], "correct_answer": "減少", "explanations": {"減少": "数量や程度が増えることの対義語で、この文脈の「水量が増大する」の反対の意味にあたる。", "維持": "同じ状態を保つ意味で、増減の対義語ではない。", "安定": "変動が少ない状態を指し、増大の対義語として辞書に並ぶ語ではない。", "固定": "動かないように定めることで、数量の増減を表す語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38266, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減少", "is_correct": true, "explanation": "数量や程度が増えることの対義語で、「学生の負担が増大しない」の反対の意味にあたる。"}, {"text": "増加", "is_correct": false, "explanation": "増大の類義語にあたり、対義語ではない。"}, {"text": "上昇", "is_correct": false, "explanation": "数値や水準が上がることで、増大の類義語にあたり、対義語ではない。"}, {"text": "継続", "is_correct": false, "explanation": "続けることを指し、増減の対義語ではない。"}], "correct_answer": "減少", "explanations": {"減少": "数量や程度が増えることの対義語で、「学生の負担が増大しない」の反対の意味にあたる。", "増加": "増大の類義語にあたり、対義語ではない。", "上昇": "数値や水準が上がることで、増大の類義語にあたり、対義語ではない。", "継続": "続けることを指し、増減の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38266, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "大きくなること。", "primary_collocate": null, "pronunciation": "ぞうだい", "ipa": "dzoːdai", "syllable_count": 4, "sentences": [{"text": "人口の増大に合わせて、市は新しい学校を建てることにした。", "target_word": "増大", "complexity_tier": "T3", "furigana": "人口[じんこう]の増大[ぞうだい]に合[あ]わせて、市[し]は新[あたら]しい学校[がっこう]を建[た]てることにした。", "sentence_source": "generated"}, {"text": "仕事の量が増大したので、新しい人を二人入れた。", "target_word": "増大", "complexity_tier": "T3", "furigana": "仕事[しごと]の量[りょう]が増大[ぞうだい]したので、新[あたら]しい人[ひと]を二人[ふたり]入[い]れた。", "sentence_source": "generated"}, {"text": "夏になると、ごみの量が増大して、回収が間に合わなくなる。", "target_word": "増大", "complexity_tier": "T3", "furigana": "夏[なつ]になると、ごみの量[りょう]が増大[ぞうだい]して、回収[かいしゅう]が間[ま]に合[あ]わなくなる。", "sentence_source": "generated"}, {"text": "台風の影響で川の水量が増大し、橋の近くは通れなくなった。", "target_word": "増大", "complexity_tier": "T3", "furigana": "台風[たいふう]の影響[えいきょう]で川[かわ]の水量[すいりょう]が増大[ぞうだい]し、橋[はし]の近[ちか]くは通[とお]れなくなった。", "sentence_source": "generated"}, {"text": "輸入の増大は、国内の農家にとって大きな問題だ。", "target_word": "増大", "complexity_tier": "T3", "furigana": "輸入[ゆにゅう]の増大[ぞうだい]は、国内[こくない]の農家[のうか]にとって大[おお]きな問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "夏休みに入ると、観光客の数が増大した。", "target_word": "増大", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに入[はい]ると、観光客[かんこうきゃく]の数[かず]が増大[ぞうだい]した。", "sentence_source": "generated"}, {"text": "会社の利益が増大したため、社員にボーナスが出た。", "target_word": "増大", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の利益[りえき]が増大[ぞうだい]したため、社員[しゃいん]にボーナスが出[で]た。", "sentence_source": "generated"}, {"text": "費用が増大して予算を超えたので、計画を見直すことになった。", "target_word": "増大", "complexity_tier": "T3", "furigana": "費用[ひよう]が増大[ぞうだい]して予算[よさん]を超[こ]えたので、計画[けいかく]を見直[みなお]すことになった。", "sentence_source": "generated"}, {"text": "子どもの数が減る一方で、お年寄りの医療費は増大している。", "target_word": "増大", "complexity_tier": "T3", "furigana": "子[こ]どもの数[かず]が減[へ]る一方[いっぽう]で、お年寄[としよ]りの医療費[いりょうひ]は増大[ぞうだい]している。", "sentence_source": "generated"}, {"text": "学生の負担が増大しないよう、先生は宿題の量を調整した。", "target_word": "増大", "complexity_tier": "T3", "furigana": "学生[がくせい]の負担[ふたん]が増大[ぞうだい]しないよう、先生[せんせい]は宿題[しゅくだい]の量[りょう]を調整[ちょうせい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "増大", "label": "基本形"}, {"form": "増大する", "label": "する形"}, {"form": "増大した", "label": "た形"}, {"form": "増大して", "label": "て形"}, {"form": "増大している", "label": "ている形"}], "register": "formal", "sense_fingerprint": "数や量、規模などがふえて大きくなること(サ変名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039fd23c-3eee-46a3-96b4-4e59688a4301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38266, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "増大", "is_correct": true, "explanation": "「人口の増大」で人口が増えること、「合わせて」で計画の前提になることが通り、文が成り立つ。"}, {"text": "修理", "is_correct": false, "explanation": "「人口の修理」は意味をなさない。人口は直す対象にならない。"}, {"text": "挑戦", "is_correct": false, "explanation": "「人口の挑戦」は組み合わせとして不自然で、文の中で意味が通らない。"}, {"text": "注意", "is_correct": false, "explanation": "「人口の注意に合わせて」は文脈に合わず、人口を対象にした注意という意味にもならない。"}], "explanations": {"増大": "「人口の増大」で人口が増えること、「合わせて」で計画の前提になることが通り、文が成り立つ。", "修理": "「人口の修理」は意味をなさない。人口は直す対象にならない。", "挑戦": "「人口の挑戦」は組み合わせとして不自然で、文の中で意味が通らない。", "注意": "「人口の注意に合わせて」は文脈に合わず、人口を対象にした注意という意味にもならない。"}, "sentence_index": 0, "correct_answer": "増大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "画面を増大して、小さい文字を読んだ。", "explanation": "ここは〈拡大〉の意味。増大は数量や程度が増えることで、画面の表示を大きくする場合には使わない。"}, {"text": "家族が増えたので、家を増大した。", "explanation": "ここは〈増築〉の意味。建物を広げることは増築と言い、増大は数量や程度に使う。"}, {"text": "店員さんに、ご飯を増大してもらった。", "explanation": "ここは〈増量〉の意味。食べ物の分量を増やすときは増量と言い、増大とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38266, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "増大", "is_correct": true, "explanation": "利益が大きくなったことを表し、「増大したため、ボーナスが出た」で文が通る。"}, {"text": "発表", "is_correct": false, "explanation": "「利益が発表した」は主語と述語が合わず、意味をなさない。"}, {"text": "担当", "is_correct": false, "explanation": "「利益が担当した」は意味が成り立たない。利益は担当する主体にならない。"}, {"text": "挨拶", "is_correct": false, "explanation": "「利益が挨拶した」は文脈に合わず、利益を主語にした意味が成り立たない。"}], "explanations": {"増大": "利益が大きくなったことを表し、「増大したため、ボーナスが出た」で文が通る。", "発表": "「利益が発表した」は主語と述語が合わず、意味をなさない。", "担当": "「利益が担当した」は意味が成り立たない。利益は担当する主体にならない。", "挨拶": "「利益が挨拶した」は文脈に合わず、利益を主語にした意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "増大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風船に息を入れて、風船を増大した。", "explanation": "ここは〈膨らませる〉の意味。空気を入れて物を大きくふくらませるのは膨らませると言い、増大とは言わない。"}, {"text": "細菌が増大して、食品が傷んだ。", "explanation": "ここは〈増殖〉の意味。生物が殖えることには増殖を使い、増大は言わない。"}, {"text": "工場の設備を増大して、生産を広げた。", "explanation": "ここは〈増設〉の意味。機械や設備を付け足すことは増設と言い、増大は言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38266, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ごみの量が増大くなったので、回収を増やした。", "corrected_sentence": "ごみの量が増大したので、回収を増やした。", "error_description": "誤りの箇所は「増大くなった」。増大はサ変名詞なので、正しくは「増大した」。形容詞の活用（大きくなった）と混同した誤りで、誤った形は「増大くなった」、正しい形は「増大した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38266, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "利益が増大ったので、社員にボーナスを出した。", "corrected_sentence": "利益が増大したので、社員にボーナスを出した。", "error_description": "誤りの箇所は「増大った」。増大はサ変動詞なので過去形は「増大した」で、「増大った」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38267, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減少", "is_correct": true, "explanation": "程度が大きくなることの対義語で、「影響力が増大した」の反対の意味にあたる。"}, {"text": "維持", "is_correct": false, "explanation": "同じ状態を保つ意味で、増減の対義語ではない。"}, {"text": "安定", "is_correct": false, "explanation": "変動が少ない状態を指し、増大の対義語として並ぶ語ではない。"}, {"text": "固定", "is_correct": false, "explanation": "動かないように定めることで、程度の増減を表す語ではない。"}], "correct_answer": "減少", "explanations": {"減少": "程度が大きくなることの対義語で、「影響力が増大した」の反対の意味にあたる。", "維持": "同じ状態を保つ意味で、増減の対義語ではない。", "安定": "変動が少ない状態を指し、増大の対義語として並ぶ語ではない。", "固定": "動かないように定めることで、程度の増減を表す語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
