INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38267, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の量や程度が、前よりもっと大きくなること。", "primary_collocate": null, "pronunciation": "ぞうだい", "ipa": "dzoːdai", "syllable_count": 4, "sentences": [{"text": "地震のあと、町の人たちの不安は日ごとに増大していった。", "target_word": "増大", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、町[まち]の人[ひと]たちの不安[ふあん]は日[ひ]ごとに増大[ぞうだい]していった。", "sentence_source": "generated"}, {"text": "彼の影響力は、この数年で急激に増大した。", "target_word": "増大", "complexity_tier": "T3", "furigana": "彼[かれ]の影響力[えいきょうりょく]は、この数年[すうねん]で急激[きゅうげき]に増大[ぞうだい]した。", "sentence_source": "generated"}, {"text": "説明が足りず、客の不満が増大する一方だった。", "target_word": "増大", "complexity_tier": "T3", "furigana": "説明[せつめい]が足[た]りず、客[きゃく]の不満[ふまん]が増大[ぞうだい]する一方[いっぽう]だった。", "sentence_source": "generated"}, {"text": "気温の上昇とともに、熱中症の危険が増大する。", "target_word": "増大", "complexity_tier": "T3", "furigana": "気温[きおん]の上昇[じょうしょう]とともに、熱中症[ねっちゅうしょう]の危険[きけん]が増大[ぞうだい]する。", "sentence_source": "generated"}, {"text": "工事が長引き、費用の増大が心配されている。", "target_word": "増大", "complexity_tier": "T3", "furigana": "工事[こうじ]が長引[ながび]き、費用[ひよう]の増大[ぞうだい]が心配[しんぱい]されている。", "sentence_source": "generated"}, {"text": "国の借金の増大を止めるために、税金の使い方を見直す。", "target_word": "増大", "complexity_tier": "T3", "furigana": "国[くに]の借金[しゃっきん]の増大[ぞうだい]を止[と]めるために、税金[ぜいきん]の使[つか]い方[かた]を見直[みなお]す。", "sentence_source": "generated"}, {"text": "雨の日は道が混み、事故の危険性が増大するので、早めに出発しよう。", "target_word": "増大", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は道[みち]が混[こ]み、事故[じこ]の危険性[きけんせい]が増大[ぞうだい]するので、早[はや]めに出発[しゅっぱつ]しよう。", "sentence_source": "generated"}, {"text": "試合に勝つたびに、チームへの期待が増大した。", "target_word": "増大", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]つたびに、チームへの期待[きたい]が増大[ぞうだい]した。", "sentence_source": "generated"}, {"text": "景気が悪くなると、失業者が増大する。", "target_word": "増大", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]くなると、失業者[しつぎょうしゃ]が増大[ぞうだい]する。", "sentence_source": "generated"}, {"text": "客の不満が増大するにつれ、店員への苦情も多くなっていった。", "target_word": "増大", "complexity_tier": "T3", "furigana": "客[きゃく]の不満[ふまん]が増大[ぞうだい]するにつれ、店員[てんいん]への苦情[くじょう]も多[おお]くなっていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "増大", "label": "基本形"}, {"form": "増大する", "label": "する形"}, {"form": "増大した", "label": "た形"}, {"form": "増大して", "label": "て形"}, {"form": "増大している", "label": "ている形"}], "register": "formal", "sense_fingerprint": "不安・危険・影響など、物事の程度が前より強く大きくなること(サ変名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039fd23c-3eee-46a3-96b4-4e59688a4301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38267, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "増大", "is_correct": true, "explanation": "不安の程度が強くなっていく意味で、「日ごとに増大していった」が通る。"}, {"text": "挑戦", "is_correct": false, "explanation": "「不安は日ごとに挑戦していった」は意味をなさない。不安は挑む主体にならない。"}, {"text": "修理", "is_correct": false, "explanation": "「不安を修理していった」は文脈に合わない。不安は直す対象にならない。"}, {"text": "発表", "is_correct": false, "explanation": "「不安が発表していった」は主語と述語が合わず、意味が通らない。"}], "explanations": {"増大": "不安の程度が強くなっていく意味で、「日ごとに増大していった」が通る。", "挑戦": "「不安は日ごとに挑戦していった」は意味をなさない。不安は挑む主体にならない。", "修理": "「不安を修理していった」は文脈に合わない。不安は直す対象にならない。", "発表": "「不安が発表していった」は主語と述語が合わず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "増大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スマホの画面を増大して、地図を見やすくした。", "explanation": "ここは〈拡大〉の意味。画面の表示を大きくするのは拡大で、増大は数量や程度に使う。"}, {"text": "子どもが増えたので、家を増大した。", "explanation": "ここは〈増築〉の意味。建物を広げることは増築と言い、増大は言わない。"}, {"text": "毎日練習して、ピアノの腕が増大した。", "explanation": "ここは〈向上〉の意味。腕前が上がることは向上で、増大は数量や程度に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38267, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "増大", "is_correct": true, "explanation": "事故の危険性が大きくなる意味で、「危険性が増大するので」が通る。"}, {"text": "担当", "is_correct": false, "explanation": "「危険性が担当するので」は意味が成り立たない。"}, {"text": "挨拶", "is_correct": false, "explanation": "「危険性が挨拶するので」は文脈に合わず、意味が通らない。"}, {"text": "注意", "is_correct": false, "explanation": "「危険性が注意するので」は主語と述語が合わず、意味が通らない。"}], "explanations": {"増大": "事故の危険性が大きくなる意味で、「危険性が増大するので」が通る。", "担当": "「危険性が担当するので」は意味が成り立たない。", "挨拶": "「危険性が挨拶するので」は文脈に合わず、意味が通らない。", "注意": "「危険性が注意するので」は主語と述語が合わず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "増大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "細菌が増大して、食品が傷んだ。", "explanation": "ここは〈増殖〉の意味。生物が殖えることには増殖を使い、増大は言わない。"}, {"text": "店員さんに、ご飯を増大してもらった。", "explanation": "ここは〈増量〉の意味。食べ物の分量を増やすときは増量と言い、増大とは言わない。"}, {"text": "風邪をひいて、体温が増大した。", "explanation": "ここは〈上昇〉の意味。温度や数値が上がることには上昇を使い、体温が上がるのに増大とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38267, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "影響力が増大ので、計画を変えた。", "corrected_sentence": "影響力が増大したので、計画を変えた。", "error_description": "誤りの箇所は「ので」の直前。サ変名詞「増大」に「ので」を続けるには「な」（増大なので）か「した」（増大したので）が必要で、「増大ので」は「な」が欠けている。正しい文は「増大したので」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38267, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "景気が悪くなると、失業者が増大させるだろう。", "corrected_sentence": "景気が悪くなると、失業者が増大するだろう。", "error_description": "誤りの箇所は「増大させる」。「させる」は他動詞の使役形で、この文の主語（失業者）は自然に増える側なので、自動詞の「増大する」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38268, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「強い」の主語を示す「が」で、「傾向が強い」と結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「傾向を強い」は文として成り立たない。「強い」は「が」で主語を取る。"}, {"text": "に", "is_correct": false, "explanation": "「傾向に強い」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「傾向で強い」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「強い」の主語を示す「が」で、「傾向が強い」と結ぶ。", "を": "「傾向を強い」は文として成り立たない。「強い」は「が」で主語を取る。", "に": "「傾向に強い」は文として成り立たない。", "で": "「傾向で強い」は文として成り立たない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38268, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38268, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「つねにそういうふうになる」ということがら。", "primary_collocate": null, "pronunciation": "けいこう", "ipa": "keːkoː", "syllable_count": 4, "sentences": [{"text": "彼は緊張すると、早口になる傾向がある。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "彼[かれ]は緊張[きんちょう]すると、早口[はやくち]になる傾向[けいこう]がある。", "sentence_source": "generated"}, {"text": "最近の若者は、新聞を読まない傾向が強い。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "最近[さいきん]の若者[わかもの]は、新聞[しんぶん]を読[よ]まない傾向[けいこう]が強[つよ]い。", "sentence_source": "generated"}, {"text": "夏は食べ物が傷みやすい傾向があるので、気をつけたほうがいい。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "夏[なつ]は食[た]べ物[もの]が傷[いた]みやすい傾向[けいこう]があるので、気[き]をつけたほうがいい。", "sentence_source": "generated"}, {"text": "弟は何でも人のせいにする傾向があって、よく母に注意される。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "弟[おとうと]は何[なん]でも人[ひと]のせいにする傾向[けいこう]があって、よく母[はは]に注意[ちゅうい]される。", "sentence_source": "generated"}, {"text": "雨の日は客が少なくなる傾向があるため、店は早めに閉める。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は客[きゃく]が少[すく]なくなる傾向[けいこう]があるため、店[みせ]は早[はや]めに閉[し]める。", "sentence_source": "generated"}, {"text": "このクラスの生徒は、授業中に質問をしない傾向がある。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "このクラスの生徒[せいと]は、授業中[じゅぎょうちゅう]に質問[しつもん]をしない傾向[けいこう]がある。", "sentence_source": "generated"}, {"text": "年を取ると、新しいことを避ける傾向が出てくると言われる。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "年[とし]を取[と]ると、新[あたら]しいことを避[さ]ける傾向[けいこう]が出[で]てくると言[い]われる。", "sentence_source": "generated"}, {"text": "私は疲れると、甘い物が食べたくなる傾向がある。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "私[わたし]は疲[つか]れると、甘[あま]い物[もの]が食[た]べたくなる傾向[けいこう]がある。", "sentence_source": "generated"}, {"text": "調査によると、都会に住む人ほど運動不足になる傾向が見られる。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "調査[ちょうさ]によると、都会[とかい]に住[す]む人[ひと]ほど運動不足[うんどうぶそく]になる傾向[けいこう]が見[み]られる。", "sentence_source": "generated"}, {"text": "あの子は人前に出ると、急に黙ってしまう傾向がある。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "あの子[こ]は人前[ひとまえ]に出[で]ると、急[きゅう]に黙[だま]ってしまう傾向[けいこう]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "傾向", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人や物がいつもそうなりやすい性質・癖(なりやすさ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039fd23c-3eee-46a3-96b4-4e59688a4301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38268, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "傾向", "is_correct": true, "explanation": "「早口になる傾向がある」で、いつもそうなりやすいという意味が通る。"}, {"text": "挑戦", "is_correct": false, "explanation": "「早口になる挑戦がある」は意味が成り立たない。"}, {"text": "修理", "is_correct": false, "explanation": "「早口になる修理がある」は文脈に合わない。"}, {"text": "宣伝", "is_correct": false, "explanation": "「早口になる宣伝がある」は意味が通らない。"}], "explanations": {"傾向": "「早口になる傾向がある」で、いつもそうなりやすいという意味が通る。", "挑戦": "「早口になる挑戦がある」は意味が成り立たない。", "修理": "「早口になる修理がある」は文脈に合わない。", "宣伝": "「早口になる宣伝がある」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "傾向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋根の傾向を測って、雨水が流れるように直した。", "explanation": "ここは〈傾斜〉の意味。建物や地面の斜めの度合いは傾斜と言い、傾向は人や物事の性質に使う。"}, {"text": "彼女は、窓が大きくて光の傾向が良い部屋に住んでいる。", "explanation": "ここは〈日当たり〉の意味。部屋に入る光の具合は日当たりと言い、傾向とは言わない。"}, {"text": "昨日は、歩く傾向を上げて、約束に間に合った。", "explanation": "ここは〈速さ〉の意味。歩く速さを上げるのは速さと言い、傾向とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38268, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "傾向", "is_correct": true, "explanation": "「避ける傾向が出てくる」で、いつもそうなりやすいという意味が通る。"}, {"text": "注意", "is_correct": false, "explanation": "「避ける注意が出てくる」は意味が成り立たない。"}, {"text": "担当", "is_correct": false, "explanation": "「避ける担当が出てくる」は文脈に合わない。"}, {"text": "挨拶", "is_correct": false, "explanation": "「避ける挨拶が出てくる」は意味をなさない。"}], "explanations": {"傾向": "「避ける傾向が出てくる」で、いつもそうなりやすいという意味が通る。", "注意": "「避ける注意が出てくる」は意味が成り立たない。", "担当": "「避ける担当が出てくる」は文脈に合わない。", "挨拶": "「避ける挨拶が出てくる」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "傾向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店のケーキは、傾向が安い。", "explanation": "ここは〈値段〉の意味。品物の価格は値段と言い、傾向は使わない。"}, {"text": "会議の傾向を、朝の九時に決めた。", "explanation": "ここは〈時刻〉の意味。何時に行うかは時刻と言い、傾向とは言わない。"}, {"text": "駅までの傾向を測って、歩く時間を計った。", "explanation": "ここは〈距離〉の意味。場所の隔たりは距離と言い、傾向は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38268, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は緊張すると、早口になる傾向をあるようだ。", "corrected_sentence": "彼は緊張すると、早口になる傾向があるようだ。", "error_description": "誤りの箇所は「傾向を」。「ある」は「傾向が」と結ぶため、正しくは「傾向がある」。助詞「を」が誤りで、正しい助詞は「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38268, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年を取ると、新しいことを避ける傾向が出てきるとよく言われる。", "corrected_sentence": "年を取ると、新しいことを避ける傾向が出てくるとよく言われる。", "error_description": "誤りの箇所は「出てきる」。「出てくる」の活用が崩れている。正しくは「出てくる」で、カ変動詞「くる」の形を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
