INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38269, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事が、いつも同じような方向に進むようす。", "primary_collocate": null, "pronunciation": "けいこう", "ipa": "keːkoː", "syllable_count": 4, "sentences": [{"text": "物価は、この数年上がる傾向にある。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "物価[ぶっか]は、この数年[すうねん]上[あ]がる傾向[けいこう]にある。", "sentence_source": "generated"}, {"text": "株価は先月から下降の傾向を示している。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "株価[かぶか]は先月[せんげつ]から下降[かこう]の傾向[けいこう]を示[しめ]している。", "sentence_source": "generated"}, {"text": "気温は年々高くなる傾向にあり、夏が長く感じられる。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "気温[きおん]は年々[ねんねん]高[たか]くなる傾向[けいこう]にあり、夏[なつ]が長[なが]く感[かん]じられる。", "sentence_source": "generated"}, {"text": "売り上げは、春から少しずつ回復する傾向を見せている。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げは、春[はる]から少[すこ]しずつ回復[かいふく]する傾向[けいこう]を見[み]せている。", "sentence_source": "generated"}, {"text": "若い人が都会に集まる傾向は、今も変わらない。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "若[わか]い人[ひと]が都会[とかい]に集[あつ]まる傾向[けいこう]は、今[いま]も変[か]わらない。", "sentence_source": "generated"}, {"text": "患者の数は減少の傾向にあるが、油断はできない。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "患者[かんじゃ]の数[かず]は減少[げんしょう]の傾向[けいこう]にあるが、油断[ゆだん]はできない。", "sentence_source": "generated"}, {"text": "海の水温が上昇する傾向が続き、とれる魚の種類が変わってきた。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "海[うみ]の水温[すいおん]が上昇[じょうしょう]する傾向[けいこう]が続[つづ]き、とれる魚[さかな]の種類[しゅるい]が変[か]わってきた。", "sentence_source": "generated"}, {"text": "この地域では、人口が減る傾向に歯止めがかからない。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、人口[じんこう]が減[へ]る傾向[けいこう]に歯止[はど]めがかからない。", "sentence_source": "generated"}, {"text": "世界の景気は、ゆるやかに良くなる傾向にある。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "世界[せかい]の景気[けいき]は、ゆるやかに良[よ]くなる傾向[けいこう]にある。", "sentence_source": "generated"}, {"text": "去年から、紙の本より電子書籍を選ぶ傾向が広がっている。", "target_word": "傾向", "complexity_tier": "T3", "furigana": "去年[きょねん]から、紙[かみ]の本[ほん]より電子書籍[でんししょせき]を選[えら]ぶ傾向[けいこう]が広[ひろ]がっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "傾向", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物価・人口・景気など世の中の動きが一定の方向へ進んでいくようす(動向)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039fd23c-3eee-46a3-96b4-4e59688a4301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38269, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "傾向", "is_correct": true, "explanation": "「上がる傾向にある」で、物価の動きが一定の方向へ進むという意味が通る。"}, {"text": "挑戦", "is_correct": false, "explanation": "「上がる挑戦にある」は意味が成り立たない。"}, {"text": "修理", "is_correct": false, "explanation": "「上がる修理にある」は文脈に合わない。"}, {"text": "注意", "is_correct": false, "explanation": "「上がる注意にある」は意味が通らない。"}], "explanations": {"傾向": "「上がる傾向にある」で、物価の動きが一定の方向へ進むという意味が通る。", "挑戦": "「上がる挑戦にある」は意味が成り立たない。", "修理": "「上がる修理にある」は文脈に合わない。", "注意": "「上がる注意にある」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "傾向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "船は北の傾向へ進んだ。", "explanation": "ここは〈方角〉の意味。進む向きは方角と言い、傾向は物事の動きの流れを指すので船の向きには使わない。"}, {"text": "山の傾向を測って、地図に書き込んだ。", "explanation": "ここは〈高さ〉の意味。山の高さは高さと言い、傾向は使わない。"}, {"text": "列の傾向を待った。", "explanation": "ここは〈順番〉の意味。並ぶ順序は順番と言い、傾向とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38269, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "傾向", "is_correct": true, "explanation": "「上昇する傾向が続き」で、水温の動きが一定方向に進むという意味が通る。"}, {"text": "宣伝", "is_correct": false, "explanation": "「上昇する宣伝が続き」は意味が成り立たない。"}, {"text": "発表", "is_correct": false, "explanation": "「上昇する発表が続き」は文脈に合わない。"}, {"text": "担当", "is_correct": false, "explanation": "「上昇する担当が続き」は意味が通らない。"}], "explanations": {"傾向": "「上昇する傾向が続き」で、水温の動きが一定方向に進むという意味が通る。", "宣伝": "「上昇する宣伝が続き」は意味が成り立たない。", "発表": "「上昇する発表が続き」は文脈に合わない。", "担当": "「上昇する担当が続き」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "傾向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅までの傾向を測り、歩く時間を計った。", "explanation": "ここは〈距離〉の意味。場所の隔たりは距離と言い、傾向は使わない。"}, {"text": "部屋の傾向を測って、家具を配置した。", "explanation": "ここは〈面積〉の意味。広さの数値は面積と言い、傾向は使わない。"}, {"text": "荷物の傾向を量って、料金を決めた。", "explanation": "ここは〈重さ〉の意味。量る対象の重さは重さと言い、傾向とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38269, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "物価は、この数年上がる傾向をあるようだ。", "corrected_sentence": "物価は、この数年上がる傾向にあるようだ。", "error_description": "誤りの箇所は「傾向を」。「ある」と結ぶには「に」（傾向にある）か「が」（傾向がある）を使い、どちらも自然。助詞「を」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38269, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海の水温が上昇する傾向が続くて、とれる魚の種類が変わってきた。", "corrected_sentence": "海の水温が上昇する傾向が続いて、とれる魚の種類が変わってきた。", "error_description": "誤りの箇所は「続くて」。「続く」の「て形」は「続いて」が正しい。「続くて」は活用の誤りで、正しくは「続いて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38270, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「特別という意味」で、内容を示す「という」になる。"}, {"text": "を", "is_correct": false, "explanation": "「特別をいう意味」は引用の形として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「特別でいう意味」は文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「特別がいう意味」は文として成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「特別という意味」で、内容を示す「という」になる。", "を": "「特別をいう意味」は引用の形として成り立たない。", "で": "「特別でいう意味」は文として成り立たない。", "が": "「特別がいう意味」は文として成り立たない。"}, "error_tags": {"を": "wrong_case", "で": "wrong_case", "が": "wrong_case"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "普通", "is_correct": true, "explanation": "「普通」は特別で価値が高いことの反対。"}, {"text": "高級", "is_correct": false, "explanation": "「高級」はプレミアムに近く、反対ではない。"}, {"text": "特別", "is_correct": false, "explanation": "「特別」は同じ方向の意味で、反対ではない。"}, {"text": "贅沢", "is_correct": false, "explanation": "「贅沢」もプレミアムに近い意味で、反対ではない。"}], "correct_answer": "普通", "explanations": {"普通": "「普通」は特別で価値が高いことの反対。", "高級": "「高級」はプレミアムに近く、反対ではない。", "特別": "「特別」は同じ方向の意味で、反対ではない。", "贅沢": "「贅沢」もプレミアムに近い意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38270, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「プレミアムを売りにする」で、対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「ブランドは」が主語なので「プレミアムが売りにしている」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「プレミアムと売りにしている」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「プレミアムへ売りにしている」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「プレミアムを売りにする」で、対象を示す。", "が": "「ブランドは」が主語なので「プレミアムが売りにしている」は成り立たない。", "と": "「プレミアムと売りにしている」は文として成り立たない。", "へ": "「プレミアムへ売りにしている」は文として成り立たない。"}, "error_tags": {"が": "wrong_subject", "と": "wrong_case", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平凡", "is_correct": true, "explanation": "「平凡」は特別でないことで、プレミアムの反対。"}, {"text": "高価", "is_correct": false, "explanation": "「高価」は値段が高いことで、プレミアムに近い。"}, {"text": "上質", "is_correct": false, "explanation": "「上質」は質が高いことで、プレミアムに近い。"}, {"text": "豪華", "is_correct": false, "explanation": "「豪華」は華やかで特別なことで、反対ではない。"}], "correct_answer": "平凡", "explanations": {"平凡": "「平凡」は特別でないことで、プレミアムの反対。", "高価": "「高価」は値段が高いことで、プレミアムに近い。", "上質": "「上質」は質が高いことで、プレミアムに近い。", "豪華": "「豪華」は華やかで特別なことで、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38270, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特別で価値が高く、高い代金を払う理由になること。", "primary_collocate": null, "pronunciation": "ぷれみあむ", "ipa": "pɯɾemiamɯ", "syllable_count": 5, "sentences": [{"text": "これはプレミアムな商品です。", "target_word": "プレミアム", "complexity_tier": "T2", "furigana": "これはプレミアムな商品[しょうひん]です。", "sentence_source": "generated"}, {"text": "プレミアムは特別という意味です。", "target_word": "プレミアム", "complexity_tier": "T2", "furigana": "プレミアムは特別[とくべつ]という意味[いみ]です。", "sentence_source": "generated"}, {"text": "このホテルはプレミアムの部屋が人気だ。", "target_word": "プレミアム", "complexity_tier": "T2", "furigana": "このホテルはプレミアムの部屋[へや]が人気[にんき]だ。", "sentence_source": "generated"}, {"text": "私は誕生日にプレミアムなケーキを買った。", "target_word": "プレミアム", "complexity_tier": "T3", "furigana": "私[わたし]は誕生日[たんじょうび]にプレミアムなケーキを買[か]った。", "sentence_source": "generated"}, {"text": "プレミアムを感じる体験がしたい。", "target_word": "プレミアム", "complexity_tier": "T3", "furigana": "プレミアムを感[かん]じる体験[たいけん]がしたい。", "sentence_source": "generated"}, {"text": "新しい店は、プレミアムな時間を過ごせると言っている。", "target_word": "プレミアム", "complexity_tier": "T4", "furigana": "新[あたら]しい店[みせ]は、プレミアムな時間[じかん]を過[す]ごせると言[い]っている。", "sentence_source": "generated"}, {"text": "高くても、プレミアムが好きな人は多い。", "target_word": "プレミアム", "complexity_tier": "T3", "furigana": "高[たか]くても、プレミアムが好[す]きな人[ひと]は多[おお]い。", "sentence_source": "generated"}, {"text": "このブランドは、プレミアムを売りにしている。", "target_word": "プレミアム", "complexity_tier": "T3", "furigana": "このブランドは、プレミアムを売[う]りにしている。", "sentence_source": "generated"}, {"text": "飛行機のプレミアムは席が広くて楽だ。", "target_word": "プレミアム", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]のプレミアムは席[せき]が広[ひろ]くて楽[らく]だ。", "sentence_source": "generated"}, {"text": "プレミアムであることが、値段の理由になっている。", "target_word": "プレミアム", "complexity_tier": "T4", "furigana": "プレミアムであることが、値段[ねだん]の理由[りゆう]になっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プレミアムな", "label": "活用"}, {"form": "プレミアム会員", "label": "派生"}, {"form": "プレミアム感", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 特別で価値が高いこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24217c32-83c6-4579-9e1d-cf4f10e2dc79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38270, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プレミアム", "is_correct": true, "explanation": "「特別で価値が高い」商品を表すので意味が合う。"}, {"text": "ネガティブ", "is_correct": false, "explanation": "形は合うが、商品の特別さを表す意味にならない。"}, {"text": "ルーズ", "is_correct": false, "explanation": "形は合うが、「ルーズな商品」では意味が合わない。"}, {"text": "ヒステリック", "is_correct": false, "explanation": "形は合うが、人の様子を表す語で商品には意味が合わない。"}], "explanations": {"プレミアム": "「特別で価値が高い」商品を表すので意味が合う。", "ネガティブ": "形は合うが、商品の特別さを表す意味にならない。", "ルーズ": "形は合うが、「ルーズな商品」では意味が合わない。", "ヒステリック": "形は合うが、人の様子を表す語で商品には意味が合わない。"}, "sentence_index": 0, "correct_answer": "プレミアム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "プレミアムな雨が昨日から降り続けている。", "explanation": "雨は特別で価値が高いものではないので、プレミアムは合わない。"}, {"text": "安くて普通のシャツなので、プレミアムな商品だ。", "explanation": "プレミアムは特別で高価なことなので、安くて普通の物には使えない。"}, {"text": "プレミアムは走るのが速い人のことだ。", "explanation": "プレミアムは人の能力ではなく、特別で価値が高いことを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38270, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プレミアム", "is_correct": true, "explanation": "高くても好む理由になる特別さを表すので意味が合う。"}, {"text": "残業", "is_correct": false, "explanation": "形は合うが、「高くても好き」という流れに意味が合わない。"}, {"text": "渋滞", "is_correct": false, "explanation": "形は合うが、「高くても渋滞が好き」では意味が合わない。"}, {"text": "雨", "is_correct": false, "explanation": "形は合うが、高くても選ぶ対象として意味が合わない。"}], "explanations": {"プレミアム": "高くても好む理由になる特別さを表すので意味が合う。", "残業": "形は合うが、「高くても好き」という流れに意味が合わない。", "渋滞": "形は合うが、「高くても渋滞が好き」では意味が合わない。", "雨": "形は合うが、高くても選ぶ対象として意味が合わない。"}, "sentence_index": 6, "correct_answer": "プレミアム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "プレミアムなゴミを毎日捨てている。", "explanation": "ゴミは特別で価値が高い物ではないので、プレミアムは合わない。"}, {"text": "プレミアムが痛くて、病院に行った。", "explanation": "プレミアムは特別で価値が高いことで、体の部分ではないので「痛い」とは言えない。"}, {"text": "駅から遠くて不便なので、プレミアムな部屋だ。", "explanation": "不便な部屋は価値が高いとは言えず、プレミアムの意味に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38270, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "これはプレミアムを商品です。", "corrected_sentence": "これはプレミアムな商品です。", "error_description": "名詞を修飾する形は「プレミアムな」で、「を」は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38270, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店はプレミアムだ時計を売っている。", "corrected_sentence": "この店はプレミアムな時計を売っている。", "error_description": "名詞を修飾するときは「プレミアムな」を使う。「だ」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38271, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「プレミアムがつく」で、プレミアムが主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「つく」は自動詞なので「を」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "「プレミアムでついている」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「プレミアムとついている」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「プレミアムがつく」で、プレミアムが主語になる。", "を": "「つく」は自動詞なので「を」は使えない。", "で": "「プレミアムでついている」は文として成り立たない。", "と": "「プレミアムとついている」は文として成り立たない。"}, "error_tags": {"を": "transitivity", "で": "wrong_case", "と": "wrong_case"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "割引", "is_correct": true, "explanation": "通常価格から差し引く「割引」は、上乗せのプレミアムの反対。"}, {"text": "割増", "is_correct": false, "explanation": "「割増」はプレミアムとほぼ同じ意味で、反対ではない。"}, {"text": "手数料", "is_correct": false, "explanation": "手数料は別に払う費用で、プレミアムの反対ではない。"}, {"text": "税金", "is_correct": false, "explanation": "税金は納めるお金で、プレミアムの反対ではない。"}], "correct_answer": "割引", "explanations": {"割引": "通常価格から差し引く「割引」は、上乗せのプレミアムの反対。", "割増": "「割増」はプレミアムとほぼ同じ意味で、反対ではない。", "手数料": "手数料は別に払う費用で、プレミアムの反対ではない。", "税金": "税金は納めるお金で、プレミアムの反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38271, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「プレミアムを払う」で、払う対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「彼は」が主語なので、「プレミアムが払った」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「プレミアムと払った」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「プレミアムの払った」では動詞の前の格助詞が欠けて不自然。"}], "correct_answer": "を", "explanations": {"を": "「プレミアムを払う」で、払う対象を示す。", "が": "「彼は」が主語なので、「プレミアムが払った」は成り立たない。", "と": "「プレミアムと払った」は文として成り立たない。", "の": "「プレミアムの払った」では動詞の前の格助詞が欠けて不自然。"}, "error_tags": {"が": "wrong_subject", "と": "wrong_case", "の": "wrong_case"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ディスカウント", "is_correct": true, "explanation": "価格を下げるディスカウントは、上乗せのプレミアムの反対。"}, {"text": "チップ", "is_correct": false, "explanation": "チップは上乗せの一種で、反対ではない。"}, {"text": "ロイヤリティ", "is_correct": false, "explanation": "使用料のことで、プレミアムの反対ではない。"}, {"text": "コミッション", "is_correct": false, "explanation": "手数料のことで、プレミアムの反対ではない。"}], "correct_answer": "ディスカウント", "explanations": {"ディスカウント": "価格を下げるディスカウントは、上乗せのプレミアムの反対。", "チップ": "チップは上乗せの一種で、反対ではない。", "ロイヤリティ": "使用料のことで、プレミアムの反対ではない。", "コミッション": "手数料のことで、プレミアムの反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38271, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "通常の価格や価値に上乗せされる追加の金額。割増金。", "primary_collocate": null, "pronunciation": "ぷれみあむ", "ipa": "pɯɾemiamɯ", "syllable_count": 5, "sentences": [{"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "プレミアム", "complexity_tier": "T6", "furigana": "イールドカーブ・コントロールの下[もと]では、市場[しじょう]メカニズムを通[つう]じた適正[てきせい]なリスクプレミアムの形成[けいせい]が阻害[そがい]され、結果[けっか]として財政[ざいせい]の持続[じぞく]可能性[かのうせい]を担保[たんぽ]するべき債務[さいむ]の価格的[かかくてき]シグナルが鈍磨[どんま]する懸念[けねん]が拭[ぬぐ]えない。", "sentence_source": "mined"}, {"text": "この切手にはプレミアムがついている。", "target_word": "プレミアム", "complexity_tier": "T3", "furigana": "この切手[きって]にはプレミアムがついている。", "sentence_source": "generated"}, {"text": "古いカードにプレミアムがついた。", "target_word": "プレミアム", "complexity_tier": "T2", "furigana": "古[ふる]いカードにプレミアムがついた。", "sentence_source": "generated"}, {"text": "発売日のチケットは、プレミアムを払っても買いたい人が多い。", "target_word": "プレミアム", "complexity_tier": "T4", "furigana": "発売日[はつばいび]のチケットは、プレミアムを払[はら]っても買[か]いたい人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "限定品にはプレミアムがつくことがある。", "target_word": "プレミアム", "complexity_tier": "T3", "furigana": "限定品[げんていひん]にはプレミアムがつくことがある。", "sentence_source": "generated"}, {"text": "プレミアムは通常の価格との差額だ。", "target_word": "プレミアム", "complexity_tier": "T2", "furigana": "プレミアムは通常[つうじょう]の価格[かかく]との差額[さがく]だ。", "sentence_source": "generated"}, {"text": "人気の品はプレミアムの分だけ高く売られている。", "target_word": "プレミアム", "complexity_tier": "T4", "furigana": "人気[にんき]の品[しな]はプレミアムの分[ぶん]だけ高[たか]く売[う]られている。", "sentence_source": "generated"}, {"text": "彼は珍しい本にプレミアムを払った。", "target_word": "プレミアム", "complexity_tier": "T2", "furigana": "彼[かれ]は珍[めずら]しい本[ほん]にプレミアムを払[はら]った。", "sentence_source": "generated"}, {"text": "人気のチケットに高いプレミアムをつけて売る人もいる。", "target_word": "プレミアム", "complexity_tier": "T3", "furigana": "人気[にんき]のチケットに高[たか]いプレミアムをつけて売[う]る人[ひと]もいる。", "sentence_source": "generated"}, {"text": "このワインはプレミアムが高すぎて買えない。", "target_word": "プレミアム", "complexity_tier": "T3", "furigana": "このワインはプレミアムが高[たか]すぎて買[か]えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プレミアム価格", "label": "派生"}, {"form": "プレミアム会員", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 通常価格に上乗せされる追加金額", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24217c32-83c6-4579-9e1d-cf4f10e2dc79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38271, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プレミアム", "is_correct": true, "explanation": "「リスクプレミアム」は金融用語で、上乗せされる追加分を表すので文意に合う。"}, {"text": "ペナルティ", "is_correct": false, "explanation": "形は合うが、「適正なリスクペナルティの形成」では意味が合わない。"}, {"text": "マニュアル", "is_correct": false, "explanation": "形は合うが、市場の価格形成の話に「マニュアル」では意味が合わない。"}, {"text": "ジャンル", "is_correct": false, "explanation": "形は合うが、リスクの価格に関する文脈で意味が合わない。"}], "explanations": {"プレミアム": "「リスクプレミアム」は金融用語で、上乗せされる追加分を表すので文意に合う。", "ペナルティ": "形は合うが、「適正なリスクペナルティの形成」では意味が合わない。", "マニュアル": "形は合うが、市場の価格形成の話に「マニュアル」では意味が合わない。", "ジャンル": "形は合うが、リスクの価格に関する文脈で意味が合わない。"}, "sentence_index": 0, "correct_answer": "プレミアム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、公園でプレミアムを散歩している。", "explanation": "プレミアムは追加金額を表す名詞で、散歩する対象にはならない。"}, {"text": "このシャツは値引きされて、プレミアムの分だけ安くなった。", "explanation": "プレミアムは上乗せされる金額で、安くなる分ではない。意味が逆になっている。"}, {"text": "プレミアムを食べたら、とても甘かった。", "explanation": "プレミアムは金額のことで、食べ物ではないので「食べる」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38271, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プレミアム", "is_correct": true, "explanation": "人気で通常より高くなる分は「プレミアム」で、文意に合う。"}, {"text": "カロリー", "is_correct": false, "explanation": "形は合うが、高く売られる理由として意味が合わない。"}, {"text": "ジャンル", "is_correct": false, "explanation": "形は合うが、「ジャンルの分だけ高く」では意味が合わない。"}, {"text": "ルール", "is_correct": false, "explanation": "形は合うが、値段が上がる分としては意味が合わない。"}], "explanations": {"プレミアム": "人気で通常より高くなる分は「プレミアム」で、文意に合う。", "カロリー": "形は合うが、高く売られる理由として意味が合わない。", "ジャンル": "形は合うが、「ジャンルの分だけ高く」では意味が合わない。", "ルール": "形は合うが、値段が上がる分としては意味が合わない。"}, "sentence_index": 6, "correct_answer": "プレミアム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女はプレミアムを聞いて、ピアノを弾いた。", "explanation": "プレミアムは追加金額で、聞くものではない。"}, {"text": "古い切手の価値が下がって、高いプレミアムがついた。", "explanation": "プレミアムは価値が上がったときにつくもので、下がった話とは矛盾する。"}, {"text": "プレミアムは雨の日に空から落ちてくる。", "explanation": "プレミアムは金額のことで、空から落ちてくる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38271, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "珍しい皿にプレミアムが泳いでいる。", "corrected_sentence": "珍しい皿にプレミアムがついている。", "error_description": "プレミアムは「泳ぐ」の主語にならない。価値の上乗せには「ついている」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38271, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このワインはプレミアムを高すぎて買えない。", "corrected_sentence": "このワインはプレミアムが高すぎて買えない。", "error_description": "「高い」の主語は「が」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
