INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38272, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることが続かないで、短い間だけのこと。", "primary_collocate": null, "pronunciation": "いちじ", "ipa": "itɕidʑi", "syllable_count": 3, "sentences": [{"text": "彼は留学先から一時帰国し、家族と数日過ごした。", "target_word": "一時", "complexity_tier": "T3", "furigana": "彼[かれ]は留学先[りゅうがくさき]から一時[いちじ]帰国[きこく]し、家族[かぞく]と数日[すうじつ]過[す]ごした。", "sentence_source": "generated"}, {"text": "店は改装のため一時休業している。", "target_word": "一時", "complexity_tier": "T3", "furigana": "店[みせ]は改装[かいそう]のため一時[いちじ]休業[きゅうぎょう]している。", "sentence_source": "generated"}, {"text": "この橋は工事のため、一時通行止めになっている。", "target_word": "一時", "complexity_tier": "T3", "furigana": "この橋[はし]は工事[こうじ]のため、一時[いちじ]通行止[つうこうど]めになっている。", "sentence_source": "generated"}, {"text": "彼女は学費のため、大学を一時休学した。", "target_word": "一時", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は学費[がくひ]のため、大学[だいがく]を一時[いちじ]休学[きゅうがく]した。", "sentence_source": "generated"}, {"text": "母は病気で一時入院したが、今は元気に働いている。", "target_word": "一時", "complexity_tier": "T3", "furigana": "母[はは]は病気[びょうき]で一時[いちじ]入院[にゅういん]したが、今[いま]は元気[げんき]に働[はたら]いている。", "sentence_source": "generated"}, {"text": "この歌は一時流行したけれど、今では誰も歌わない。", "target_word": "一時", "complexity_tier": "T3", "furigana": "この歌[うた]は一時[いちじ]流行[りゅうこう]したけれど、今[いま]では誰[だれ]も歌[うた]わない。", "sentence_source": "generated"}, {"text": "子どもを一時保育に預けて、買い物に出かけた。", "target_word": "一時", "complexity_tier": "T3", "furigana": "子[こ]どもを一時[いちじ]保育[ほいく]に預[あず]けて、買[か]い物[もの]に出[で]かけた。", "sentence_source": "generated"}, {"text": "雨のため、試合は一時中断された。", "target_word": "一時", "complexity_tier": "T3", "furigana": "雨[あめ]のため、試合[しあい]は一時[いちじ]中断[ちゅうだん]された。", "sentence_source": "generated"}, {"text": "台風の接近で、住民は一時避難した。", "target_word": "一時", "complexity_tier": "T3", "furigana": "台風[たいふう]の接近[せっきん]で、住民[じゅうみん]は一時[いちじ]避難[ひなん]した。", "sentence_source": "generated"}, {"text": "売り場の照明は、点検のため一時消灯された。", "target_word": "一時", "complexity_tier": "T3", "furigana": "売[う]り場[ば]の照明[しょうめい]は、点検[てんけん]のため一時[いちじ]消灯[しょうとう]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一時", "label": "基本形"}, {"form": "一時の", "label": "連体形(の)"}], "register": "neutral", "sense_fingerprint": "ずっとではなく、ある短い期間だけであること(過去の一時期・その場かぎり)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039fd23c-3eee-46a3-96b4-4e59688a4301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38272, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一時", "is_correct": true, "explanation": "ここは「いったん帰る」の意味。「留学先から一時帰国」は短い期間だけ帰ることを表し、文の意味に合う。"}, {"text": "全部", "is_correct": false, "explanation": "「全部」は「すべて」の意味で、「留学先から＿＿帰国し」に入れても期間の意味が通らず不自然。"}, {"text": "市内", "is_correct": false, "explanation": "「市内」は場所の範囲を表すので、「留学先から市内帰国」とは言えない。"}, {"text": "大量", "is_correct": false, "explanation": "「大量」は数量を表し、帰国の仕方を修飾できない。「大量帰国」は文脈に合わない。"}], "explanations": {"一時": "ここは「いったん帰る」の意味。「留学先から一時帰国」は短い期間だけ帰ることを表し、文の意味に合う。", "全部": "「全部」は「すべて」の意味で、「留学先から＿＿帰国し」に入れても期間の意味が通らず不自然。", "市内": "「市内」は場所の範囲を表すので、「留学先から市内帰国」とは言えない。", "大量": "「大量」は数量を表し、帰国の仕方を修飾できない。「大量帰国」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "一時"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社の一時試験に合格した。", "explanation": "ここは「一次（最初の段階）」の意味。一時は短い期間を表すので、試験の段階を表す語としては使えない。"}, {"text": "この果物は一時食べたら忘れられない味だ。", "explanation": "一時は期間を表す語で、「一度食べたら」の回数の意味は表せない。"}, {"text": "ボールが一時で見えなくなった。", "explanation": "一時は期間を表す語で、「一時で」と言うと不自然になり、すぐ消えるという意味は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38272, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一時", "is_correct": true, "explanation": "ここは「短い間だけ」の意味。「一時保育」は一時的に子どもを預ける保育を表し、文に合う。"}, {"text": "全身", "is_correct": false, "explanation": "「全身」は体全体を表す語で、「子どもを＿＿保育に預けて」に入れると意味が通らない。"}, {"text": "病弱", "is_correct": false, "explanation": "「病弱」は体が弱いことを表すので、「病弱保育」とは言わず、預け方の説明にならない。"}, {"text": "途中", "is_correct": false, "explanation": "「途中」は途中の段階を表し、「途中保育に預けて」は保育の種類として成り立たない。"}], "explanations": {"一時": "ここは「短い間だけ」の意味。「一時保育」は一時的に子どもを預ける保育を表し、文に合う。", "全身": "「全身」は体全体を表す語で、「子どもを＿＿保育に預けて」に入れると意味が通らない。", "病弱": "「病弱」は体が弱いことを表すので、「病弱保育」とは言わず、預け方の説明にならない。", "途中": "「途中」は途中の段階を表し、「途中保育に預けて」は保育の種類として成り立たない。"}, "sentence_index": 6, "correct_answer": "一時"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その契約は一時の約束だが、死ぬまで守る義務がある。", "explanation": "一時は短い期間を表すので、死ぬまで守る義務の話には合わない。"}, {"text": "その知らせを聞いて、一時も早く駆けつけた。", "explanation": "「一刻も早く」の意味に寄っており、短い期間を表す一時の意味とはずれる。"}, {"text": "店員は一時ありがとうございますと頭を下げた。", "explanation": "一時は挨拶の決まり文句に使う語ではなく、短い期間を表す語なので使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38272, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台風のため、駅前の店は一時を休業している。", "corrected_sentence": "台風のため、駅前の店は一時休業している。", "error_description": "「一時」に「を」が付いている誤り。「一時休業している」と副詞的に使うので、「を」は不要。誤りは「一時を」、正しくは「一時」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38272, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祭りの準備のため、広場は一時な閉鎖になっている。", "corrected_sentence": "祭りの準備のため、広場は一時閉鎖になっている。", "error_description": "「一時」に「な」が付いている誤り。「一時」は「一時的な」とは違い、「な」を付けると形容動詞にならない。「一時閉鎖」が正しい形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
