INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38273, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある状態や現象が、長く続かずに終わることを表す。", "primary_collocate": null, "pronunciation": "いちじ", "ipa": "itɕidʑi", "syllable_count": 3, "sentences": [{"text": "朝は一時雨が降ったが、昼にはやんで青空になった。", "target_word": "一時", "complexity_tier": "T3", "furigana": "朝[あさ]は一時[いちじ]雨[あめ]が降[ふ]ったが、昼[ひる]にはやんで青空[あおぞら]になった。", "sentence_source": "generated"}, {"text": "大きな地震のあと、町では一時停電が起きた。", "target_word": "一時", "complexity_tier": "T3", "furigana": "大[おお]きな地震[じしん]のあと、町[まち]では一時[いちじ]停電[ていでん]が起[お]きた。", "sentence_source": "generated"}, {"text": "症状は一時改善したが、夜にまた悪くなってしまった。", "target_word": "一時", "complexity_tier": "T3", "furigana": "症状[しょうじょう]は一時[いちじ]改善[かいぜん]したが、夜[よる]にまた悪[わる]くなってしまった。", "sentence_source": "generated"}, {"text": "午後は一時晴れ、夕方からまた雨が降り出した。", "target_word": "一時", "complexity_tier": "T3", "furigana": "午後[ごご]は一時[いちじ]晴[は]れ、夕方[ゆうがた]からまた雨[あめ]が降[ふ]り出[だ]した。", "sentence_source": "generated"}, {"text": "工事のため、水道が一時断水した。", "target_word": "一時", "complexity_tier": "T3", "furigana": "工事[こうじ]のため、水道[すいどう]が一時[いちじ]断水[だんすい]した。", "sentence_source": "generated"}, {"text": "妹は一時休学していたが、今ではもう学校に通っている。", "target_word": "一時", "complexity_tier": "T3", "furigana": "妹[いもうと]は一時[いちじ]休学[きゅうがく]していたが、今[いま]ではもう学校[がっこう]に通[かよ]っている。", "sentence_source": "generated"}, {"text": "景気は一時回復したが、長くは続かなかった。", "target_word": "一時", "complexity_tier": "T3", "furigana": "景気[けいき]は一時[いちじ]回復[かいふく]したが、長[なが]くは続[つづ]かなかった。", "sentence_source": "generated"}, {"text": "機械は一時停止したが、すぐに動き出した。", "target_word": "一時", "complexity_tier": "T3", "furigana": "機械[きかい]は一時[いちじ]停止[ていし]したが、すぐに動[うご]き出[だ]した。", "sentence_source": "generated"}, {"text": "通信が一時中断したが、すぐ元通りになった。", "target_word": "一時", "complexity_tier": "T3", "furigana": "通信[つうしん]が一時[いちじ]中断[ちゅうだん]したが、すぐ元通[もとどお]りになった。", "sentence_source": "generated"}, {"text": "路線は一時運休したが、午後には再開した。", "target_word": "一時", "complexity_tier": "T3", "furigana": "路線[ろせん]は一時[いちじ]運休[うんきゅう]したが、午後[ごご]には再開[さいかい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一時", "label": "基本形"}, {"form": "一時の", "label": "連体形(の)"}], "register": "neutral", "sense_fingerprint": "雨・停電・痛みなどの状態や現象が、しばらくして終わること(その間だけ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039fd23c-3eee-46a3-96b4-4e59688a4301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38273, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一時", "is_correct": true, "explanation": "ここは「ある状態が短い間だけ続く」の意味。「朝は一時雨が降った」で、雨が短い時間だけ降ったことを表す。"}, {"text": "全国", "is_correct": false, "explanation": "「全国」は地域の範囲を表し、「朝は全国雨が降った」とは言えない。"}, {"text": "無断", "is_correct": false, "explanation": "「無断」は許可を得ないことを表し、雨の降り方を説明できない。"}, {"text": "夕方", "is_correct": false, "explanation": "「夕方」は時間帯で、「朝は夕方雨が降った」は朝と矛盾する。"}], "explanations": {"一時": "ここは「ある状態が短い間だけ続く」の意味。「朝は一時雨が降った」で、雨が短い時間だけ降ったことを表す。", "全国": "「全国」は地域の範囲を表し、「朝は全国雨が降った」とは言えない。", "無断": "「無断」は許可を得ないことを表し、雨の降り方を説明できない。", "夕方": "「夕方」は時間帯で、「朝は夕方雨が降った」は朝と矛盾する。"}, "sentence_index": 0, "correct_answer": "一時"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場の一時の停電が一年も続いた。", "explanation": "一時は短い間だけのことを表すので、一年も続く停電には合わない。"}, {"text": "その痛みは一時の症状で、ずっと消えなかった。", "explanation": "一時は短く終わる状態を表すので、ずっと消えない症状の説明には合わない。"}, {"text": "その痛みは一時で消えた。", "explanation": "一時は期間を表す語で、「一時で」と言うと不自然になり、すぐ消えたという意味は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38273, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一時", "is_correct": true, "explanation": "ここは「続かずに終わる」の意味。「景気は一時回復した」で、回復が長く続かなかったことを表す。"}, {"text": "完治", "is_correct": false, "explanation": "「完治」は病気が完全に治ることで、「景気は＿＿回復」に入れると意味が通らない。"}, {"text": "倒産", "is_correct": false, "explanation": "「倒産」は会社がつぶれることで、「景気は倒産回復」とは言えない。"}, {"text": "不況", "is_correct": false, "explanation": "「不況」は景気の状態を表す名詞だが、「景気は不況回復した」とは言えず、文の意味に合わない。"}], "explanations": {"一時": "ここは「続かずに終わる」の意味。「景気は一時回復した」で、回復が長く続かなかったことを表す。", "完治": "「完治」は病気が完全に治ることで、「景気は＿＿回復」に入れると意味が通らない。", "倒産": "「倒産」は会社がつぶれることで、「景気は倒産回復」とは言えない。", "不況": "「不況」は景気の状態を表す名詞だが、「景気は不況回復した」とは言えず、文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "一時"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故の連絡を受け、一時も早く病院へ向かった。", "explanation": "「一刻も早く」の意味に寄っており、ある状態が短く終わるという一時の意味とはずれる。"}, {"text": "この機械は一時壊れると、もう二度と直らない。", "explanation": "一時は期間を表す語で、「一度壊れる」という回数の意味は表せない。"}, {"text": "その別れは一時の別れとなり、二度と会えないことになった。", "explanation": "「一時の別れ」は短い間の別れを表すので、二度と会えないという内容と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38273, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "強い風で、電車は一時で止まった。", "corrected_sentence": "強い風で、電車は一時止まった。", "error_description": "「一時」の後に「で」が付いている誤り。「一時止まった」の形で、助詞なしで状態の終わりを表すので、「で」は不要。誤りは「一時で」、正しくは「一時」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38273, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場の機械は一時を停止した。", "corrected_sentence": "工場の機械は一時停止した。", "error_description": "「一時」に「を」が付いている誤り。停止の対象は機械であり、「一時」は目的語にならないので「を」は不要。誤りは「一時を」、正しくは「一時」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38274, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す格。「ブームがあった」の形で、「あった」に自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す格。「ある」は自動詞なので「を」は取れない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す格。「ブームとあった」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格。「ブームへあった」は不自然。"}], "correct_answer": "が", "explanations": {"が": "主語を示す格。「ブームがあった」の形で、「あった」に自然に続く。", "を": "目的語を示す格。「ある」は自動詞なので「を」は取れない。", "と": "並列や相手を示す格。「ブームとあった」は文が成り立たない。", "へ": "方向を示す格。「ブームへあった」は不自然。"}, "error_tags": {"を": "「ある」は自動詞のため目的語を取らない", "と": "並列・相手を示し、ここでは文が成り立たない", "へ": "方向を示し、「ブームへあった」は不自然"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38274, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」。「作りのブーム」と名詞をつなぐ。"}, {"text": "に", "is_correct": false, "explanation": "存在や場所を示す格。「作りにブーム」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の格。名詞同士をつなぐ役割にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す格。「作りからブーム」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」。「作りのブーム」と名詞をつなぐ。", "に": "存在や場所を示す格。「作りにブーム」は不自然。", "で": "手段や場所の格。名詞同士をつなぐ役割にならない。", "から": "起点を示す格。「作りからブーム」は意味が通らない。"}, "error_tags": {"に": "存在や場所を示す格で、「作りにブーム」は不自然", "で": "手段・場所を示す格で、名詞をつなぐ役割にならない", "から": "起点を示す格で、ここでは意味が通らない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38274, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんの人がいっせいに同じことをしたいと思うこと。", "primary_collocate": null, "pronunciation": "ぶーむ", "ipa": "bɯːmɯ", "syllable_count": 3, "sentences": [{"text": "今、学校では縄跳びのブームが来ている。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "今[いま]、学校[がっこう]では縄跳[なわとび]びのブームが来[き]ている。", "sentence_source": "generated"}, {"text": "数年前にタピオカのブームがあったが、今は落ち着いた。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "数年前[すうねんまえ]にタピオカのブームがあったが、今[いま]は落[お]ち着[つ]いた。", "sentence_source": "generated"}, {"text": "クラスで消しゴム集めのブームが起こった。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "クラスで消[け]しゴム集[あつ]めのブームが起[お]こった。", "sentence_source": "generated"}, {"text": "ブームが去ると、あの店の客は急に減った。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "ブームが去[さ]ると、あの店[みせ]の客[きゃく]は急[きゅう]に減[へ]った。", "sentence_source": "generated"}, {"text": "友だちの間で、カードゲームがブームになっている。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "友[とも]だちの間[あいだ]で、カードゲームがブームになっている。", "sentence_source": "generated"}, {"text": "犬を飼うブームが広がり、ペット店が増えた。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "犬[いぬ]を飼[か]うブームが広[ひろ]がり、ペット店[てん]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "一時のブームで終わらず、この遊びは長く続いている。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "一時[いちじ]のブームで終[お]わらず、この遊[あそ]びは長[なが]く続[つづ]いている。", "sentence_source": "generated"}, {"text": "うちでは、今、ホットケーキ作りのブームだ。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "うちでは、今[いま]、ホットケーキ作[づく]りのブームだ。", "sentence_source": "generated"}, {"text": "ブームに乗って、多くの店が同じ商品を売り始めた。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "ブームに乗[の]って、多[おお]くの店[みせ]が同[おな]じ商品[しょうひん]を売[う]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "町中で同じ服を着る人が増え、まさにブームだと思った。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "町中[まちじゅう]で同[おな]じ服[ふく]を着[き]る人[ひと]が増[ふ]え、まさにブームだと思[おも]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブーム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "多くの人が同じことを一斉にしたがる流行(身近な遊び・習慣)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fb64f-2b7d-47f2-a572-4d369e136007') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38274, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブーム", "is_correct": true, "explanation": "正解。一時的な流行を指し、「縄跳びのブームが来ている」で自然につながる。"}, {"text": "ゴール", "is_correct": false, "explanation": "目標地点のこと。「縄跳びのゴールが来ている」は意味が通らない。"}, {"text": "マイク", "is_correct": false, "explanation": "音を拾う機器のこと。「縄跳びのマイクが来ている」は文が成り立たない。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓の布のこと。「縄跳びのカーテンが来ている」は不自然。"}], "explanations": {"ブーム": "正解。一時的な流行を指し、「縄跳びのブームが来ている」で自然につながる。", "ゴール": "目標地点のこと。「縄跳びのゴールが来ている」は意味が通らない。", "マイク": "音を拾う機器のこと。「縄跳びのマイクが来ている」は文が成り立たない。", "カーテン": "窓の布のこと。「縄跳びのカーテンが来ている」は不自然。"}, "sentence_index": 0, "correct_answer": "ブーム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この歌は、ブームを感じて作曲された。", "explanation": "ここは〈感動〉の意味。ブームは流行の状態を指し、感じ取る対象にはならない。"}, {"text": "友人は趣味にブームして、毎日練習している。", "explanation": "〈熱中〉の意味。ブームは世間で流行している状態を指し、個人が熱中する動詞形としては使わない。"}, {"text": "その歌手は次々とブームを飛ばした。", "explanation": "〈ヒット〉の意味。ブームは流行の状態を指し、ヒット作のように「飛ばす」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38274, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブーム", "is_correct": true, "explanation": "正解。一時的な流行を指し、「一時の〜で終わらず」に入る。"}, {"text": "ハンドル", "is_correct": false, "explanation": "操作する握りのこと。「一時のハンドルで終わらず」は意味が通らない。"}, {"text": "レジ", "is_correct": false, "explanation": "会計の場所のこと。「一時のレジで終わらず」は文が成り立たない。"}, {"text": "ベンチ", "is_correct": false, "explanation": "腰掛けのこと。「一時のベンチで終わらず」は不自然。"}], "explanations": {"ブーム": "正解。一時的な流行を指し、「一時の〜で終わらず」に入る。", "ハンドル": "操作する握りのこと。「一時のハンドルで終わらず」は意味が通らない。", "レジ": "会計の場所のこと。「一時のレジで終わらず」は文が成り立たない。", "ベンチ": "腰掛けのこと。「一時のベンチで終わらず」は不自然。"}, "sentence_index": 6, "correct_answer": "ブーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "有名ブームの服は、やはり質がいい。", "explanation": "〈ブランド〉の意味。ブームは一時的な人気の広がりで、有名という意味ではない。"}, {"text": "あの先輩は、ブームの約束を必ず守る。", "explanation": "ここは〈約束〉の意味。ブームは流行の状態を指すので、約束の対象にはならない。"}, {"text": "そのブームは、ついに映画に出た。", "explanation": "〈スター〉の意味。ブームは人ではないので、映画に出演するとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38274, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちの間で、ゲームのブームを広がった。", "corrected_sentence": "友だちの間で、ゲームのブームが広がった。", "error_description": "助詞の誤り。「ブームが広がる」の「が」を「を」に変えている。「広がる」は自動詞なので目的語の「を」は取れない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38274, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一時のブームが去らると、店は静かになった。", "corrected_sentence": "一時のブームが去ると、店は静かになった。", "error_description": "活用の誤り。「去る」の辞書形に「と」が続く形は「去ると」で、「去らると」という活用はない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38275, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す格。「ブームが一時的なもの」の形で、主語「ブーム」を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す格。「ブームを…と言われても」は、言われる側が主語なので成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す格。「ブームに一時的なもの」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格。「ブームへ一時的なもの」は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す格。「ブームが一時的なもの」の形で、主語「ブーム」を示す。", "を": "目的語を示す格。「ブームを…と言われても」は、言われる側が主語なので成り立たない。", "に": "位置や相手を示す格。「ブームに一時的なもの」は不自然。", "へ": "方向を示す格。「ブームへ一時的なもの」は文が成り立たない。"}, "error_tags": {"を": "目的語の格だが、「言われる」の主語はブームなので成り立たない", "に": "位置や相手を示し、「ブームに一時的なもの」は不自然", "へ": "方向を示し、ここでは文が成り立たない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38275, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "結果や変化の先を示す格。「ブームになった」の形で、「なる」に続く。"}, {"text": "が", "is_correct": false, "explanation": "主語の格。「ブームがなった」は「なる」と結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の格。「ブームでなった」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「ブームのなった」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "結果や変化の先を示す格。「ブームになった」の形で、「なる」に続く。", "が": "主語の格。「ブームがなった」は「なる」と結びつかない。", "で": "手段や場所の格。「ブームでなった」は成り立たない。", "の": "連体修飾の「の」。「ブームのなった」は成り立たない。"}, "error_tags": {"が": "主語の格で、「なる」には「に」が続く", "で": "手段・場所を示す格で、「なる」と結びつかない", "の": "連体修飾で、「ブームのなった」は成り立たない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38275, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事や現象が一時的に非常に人気になり、多くの人々が熱中する状態。", "primary_collocate": null, "pronunciation": "ぶーむ", "ipa": "bɯːmɯ", "syllable_count": 3, "sentences": [{"text": "この映画をきっかけに、昔の音楽が再びブームになった。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "この映画[えいが]をきっかけに、昔[むかし]の音楽[おんがく]が再[ふたた]びブームになった。", "sentence_source": "generated"}, {"text": "ブームが一時的なものだと言われても、店は商品を大量に作った。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "ブームが一時的[いちじてき]なものだと言[い]われても、店[みせ]は商品[しょうひん]を大量[たいりょう]に作[つく]った。", "sentence_source": "generated"}, {"text": "テレビで紹介されて、納豆のブームが起きた。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "テレビで紹介[しょうかい]されて、納豆[なっとう]のブームが起[お]きた。", "sentence_source": "generated"}, {"text": "ブームが過ぎると、人々は別の流行に夢中になった。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "ブームが過[す]ぎると、人々[ひとびと]は別[べつ]の流行[りゅうこう]に夢中[むちゅう]になった。", "sentence_source": "generated"}, {"text": "その歌手のブームは、わずか一年で終わった。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "その歌手[かしゅ]のブームは、わずか一年[いちねん]で終[お]わった。", "sentence_source": "generated"}, {"text": "ブームの最中は、どの店も行列ができていた。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "ブームの最中[さいちゅう]は、どの店[みせ]も行列[ぎょうれつ]ができていた。", "sentence_source": "generated"}, {"text": "急なブームで、品切れが続いている。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "急[きゅう]なブームで、品切[しなぎ]れが続[つづ]いている。", "sentence_source": "generated"}, {"text": "一度ブームになった物は、またいつか戻ってくることがある。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "一度[いちど]ブームになった物[もの]は、またいつか戻[もど]ってくることがある。", "sentence_source": "generated"}, {"text": "登山のブームのおかげで、山道具の売り上げが伸びた。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "登山[とざん]のブームのおかげで、山道具[やまどうぐ]の売[う]り上[あ]げが伸[の]びた。", "sentence_source": "generated"}, {"text": "ブームに左右されない、長く愛される商品を作りたい。", "target_word": "ブーム", "complexity_tier": "T3", "furigana": "ブームに左右[さゆう]されない、長[なが]く愛[あい]される商品[しょうひん]を作[つく]りたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブーム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事が一時的に大人気になり人々が熱中する社会現象・市場の流行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fb64f-2b7d-47f2-a572-4d369e136007') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38275, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブーム", "is_correct": true, "explanation": "正解。一時的に人気になる状態を指し、「再びブームになった」に入る。"}, {"text": "ユーモア", "is_correct": false, "explanation": "面白さのこと。「再びユーモアになった」は意味が通らない。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓の布のこと。「再びカーテンになった」は文が成り立たない。"}, {"text": "ゴール", "is_correct": false, "explanation": "目標や得点のこと。「再びゴールになった」は意味が通らない。"}], "explanations": {"ブーム": "正解。一時的に人気になる状態を指し、「再びブームになった」に入る。", "ユーモア": "面白さのこと。「再びユーモアになった」は意味が通らない。", "カーテン": "窓の布のこと。「再びカーテンになった」は文が成り立たない。", "ゴール": "目標や得点のこと。「再びゴールになった」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "ブーム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その歌手は、ブームを感じてこの曲を作曲した。", "explanation": "ここは〈感動〉の意味。ブームは流行の状態を指し、感じ取る対象にはならない。"}, {"text": "その新人は次々とブームを飛ばした。", "explanation": "〈ヒット〉の意味。ブームは流行の状態を指し、「飛ばす」とは合わない。"}, {"text": "父は釣りにブームして、週末は出かけてばかりだ。", "explanation": "〈熱中〉の意味。ブームは世間の流行を指し、個人が熱中する動詞形では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38275, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブーム", "is_correct": true, "explanation": "正解。一時的な人気の広がりを指し、「急な〜で、品切れが続いている」に入る。"}, {"text": "家具", "is_correct": false, "explanation": "家の調度品のこと。「急な家具で品切れが続いている」は意味が通らない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除の道具のこと。「急な掃除機で」は文脈に合わない。"}, {"text": "テント", "is_correct": false, "explanation": "野外の寝床のこと。「急なテントで品切れ」は意味が通らない。"}], "explanations": {"ブーム": "正解。一時的な人気の広がりを指し、「急な〜で、品切れが続いている」に入る。", "家具": "家の調度品のこと。「急な家具で品切れが続いている」は意味が通らない。", "掃除機": "掃除の道具のこと。「急な掃除機で」は文脈に合わない。", "テント": "野外の寝床のこと。「急なテントで品切れ」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "ブーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの店主はブームで、今も現役で働いている。", "explanation": "〈ベテラン〉の意味。ブームは人ではなく流行を指すので、人として現役で働くとは言わない。"}, {"text": "その作家は、ブームを一つずつ手で磨いている。", "explanation": "〈作品〉の意味。作品は手で磨くものだが、流行を手で磨くとは言えない。"}, {"text": "そのダンサーは毎日、ブームを踊っている。", "explanation": "〈ダンス〉の意味。踊るのは動作のダンスで、流行を踊るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38275, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昔のアニメが再びブームをなった。", "corrected_sentence": "昔のアニメが再びブームになった。", "error_description": "助詞の誤り。「ブームになる」の「に」を「を」に変えている。「なる」は「に」を取るため、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38275, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "テレビで紹介されたあと、この商品はブームになれ、品切れが続いている。", "corrected_sentence": "テレビで紹介されたあと、この商品はブームになり、品切れが続いている。", "error_description": "活用の誤り。連用形「なり」が正しく、「なれ」は命令形で、文の流れに合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38276, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「長期にわたる」の「に」。期間の範囲を表す「にわたる」の形で、文の意味に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すが、「長期がわたる」では主語として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を表すが、「わたる」は目的語を取らないので「長期をわたる」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、「長期でわたる」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「長期にわたる」の「に」。期間の範囲を表す「にわたる」の形で、文の意味に合う。", "が": "「が」は主語を表すが、「長期がわたる」では主語として成り立たない。", "を": "「を」は対象を表すが、「わたる」は目的語を取らないので「長期をわたる」は不自然。", "で": "「で」は場所や手段を表すので、「長期でわたる」は意味が通らない。"}, "error_tags": {"が": "主格", "を": "対象", "で": "場所・手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短期", "is_correct": true, "explanation": "「長期」の対義語。「短期」は短い期間を表し、長期と対になる。"}, {"text": "準備", "is_correct": false, "explanation": "「準備」は事前に整えることで、「長期」の対義語ではない。"}, {"text": "仕事", "is_correct": false, "explanation": "「仕事」は働くことや職務を表し、「長期」とは対義の関係にない。"}, {"text": "計画", "is_correct": false, "explanation": "「計画」は予定を立てることで、「長期」の対義語ではない。"}], "correct_answer": "短期", "explanations": {"短期": "「長期」の対義語。「短期」は短い期間を表し、長期と対になる。", "準備": "「準備」は事前に整えることで、「長期」の対義語ではない。", "仕事": "「仕事」は働くことや職務を表し、「長期」とは対義の関係にない。", "計画": "「計画」は予定を立てることで、「長期」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38276, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「長期に使う」の「に」。長い期間にわたって使うことを表し、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すが、「長期が使う」では主語にならず意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「長期から使う」は起点の意味にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「長期へ使う」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「長期に使う」の「に」。長い期間にわたって使うことを表し、文に合う。", "が": "「が」は主語を表すが、「長期が使う」では主語にならず意味が通らない。", "から": "「から」は起点を表すので、「長期から使う」は起点の意味にならず不自然。", "へ": "「へ」は方向を表すので、「長期へ使う」は意味が通らない。"}, "error_tags": {"が": "主格", "から": "起点", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短期", "is_correct": true, "explanation": "「長期」の対義語。「短期」は短い期間を表し、長期と対になる。"}, {"text": "成果", "is_correct": false, "explanation": "「成果」は努力の結果を表し、「長期」の対義語ではない。"}, {"text": "会社", "is_correct": false, "explanation": "「会社」は事業を行う組織を表し、「長期」とは対義の関係にない。"}, {"text": "見通し", "is_correct": false, "explanation": "「見通し」は先の状況の予想を表し、「長期」の対義語ではない。"}], "correct_answer": "短期", "explanations": {"短期": "「長期」の対義語。「短期」は短い期間を表し、長期と対になる。", "成果": "「成果」は努力の結果を表し、「長期」の対義語ではない。", "会社": "「会社」は事業を行う組織を表し、「長期」とは対義の関係にない。", "見通し": "「見通し」は先の状況の予想を表し、「長期」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38276, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "長い時間が続くこと。", "primary_collocate": null, "pronunciation": "ちょうき", "ipa": "tɕoːki", "syllable_count": 3, "sentences": [{"text": "短期の計画より、長期の計画のほうが準備に時間がかかる。", "target_word": "長期", "complexity_tier": "T3", "furigana": "短期[たんき]の計画[けいかく]より、長期[ちょうき]の計画[けいかく]のほうが準備[じゅんび]に時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "この病気は治療が長期にわたるため、仕事との両立が難しい。", "target_word": "長期", "complexity_tier": "T3", "furigana": "この病気[びょうき]は治療[ちりょう]が長期[ちょうき]にわたるため、仕事[しごと]との両立[りょうりつ]が難[むずか]しい。", "sentence_source": "generated"}, {"text": "長期にわたる雨で、川の水があふれそうになった。", "target_word": "長期", "complexity_tier": "T3", "furigana": "長期[ちょうき]にわたる雨[あめ]で、川[かわ]の水[みず]があふれそうになった。", "sentence_source": "generated"}, {"text": "準備に長期を要する仕事なので、すぐには始められない。", "target_word": "長期", "complexity_tier": "T3", "furigana": "準備[じゅんび]に長期[ちょうき]を要[よう]する仕事[しごと]なので、すぐには始[はじ]められない。", "sentence_source": "generated"}, {"text": "工事が長期に及び、近所の人たちは不満を言っている。", "target_word": "長期", "complexity_tier": "T3", "furigana": "工事[こうじ]が長期[ちょうき]に及[およ]び、近所[きんじょ]の人[ひと]たちは不満[ふまん]を言[い]っている。", "sentence_source": "generated"}, {"text": "短期ではなく長期を見すえて、貯金を始めた。", "target_word": "長期", "complexity_tier": "T3", "furigana": "短期[たんき]ではなく長期[ちょうき]を見[み]すえて、貯金[ちょきん]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "売り上げが長期にわたって落ち込み、店は閉まることになった。", "target_word": "長期", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが長期[ちょうき]にわたって落[お]ち込[こ]み、店[みせ]は閉[し]まることになった。", "sentence_source": "generated"}, {"text": "この薬は短期なら安全だが、長期に使うと体に悪い影響が出る。", "target_word": "長期", "complexity_tier": "T3", "furigana": "この薬[くすり]は短期[たんき]なら安全[あんぜん]だが、長期[ちょうき]に使[つか]うと体[からだ]に悪[わる]い影響[えいきょう]が出[で]る。", "sentence_source": "generated"}, {"text": "戦争が長期の見通しになると、国の経済は苦しくなる。", "target_word": "長期", "complexity_tier": "T3", "furigana": "戦争[せんそう]が長期[ちょうき]の見通[みとお]しになると、国[くに]の経済[けいざい]は苦[くる]しくなる。", "sentence_source": "generated"}, {"text": "短期の成果は出なかったが、長期で見れば会社は成長している。", "target_word": "長期", "complexity_tier": "T3", "furigana": "短期[たんき]の成果[せいか]は出[で]なかったが、長期[ちょうき]で見[み]れば会社[かいしゃ]は成長[せいちょう]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "長期", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "長い期間にわたって続くこと。短期の反対。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 見すえ (Zipf 1.39)']::text[], '039fd23c-3eee-46a3-96b4-4e59688a4301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38276, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "長期", "is_correct": true, "explanation": "ここは「長い期間」の意味。「長期の計画」は期間が長い計画を表し、「短期の計画より」との対比に合う。"}, {"text": "感動", "is_correct": false, "explanation": "「感動」は心が強く動くことで、「感動の計画」とは言えず、対比にもならない。"}, {"text": "高熱", "is_correct": false, "explanation": "「高熱」は体温の高さを表すので、「高熱の計画」は意味が通らない。"}, {"text": "陶器", "is_correct": false, "explanation": "「陶器」は焼き物の器を表し、「陶器の計画」は文の意味に合わない。"}], "explanations": {"長期": "ここは「長い期間」の意味。「長期の計画」は期間が長い計画を表し、「短期の計画より」との対比に合う。", "感動": "「感動」は心が強く動くことで、「感動の計画」とは言えず、対比にもならない。", "高熱": "「高熱」は体温の高さを表すので、「高熱の計画」は意味が通らない。", "陶器": "「陶器」は焼き物の器を表し、「陶器の計画」は文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "長期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は分厚い長期の小説を読み終えた。", "explanation": "長期は期間の長さを表すので、作品の分量には使えない。"}, {"text": "彼女の長期は、粘り強さだ。", "explanation": "長期は期間の長さなので、人の良い点を表す語としては使えない。"}, {"text": "彼は長期を後ろでくくっていた。", "explanation": "長期は時間の長さを表すので、髪の長さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38276, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "長期", "is_correct": true, "explanation": "ここは「長い期間」の意味。「長期にわたって」は長い期間続いたことを表し、文に合う。"}, {"text": "大量", "is_correct": false, "explanation": "「大量」は数量の多さを表し、「大量にわたって」とは言えない。"}, {"text": "重症", "is_correct": false, "explanation": "「重症」は病気や怪我の程度を表すので、「重症にわたって」は意味が通らない。"}, {"text": "過剰", "is_correct": false, "explanation": "「過剰」は必要以上であることを表し、「過剰にわたって」は文の意味に合わない。"}], "explanations": {"長期": "ここは「長い期間」の意味。「長期にわたって」は長い期間続いたことを表し、文に合う。", "大量": "「大量」は数量の多さを表し、「大量にわたって」とは言えない。", "重症": "「重症」は病気や怪我の程度を表すので、「重症にわたって」は意味が通らない。", "過剰": "「過剰」は必要以上であることを表し、「過剰にわたって」は文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "長期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅前には長期の列ができていた。", "explanation": "長期は期間の長さを表すので、列の長さには使えない。"}, {"text": "彼は長期で、人混みでもすぐに見つかる。", "explanation": "長期は期間の長さなので、人の背の高さには使えない。"}, {"text": "祖母は長期が好きで、いつも話が止まらない。", "explanation": "長期は時間の長さを表すので、話し続けることは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38276, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この工事は長期わたるため、近所の人が困っている。", "corrected_sentence": "この工事は長期にわたるため、近所の人が困っている。", "error_description": "「長期」の後の「に」が抜けている誤り。「長期にわたる」の形で期間の範囲を表すので、「に」が必要。誤りは「長期わたる」、正しくは「長期にわたる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38276, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は長期な計画を立てて、新しい工場を建てた。", "corrected_sentence": "会社は長期の計画を立てて、新しい工場を建てた。", "error_description": "「長期」に「な」が付いている誤り。「長期」は名詞なので、「の計画」と続ける。誤りは「長期な」、正しくは「長期の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38277, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短期", "is_correct": true, "explanation": "「長期」の対義語。「短期の休み」は短い期間の休みを表し、長期の休みと対になる。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫」は食品を冷やす家電で、「長期」の対義語ではない。"}, {"text": "中身", "is_correct": false, "explanation": "「中身」は入っている物を表し、「長期」とは対義の関係にない。"}, {"text": "旅行", "is_correct": false, "explanation": "「旅行」は出かけて過ごすことで、「長期」の対義語ではない。"}], "correct_answer": "短期", "explanations": {"短期": "「長期」の対義語。「短期の休み」は短い期間の休みを表し、長期の休みと対になる。", "冷蔵庫": "「冷蔵庫」は食品を冷やす家電で、「長期」の対義語ではない。", "中身": "「中身」は入っている物を表し、「長期」とは対義の関係にない。", "旅行": "「旅行」は出かけて過ごすことで、「長期」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38277, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短期", "is_correct": true, "explanation": "「長期」の対義語。「短期の天気予報」は短い期間の予報を表し、長期の予報と対になる。"}, {"text": "寒さ", "is_correct": false, "explanation": "「寒さ」は気温の低さを表し、「長期」の対義語ではない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は空の状態を表す語で、「長期」とは対義の関係にない。"}, {"text": "厳しさ", "is_correct": false, "explanation": "「厳しさ」は程度の強さを表し、「長期」の対義語ではない。"}], "correct_answer": "短期", "explanations": {"短期": "「長期」の対義語。「短期の天気予報」は短い期間の予報を表し、長期の予報と対になる。", "寒さ": "「寒さ」は気温の低さを表し、「長期」の対義語ではない。", "天気": "「天気」は空の状態を表す語で、「長期」とは対義の関係にない。", "厳しさ": "「厳しさ」は程度の強さを表し、「長期」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38277, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ある状態や期間が、短くなく、先まで続く様子。", "primary_collocate": null, "pronunciation": "ちょうき", "ipa": "tɕoːki", "syllable_count": 3, "sentences": [{"text": "長期の休みが取れたので、祖父母の家に一か月泊まった。", "target_word": "長期", "complexity_tier": "T3", "furigana": "長期[ちょうき]の休[やす]みが取[と]れたので、祖父母[そふぼ]の家[いえ]に一[いっ]か月[げつ]泊[と]まった。", "sentence_source": "generated"}, {"text": "彼は長期の入院を終えて、ようやく家に帰ってきた。", "target_word": "長期", "complexity_tier": "T3", "furigana": "彼[かれ]は長期[ちょうき]の入院[にゅういん]を終[お]えて、ようやく家[いえ]に帰[かえ]ってきた。", "sentence_source": "generated"}, {"text": "長期の出張が続いたので、家族と話す時間が減った。", "target_word": "長期", "complexity_tier": "T3", "furigana": "長期[ちょうき]の出張[しゅっちょう]が続[つづ]いたので、家族[かぞく]と話[はな]す時間[じかん]が減[へ]った。", "sentence_source": "generated"}, {"text": "長期の旅行に出るので、冷蔵庫の中身を空にしておいた。", "target_word": "長期", "complexity_tier": "T3", "furigana": "長期[ちょうき]の旅行[りょこう]に出[で]るので、冷蔵庫[れいぞうこ]の中身[なかみ]を空[から]にしておいた。", "sentence_source": "generated"}, {"text": "長期の契約を結べば、毎月の料金が安くなる。", "target_word": "長期", "complexity_tier": "T3", "furigana": "長期[ちょうき]の契約[けいやく]を結[むす]べば、毎月[まいつき]の料金[りょうきん]が安[やす]くなる。", "sentence_source": "generated"}, {"text": "銀行から長期の資金を借りて、新しい工場を建てた。", "target_word": "長期", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]から長期[ちょうき]の資金[しきん]を借[か]りて、新[あたら]しい工場[こうじょう]を建[た]てた。", "sentence_source": "generated"}, {"text": "長期の計画を立てるときは、五年後の自分を想像してみるといい。", "target_word": "長期", "complexity_tier": "T3", "furigana": "長期[ちょうき]の計画[けいかく]を立[た]てるときは、五年後[ごねんご]の自分[じぶん]を想像[そうぞう]してみるといい。", "sentence_source": "generated"}, {"text": "長期の干ばつが続き、野菜の値段が上がっている。", "target_word": "長期", "complexity_tier": "T3", "furigana": "長期[ちょうき]の干[かん]ばつが続[つづ]き、野菜[やさい]の値段[ねだん]が上[あ]がっている。", "sentence_source": "generated"}, {"text": "彼女は長期の留学を終えて、英語が上手になった。", "target_word": "長期", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は長期[ちょうき]の留学[りゅうがく]を終[お]えて、英語[えいご]が上手[じょうず]になった。", "sentence_source": "generated"}, {"text": "長期の天気予報によると、今年の冬は寒さが厳しいそうだ。", "target_word": "長期", "complexity_tier": "T3", "furigana": "長期[ちょうき]の天気予報[てんきよほう]によると、今年[ことし]の冬[ふゆ]は寒[さむ]さが厳[きび]しいそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "長期", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "「長期の〜」の形で、期間が長く先まで続く様子を表す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039fd23c-3eee-46a3-96b4-4e59688a4301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38277, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "長期", "is_correct": true, "explanation": "ここは「期間が長い」の意味。「長期の休み」は長い期間の休みを表し、文に合う。"}, {"text": "血圧", "is_correct": false, "explanation": "「血圧」は血管の中の圧力を表し、「血圧の休み」は意味が通らない。"}, {"text": "静脈", "is_correct": false, "explanation": "「静脈」は血液を心臓に戻す血管で、「静脈の休み」とは言えない。"}, {"text": "盲目", "is_correct": false, "explanation": "「盲目」は目が見えないことを表し、「盲目の休み」は文の意味に合わない。"}], "explanations": {"長期": "ここは「期間が長い」の意味。「長期の休み」は長い期間の休みを表し、文に合う。", "血圧": "「血圧」は血管の中の圧力を表し、「血圧の休み」は意味が通らない。", "静脈": "「静脈」は血液を心臓に戻す血管で、「静脈の休み」とは言えない。", "盲目": "「盲目」は目が見えないことを表し、「盲目の休み」は文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "長期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その監督の長期の映画は、どれも三時間を超えた。", "explanation": "長期は期間の長さを表すので、映画の長さには使えない。"}, {"text": "長期の選手がゴールを決めた。", "explanation": "長期は期間の長さを表すので、人の背の高さには使えない。"}, {"text": "長期の男が店に入ってきた。", "explanation": "長期は期間の長さなので、髪の長さを表す語としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38277, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "長期", "is_correct": true, "explanation": "ここは「期間が長い」の意味。「長期の計画」は先まで続く長い期間の計画を表し、文に合う。"}, {"text": "盲腸", "is_correct": false, "explanation": "「盲腸」は腹部の臓器の一つで、「盲腸の計画」は意味が通らない。"}, {"text": "口腔", "is_correct": false, "explanation": "「口腔」は口の中を表す語で、「口腔の計画」とは言えない。"}, {"text": "陶器", "is_correct": false, "explanation": "「陶器」は焼き物の器を表し、「陶器の計画」は文の意味に合わない。"}], "explanations": {"長期": "ここは「期間が長い」の意味。「長期の計画」は先まで続く長い期間の計画を表し、文に合う。", "盲腸": "「盲腸」は腹部の臓器の一つで、「盲腸の計画」は意味が通らない。", "口腔": "「口腔」は口の中を表す語で、「口腔の計画」とは言えない。", "陶器": "「陶器」は焼き物の器を表し、「陶器の計画」は文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "長期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝早く、店の前には長期の列ができていた。", "explanation": "長期は期間の長さを表すので、人の列の長さには使えない。"}, {"text": "彼女の長期は、人の話をよく聞けることだ。", "explanation": "長期は期間の長さなので、人の良い点を表す語としては使えない。"}, {"text": "電話の向こうで、父は長期を始めた。", "explanation": "長期は時間の長さを表すので、話を続けることは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38277, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏は長期が休みが取れるので、家族で旅行した。", "corrected_sentence": "夏は長期の休みが取れるので、家族で旅行した。", "error_description": "「長期」の後の助詞が誤り。「長期の休み」と続けて「休み」を修飾するので、「が」ではなく「の」が必要。誤りは「長期が」、正しくは「長期の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38277, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は長期は出張に向けて準備を始めた。", "corrected_sentence": "父は長期の出張に向けて準備を始めた。", "error_description": "「長期」の後の助詞が誤り。「長期の出張」と続けて「出張」を修飾するので、「は」ではなく「の」が必要。誤りは「長期は」、正しくは「長期の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38278, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「身長の基準を決めて」は、決める対象を示す「を」で、身長の基準を定めるという文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「基準が決めて」は基準が決める主体になり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「基準の決めて」は所属の「の」の後に動詞が続き、文が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「基準へ決めて」は方向の「へ」が決定の行為とつながらず、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「身長の基準を決めて」は、決める対象を示す「を」で、身長の基準を定めるという文に合う。", "が": "「基準が決めて」は基準が決める主体になり、文が成り立たない。", "の": "「基準の決めて」は所属の「の」の後に動詞が続き、文が崩れる。", "へ": "「基準へ決めて」は方向の「へ」が決定の行為とつながらず、意味が通らない。"}, "error_tags": {"を": "対象", "が": "主語", "の": "所属", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38278, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「基準にすると」は、基にするという意味で、成績を基準にすると伸びたという文に合う。"}, {"text": "で", "is_correct": false, "explanation": "「基準ですると」は「で」が「する」とつながらず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「基準よりすると」は比較の「より」が「する」の行為と合わず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「基準をすると」は目的語が二つ並ぶ形になり、基にする意味が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「基準にすると」は、基にするという意味で、成績を基準にすると伸びたという文に合う。", "で": "「基準ですると」は「で」が「する」とつながらず、意味が通らない。", "より": "「基準よりすると」は比較の「より」が「する」の行為と合わず、文が成り立たない。", "を": "「基準をすると」は目的語が二つ並ぶ形になり、基にする意味が成り立たない。"}, "error_tags": {"に": "基準・拠り所", "で": "手段", "より": "比較", "を": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38278, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を比べるときに使う、もとになるものです。", "primary_collocate": null, "pronunciation": "きじゅん", "ipa": "kid͡ʑuɴ", "syllable_count": 3, "sentences": [{"text": "値段を基準にして、三つの店を比べた。", "target_word": "基準", "complexity_tier": "T3", "furigana": "値段[ねだん]を基準[きじゅん]にして、三[みっ]つの店[みせ]を比[くら]べた。", "sentence_source": "generated"}, {"text": "身長の基準を決めて、全員の体を測った。", "target_word": "基準", "complexity_tier": "T3", "furigana": "身長[しんちょう]の基準[きじゅん]を決[き]めて、全員[ぜんいん]の体[からだ]を測[はか]った。", "sentence_source": "generated"}, {"text": "同じ基準で比べないと、どちらが大きいか分からない。", "target_word": "基準", "complexity_tier": "T3", "furigana": "同[おな]じ基準[きじゅん]で比[くら]べないと、どちらが大[おお]きいか分[わ]からない。", "sentence_source": "generated"}, {"text": "今月の売り上げを基準にして、来月の目標を立てる。", "target_word": "基準", "complexity_tier": "T3", "furigana": "今月[こんげつ]の売[う]り上[あ]げを基準[きじゅん]にして、来月[らいげつ]の目標[もくひょう]を立[た]てる。", "sentence_source": "generated"}, {"text": "測り方が違うデータは、比べるときの基準にはできない。", "target_word": "基準", "complexity_tier": "T3", "furigana": "測[はか]り方[かた]が違[ちが]うデータは、比[くら]べるときの基準[きじゅん]にはできない。", "sentence_source": "generated"}, {"text": "室温が基準より高いと、冷房が自動で入る。", "target_word": "基準", "complexity_tier": "T3", "furigana": "室温[しつおん]が基準[きじゅん]より高[たか]いと、冷房[れいぼう]が自動[じどう]で入[はい]る。", "sentence_source": "generated"}, {"text": "この線を基準に、まっすぐ布を切ってください。", "target_word": "基準", "complexity_tier": "T3", "furigana": "この線[せん]を基準[きじゅん]に、まっすぐ布[ぬの]を切[き]ってください。", "sentence_source": "generated"}, {"text": "昨年の成績を基準にすると、今年は大きく伸びた。", "target_word": "基準", "complexity_tier": "T3", "furigana": "昨年[さくねん]の成績[せいせき]を基準[きじゅん]にすると、今年[ことし]は大[おお]きく伸[の]びた。", "sentence_source": "generated"}, {"text": "基準になる点がないと、地図の向きが分からない。", "target_word": "基準", "complexity_tier": "T3", "furigana": "基準[きじゅん]になる点[てん]がないと、地図[ちず]の向[む]きが分[わ]からない。", "sentence_source": "generated"}, {"text": "最初に測った数字を基準にして、その後の変化を比べた。", "target_word": "基準", "complexity_tier": "T3", "furigana": "最初[さいしょ]に測[はか]った数字[すうじ]を基準[きじゅん]にして、その後[ご]の変化[へんか]を比[くら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "基準", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "二つ以上のものを比べるときに、ものさしとして使うもとの数値や点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e80f88b3-ea1d-43b4-8f13-7d86ed2c4372') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38278, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基準", "is_correct": true, "explanation": "「値段を基準にして」は、値段をもとにして比べるという意味になり、文脈に合う。"}, {"text": "色", "is_correct": false, "explanation": "「値段を色にして」は、色を比べのもとにするという意味になり、文が成り立たない。"}, {"text": "地図", "is_correct": false, "explanation": "「値段を地図にして」は、地図を比べのもとにする意味になり、文脈に合わない。"}, {"text": "距離", "is_correct": false, "explanation": "「値段を距離にして」は意味が通らず、値段を比べるための基準にはならない。"}], "explanations": {"基準": "「値段を基準にして」は、値段をもとにして比べるという意味になり、文脈に合う。", "色": "「値段を色にして」は、色を比べのもとにするという意味になり、文が成り立たない。", "地図": "「値段を地図にして」は、地図を比べのもとにする意味になり、文脈に合わない。", "距離": "「値段を距離にして」は意味が通らず、値段を比べるための基準にはならない。"}, "sentence_index": 0, "correct_answer": "基準"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は遅れた基準をわかりやすく説明してくれた。", "explanation": "ここは〈理由〉の意味。遅れた原因を説明するのは理由で、比べるもとの数値や点を表す基準は説明の対象にならない。"}, {"text": "旅行中、山の基準をずっと眺めていた。", "explanation": "ここは〈景色〉の意味。眺めるのは目に見える景色で、比べるもとになる点や数値の基準は眺められない。"}, {"text": "薬を飲んで、基準を治した。", "explanation": "ここは〈病気〉の意味。治すのは病気や怪我で、比べるための基準は治療の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38278, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基準", "is_correct": true, "explanation": "「この線を基準に」は、この線をもとにして布を切るという意味で、文脈に合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「この線を鉛筆に」は、線を道具にするという意味になり、布を切る指示として成り立たない。"}, {"text": "針", "is_correct": false, "explanation": "「この線を針に」は、線を道具にする意味になり、文脈に合わない。"}, {"text": "糸", "is_correct": false, "explanation": "「この線を糸に」は、線を材料にする意味になり、まっすぐ布を切る指示には合わない。"}], "explanations": {"基準": "「この線を基準に」は、この線をもとにして布を切るという意味で、文脈に合う。", "鉛筆": "「この線を鉛筆に」は、線を道具にするという意味になり、布を切る指示として成り立たない。", "針": "「この線を針に」は、線を道具にする意味になり、文脈に合わない。", "糸": "「この線を糸に」は、線を材料にする意味になり、まっすぐ布を切る指示には合わない。"}, "sentence_index": 6, "correct_answer": "基準"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達と並んで、基準を撮った。", "explanation": "ここは〈写真〉の意味。撮れるのは写真などの映像で、比べるもとの数値や点は撮影の対象にならない。"}, {"text": "夕方になって、基準が降り始めた。", "explanation": "ここは〈雨〉の意味。降るのは雨や雪で、比べるもとの基準は降りはしない。"}, {"text": "夏休みの最後に、基準を終わらせた。", "explanation": "ここは〈宿題〉の意味。終わらせるのは宿題などの課題で、比べるもとの数値や点は終わらせる対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38278, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "季節の変化を基準をして、作物を選ぶ。", "corrected_sentence": "季節の変化を基準にして、作物を選ぶ。", "error_description": "「基準にして」の「に」は、基準を拠り所にする意味で使う助詞。「を」を続けると「基準をする」となり、意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38278, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "平均点を基準を、合格者を決めた。", "corrected_sentence": "平均点を基準に、合格者を決めた。", "error_description": "判断のもとにするときは「基準に」と書く。「基準を」と続けると目的語が二つ重なり、意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38279, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「基準にして」は判断の拠り所を示し、態度を基準にして決めるという文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「基準がして決める」は基準が主語になり、「にして」の形が崩れて文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「基準をして決める」は目的語になり、「にして」の意味が成り立たず不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "「基準の、して決める」は所属の「の」の後に文が続かず、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「基準にして」は判断の拠り所を示し、態度を基準にして決めるという文に合う。", "が": "「基準がして決める」は基準が主語になり、「にして」の形が崩れて文が成り立たない。", "を": "「基準をして決める」は目的語になり、「にして」の意味が成り立たず不自然になる。", "の": "「基準の、して決める」は所属の「の」の後に文が続かず、意味が通らない。"}, "error_tags": {"に": "基準・拠り所", "が": "主語", "を": "対象", "の": "所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38279, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「基準に選ぶ」は判断の拠り所を示し、何を基準に選ぶかという文に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「基準へ選ぶ」は方向の「へ」が選ぶ行為とつながらず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「基準より選ぶ」は比較の「より」が選ぶ行為に合わず、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「基準が選ぶ」は基準が主語になり、「何を」と合わず文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「基準に選ぶ」は判断の拠り所を示し、何を基準に選ぶかという文に合う。", "へ": "「基準へ選ぶ」は方向の「へ」が選ぶ行為とつながらず、意味が通らない。", "より": "「基準より選ぶ」は比較の「より」が選ぶ行為に合わず、文が成り立たない。", "が": "「基準が選ぶ」は基準が主語になり、「何を」と合わず文が成り立たない。"}, "error_tags": {"に": "基準・拠り所", "へ": "方向", "より": "比較", "が": "主格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38279, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "判断や評価のための基盤となる、よりどころ。", "primary_collocate": null, "pronunciation": "きじゅん", "ipa": "kid͡ʑuɴ", "syllable_count": 3, "sentences": [{"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "基準", "complexity_tier": "T3", "furigana": "かかる感覚的[かんかくてき]知見[ちけん]の蓄積[ちくせき]は、単一[たんいつ]品種[ひんしゅ]を基準[きじゅん]とした旧来[きゅうらい]の分類[ぶんるい]体系[たいけい]を相対化[そうたいか]し、微細[びさい]な区画[くかく]ごとの個性[こせい]を階層的[かいそうてき]に位置[いち]づけるアペラシオンの概念[がいねん]を、より厳密[げんみつ]かつ動的[どうてき]なヒエラルキーへと昇華[しょうか]させ、ワインの価値[かち]評価[ひょうか]基準[きじゅん]そのものを哲学的[てつがくてき]かつ実践的[じっせんてき]に再定義[さいていぎ]しているのである。", "sentence_source": "mined"}, {"text": "合格かどうかは、点数ではなく態度を基準にして決める。", "target_word": "基準", "complexity_tier": "T3", "furigana": "合格[ごうかく]かどうかは、点数[てんすう]ではなく態度[たいど]を基準[きじゅん]にして決[き]める。", "sentence_source": "generated"}, {"text": "この店は、味の基準が厳しいことで有名だ。", "target_word": "基準", "complexity_tier": "T3", "furigana": "この店[みせ]は、味[あじ]の基準[きじゅん]が厳[きび]しいことで有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "安全の基準を満たしていない製品は、売ることができない。", "target_word": "基準", "complexity_tier": "T3", "furigana": "安全[あんぜん]の基準[きじゅん]を満[み]たしていない製品[せいひん]は、売[う]ることができない。", "sentence_source": "generated"}, {"text": "評価の基準があいまいだと、採点する人によって結果が変わってしまう。", "target_word": "基準", "complexity_tier": "T3", "furigana": "評価[ひょうか]の基準[きじゅん]があいまいだと、採点[さいてん]する人[ひと]によって結果[けっか]が変[か]わってしまう。", "sentence_source": "generated"}, {"text": "給料は、経験年数を基準に決められている。", "target_word": "基準", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]は、経験[けいけん]年数[ねんすう]を基準[きじゅん]に決[き]められている。", "sentence_source": "generated"}, {"text": "新しい基準が決まり、建物の高さに制限がかかった。", "target_word": "基準", "complexity_tier": "T3", "furigana": "新[あたら]しい基準[きじゅん]が決[き]まり、建物[たてもの]の高[たか]さに制限[せいげん]がかかった。", "sentence_source": "generated"}, {"text": "何を基準に選ぶかによって、一番よい答えは変わる。", "target_word": "基準", "complexity_tier": "T3", "furigana": "何[なに]を基準[きじゅん]に選[えら]ぶかによって、一番[いちばん]よい答[こた]えは変[か]わる。", "sentence_source": "generated"}, {"text": "国によって環境の基準が違うため、輸出には注意が必要だ。", "target_word": "基準", "complexity_tier": "T3", "furigana": "国[くに]によって環境[かんきょう]の基準[きじゅん]が違[ちが]うため、輸出[ゆしゅつ]には注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "彼は自分の基準で人を判断しすぎるところがある。", "target_word": "基準", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の基準[きじゅん]で人[ひと]を判断[はんだん]しすぎるところがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "基準", "label": "基本形"}], "register": "formal", "sense_fingerprint": "合否や良し悪しを判断・評価するときのよりどころとなる決まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: アペラシオン (Zipf 1.01)']::text[], 'e80f88b3-ea1d-43b4-8f13-7d86ed2c4372') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38279, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基準", "is_correct": true, "explanation": "「単一品種を基準とした」は、単一品種を判断のよりどころにする意味で自然に通る。"}, {"text": "栽培", "is_correct": false, "explanation": "「単一品種を栽培とした」は、栽培は行為であり判断のよりどころにはならず、意味が通らない。"}, {"text": "産地", "is_correct": false, "explanation": "「単一品種を産地とした」は、産地が品種の拠り所になるという意味にならず、不自然。"}, {"text": "熟成", "is_correct": false, "explanation": "「単一品種を熟成とした」は、熟成は行為や過程で、判断の拠り所とは結びつかず成り立たない。"}], "explanations": {"基準": "「単一品種を基準とした」は、単一品種を判断のよりどころにする意味で自然に通る。", "栽培": "「単一品種を栽培とした」は、栽培は行為であり判断のよりどころにはならず、意味が通らない。", "産地": "「単一品種を産地とした」は、産地が品種の拠り所になるという意味にならず、不自然。", "熟成": "「単一品種を熟成とした」は、熟成は行為や過程で、判断の拠り所とは結びつかず成り立たない。"}, "sentence_index": 0, "correct_answer": "基準"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は基準がとても温かい人で、皆に好かれている。", "explanation": "ここは〈人柄〉の意味。人の性格を温かいと言うのであって、判断のよりどころの基準には温かさを表せない。"}, {"text": "彼女は基準がとても豊かで、よく笑う。", "explanation": "ここは〈感情〉の意味。豊かさは感情について言う語で、判断の決まりである基準には使えない。"}, {"text": "この建物は基準が丈夫だ。", "explanation": "ここは〈基礎〉の意味。建物の土台を指す基礎が丈夫だと言うところで、判断の決まりを指す基準は土台にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38279, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基準", "is_correct": true, "explanation": "「新しい基準が決まり」は、新しい判断の決まりが定まったという意味で、建物の高さ制限の流れに合う。"}, {"text": "期限", "is_correct": false, "explanation": "「新しい期限が決まり」は時間の区切りの話になり、建物の高さ制限を決める根拠とはつながらない。"}, {"text": "目標", "is_correct": false, "explanation": "「新しい目標が決まり」は目指す到達点の意味になり、建物の高さ制限の決定とはかみ合わない。"}, {"text": "予定", "is_correct": false, "explanation": "「新しい予定が決まり」は日程の意味になり、建物の高さに制限がかかる流れに合わない。"}], "explanations": {"基準": "「新しい基準が決まり」は、新しい判断の決まりが定まったという意味で、建物の高さ制限の流れに合う。", "期限": "「新しい期限が決まり」は時間の区切りの話になり、建物の高さ制限を決める根拠とはつながらない。", "目標": "「新しい目標が決まり」は目指す到達点の意味になり、建物の高さ制限の決定とはかみ合わない。", "予定": "「新しい予定が決まり」は日程の意味になり、建物の高さに制限がかかる流れに合わない。"}, "sentence_index": 6, "correct_answer": "基準"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部屋の基準を明るくして、本を読んだ。", "explanation": "ここは〈照明〉の意味。部屋を明るくするのは照明で、判断のよりどころを指す基準は明るさを変えるものではない。"}, {"text": "今日は基準が悪いので、洗濯物を外に干せない。", "explanation": "ここは〈天気〉の意味。雨や晴れの具合を言うのが天気で、判断のよりどころの基準では表せない。"}, {"text": "この服は基準が褪せてしまった。", "explanation": "ここは〈色〉の意味。褪せるのは色についての言い方で、判断の決まりである基準は色あせることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38279, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "合格の基準を達した人だけが選ばれた。", "corrected_sentence": "合格の基準に達した人だけが選ばれた。", "error_description": "「達する」は到達先を「に」で示すので、基準には「に」が正しい。「を」は他動詞の目的語に使う助詞で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38279, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この基準に守れば、合格できる。", "corrected_sentence": "この基準を守れば、合格できる。", "error_description": "「守る」は守るものを「を」で示すので、「基準を守る」が正しい。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38280, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「金融の会社」のように、名詞と名詞を「の」でつなぐ用法で、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「金融が会社で働く」となり、金融という仕組みが働くことになって不自然。"}, {"text": "を", "is_correct": false, "explanation": "「金融を会社で働く」は、働くという動作の対象にならないので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「金融に会社で働く」は、名詞同士をつなぐ用法がなく不自然。"}], "correct_answer": "の", "explanations": {"の": "「金融の会社」のように、名詞と名詞を「の」でつなぐ用法で、文に合う。", "が": "「金融が会社で働く」となり、金融という仕組みが働くことになって不自然。", "を": "「金融を会社で働く」は、働くという動作の対象にならないので不自然。", "に": "「金融に会社で働く」は、名詞同士をつなぐ用法がなく不自然。"}, "error_tags": {"が": "主格", "を": "目的格", "に": "帰着点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38280, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「扱う」の目的語を示す「を」で、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「金融に扱う」では、扱う対象を示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「金融と扱う」は並列の相手を示すだけで、扱う対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「金融へ扱う」は方向を示すが、扱う対象を表せないので不自然。"}], "correct_answer": "を", "explanations": {"を": "「扱う」の目的語を示す「を」で、文に合う。", "に": "「金融に扱う」では、扱う対象を示せず不自然。", "と": "「金融と扱う」は並列の相手を示すだけで、扱う対象にはならない。", "へ": "「金融へ扱う」は方向を示すが、扱う対象を表せないので不自然。"}, "error_tags": {"に": "着点", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38280, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お金の貸し借りや投資など、資金の流れをあつかう仕事や仕組みのこと。", "primary_collocate": null, "pronunciation": "きんゆう", "ipa": "kiɴjɯː", "syllable_count": 4, "sentences": [{"text": "金融は、お金を貸したり借りたりする仕事の全体を指す。", "target_word": "金融", "complexity_tier": "T3", "furigana": "金融[きんゆう]は、お金[かね]を貸[か]したり借[か]りたりする仕事[しごと]の全体[ぜんたい]を指[さ]す。", "sentence_source": "generated"}, {"text": "兄は大学を出てから、金融の会社で働いている。", "target_word": "金融", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]を出[で]てから、金融[きんゆう]の会社[かいしゃ]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "金融の仕組みを知らないと、ローンの利子が理解できない。", "target_word": "金融", "complexity_tier": "T3", "furigana": "金融[きんゆう]の仕組[しく]みを知[し]らないと、ローンの利子[りし]が理解[りかい]できない。", "sentence_source": "generated"}, {"text": "世界的な不況で、金融の世界は大きく揺れた。", "target_word": "金融", "complexity_tier": "T3", "furigana": "世界的[せかいてき]な不況[ふきょう]で、金融[きんゆう]の世界[せかい]は大[おお]きく揺[ゆ]れた。", "sentence_source": "generated"}, {"text": "金融に強い弁護士に、会社の借金について相談した。", "target_word": "金融", "complexity_tier": "T3", "furigana": "金融[きんゆう]に強[つよ]い弁護士[べんごし]に、会社[かいしゃ]の借金[しゃっきん]について相談[そうだん]した。", "sentence_source": "generated"}, {"text": "金融の専門家は、金利が上がると家を買う人が減ると話した。", "target_word": "金融", "complexity_tier": "T3", "furigana": "金融[きんゆう]の専門家[せんもんか]は、金利[きんり]が上[あ]がると家[いえ]を買[か]う人[ひと]が減[へ]ると話[はな]した。", "sentence_source": "generated"}, {"text": "金融について学ぶために、経済の本を何冊も読んだ。", "target_word": "金融", "complexity_tier": "T3", "furigana": "金融[きんゆう]について学[まな]ぶために、経済[けいざい]の本[ほん]を何冊[なんさつ]も読[よ]んだ。", "sentence_source": "generated"}, {"text": "この町には、金融を扱う大きな銀行の本店がある。", "target_word": "金融", "complexity_tier": "T3", "furigana": "この町[まち]には、金融[きんゆう]を扱[あつか]う大[おお]きな銀行[ぎんこう]の本店[ほんてん]がある。", "sentence_source": "generated"}, {"text": "金融が不安定になると、会社は必要なお金を借りにくくなる。", "target_word": "金融", "complexity_tier": "T3", "furigana": "金融[きんゆう]が不安定[ふあんてい]になると、会社[かいしゃ]は必要[ひつよう]なお金[かね]を借[か]りにくくなる。", "sentence_source": "generated"}, {"text": "金融の知識がなかったので、投資の話がよく分からなかった。", "target_word": "金融", "complexity_tier": "T3", "furigana": "金融[きんゆう]の知識[ちしき]がなかったので、投資[とうし]の話[はなし]がよく分[わ]からなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "金融", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "お金の貸し借りや投資など、資金の流れをあつかう仕事や仕組み。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039fd23c-3eee-46a3-96b4-4e59688a4301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38280, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金融", "is_correct": true, "explanation": "「お金の貸し借りや投資などの仕組み全体」を指す語で、文の定義に合う。"}, {"text": "医療", "is_correct": false, "explanation": "医療は病気の治療を指す語で、お金の貸し借りの仕事全体を指すとは言えない。"}, {"text": "農業", "is_correct": false, "explanation": "農業は作物や家畜を育てる仕事なので、貸し借りの仕事の全体には当たらない。"}, {"text": "交通", "is_correct": false, "explanation": "交通は人や物を運ぶことを指し、お金を扱う仕事とは無関係なので文に合わない。"}], "explanations": {"金融": "「お金の貸し借りや投資などの仕組み全体」を指す語で、文の定義に合う。", "医療": "医療は病気の治療を指す語で、お金の貸し借りの仕事全体を指すとは言えない。", "農業": "農業は作物や家畜を育てる仕事なので、貸し借りの仕事の全体には当たらない。", "交通": "交通は人や物を運ぶことを指し、お金を扱う仕事とは無関係なので文に合わない。"}, "sentence_index": 0, "correct_answer": "金融"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国の金融が赤字なので、消費税の引き上げが議論されている。", "explanation": "ここは〈財政〉の意味。国や自治体のお金の収支を指すので、金融（お金の貸し借りや投資の仕組み）とは合わない。"}, {"text": "引っ越してから、金融の住民と毎朝あいさつを交わしている。", "explanation": "ここは〈近隣〉（近所）の意味。金融は人を指さないので、住民には使えない。"}, {"text": "道で金融を拾って、交番に届けた。", "explanation": "ここは〈金銭〉（お金そのもの）の意味。金融は仕組みを指し、拾って届けるものにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38280, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金融", "is_correct": true, "explanation": "「金融について学ぶ」は、後ろの「経済の本」と話題がつながり、文に合う。"}, {"text": "料理", "is_correct": false, "explanation": "「料理について学ぶために、経済の本を何冊も読んだ」は話題がつながらず不自然。"}, {"text": "手芸", "is_correct": false, "explanation": "「手芸について学ぶために、経済の本を何冊も読んだ」は後ろの経済の本と噛み合わない。"}, {"text": "天文", "is_correct": false, "explanation": "天文は天体の学問で、経済の本を何冊も読む理由として文が成り立たない。"}], "explanations": {"金融": "「金融について学ぶ」は、後ろの「経済の本」と話題がつながり、文に合う。", "料理": "「料理について学ぶために、経済の本を何冊も読んだ」は話題がつながらず不自然。", "手芸": "「手芸について学ぶために、経済の本を何冊も読んだ」は後ろの経済の本と噛み合わない。", "天文": "天文は天体の学問で、経済の本を何冊も読む理由として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "金融"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "金融の板で、ドアの取っ手を作った。", "explanation": "ここは〈金属〉の意味。金融は材料の名前ではないので、金属の板の代わりには使えない。"}, {"text": "金融を水槽で飼い始めた。", "explanation": "ここは〈金魚〉の意味。金融は生き物を指さないので、水槽で飼う対象にはならない。"}, {"text": "彼は金融にしたので、クラスで目立つようになった。", "explanation": "ここは〈金髪〉（髪の色）の意味。金融は髪の色には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38280, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は金融が詳しいので、ローンの相談に乗ってくれた。", "corrected_sentence": "彼女は金融に詳しいので、ローンの相談に乗ってくれた。", "error_description": "「詳しい」は「に」を取るので、「金融が」は誤り。正しくは「金融に詳しい」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38280, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は金融をくわしい人に、仕組みを聞いた。", "corrected_sentence": "私は金融にくわしい人に、仕組みを聞いた。", "error_description": "「くわしい」は「に」を取るので、「金融を」は誤り。正しくは「金融にくわしい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38282, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「ファンドで本を買う」は、ファンドのお金を使って買う手段を表し、自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「ファンドを本を買う」と目的語が二つ重なり、文が成り立たないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「ファンドに本を買う」では、ファンドを買う先や相手として扱うことになり、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「ファンドへ本を買う」は方向を表すが、ファンドは本を買う方向にはなりえないので合わない。"}], "correct_answer": "で", "explanations": {"で": "「ファンドで本を買う」は、ファンドのお金を使って買う手段を表し、自然に成り立つ。", "を": "「ファンドを本を買う」と目的語が二つ重なり、文が成り立たないので合わない。", "に": "「ファンドに本を買う」では、ファンドを買う先や相手として扱うことになり、意味が通らない。", "へ": "「ファンドへ本を買う」は方向を表すが、ファンドは本を買う方向にはなりえないので合わない。"}, "error_tags": {"を": "目的語の重複", "に": "相手・場所の格", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38282, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「動物を守るファンドに」は、お金を送る先を表し、文として正しく成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「ファンドを、毎月少しずつお金を送っている」では、ファンドを送る物として扱うことになり不自然。"}, {"text": "の", "is_correct": false, "explanation": "「ファンドの、毎月少しずつ」と続くと句の切れ目が不自然で、送る先を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「ファンドと、毎月少しずつ」は並列になり、送る先として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「動物を守るファンドに」は、お金を送る先を表し、文として正しく成り立つ。", "を": "「ファンドを、毎月少しずつお金を送っている」では、ファンドを送る物として扱うことになり不自然。", "の": "「ファンドの、毎月少しずつ」と続くと句の切れ目が不自然で、送る先を示せない。", "と": "「ファンドと、毎月少しずつ」は並列になり、送る先として成り立たない。"}, "error_tags": {"を": "目的語の格", "の": "連体修飾", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38282, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お金を集めて、みんなで何かをするためにつかうお金のことです。", "primary_collocate": null, "pronunciation": "ふぁんど", "ipa": "ɸaɴdo", "syllable_count": 3, "sentences": [{"text": "町の人がお金を出し合って、ファンドを作った。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]がお金[かね]を出[だ]し合[あ]って、ファンドを作[つく]った。", "sentence_source": "generated"}, {"text": "学校の図書館のために、ファンドで本を買う。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "学校[がっこう]の図書館[としょかん]のために、ファンドで本[ほん]を買[か]う。", "sentence_source": "generated"}, {"text": "このファンドは、災害にあった人を助けるために集められた。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "このファンドは、災害[さいがい]にあった人[ひと]を助[たす]けるために集[あつ]められた。", "sentence_source": "generated"}, {"text": "村の祭りを続けるため、みんなでファンドに寄付した。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "村[むら]の祭[まつ]りを続[つづ]けるため、みんなでファンドに寄付[きふ]した。", "sentence_source": "generated"}, {"text": "ファンドが集まれば、新しい遊び場を建てられる。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "ファンドが集[あつ]まれば、新[あたら]しい遊[あそ]び場[ば]を建[た]てられる。", "sentence_source": "generated"}, {"text": "友人たちは旅行用のファンドを作り、毎月千円ずつ出している。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "友人[ゆうじん]たちは旅行用[りょこうよう]のファンドを作[つく]り、毎月[まいつき]千円[せんえん]ずつ出[だ]している。", "sentence_source": "generated"}, {"text": "ファンドのお金は、子どもたちの給食費に使われる。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "ファンドのお金[かね]は、子[こ]どもたちの給食費[きゅうしょくひ]に使[つか]われる。", "sentence_source": "generated"}, {"text": "動物を守るファンドに、毎月少しずつお金を送っている。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "動物[どうぶつ]を守[まも]るファンドに、毎月[まいつき]少[すこ]しずつお金[かね]を送[おく]っている。", "sentence_source": "generated"}, {"text": "ファンドの代表が、集まったお金の使い道を発表した。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "ファンドの代表[だいひょう]が、集[あつ]まったお金[かね]の使[つか]い道[みち]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "地域のファンドのおかげで、古い橋を直すことができた。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "地域[ちいき]のファンドのおかげで、古[ふる]い橋[はし]を直[なお]すことができた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ファンド", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "みんなで出し合って、共通の目的に使うために集めたお金(基金)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fb64f-2b7d-47f2-a572-4d369e136007') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38282, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ファンド", "is_correct": true, "explanation": "出し合ったお金を共通の目的のために集めた基金を指し、「ファンドを作った」と自然につながる。"}, {"text": "ため息", "is_correct": false, "explanation": "ため息は「つく」ものであり、お金を出し合って作る対象にはならないので空欄に入らない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は「覚える」ものであり、作るものではないので空欄に入らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は作るものではなく、お金を出し合う文脈とも合わないので空欄に入らない。"}], "explanations": {"ファンド": "出し合ったお金を共通の目的のために集めた基金を指し、「ファンドを作った」と自然につながる。", "ため息": "ため息は「つく」ものであり、お金を出し合って作る対象にはならないので空欄に入らない。", "眠気": "眠気は「覚える」ものであり、作るものではないので空欄に入らない。", "天気": "天気は作るものではなく、お金を出し合う文脈とも合わないので空欄に入らない。"}, "sentence_index": 0, "correct_answer": "ファンド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女はそのバンドの熱心なファンドだ。", "explanation": "ファンドには「応援する人（ファン）」の意味はなく、この文では合わない。"}, {"text": "ファンドの返済が終わって、ほっとした。", "explanation": "ファンドには「借金」の意味はなく、返済する借金の意味では使えない。"}, {"text": "今日の出来事を、ファンドに書いた。", "explanation": "ファンドには「日記」の意味はなく、出来事を書き留める帳面の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38282, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ファンド", "is_correct": true, "explanation": "集めたお金を共通の目的に使う基金を指し、「ファンドのお金」と自然に続く。"}, {"text": "呼吸", "is_correct": false, "explanation": "呼吸は体の働きであり、お金の出どころや持ち主にはならないので空欄に入らない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている人が出す息で、お金の話には当てはまらないので空欄に入らない。"}, {"text": "鼻水", "is_correct": false, "explanation": "鼻水はお金と結びつかず、空欄に入れると文が成り立たない。"}], "explanations": {"ファンド": "集めたお金を共通の目的に使う基金を指し、「ファンドのお金」と自然に続く。", "呼吸": "呼吸は体の働きであり、お金の出どころや持ち主にはならないので空欄に入らない。", "寝息": "寝息は眠っている人が出す息で、お金の話には当てはまらないので空欄に入らない。", "鼻水": "鼻水はお金と結びつかず、空欄に入れると文が成り立たない。"}, "sentence_index": 6, "correct_answer": "ファンド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "財布に残ったファンドで、ジュースを買った。", "explanation": "ファンドには「小銭」の意味はなく、財布に残った現金の意味では使えない。"}, {"text": "ファンドは、自分の好きなように使ってよいお金だ。", "explanation": "ファンドには「小遣い」の意味はなく、個人が自由に使うお金の意味では使えない。"}, {"text": "ファンドは、仕事への対価として毎月支払われる。", "explanation": "ファンドには「報酬」の意味はなく、働いた対価として払われるお金の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38282, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村の人たちは、ファンドに立ち上げた。", "corrected_sentence": "村の人たちは、ファンドを立ち上げた。", "error_description": "「立ち上げる」の対象はファンドなので目的語の「を」が正しく、「に」は誤り。「に」だと立ち上げる先になり、ファンドを作るという意味が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38282, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の人たちは、ファンドの寄付した。", "corrected_sentence": "町の人たちは、ファンドに寄付した。", "error_description": "寄付先を示す「に」が「の」に変わっており、「寄付した」に続く寄付先が示されない。正しくは「ファンドに寄付した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38283, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「このファンドは」と主題を示し、ファンドについて述べる文として正しい。"}, {"text": "の", "is_correct": false, "explanation": "「このファンドの、」と続くと名詞が欠け、投資の主語として文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「このファンドと、世界の株式に投資している」は並列になり、主語が一つに定まらず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「このファンドへ」は方向を表すが、ファンドが投資の向きになるような文ではないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「このファンドは」と主題を示し、ファンドについて述べる文として正しい。", "の": "「このファンドの、」と続くと名詞が欠け、投資の主語として文が成り立たない。", "と": "「このファンドと、世界の株式に投資している」は並列になり、主語が一つに定まらず不自然。", "へ": "「このファンドへ」は方向を表すが、ファンドが投資の向きになるような文ではないので合わない。"}, "error_tags": {"の": "連体修飾", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38283, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ファンドの価格は」と、ファンドの値段を示す連体の「の」で正しく続く。"}, {"text": "が", "is_correct": false, "explanation": "「ファンドが価格は」と主語が二つ重なり、ファンドの値段を示す形にならないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「ファンドで価格は」は手段の意味になり、ファンドの値段を示す文としては成り立たないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「ファンドから価格は」は起点の意味になり、ファンドの値段を示せないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「ファンドの価格は」と、ファンドの値段を示す連体の「の」で正しく続く。", "が": "「ファンドが価格は」と主語が二つ重なり、ファンドの値段を示す形にならないので合わない。", "で": "「ファンドで価格は」は手段の意味になり、ファンドの値段を示す文としては成り立たないので合わない。", "から": "「ファンドから価格は」は起点の意味になり、ファンドの値段を示せないので合わない。"}, "error_tags": {"が": "主語の重複", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38283, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "投資や事業のために、複数の出資者から集められた資金のこと。特に、株式や債券などで運用される資産のまとまりを指す。", "primary_collocate": null, "pronunciation": "ふぁんど", "ipa": "ɸaɴdo", "syllable_count": 3, "sentences": [{"text": "彼は退職金の一部をファンドで運用している。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "彼[かれ]は退職金[たいしょくきん]の一部[いちぶ]をファンドで運用[うんよう]している。", "sentence_source": "generated"}, {"text": "このファンドは、世界の株式に投資している。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "このファンドは、世界[せかい]の株式[かぶしき]に投資[とうし]している。", "sentence_source": "generated"}, {"text": "複数の投資家から資金を集めて、ファンドが作られた。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "複数[ふくすう]の投資家[とうしか]から資金[しきん]を集[あつ]めて、ファンドが作[つく]られた。", "sentence_source": "generated"}, {"text": "ファンドの運用成績が悪く、投資家は不満を口にした。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "ファンドの運用成績[うんようせいせき]が悪[わる]く、投資家[とうしか]は不満[ふまん]を口[くち]にした。", "sentence_source": "generated"}, {"text": "債券中心のファンドは、値動きが比較的小さい。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "債券中心[さいけんちゅうしん]のファンドは、値動[ねうご]きが比較的[ひかくてき]小[ちい]さい。", "sentence_source": "generated"}, {"text": "運用会社は、新しいファンドの募集を始めた。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "運用会社[うんようがいしゃ]は、新[あたら]しいファンドの募集[ぼしゅう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼女はファンドに毎月一万円ずつ積み立てている。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はファンドに毎月[まいつき]一万円[いちまんえん]ずつ積[つ]み立[た]てている。", "sentence_source": "generated"}, {"text": "ファンドの価格は、組み入れた株の値段によって上下する。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "ファンドの価格[かかく]は、組[く]み入[い]れた株[かぶ]の値段[ねだん]によって上下[じょうげ]する。", "sentence_source": "generated"}, {"text": "手数料の安いファンドを選ぶのが大切だ。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "手数料[てすうりょう]の安[やす]いファンドを選[えら]ぶのが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "大手の運用会社が、環境分野に投資するファンドを立ち上げた。", "target_word": "ファンド", "complexity_tier": "T3", "furigana": "大手[おおて]の運用会社[うんようがいしゃ]が、環境分野[かんきょうぶんや]に投資[とうし]するファンドを立[た]ち上[あ]げた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ファンド", "label": "基本形"}], "register": "business", "sense_fingerprint": "複数の出資者から集めて株式・債券などで運用する投資資金(投資ファンド)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fb64f-2b7d-47f2-a572-4d369e136007') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38283, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ファンド", "is_correct": true, "explanation": "投資のために集めた資金を指し、「ファンドで運用する」と自然につながる。"}, {"text": "返済", "is_correct": false, "explanation": "返済は借金を返すことで、運用の手段にはならないので空欄に入らない。"}, {"text": "罰金", "is_correct": false, "explanation": "罰金は科されるお金で、運用の手段ではないので空欄に入らない。"}, {"text": "解約", "is_correct": false, "explanation": "解約は契約を終わらせることで、お金を運用する手段にはならないので空欄に入らない。"}], "explanations": {"ファンド": "投資のために集めた資金を指し、「ファンドで運用する」と自然につながる。", "返済": "返済は借金を返すことで、運用の手段にはならないので空欄に入らない。", "罰金": "罰金は科されるお金で、運用の手段ではないので空欄に入らない。", "解約": "解約は契約を終わらせることで、お金を運用する手段にはならないので空欄に入らない。"}, "sentence_index": 0, "correct_answer": "ファンド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ファンドを毎月払って、部屋を借りている。", "explanation": "ファンドには「家賃」の意味はなく、部屋を借りる対価の意味では使えない。"}, {"text": "給料の一部は、ファンドに預金して利息を受け取っている。", "explanation": "ファンドには「定期預金」の意味はなく、元本が守られて利息がつく預金の意味では使えない。"}, {"text": "ファンドは、毎月の仕事への対価として支払われる。", "explanation": "ファンドには「給料」の意味はなく、働いた対価として払われるお金の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38283, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ファンド", "is_correct": true, "explanation": "積み立て先として集めた資金を指し、「ファンドに積み立てている」と自然に続く。"}, {"text": "家賃", "is_correct": false, "explanation": "家賃は住む場所の対価であり、積み立ての先にはならないので空欄に入らない。"}, {"text": "利息", "is_correct": false, "explanation": "利息はお金に付く利益で、積み立てる先ではないので空欄に入らない。"}, {"text": "返金", "is_correct": false, "explanation": "返金は払ったお金が戻ることで、積み立ての先とは合わないので空欄に入らない。"}], "explanations": {"ファンド": "積み立て先として集めた資金を指し、「ファンドに積み立てている」と自然に続く。", "家賃": "家賃は住む場所の対価であり、積み立ての先にはならないので空欄に入らない。", "利息": "利息はお金に付く利益で、積み立てる先ではないので空欄に入らない。", "返金": "返金は払ったお金が戻ることで、積み立ての先とは合わないので空欄に入らない。"}, "sentence_index": 6, "correct_answer": "ファンド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ファンドは、貸したお金を利子をつけて返してもらうものだ。", "explanation": "ファンドには「貸付金」の意味はなく、利子をつけて返してもらう貸し出しの意味では使えない。"}, {"text": "ファンドは、会社を辞めるときに一度だけもらえる。", "explanation": "ファンドには「退職金」の意味はなく、退職時に一度払われるお金の意味では使えない。"}, {"text": "ファンドは、交通違反をした人が払うお金だ。", "explanation": "ファンドには「罰金」の意味はなく、違反への罰として払うお金の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38283, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は貯金の一部をファンドを運用している。", "corrected_sentence": "母は貯金の一部をファンドで運用している。", "error_description": "「運用する」の目的語は「貯金の一部」なので、手段を示す「で」が正しい。「ファンドを」と「を」を重ねると目的語が二つになり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38283, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は毎月、ファンドの三万円ずつ積み立てている。", "corrected_sentence": "父は毎月、ファンドに三万円ずつ積み立てている。", "error_description": "「ファンドの」は「三万円」を修飾する形になり、「積み立てる」の先が示されない。積み立て先は「ファンドに」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38284, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38284, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「マネージャーのおかげで」という決まった言い方で、正しい。"}, {"text": "が", "is_correct": false, "explanation": "「マネージャーがおかげで」とは言えず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「マネージャーでおかげで」は不自然で、意味の並びが合わない。"}, {"text": "を", "is_correct": false, "explanation": "「マネージャーをおかげで」とは言えず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「マネージャーのおかげで」という決まった言い方で、正しい。", "が": "「マネージャーがおかげで」とは言えず、文が成り立たない。", "で": "「マネージャーでおかげで」は不自然で、意味の並びが合わない。", "を": "「マネージャーをおかげで」とは言えず、文が成り立たない。"}, "error_tags": {"が": "主語", "で": "手段", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38284, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "会社で、人をまとめて、仕事を進める人のこと。", "primary_collocate": null, "pronunciation": "まねーじゃー", "ipa": "maneːdʑaː", "syllable_count": 5, "sentences": [{"text": "会社のマネージャーは、毎朝、チームの仕事を確認します。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "会社[かいしゃ]のマネージャーは、毎朝[まいあさ]、チームの仕事[しごと]を確認[かくにん]します。", "sentence_source": "generated"}, {"text": "新しいマネージャーは、みんなの話をよく聞いてくれます。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "新[あたら]しいマネージャーは、みんなの話[はなし]をよく聞[き]いてくれます。", "sentence_source": "generated"}, {"text": "私は来月からマネージャーとして、五人の部下をまとめます。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "私[わたし]は来月[らいげつ]からマネージャーとして、五人[ごにん]の部下[ぶか]をまとめます。", "sentence_source": "generated"}, {"text": "マネージャーが仕事を分けてくれたので、残業が減りました。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "マネージャーが仕事[しごと]を分[わ]けてくれたので、残業[ざんぎょう]が減[へ]りました。", "sentence_source": "generated"}, {"text": "わからないことがあったので、マネージャーに相談しました。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "わからないことがあったので、マネージャーに相談[そうだん]しました。", "sentence_source": "generated"}, {"text": "マネージャーは、予定が遅れないように、毎週メンバーと話しています。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "マネージャーは、予定[よてい]が遅[おく]れないように、毎週[まいしゅう]メンバーと話[はな]しています。", "sentence_source": "generated"}, {"text": "田中さんはまじめな働き方が認められて、マネージャーになりました。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "田中[たなか]さんはまじめな働[はたら]き方[かた]が認[みと]められて、マネージャーになりました。", "sentence_source": "generated"}, {"text": "マネージャーのおかげで、新入社員もすぐに仕事に慣れました。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "マネージャーのおかげで、新入社員[しんにゅうしゃいん]もすぐに仕事[しごと]に慣[な]れました。", "sentence_source": "generated"}, {"text": "この店のマネージャーは、アルバイトの予定を決める人です。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "この店[みせ]のマネージャーは、アルバイトの予定[よてい]を決[き]める人[ひと]です。", "sentence_source": "generated"}, {"text": "マネージャーが来週の出張を許可してくれました。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "マネージャーが来週[らいしゅう]の出張[しゅっちょう]を許可[きょか]してくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マネージャー", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "会社で人をまとめ仕事を進める人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965ae35d-beef-46d8-a8ec-408e2f838578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38284, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マネージャー", "is_correct": true, "explanation": "会社で人を束ねて仕事を確認する人を指すので、主語として文が成り立つ。"}, {"text": "コピー機", "is_correct": false, "explanation": "書類を複写する機械で、毎朝チームの仕事を確認する主体にはならない。"}, {"text": "エレベーター", "is_correct": false, "explanation": "人や荷物を階へ運ぶ装置で、チームの仕事の進み具合を確認することはできない。"}, {"text": "ロッカー", "is_correct": false, "explanation": "荷物を入れる収納家具で、チームの仕事を確認する役割にはならない。"}], "explanations": {"マネージャー": "会社で人を束ねて仕事を確認する人を指すので、主語として文が成り立つ。", "コピー機": "書類を複写する機械で、毎朝チームの仕事を確認する主体にはならない。", "エレベーター": "人や荷物を階へ運ぶ装置で、チームの仕事の進み具合を確認することはできない。", "ロッカー": "荷物を入れる収納家具で、チームの仕事を確認する役割にはならない。"}, "sentence_index": 0, "correct_answer": "マネージャー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は新人選手に、毎日ドリブルのやり方を教えるマネージャーです。", "explanation": "ここは〈コーチ〉の意味。技術を教えるのはコーチの役目で、マネージャーは組織の運営と調整を担うので合わない。"}, {"text": "マネージャーが、大きな鍋で、スープを煮込みました。", "explanation": "ここは〈料理人〉の意味。鍋で料理を作るのは料理人の仕事で、人をまとめて仕事を進める人の意味とは合わない。"}, {"text": "彼女は三年間、チームのマネージャーとして試合に出ています。", "explanation": "ここは〈メンバー〉の意味で使う言葉。試合に出るのは選手で、マネージャーは運営を支える係なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38284, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マネージャー", "is_correct": true, "explanation": "役職の名前として「になる」に続くので、文が自然に成り立つ。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓にかける布で、人が就く役職にはならない。"}, {"text": "ポスター", "is_correct": false, "explanation": "掲示用の印刷物で、役職として「になる」ことはない。"}, {"text": "ストーブ", "is_correct": false, "explanation": "暖房器具で、役職として「になる」ことはない。"}], "explanations": {"マネージャー": "役職の名前として「になる」に続くので、文が自然に成り立つ。", "カーテン": "窓にかける布で、人が就く役職にはならない。", "ポスター": "掲示用の印刷物で、役職として「になる」ことはない。", "ストーブ": "暖房器具で、役職として「になる」ことはない。"}, "sentence_index": 6, "correct_answer": "マネージャー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "マネージャーが、子どもに九九を教えました。", "explanation": "ここは〈先生〉の意味。九九を教えるのは先生の役目で、会社で人をまとめて仕事を進める人の意味とは合わない。"}, {"text": "マネージャーが、山道の安全なルートを決めて案内しました。", "explanation": "ここは〈ガイド〉の意味で使う言葉。道案内をする人のことで、会社で人を束ねる人の意味とは合わない。"}, {"text": "マネージャーが試合の判定を下して、試合が終わりました。", "explanation": "ここは〈審判〉の意味で使う言葉。判定を下す役割で、会社で仕事を進める人の意味とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38284, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は会議の結果をマネージャーを報告しました。", "corrected_sentence": "私は会議の結果をマネージャーに報告しました。", "error_description": "「報告する」の相手にはマネージャーに「に」を付ける。「を」は目的語の印なので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38284, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しいマネージャーを従ってください。", "corrected_sentence": "新しいマネージャーに従ってください。", "error_description": "「従う」は相手に「に」を付ける。「を」は目的語の印なので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38285, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「マネージャーが」で主語になり、「調整しました」の行為者として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「マネージャーを」だと目的語になり、行為の主語が立たず、目的語も重なって不自然。"}, {"text": "の", "is_correct": false, "explanation": "「マネージャーの、」の形では続かず、文として不自然。"}, {"text": "より", "is_correct": false, "explanation": "「マネージャーより」は比べる相手を示すので、主語にならず「調整しました」とつながらない。"}], "correct_answer": "が", "explanations": {"が": "「マネージャーが」で主語になり、「調整しました」の行為者として正しい。", "を": "「マネージャーを」だと目的語になり、行為の主語が立たず、目的語も重なって不自然。", "の": "「マネージャーの、」の形では続かず、文として不自然。", "より": "「マネージャーより」は比べる相手を示すので、主語にならず「調整しました」とつながらない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
