INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38285, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "組織やチームを統括し、業務の計画・指揮・調整を行う責任者のこと。", "primary_collocate": null, "pronunciation": "まねーじゃー", "ipa": "maneːdʑaː", "syllable_count": 5, "sentences": [{"text": "マネージャーは、計画を立てて、チーム全体を指揮する責任があります。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "マネージャーは、計画[けいかく]を立[た]てて、チーム全体[ぜんたい]を指揮[しき]する責任[せきにん]があります。", "sentence_source": "generated"}, {"text": "部門のマネージャーが、来年の予算を調整しました。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "部門[ぶもん]のマネージャーが、来年[らいねん]の予算[よさん]を調整[ちょうせい]しました。", "sentence_source": "generated"}, {"text": "彼女は三年間、営業チームのマネージャーを務めています。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は三年間[さんねんかん]、営業[えいぎょう]チームのマネージャーを務[つと]めています。", "sentence_source": "generated"}, {"text": "問題が起きたとき、マネージャーは責任を持って判断しなければなりません。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "問題[もんだい]が起[お]きたとき、マネージャーは責任[せきにん]を持[も]って判断[はんだん]しなければなりません。", "sentence_source": "generated"}, {"text": "マネージャーは、メンバー同士の意見の違いを調整します。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "マネージャーは、メンバー同士[どうし]の意見[いけん]の違[ちが]いを調整[ちょうせい]します。", "sentence_source": "generated"}, {"text": "新しい店のマネージャーに、経験豊かな人が選ばれました。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]のマネージャーに、経験豊[けいけんゆた]かな人[ひと]が選[えら]ばれました。", "sentence_source": "generated"}, {"text": "マネージャーの仕事は、自分で作業するより、全体の進み方を見ることです。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "マネージャーの仕事[しごと]は、自分[じぶん]で作業[さぎょう]するより、全体[ぜんたい]の進[すす]み方[かた]を見[み]ることです。", "sentence_source": "generated"}, {"text": "会議で、マネージャーが各チームの計画を説明しました。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "会議[かいぎ]で、マネージャーが各[かく]チームの計画[けいかく]を説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "優秀なマネージャーは、部下の力を引き出して、成果を上げます。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "優秀[ゆうしゅう]なマネージャーは、部下[ぶか]の力[ちから]を引[ひ]き出[だ]して、成果[せいか]を上[あ]げます。", "sentence_source": "generated"}, {"text": "工場のマネージャーが、安全のためのルールを見直しました。", "target_word": "マネージャー", "complexity_tier": "T3", "furigana": "工場[こうじょう]のマネージャーが、安全[あんぜん]のためのルールを見直[みなお]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マネージャー", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "組織を統括し計画と指揮を担う責任者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965ae35d-beef-46d8-a8ec-408e2f838578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38285, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マネージャー", "is_correct": true, "explanation": "組織を統括して計画と指揮を担う責任者なので、主語として文が成り立つ。"}, {"text": "カレンダー", "is_correct": false, "explanation": "日付を示す掲示物で、計画を立てて指揮する主体にはならない。"}, {"text": "金庫", "is_correct": false, "explanation": "貴重品を保管する箱で、チーム全体を指揮することはできない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花を生ける器で、計画を立てて指揮する役割にはならない。"}], "explanations": {"マネージャー": "組織を統括して計画と指揮を担う責任者なので、主語として文が成り立つ。", "カレンダー": "日付を示す掲示物で、計画を立てて指揮する主体にはならない。", "金庫": "貴重品を保管する箱で、チーム全体を指揮することはできない。", "花瓶": "花を生ける器で、計画を立てて指揮する役割にはならない。"}, "sentence_index": 0, "correct_answer": "マネージャー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "マネージャーが、庭の木を丁寧に剪定しました。", "explanation": "ここは〈庭師〉の意味。木を切りそろえる仕事は庭師で、組織の計画や指揮を担う責任者の意味とは合わない。"}, {"text": "マネージャーが試合の判定を下して、試合が終わりました。", "explanation": "ここは〈審判〉の意味で使う言葉。判定を下す役割で、計画・指揮・調整を行う責任者の意味とは合わない。"}, {"text": "彼は三年間、野球チームのマネージャーとして試合に出ています。", "explanation": "ここは〈選手〉の意味で使う言葉。試合に出るのは選手で、マネージャーは運営側なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38285, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マネージャー", "is_correct": true, "explanation": "仕事の進め方を見る主体として、「マネージャーの仕事は」と主語の位置に入る。"}, {"text": "体温計", "is_correct": false, "explanation": "体温を測る器具で、仕事の進み方を見ることはできない。"}, {"text": "本棚", "is_correct": false, "explanation": "本を置く家具で、仕事の進み方を見る主体にはならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は食品を冷やす家電で、仕事の進み方を見る主体にはならない。"}], "explanations": {"マネージャー": "仕事の進め方を見る主体として、「マネージャーの仕事は」と主語の位置に入る。", "体温計": "体温を測る器具で、仕事の進み方を見ることはできない。", "本棚": "本を置く家具で、仕事の進み方を見る主体にはならない。", "冷蔵庫": "冷蔵庫は食品を冷やす家電で、仕事の進み方を見る主体にはならない。"}, "sentence_index": 6, "correct_answer": "マネージャー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "マネージャーが、ロビーの床をきれいに磨きました。", "explanation": "ここは〈清掃員〉の意味。床を磨くのは清掃員の仕事で、組織を統括する責任者の意味とは合わない。"}, {"text": "マネージャーが、山道の安全なルートを決めて案内しました。", "explanation": "ここは〈ガイド〉の意味で使う言葉。道案内をする人のことで、組織の計画と指揮を担う責任者の意味とは合わない。"}, {"text": "マネージャーが、患者の体温を測りました。", "explanation": "ここは〈看護師〉の意味。体温を測るのは看護師の仕事で、組織の計画と指揮を担う責任者の意味とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38285, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は三年間、工場のマネージャーで務めました。", "corrected_sentence": "彼は三年間、工場のマネージャーを務めました。", "error_description": "「務める」は目的語に「を」を付ける。「で」では「務めました」と結びつかず、文として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38285, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "プロジェクトのマネージャーで判断を任せた。", "corrected_sentence": "プロジェクトのマネージャーに判断を任せた。", "error_description": "「任せる」は相手に「に」を付ける。「で」は手段や場所を示すので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38286, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ポートフォリオを作っている」と、作る対象として正しく続く。"}, {"text": "が", "is_correct": false, "explanation": "「ポートフォリオが作っている」では主語になり、作る主体が示されず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ポートフォリオに作っている」は、作る先が不明で不自然。"}, {"text": "と", "is_correct": false, "explanation": "「ポートフォリオと作っている」は並列になり、作る対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「ポートフォリオを作っている」と、作る対象として正しく続く。", "が": "「ポートフォリオが作っている」では主語になり、作る主体が示されず文が成り立たない。", "に": "「ポートフォリオに作っている」は、作る先が不明で不自然。", "と": "「ポートフォリオと作っている」は並列になり、作る対象として成り立たない。"}, "error_tags": {"が": "主語の格", "に": "場所・相手", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38286, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ポートフォリオを持って」と、持つ対象として正しく続く。"}, {"text": "で", "is_correct": false, "explanation": "「厚いポートフォリオで持って」は手段になり、持つ対象が示されず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「ポートフォリオへ持って」は方向になり、持つ対象として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「ポートフォリオから持って」は起点になり、持つ対象が示されず不自然。"}], "correct_answer": "を", "explanations": {"を": "「ポートフォリオを持って」と、持つ対象として正しく続く。", "で": "「厚いポートフォリオで持って」は手段になり、持つ対象が示されず不自然。", "へ": "「ポートフォリオへ持って」は方向になり、持つ対象として成り立たない。", "から": "「ポートフォリオから持って」は起点になり、持つ対象が示されず不自然。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38286, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いろいろな種類の作品や持ち物を、ひとつにまとめて持っていること。たとえば、絵や写真を集めてひとまとめにした作品集のことです。", "primary_collocate": null, "pronunciation": "ぽーとふぉりお", "ipa": "poːtofoɾio", "syllable_count": 6, "sentences": [{"text": "画家は自分の作品をポートフォリオにまとめた。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "画家[がか]は自分[じぶん]の作品[さくひん]をポートフォリオにまとめた。", "sentence_source": "generated"}, {"text": "就職活動のために、ポートフォリオを作っている。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "就職活動[しゅうしょくかつどう]のために、ポートフォリオを作[つく]っている。", "sentence_source": "generated"}, {"text": "彼女のポートフォリオには、絵や写真がたくさん入っている。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のポートフォリオには、絵[え]や写真[しゃしん]がたくさん入[はい]っている。", "sentence_source": "generated"}, {"text": "面接で、デザイナーはポートフォリオを見せた。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "面接[めんせつ]で、デザイナーはポートフォリオを見[み]せた。", "sentence_source": "generated"}, {"text": "写真と手紙と絵を合わせたポートフォリオを、父は持っている。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "写真[しゃしん]と手紙[てがみ]と絵[え]を合[あ]わせたポートフォリオを、父[ちち]は持[も]っている。", "sentence_source": "generated"}, {"text": "ポートフォリオを見直して、持ち物の種類を増やした。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "ポートフォリオを見直[みなお]して、持[も]ち物[もの]の種類[しゅるい]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "先生は、生徒のポートフォリオを見て成長を確かめた。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]のポートフォリオを見[み]て成長[せいちょう]を確[たし]かめた。", "sentence_source": "generated"}, {"text": "厚いポートフォリオを持って、デザイン会社を訪ねた。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "厚[あつ]いポートフォリオを持[も]って、デザイン会社[がいしゃ]を訪[たず]ねた。", "sentence_source": "generated"}, {"text": "作品が増えたので、ポートフォリオを新しくした。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "作品[さくひん]が増[ふ]えたので、ポートフォリオを新[あたら]しくした。", "sentence_source": "generated"}, {"text": "ポートフォリオに入れる写真を、慎重に選んだ。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "ポートフォリオに入[い]れる写真[しゃしん]を、慎重[しんちょう]に選[えら]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポートフォリオ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "作品や持ち物などいろいろな種類をひとまとめにしたもの(作品集・資料集)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fb64f-2b7d-47f2-a572-4d369e136007') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38286, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポートフォリオ", "is_correct": true, "explanation": "作品を集めてまとめた作品集を指し、「作品をポートフォリオにまとめた」と自然につながる。"}, {"text": "展示会", "is_correct": false, "explanation": "展示会は作品を並べる催しであり、作品をまとめる先にはならないので空欄に入らない。"}, {"text": "おもちゃ", "is_correct": false, "explanation": "おもちゃは遊ぶ物であり、作品をまとめる先ではないので空欄に入らない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は体の感覚であり、まとめる対象にはならないので空欄に入らない。"}], "explanations": {"ポートフォリオ": "作品を集めてまとめた作品集を指し、「作品をポートフォリオにまとめた」と自然につながる。", "展示会": "展示会は作品を並べる催しであり、作品をまとめる先にはならないので空欄に入らない。", "おもちゃ": "おもちゃは遊ぶ物であり、作品をまとめる先ではないので空欄に入らない。", "眠気": "眠気は体の感覚であり、まとめる対象にはならないので空欄に入らない。"}, "sentence_index": 0, "correct_answer": "ポートフォリオ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ポートフォリオは、一枚の絵を飾る額縁のことだ。", "explanation": "ポートフォリオには「額縁」の意味はなく、絵を飾る枠の意味では使えない。"}, {"text": "クラブのポートフォリオに、新しい部員の名前を書き加えた。", "explanation": "ポートフォリオには「名簿」の意味はなく、部員の名前を並べた一覧の意味では使えない。"}, {"text": "ポートフォリオを見れば、電車の発車時刻が分かる。", "explanation": "ポートフォリオには「時刻表」の意味はなく、発車時刻を並べた表の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38286, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポートフォリオ", "is_correct": true, "explanation": "生徒の作品をまとめた資料を指し、「生徒のポートフォリオを見て」と自然に続く。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠る人が出す息で、成長を確かめる対象にはならないので空欄に入らない。"}, {"text": "鼻水", "is_correct": false, "explanation": "鼻水は成長を確かめる対象にならず、空欄に入ると文が成り立たない。"}, {"text": "呼吸", "is_correct": false, "explanation": "呼吸は体の働きであり、成長を確かめる資料にはならないので空欄に入らない。"}], "explanations": {"ポートフォリオ": "生徒の作品をまとめた資料を指し、「生徒のポートフォリオを見て」と自然に続く。", "寝息": "寝息は眠る人が出す息で、成長を確かめる対象にはならないので空欄に入らない。", "鼻水": "鼻水は成長を確かめる対象にならず、空欄に入ると文が成り立たない。", "呼吸": "呼吸は体の働きであり、成長を確かめる資料にはならないので空欄に入らない。"}, "sentence_index": 6, "correct_answer": "ポートフォリオ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ポートフォリオに毎日の支出を書き込んだ。", "explanation": "ポートフォリオには「家計簿」の意味はなく、毎日の支出を記録する帳簿の意味では使えない。"}, {"text": "ポートフォリオに、戦争の出来事を年ごとに書いた。", "explanation": "ポートフォリオには「年表」の意味はなく、出来事を年ごとに並べた表の意味では使えない。"}, {"text": "ポートフォリオを立てて、一週間の食事を決めた。", "explanation": "ポートフォリオには「献立」の意味はなく、一週間の食事の計画の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38286, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "写真家は、作品をポートフォリオを入れた。", "corrected_sentence": "写真家は、作品をポートフォリオに入れた。", "error_description": "「入れる」の場所を示すのは「に」で、「を」は誤り。「を」だと入れる対象になってしまい、作品を収める先が示されない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38286, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、新しいポートフォリオで持って、面接に行った。", "corrected_sentence": "彼女は、新しいポートフォリオを持って、面接に行った。", "error_description": "「持つ」の対象はポートフォリオなので「を」が正しく、「で」は誤り。「で」だと手段になり、持って行く物が示されない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38287, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ポートフォリオを分散させた」と、分散させる対象として正しく続く。"}, {"text": "が", "is_correct": false, "explanation": "「ポートフォリオが分散させた」は主語になり、分散させる対象が欠けて文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「ポートフォリオの分散させた」では、動詞を修飾する形が成り立たず文が完結しない。"}, {"text": "と", "is_correct": false, "explanation": "「ポートフォリオと分散させた」は並列になり、分散させる対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「ポートフォリオを分散させた」と、分散させる対象として正しく続く。", "が": "「ポートフォリオが分散させた」は主語になり、分散させる対象が欠けて文が成り立たない。", "の": "「ポートフォリオの分散させた」では、動詞を修飾する形が成り立たず文が完結しない。", "と": "「ポートフォリオと分散させた」は並列になり、分散させる対象として成り立たない。"}, "error_tags": {"が": "主語の格", "の": "連体修飾", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38287, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ポートフォリオの内容」と所属を示す「の」で正しく続く。"}, {"text": "を", "is_correct": false, "explanation": "「ポートフォリオを内容を確認」と二つの「を」が並び、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「ポートフォリオが内容を確認している」は主語になり、確認する主体として不自然で文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「ポートフォリオへ内容を確認」は方向を表すが、確認の対象にはならない。"}], "correct_answer": "の", "explanations": {"の": "「ポートフォリオの内容」と所属を示す「の」で正しく続く。", "を": "「ポートフォリオを内容を確認」と二つの「を」が並び、文が成り立たない。", "が": "「ポートフォリオが内容を確認している」は主語になり、確認する主体として不自然で文が成り立たない。", "へ": "「ポートフォリオへ内容を確認」は方向を表すが、確認の対象にはならない。"}, "error_tags": {"を": "目的語の重複", "が": "主語の格", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38287, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "投資で、複数の資産を組み合わせた集まり。リスクを分散するために、異なる種類の資産をバランスよく持つこと。", "primary_collocate": null, "pronunciation": "ぽーとふぉりお", "ipa": "poːtofoɾio", "syllable_count": 6, "sentences": [{"text": "リスクを減らすために、ポートフォリオを組み直した。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "リスクを減[へ]らすために、ポートフォリオを組[く]み直[なお]した。", "sentence_source": "generated"}, {"text": "株だけでなく債券も入れて、ポートフォリオを分散させた。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "株[かぶ]だけでなく債券[さいけん]も入[い]れて、ポートフォリオを分散[ぶんさん]させた。", "sentence_source": "generated"}, {"text": "このポートフォリオは、株式が六割、債券が四割だ。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "このポートフォリオは、株式[かぶしき]が六割[ろくわり]、債券[さいけん]が四割[よんわり]だ。", "sentence_source": "generated"}, {"text": "市場が下がっても、ポートフォリオ全体の損は小さかった。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "市場[しじょう]が下[さ]がっても、ポートフォリオ全体[ぜんたい]の損[そん]は小[ちい]さかった。", "sentence_source": "generated"}, {"text": "年齢が上がるにつれて、ポートフォリオに安全な資産を増やす人が多い。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "年齢[ねんれい]が上[あ]がるにつれて、ポートフォリオに安全[あんぜん]な資産[しさん]を増[ふ]やす人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "専門家に、ポートフォリオの組み方を相談した。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "専門家[せんもんか]に、ポートフォリオの組[く]み方[かた]を相談[そうだん]した。", "sentence_source": "generated"}, {"text": "偏ったポートフォリオは、値下がりのときに危険だ。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "偏[かたよ]ったポートフォリオは、値下[ねさ]がりのときに危険[きけん]だ。", "sentence_source": "generated"}, {"text": "運用担当者は、毎月ポートフォリオの内容を確認している。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "運用担当者[うんようたんとうしゃ]は、毎月[まいつき]ポートフォリオの内容[ないよう]を確認[かくにん]している。", "sentence_source": "generated"}, {"text": "外国の株を加えて、ポートフォリオの種類を広げた。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "外国[がいこく]の株[かぶ]を加[くわ]えて、ポートフォリオの種類[しゅるい]を広[ひろ]げた。", "sentence_source": "generated"}, {"text": "良いポートフォリオは、リスクとリターンのバランスがとれている。", "target_word": "ポートフォリオ", "complexity_tier": "T3", "furigana": "良[よ]いポートフォリオは、リスクとリターンのバランスがとれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポートフォリオ", "label": "基本形"}], "register": "business", "sense_fingerprint": "リスク分散のために複数の資産を組み合わせた投資の構成(資産の組み合わせ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fb64f-2b7d-47f2-a572-4d369e136007') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38287, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポートフォリオ", "is_correct": true, "explanation": "リスク分散のために資産を組み合わせた構成を指し、「ポートフォリオを組み直した」と自然に続く。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠る人が出す息で、組み直す対象にはならないので空欄に入らない。"}, {"text": "鼻水", "is_correct": false, "explanation": "鼻水は組み直す対象にならず、空欄に入ると文が成り立たない。"}, {"text": "呼吸", "is_correct": false, "explanation": "呼吸は体の働きであり、組み直す対象にはならないので空欄に入らない。"}], "explanations": {"ポートフォリオ": "リスク分散のために資産を組み合わせた構成を指し、「ポートフォリオを組み直した」と自然に続く。", "寝息": "寝息は眠る人が出す息で、組み直す対象にはならないので空欄に入らない。", "鼻水": "鼻水は組み直す対象にならず、空欄に入ると文が成り立たない。", "呼吸": "呼吸は体の働きであり、組み直す対象にはならないので空欄に入らない。"}, "sentence_index": 0, "correct_answer": "ポートフォリオ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ポートフォリオは、お札を入れていつも持ち歩く袋のことだ。", "explanation": "ポートフォリオには「財布」の意味はなく、お金を入れて持ち歩く入れ物の意味では使えない。"}, {"text": "ポートフォリオを立てて、一週間の食事を決めた。", "explanation": "ポートフォリオには「献立」の意味はなく、一週間の食事の計画の意味では使えない。"}, {"text": "ポートフォリオを作って、クラブの会員を確認した。", "explanation": "ポートフォリオには「名簿」の意味はなく、会員の名前を並べた一覧の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38287, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポートフォリオ", "is_correct": true, "explanation": "資産を組み合わせた投資の構成を指し、「偏ったポートフォリオ」と自然に続く。"}, {"text": "天気", "is_correct": false, "explanation": "天気は資産の組み合わせを指さず、「偏った」と結びつかないので空欄に入らない。"}, {"text": "ため息", "is_correct": false, "explanation": "ため息は資産の構成にはならず、空欄に入ると文が成り立たない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は資産の構成にはならず、「偏った」と結びつかないので空欄に入らない。"}], "explanations": {"ポートフォリオ": "資産を組み合わせた投資の構成を指し、「偏ったポートフォリオ」と自然に続く。", "天気": "天気は資産の組み合わせを指さず、「偏った」と結びつかないので空欄に入らない。", "ため息": "ため息は資産の構成にはならず、空欄に入ると文が成り立たない。", "眠気": "眠気は資産の構成にはならず、「偏った」と結びつかないので空欄に入らない。"}, "sentence_index": 6, "correct_answer": "ポートフォリオ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ポートフォリオを見れば、事件の順番がよく分かる。", "explanation": "ポートフォリオには「年表」の意味はなく、出来事を年代順に並べた表の意味では使えない。"}, {"text": "ポートフォリオを割って、夏休みの小遣いを取り出した。", "explanation": "ポートフォリオには「貯金箱」の意味はなく、硬貨を貯めて割る入れ物の意味では使えない。"}, {"text": "ポートフォリオに予定を書き込んだ。", "explanation": "ポートフォリオには「カレンダー」の意味はなく、日付ごとの予定を書く暦の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38287, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "運用担当者は、ポートフォリオを中身を見直した。", "corrected_sentence": "運用担当者は、ポートフォリオの中身を見直した。", "error_description": "「を」が二つ重なって目的語が二つになり、文が成り立たない。「中身」はポートフォリオに属することを示す「の」で結ぶ。正しくは「ポートフォリオの中身を見直した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38287, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "保守的な人は、ポートフォリオを国債を多めに入れる。", "corrected_sentence": "保守的な人は、ポートフォリオに国債を多めに入れる。", "error_description": "「入れる」の場所を示すのは「に」で、「を」は誤り。「を」だと入れる対象になってしまい、国債を組み入れる先が示されない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38288, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「考える」の目的語を示す「を」で、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「再編に考え始めた」は、考える対象を「に」で示せず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「再編で考え始めた」は手段を示す「で」になり、考える対象にならないので不自然。"}, {"text": "と", "is_correct": false, "explanation": "「再編と考え始めた」は並列になり、考える対象を示せないので不自然。"}], "correct_answer": "を", "explanations": {"を": "「考える」の目的語を示す「を」で、文に合う。", "に": "「再編に考え始めた」は、考える対象を「に」で示せず不自然。", "で": "「再編で考え始めた」は手段を示す「で」になり、考える対象にならないので不自然。", "と": "「再編と考え始めた」は並列になり、考える対象を示せないので不自然。"}, "error_tags": {"に": "着点", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f78447b-2c31-4e21-9d9a-0eadee51a7fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
