INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38290, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「農園の朝」の所属を示す「の」で、農園に属する朝という意味になります。"}, {"text": "を", "is_correct": false, "explanation": "「農園を朝は早く」では目的語の形が続かず、文の意味が成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「農園に朝は早く」は位置や帰属として結びつかず、続く文の意味が通りません。"}, {"text": "と", "is_correct": false, "explanation": "「農園と朝」は並列になり、農園と朝が早いという意味になってしまいます。"}], "correct_answer": "の", "explanations": {"の": "「農園の朝」の所属を示す「の」で、農園に属する朝という意味になります。", "を": "「農園を朝は早く」では目的語の形が続かず、文の意味が成り立ちません。", "に": "「農園に朝は早く」は位置や帰属として結びつかず、続く文の意味が通りません。", "と": "「農園と朝」は並列になり、農園と朝が早いという意味になってしまいます。"}, "error_tags": {"を": "目的語", "に": "位置・帰属", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38290, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "働く場所を示す「で」で、農園で働く人たちという意味になります。"}, {"text": "を", "is_correct": false, "explanation": "「農園を働く」は働くを他動詞として扱うことになり、自然な文になりません。"}, {"text": "に", "is_correct": false, "explanation": "「農園に働く」は勤務の場所を示す形として合わず、「で」が使われます。"}, {"text": "へ", "is_correct": false, "explanation": "「農園へ働く」は方向を示すため、働く動作の場所には使えません。"}], "correct_answer": "で", "explanations": {"で": "働く場所を示す「で」で、農園で働く人たちという意味になります。", "を": "「農園を働く」は働くを他動詞として扱うことになり、自然な文になりません。", "に": "「農園に働く」は勤務の場所を示す形として合わず、「で」が使われます。", "へ": "「農園へ働く」は方向を示すため、働く動作の場所には使えません。"}, "error_tags": {"を": "目的語", "に": "位置・帰属", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38290, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "野菜や果物を育てるための、広い土地のことです。", "primary_collocate": null, "pronunciation": "のうえん", "ipa": "noːeɴ", "syllable_count": 4, "sentences": [{"text": "祖父は広い農園で、トマトやキュウリを育てています。", "target_word": "農園", "complexity_tier": "T3", "furigana": "祖父[そふ]は広[ひろ]い農園[のうえん]で、トマトやキュウリを育[そだ]てています。", "sentence_source": "generated"}, {"text": "農園の朝は早く、毎日六時から仕事が始まります。", "target_word": "農園", "complexity_tier": "T3", "furigana": "農園[のうえん]の朝[あさ]は早[はや]く、毎日[まいにち]六時[ろくじ]から仕事[しごと]が始[はじ]まります。", "sentence_source": "generated"}, {"text": "日曜日に家族で農園へ行って、いちごを収穫しました。", "target_word": "農園", "complexity_tier": "T3", "furigana": "日曜日[にちようび]に家族[かぞく]で農園[のうえん]へ行[い]って、いちごを収穫[しゅうかく]しました。", "sentence_source": "generated"}, {"text": "この農園では、薬を使わずに野菜を作っています。", "target_word": "農園", "complexity_tier": "T3", "furigana": "この農園[のうえん]では、薬[くすり]を使[つか]わずに野菜[やさい]を作[つく]っています。", "sentence_source": "generated"}, {"text": "雨が少なかったので、農園の野菜に元気がありません。", "target_word": "農園", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]なかったので、農園[のうえん]の野菜[やさい]に元気[げんき]がありません。", "sentence_source": "generated"}, {"text": "農園の近くに小さな川があるので、水には困りません。", "target_word": "農園", "complexity_tier": "T3", "furigana": "農園[のうえん]の近[ちか]くに小[ちい]さな川[かわ]があるので、水[みず]には困[こま]りません。", "sentence_source": "generated"}, {"text": "彼は会社をやめて、田舎で農園を始めました。", "target_word": "農園", "complexity_tier": "T3", "furigana": "彼[かれ]は会社[かいしゃ]をやめて、田舎[いなか]で農園[のうえん]を始[はじ]めました。", "sentence_source": "generated"}, {"text": "農園で働く人たちは、夏の暑さに気をつけています。", "target_word": "農園", "complexity_tier": "T3", "furigana": "農園[のうえん]で働[はたら]く人[ひと]たちは、夏[なつ]の暑[あつ]さに気[き]をつけています。", "sentence_source": "generated"}, {"text": "農園で採れたばかりの果物は、とても甘いです。", "target_word": "農園", "complexity_tier": "T3", "furigana": "農園[のうえん]で採[と]れたばかりの果物[くだもの]は、とても甘[あま]いです。", "sentence_source": "generated"}, {"text": "台風が来る前に、農園の木に支えをつけました。", "target_word": "農園", "complexity_tier": "T3", "furigana": "台風[たいふう]が来[く]る前[まえ]に、農園[のうえん]の木[き]に支[ささ]えをつけました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農園", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "野菜や果物を育てる広い土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd1d8776-9703-44ca-b7cd-08292b44c2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38290, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "農園", "is_correct": true, "explanation": "広い土地で野菜を育てる場所を指す「農園」が、ここに入ります。"}, {"text": "牧場", "is_correct": false, "explanation": "牧場は家畜を飼う場所で、トマトやキュウリを育てる文脈には合いません。"}, {"text": "工場", "is_correct": false, "explanation": "工場は製品を作る施設で、作物を育てる文脈には合いません。"}, {"text": "倉庫", "is_correct": false, "explanation": "倉庫は物を保管する場所で、ここで作物を育てるという意味にはなりません。"}], "explanations": {"農園": "広い土地で野菜を育てる場所を指す「農園」が、ここに入ります。", "牧場": "牧場は家畜を飼う場所で、トマトやキュウリを育てる文脈には合いません。", "工場": "工場は製品を作る施設で、作物を育てる文脈には合いません。", "倉庫": "倉庫は物を保管する場所で、ここで作物を育てるという意味にはなりません。"}, "sentence_index": 0, "correct_answer": "農園"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この農園では、部品を機械で組み立てて、毎日千個出荷しています。", "explanation": "ここは〈工場〉の意味です。農園は野菜や果物を育てる土地なので、部品を組み立てる場所には使えません。"}, {"text": "この農園では、古い本を三万冊貸し出しています。", "explanation": "ここは〈図書館〉の意味です。本を貸し出す施設は図書館で、農園は作物を育てる土地なので合いません。"}, {"text": "この農園では、牛を三百頭育てて、毎日牛乳を搾っています。", "explanation": "ここは〈農場〉との混同です。牛を飼う場所は農場と言い、農園は野菜や果物を育てる土地なので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38290, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "農園", "is_correct": true, "explanation": "田舎で作物を育てる土地を始めた、という意味に「農園」が合います。"}, {"text": "森", "is_correct": false, "explanation": "森は自然にある林で、「始める」の対象にはならず、ここでは意味が通りません。"}, {"text": "海", "is_correct": false, "explanation": "海は始めるものではないので、田舎で何かを始めたという文脈では成り立ちません。"}, {"text": "空", "is_correct": false, "explanation": "空は「始める」の対象にできず、田舎での行動を述べる文として不自然です。"}], "explanations": {"農園": "田舎で作物を育てる土地を始めた、という意味に「農園」が合います。", "森": "森は自然にある林で、「始める」の対象にはならず、ここでは意味が通りません。", "海": "海は始めるものではないので、田舎で何かを始めたという文脈では成り立ちません。", "空": "空は「始める」の対象にできず、田舎での行動を述べる文として不自然です。"}, "sentence_index": 6, "correct_answer": "農園"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この農園では、露天風呂に入って、一時間ごとに料金を払います。", "explanation": "ここは〈温泉〉の意味です。お湯に入る施設は温泉で、農園は作物を育てる土地なので合いません。"}, {"text": "大学では農園を専攻して、土の成分を研究しています。", "explanation": "ここは〈農業〉の意味です。専攻する学問は農業と言い、農園は土地を指すので合いません。"}, {"text": "この農園では、鯛を一万匹育てて、毎月出荷しています。", "explanation": "ここは〈養殖場〉との混同です。魚を育てる施設は養殖場と言い、農園は野菜や果物を育てる土地なので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38290, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は裏の農園から、ナスを育てています。", "corrected_sentence": "祖父は裏の農園で、ナスを育てています。", "error_description": "作物を育てる場所は「で」で示します。「から」は起点を表すので、育てる場所としては不自然になります。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38290, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週、家族で農園が訪ねて、いちごを摘みました。", "corrected_sentence": "先週、家族で農園を訪ねて、いちごを摘みました。", "error_description": "「訪ねる」の対象は「を」で示します。「が」にすると農園が訪ねる主体になり、家族が訪ねたという文の意味が崩れます。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38291, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38291, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「農園の見学」の所属を示す「の」で、農園の見学という意味になります。"}, {"text": "を", "is_correct": false, "explanation": "「農園を見学は」では目的語が重なり、文の構造が成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「農園に見学は予約が必要」では見学を修飾できず、意味が通りません。"}, {"text": "が", "is_correct": false, "explanation": "「農園が見学は」では主語が二つ並び、文の構造が成り立ちません。"}], "correct_answer": "の", "explanations": {"の": "「農園の見学」の所属を示す「の」で、農園の見学という意味になります。", "を": "「農園を見学は」では目的語が重なり、文の構造が成り立ちません。", "に": "「農園に見学は予約が必要」では見学を修飾できず、意味が通りません。", "が": "「農園が見学は」では主語が二つ並び、文の構造が成り立ちません。"}, "error_tags": {"を": "目的語", "に": "位置・帰属", "が": "二重の主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38291, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "野菜や果物、花などを育てるための土地や施設。畑や果樹園などを含む。", "primary_collocate": null, "pronunciation": "のうえん", "ipa": "noːeɴ", "syllable_count": 4, "sentences": [{"text": "この農園では、野菜だけでなく花も育てています。", "target_word": "農園", "complexity_tier": "T3", "furigana": "この農園[のうえん]では、野菜[やさい]だけでなく花[はな]も育[そだ]てています。", "sentence_source": "generated"}, {"text": "観光客が果物狩りを楽しめる農園が、町の北にあります。", "target_word": "農園", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]が果物狩[くだものが]りを楽[たの]しめる農園[のうえん]が、町[まち]の北[きた]にあります。", "sentence_source": "generated"}, {"text": "農園には畑と果樹園があり、一年中なにかが収穫できます。", "target_word": "農園", "complexity_tier": "T3", "furigana": "農園[のうえん]には畑[はたけ]と果樹園[かじゅえん]があり、一年中[いちねんじゅう]なにかが収穫[しゅうかく]できます。", "sentence_source": "generated"}, {"text": "子どもたちは学校の行事で農園を訪ね、土にふれました。", "target_word": "農園", "complexity_tier": "T3", "furigana": "子[こ]どもたちは学校[がっこう]の行事[ぎょうじ]で農園[のうえん]を訪[たず]ね、土[つち]にふれました。", "sentence_source": "generated"}, {"text": "新しい農園を作るため、市は山のふもとの土地を買いました。", "target_word": "農園", "complexity_tier": "T3", "furigana": "新[あたら]しい農園[のうえん]を作[つく]るため、市[し]は山[やま]のふもとの土地[とち]を買[か]いました。", "sentence_source": "generated"}, {"text": "農園の直売所では、朝とれた野菜が安く売られています。", "target_word": "農園", "complexity_tier": "T3", "furigana": "農園[のうえん]の直売所[ちょくばいじょ]では、朝[あさ]とれた野菜[やさい]が安[やす]く売[う]られています。", "sentence_source": "generated"}, {"text": "友人の農園には小さな温室があり、冬でもバラが咲いています。", "target_word": "農園", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の農園[のうえん]には小[ちい]さな温室[おんしつ]があり、冬[ふゆ]でもバラが咲[さ]いています。", "sentence_source": "generated"}, {"text": "農園の見学は予約が必要なので、先に電話をしてください。", "target_word": "農園", "complexity_tier": "T3", "furigana": "農園[のうえん]の見学[けんがく]は予約[よやく]が必要[ひつよう]なので、先[さき]に電話[でんわ]をしてください。", "sentence_source": "generated"}, {"text": "農園の入り口に、収穫した花を並べた店があります。", "target_word": "農園", "complexity_tier": "T3", "furigana": "農園[のうえん]の入[い]り口[ぐち]に、収穫[しゅうかく]した花[はな]を並[なら]べた店[みせ]があります。", "sentence_source": "generated"}, {"text": "大きな農園を管理するには、たくさんの人手が必要です。", "target_word": "農園", "complexity_tier": "T3", "furigana": "大[おお]きな農園[のうえん]を管理[かんり]するには、たくさんの人手[ひとで]が必要[ひつよう]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農園", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "畑や果樹園を含む、作物や花を育てる土地や施設", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd1d8776-9703-44ca-b7cd-08292b44c2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38291, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "農園", "is_correct": true, "explanation": "野菜や花を育てる土地や施設を指す「農園」が、ここに入ります。"}, {"text": "空港", "is_correct": false, "explanation": "空港では花を育てないので、この文脈では意味が成り立ちません。"}, {"text": "工場", "is_correct": false, "explanation": "工場は製品を作る場所で、野菜や花を育てる文に合いません。"}, {"text": "倉庫", "is_correct": false, "explanation": "倉庫は物を保管する場所で、作物や花を育てるという内容とは合いません。"}], "explanations": {"農園": "野菜や花を育てる土地や施設を指す「農園」が、ここに入ります。", "空港": "空港では花を育てないので、この文脈では意味が成り立ちません。", "工場": "工場は製品を作る場所で、野菜や花を育てる文に合いません。", "倉庫": "倉庫は物を保管する場所で、作物や花を育てるという内容とは合いません。"}, "sentence_index": 0, "correct_answer": "農園"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもたちは学校の行事で農園を使い、バスケットボールを楽しみました。", "explanation": "ここは〈体育館〉の意味です。農園は作物を育てる土地で、スポーツをする施設としては使えません。"}, {"text": "子どもたちは学校の行事で農園を訪ね、車の組み立てラインを見学しました。", "explanation": "ここは〈工場〉の意味です。車を組み立てる施設は工場で、農園は野菜や果物などを育てる場所なので合いません。"}, {"text": "子どもたちは学校の行事で農園を訪ね、ゾウにえさをあげました。", "explanation": "ここは〈動物園〉の意味です。ゾウのような動物を見せる施設は動物園で、農園には当てはまりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38291, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "農園", "is_correct": true, "explanation": "作物を育てる土地を指す「農園」が、友人の土地として入ります。"}, {"text": "墓地", "is_correct": false, "explanation": "墓地に温室があり冬にバラが咲くという内容は、この文の流れに合いません。"}, {"text": "駐車場", "is_correct": false, "explanation": "駐車場に温室があり冬にバラが咲くという内容は、この文の流れに合いません。"}, {"text": "寺院", "is_correct": false, "explanation": "寺院の温室でバラが咲くという内容は、友人の所有を述べる文として不自然です。"}], "explanations": {"農園": "作物を育てる土地を指す「農園」が、友人の土地として入ります。", "墓地": "墓地に温室があり冬にバラが咲くという内容は、この文の流れに合いません。", "駐車場": "駐車場に温室があり冬にバラが咲くという内容は、この文の流れに合いません。", "寺院": "寺院の温室でバラが咲くという内容は、友人の所有を述べる文として不自然です。"}, "sentence_index": 6, "correct_answer": "農園"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この農園では、名画を三百点展示しています。", "explanation": "ここは〈美術館〉の意味です。作品を展示する施設は美術館で、農園は作物を育てる土地なので合いません。"}, {"text": "この農園では、午後だけ診察を受け付けています。", "explanation": "ここは〈病院〉の意味です。診察を受け付けるのは病院で、農園にはその役割がありません。"}, {"text": "この農園では、卵を一日に二万個集めています。", "explanation": "ここは〈養鶏場〉との混同です。卵を産む鶏を飼う施設は養鶏場と言い、農園は野菜や果物を育てる土地なので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38291, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この農園から、野菜だけでなく果物も育てています。", "corrected_sentence": "この農園では、野菜だけでなく果物も育てています。", "error_description": "作物を育てる場所は「では」で示します。「から」は起点を表すので、育てる場所としては不自然になります。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38291, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友人が農園を食べています。", "corrected_sentence": "友人が農園を営んでいます。", "error_description": "農園と組み合わせる動詞は「営む」です。「食べる」は飲食の対象にしか使えず、農園を対象にする動詞としては不自然です。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
