INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38292, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "一番いいこと。", "primary_collocate": null, "pronunciation": "さいてき", "ipa": "saiteki", "syllable_count": 4, "sentences": [{"text": "初心者には、この辞書が最適だ。", "target_word": "最適", "complexity_tier": "T3", "furigana": "初心者[しょしんしゃ]には、この辞書[じしょ]が最適[さいてき]だ。", "sentence_source": "generated"}, {"text": "山登りには、軽くて丈夫な靴が最適だ。", "target_word": "最適", "complexity_tier": "T3", "furigana": "山登[やまのぼ]りには、軽[かる]くて丈夫[じょうぶ]な靴[くつ]が最適[さいてき]だ。", "sentence_source": "generated"}, {"text": "この場所は、星を見るのに最適な所だ。", "target_word": "最適", "complexity_tier": "T3", "furigana": "この場所[ばしょ]は、星[ほし]を見[み]るのに最適[さいてき]な所[ところ]だ。", "sentence_source": "generated"}, {"text": "最適な方法を選ぶために、三つの案を比べた。", "target_word": "最適", "complexity_tier": "T3", "furigana": "最適[さいてき]な方法[ほうほう]を選[えら]ぶために、三[みっ]つの案[あん]を比[くら]べた。", "sentence_source": "generated"}, {"text": "夏の旅行には、涼しい北の町が最適だと思う。", "target_word": "最適", "complexity_tier": "T3", "furigana": "夏[なつ]の旅行[りょこう]には、涼[すず]しい北[きた]の町[まち]が最適[さいてき]だと思[おも]う。", "sentence_source": "generated"}, {"text": "彼は仕事に最適な人なので、みんなが推薦した。", "target_word": "最適", "complexity_tier": "T4", "furigana": "彼[かれ]は仕事[しごと]に最適[さいてき]な人[ひと]なので、みんなが推薦[すいせん]した。", "sentence_source": "generated"}, {"text": "犬の散歩は朝が最適で、昼は暑すぎる。", "target_word": "最適", "complexity_tier": "T3", "furigana": "犬[いぬ]の散歩[さんぽ]は朝[あさ]が最適[さいてき]で、昼[ひる]は暑[あつ]すぎる。", "sentence_source": "generated"}, {"text": "先生はクラスに最適な席の配置を考えた。", "target_word": "最適", "complexity_tier": "T3", "furigana": "先生[せんせい]はクラスに最適[さいてき]な席[せき]の配置[はいち]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "子どもが寝るには、静かで暗い部屋が最適だ。", "target_word": "最適", "complexity_tier": "T3", "furigana": "子[こ]どもが寝[ね]るには、静[しず]かで暗[くら]い部屋[へや]が最適[さいてき]だ。", "sentence_source": "generated"}, {"text": "赤ちゃんには、最適な温度でミルクを飲ませる。", "target_word": "最適", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんには、最適[さいてき]な温度[おんど]でミルクを飲[の]ませる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "最適", "label": "基本形"}, {"form": "最適だ", "label": "断定形"}, {"form": "最適な", "label": "連体形"}, {"form": "最適に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "目的や条件に対して一番ふさわしいこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1f5796-cc68-46b6-b5e8-fc44afd0652e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38292, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最適", "is_correct": true, "explanation": "目的や条件に合う一番の状態を表し、初心者向けの辞書の適合を示す。"}, {"text": "愉快", "is_correct": false, "explanation": "楽しく気持ちがいいことを表すので、辞書の適合の説明にはならない。"}, {"text": "盛大", "is_correct": false, "explanation": "規模が大きく立派なことを表すため、辞書が初心者に合うかどうかの説明には当てはまらない。"}, {"text": "繊細", "is_correct": false, "explanation": "感覚が細やかなことを表すので、辞書の適合を述べる文とは合わない。"}], "explanations": {"最適": "目的や条件に合う一番の状態を表し、初心者向けの辞書の適合を示す。", "愉快": "楽しく気持ちがいいことを表すので、辞書の適合の説明にはならない。", "盛大": "規模が大きく立派なことを表すため、辞書が初心者に合うかどうかの説明には当てはまらない。", "繊細": "感覚が細やかなことを表すので、辞書の適合を述べる文とは合わない。"}, "sentence_index": 0, "correct_answer": "最適"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年の売り上げは、最適を記録した。", "explanation": "ここは〈最高〉（記録的な数値）の意味。最適は条件に合うことを表し、数値が一番高いことを記録する言い方には使わない。"}, {"text": "今夜のデートは、最適に盛り上がった。", "explanation": "ここは〈大いに〉（程度がとても大きい）の意味。最適は合うかどうかを表し、盛り上がりの程度を言う副詞としては使わない。"}, {"text": "この店は人気が最適だ。", "explanation": "ここは〈最大〉（一番高いこと）の意味。最適は条件に合うことで、人気の程度が一番高いことは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38292, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最適", "is_correct": true, "explanation": "朝が一番合う時間であることを表し、昼が暑すぎるという対比とも対応する。"}, {"text": "無礼", "is_correct": false, "explanation": "礼儀に欠けることを表すため、散歩の時間帯の説明には合わない。"}, {"text": "懸命", "is_correct": false, "explanation": "一生懸命という意味で、時間帯が合うかどうかは表せない。"}, {"text": "高価", "is_correct": false, "explanation": "値段が高いことを表すので、散歩の時間帯とは関係しない。"}], "explanations": {"最適": "朝が一番合う時間であることを表し、昼が暑すぎるという対比とも対応する。", "無礼": "礼儀に欠けることを表すため、散歩の時間帯の説明には合わない。", "懸命": "一生懸命という意味で、時間帯が合うかどうかは表せない。", "高価": "値段が高いことを表すので、散歩の時間帯とは関係しない。"}, "sentence_index": 6, "correct_answer": "最適"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は最後まで最適を尽くした。", "explanation": "ここは〈最善〉の意味。「最善を尽くす」という決まった言い方があり、最適は条件に合うことを表すので「尽くす」とは組み合わない。"}, {"text": "彼は最適に笑った。", "explanation": "ここは〈最高に〉（とても、すごく）の意味。最適は合うかどうかを表し、笑いの程度を言う副詞としては使わない。"}, {"text": "彼は大会で、自己最適を更新した。", "explanation": "ここは〈自己最高〉（自分の一番の記録）の意味。最適は条件に合うことで、自分の最高記録を言う語としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38292, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部屋は、本を読むのに最適な整えられている。", "corrected_sentence": "この部屋は、本を読むのに最適に整えられている。", "error_description": "「整えられている」を修飾するので連用形「最適に」が必要。連体形「最適な」は名詞を修飾する形で、動詞を修飾できない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "最適だ", "is_correct": true, "explanation": "断定形。文末で「靴が最適だ」と述語を締める形で、ここでは答え。"}, {"text": "最適な", "is_correct": false, "explanation": "連体形で、名詞に直接続く形。「靴が最適だ」の述語には使えない。"}, {"text": "最適に", "is_correct": false, "explanation": "連用形で、動詞や形容詞を修飾する形。文の述語としては合わない。"}, {"text": "最適で", "is_correct": false, "explanation": "中止形で、後ろに「、」や「て」が続く形。文を締める述語にはならない。"}], "correct_form": "最適だ", "base_form": "最適", "form_label": "断定形", "sentence_index": 1, "explanations": {"最適だ": "断定形。文末で「靴が最適だ」と述語を締める形で、ここでは答え。", "最適な": "連体形で、名詞に直接続く形。「靴が最適だ」の述語には使えない。", "最適に": "連用形で、動詞や形容詞を修飾する形。文の述語としては合わない。", "最適で": "中止形で、後ろに「、」や「て」が続く形。文を締める述語にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38292, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この計画は、子どもの教育に最適だ方法を選んでいる。", "corrected_sentence": "この計画は、子どもの教育に最適な方法を選んでいる。", "error_description": "名詞「方法」を修飾するので連体形「最適な」が必要。断定形「最適だ」は名詞に直接続けられない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "最適な", "is_correct": true, "explanation": "連体形。名詞「配置」を直接修飾する形で、ここでは答え。"}, {"text": "最適だった", "is_correct": false, "explanation": "過去の断定形で、名詞「席」の前には直接置けない。"}, {"text": "最適だろう", "is_correct": false, "explanation": "推量形で、名詞「席」を直接修飾できない。"}, {"text": "最適ならば", "is_correct": false, "explanation": "仮定形で、名詞「席」を直接修飾できない。"}], "correct_form": "最適な", "base_form": "最適", "form_label": "連体形", "sentence_index": 7, "explanations": {"最適な": "連体形。名詞「配置」を直接修飾する形で、ここでは答え。", "最適だった": "過去の断定形で、名詞「席」の前には直接置けない。", "最適だろう": "推量形で、名詞「席」を直接修飾できない。", "最適ならば": "仮定形で、名詞「席」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38294, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「留学する意思を話す」の「を」で、話す内容を示す。"}, {"text": "が", "is_correct": false, "explanation": "「意思が両親に話した」は、「話す」の主語にはならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「意思の両親に話した」は「の」で結ぶと意味が通らず、文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「意思から両親に話した」は起点の意味になり、ここでは合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「留学する意思を話す」の「を」で、話す内容を示す。", "が": "「意思が両親に話した」は、「話す」の主語にはならず不自然。", "の": "「意思の両親に話した」は「の」で結ぶと意味が通らず、文として成り立たない。", "から": "「意思から両親に話した」は起点の意味になり、ここでは合わない。"}, "error_tags": {"が": "主語（主格）", "の": "連体修飾（所有）", "から": "起点・由来"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38294, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「意思は変わらない」の主題を示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "「意思を変わらない」は、目的語を取らない「変わる」と合わず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「意思に変わらない」は「〜に変わる」の形にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「意思と変わらない」は並列の意味になり、文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "正解。「意思は変わらない」の主題を示す「は」。", "を": "「意思を変わらない」は、目的語を取らない「変わる」と合わず不自然。", "に": "「意思に変わらない」は「〜に変わる」の形にならず不自然。", "と": "「意思と変わらない」は並列の意味になり、文が成り立たない。"}, "error_tags": {"を": "対象（目的語）", "に": "変化の結果", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38294, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをしようと思う心。", "primary_collocate": null, "pronunciation": "いし", "ipa": "iɕi", "syllable_count": 2, "sentences": [{"text": "彼にはもうこの店で働く意思がないようだ。", "target_word": "意思", "complexity_tier": "T2", "furigana": "彼[かれ]にはもうこの店[みせ]で働[はたら]く意思[いし]がないようだ。", "sentence_source": "generated"}, {"text": "私は留学する意思を両親に話した。", "target_word": "意思", "complexity_tier": "T2", "furigana": "私[わたし]は留学[りゅうがく]する意思[いし]を両親[りょうしん]に話[はな]した。", "sentence_source": "generated"}, {"text": "相手に謝る意思があるなら、早く連絡したほうがいい。", "target_word": "意思", "complexity_tier": "T3", "furigana": "相手[あいて]に謝[あやま]る意思[いし]があるなら、早[はや]く連絡[れんらく]したほうがいい。", "sentence_source": "generated"}, {"text": "投票は、国民が自分の意思を示す大切な機会だ。", "target_word": "意思", "complexity_tier": "T3", "furigana": "投票[とうひょう]は、国民[こくみん]が自分[じぶん]の意思[いし]を示[しめ]す大切[たいせつ]な機会[きかい]だ。", "sentence_source": "generated"}, {"text": "赤ちゃんは泣くことで、自分の意思を伝える。", "target_word": "意思", "complexity_tier": "T2", "furigana": "赤[あか]ちゃんは泣[な]くことで、自分[じぶん]の意思[いし]を伝[つた]える。", "sentence_source": "generated"}, {"text": "彼女は結婚する意思を固めて、指輪を買いに行った。", "target_word": "意思", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は結婚[けっこん]する意思[いし]を固[かた]めて、指輪[ゆびわ]を買[か]いに行[い]った。", "sentence_source": "generated"}, {"text": "無理に参加させず、本人の意思を尊重しましょう。", "target_word": "意思", "complexity_tier": "T3", "furigana": "無理[むり]に参加[さんか]させず、本人[ほんにん]の意思[いし]を尊重[そんちょう]しましょう。", "sentence_source": "generated"}, {"text": "会社を辞める意思は変わらないと、部長にはっきり告げた。", "target_word": "意思", "complexity_tier": "T3", "furigana": "会社[かいしゃ]を辞[や]める意思[いし]は変[か]わらないと、部長[ぶちょう]にはっきり告[つ]げた。", "sentence_source": "generated"}, {"text": "「やりたくない」という意思を、彼は黙って首を振って表した。", "target_word": "意思", "complexity_tier": "T3", "furigana": "「やりたくない」という意思[いし]を、彼[かれ]は黙[だま]って首[くび]を振[ふ]って表[あらわ]した。", "sentence_source": "generated"}, {"text": "彼には協力する意思が少しもなく、会議にも来なかった。", "target_word": "意思", "complexity_tier": "T3", "furigana": "彼[かれ]には協力[きょうりょく]する意思[いし]が少[すこ]しもなく、会議[かいぎ]にも来[こ]なかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意思", "label": "基本形"}, {"form": "意思の", "label": "連体修飾"}, {"form": "意思を", "label": "目的語"}], "register": "neutral", "sense_fingerprint": "何かをしようと思う心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b24d15-9ff0-4e3d-8f40-83d3e5a40e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38294, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意思", "is_correct": true, "explanation": "正解。「働く意思がない」で、働こうとする気持ちがないという意味になる。"}, {"text": "借金", "is_correct": false, "explanation": "「働く借金」は文として成り立たず、文脈にも合わない。"}, {"text": "味", "is_correct": false, "explanation": "「働く味」は意味が通らない。"}, {"text": "財布", "is_correct": false, "explanation": "「働く財布」は不自然で、文の意味に合わない。"}], "explanations": {"意思": "正解。「働く意思がない」で、働こうとする気持ちがないという意味になる。", "借金": "「働く借金」は文として成り立たず、文脈にも合わない。", "味": "「働く味」は意味が通らない。", "財布": "「働く財布」は不自然で、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この外国語の意思を、先生に聞いてもわからなかった。", "explanation": "ここは〈意味〉の意味。語句の意味は「意味」と言い、「意思」は人の心の働きなので合わない。"}, {"text": "彼女は怒りで意思が高ぶり、声が震えていた。", "explanation": "ここは〈感情〉の意味。感情は高ぶると言うが、意思が高ぶるとは言わないので合わない。"}, {"text": "この時計は意思が正確で、一秒も狂わない。", "explanation": "ここは〈精度〉の意味。時計の性能は精度で言い表すが、「意思」は人の心の働きなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38294, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意思", "is_correct": true, "explanation": "正解。「本人の意思を尊重する」で、本人の考えを大切にするという意味になる。"}, {"text": "天気", "is_correct": false, "explanation": "「本人の天気を尊重する」は意味が通らない。"}, {"text": "寝相", "is_correct": false, "explanation": "「本人の寝相を尊重する」は文脈に合わず、意味が通らない。"}, {"text": "靴下", "is_correct": false, "explanation": "「本人の靴下を尊重する」は意味が通らない。"}], "explanations": {"意思": "正解。「本人の意思を尊重する」で、本人の考えを大切にするという意味になる。", "天気": "「本人の天気を尊重する」は意味が通らない。", "寝相": "「本人の寝相を尊重する」は文脈に合わず、意味が通らない。", "靴下": "「本人の靴下を尊重する」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は意思が明るく、初対面の人ともすぐ打ち解ける。", "explanation": "ここは〈性格〉の意味。性格は明るい・暗いと言えるが、意思を「明るい」と言うのは誤り。"}, {"text": "この湿布は意思がすぐに効いて、肩の痛みが和らいだ。", "explanation": "ここは〈効果〉の意味。湿布には効果が効くと言うが、意思が効くとは言わない。"}, {"text": "この記事は意思が長すぎて、途中で読むのをやめた。", "explanation": "ここは〈文章〉の意味。記事の分量は文章の長さで言い表すが、「意思」は人の心の働きなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38294, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この仕事を続けるかどうかは、自分の意思に決めてください。", "corrected_sentence": "この仕事を続けるかどうかは、自分の意思で決めてください。", "error_description": "誤り：「自分の意思に決める」。正しくは「自分の意思で決める」。自分の意思を根拠として決めるという意味で、「で」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38294, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は自分の意思を断って、仲間の提案に従った。", "corrected_sentence": "彼は自分の意思を曲げて、仲間の提案に従った。", "error_description": "誤り：「意思を断って」。正しくは「意思を曲げて」。「断つ」は関係や習慣に使う動詞で、自分の考えを変えて従うという意味にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38295, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「確かめる」の対象を示す「を」で、「意思を確かめて」となる。"}, {"text": "が", "is_correct": false, "explanation": "「意思が確かめて」は、「確かめる」の対象を「が」で示せないので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「意思に確かめて」は「に」の働きが合わず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「意思で確かめて」は手段の意味にならず、文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「確かめる」の対象を示す「を」で、「意思を確かめて」となる。", "が": "「意思が確かめて」は、「確かめる」の対象を「が」で示せないので不自然。", "に": "「意思に確かめて」は「に」の働きが合わず、文が成り立たない。", "で": "「意思で確かめて」は手段の意味にならず、文脈に合わない。"}, "error_tags": {"が": "主語（主格）", "に": "方向・相手", "で": "手段・根拠"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
