INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38295, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある行動や状態を実現しようとする心の働き。意志。", "primary_collocate": null, "pronunciation": "いし", "ipa": "iɕi", "syllable_count": 2, "sentences": [{"text": "友人の忠告を聞いても、彼は自分の意思を変えなかった。", "target_word": "意思", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の忠告[ちゅうこく]を聞[き]いても、彼[かれ]は自分[じぶん]の意思[いし]を変[か]えなかった。", "sentence_source": "generated"}, {"text": "医者は、患者本人の意思を確かめてから手術を始めた。", "target_word": "意思", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、患者[かんじゃ]本人[ほんにん]の意思[いし]を確[たし]かめてから手術[しゅじゅつ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "自分の意思をはっきり伝えないと、周りは理解してくれない。", "target_word": "意思", "complexity_tier": "T3", "furigana": "自分[じぶん]の意思[いし]をはっきり伝[つた]えないと、周[まわ]りは理解[りかい]してくれない。", "sentence_source": "generated"}, {"text": "彼は意思が固く、周りに何を言われても考えを変えない。", "target_word": "意思", "complexity_tier": "T3", "furigana": "彼[かれ]は意思[いし]が固[かた]く、周[まわ]りに何[なに]を言[い]われても考[かんが]えを変[か]えない。", "sentence_source": "generated"}, {"text": "親が反対しても、彼女の意思は変わらなかった。", "target_word": "意思", "complexity_tier": "T2", "furigana": "親[おや]が反対[はんたい]しても、彼女[かのじょ]の意思[いし]は変[か]わらなかった。", "sentence_source": "generated"}, {"text": "会議では、参加者がそれぞれ自分の意思を述べた。", "target_word": "意思", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、参加者[さんかしゃ]がそれぞれ自分[じぶん]の意思[いし]を述[の]べた。", "sentence_source": "generated"}, {"text": "本人の意思に反して、無理に契約させることはできない。", "target_word": "意思", "complexity_tier": "T3", "furigana": "本人[ほんにん]の意思[いし]に反[はん]して、無理[むり]に契約[けいやく]させることはできない。", "sentence_source": "generated"}, {"text": "犬は言葉を話さないが、しぐさで意思を伝えようとする。", "target_word": "意思", "complexity_tier": "T3", "furigana": "犬[いぬ]は言葉[ことば]を話[はな]さないが、しぐさで意思[いし]を伝[つた]えようとする。", "sentence_source": "generated"}, {"text": "退会する意思がある人は、今月中に事務所へ連絡してください。", "target_word": "意思", "complexity_tier": "T3", "furigana": "退会[たいかい]する意思[いし]がある人[ひと]は、今月中[こんげつちゅう]に事務所[じむしょ]へ連絡[れんらく]してください。", "sentence_source": "generated"}, {"text": "上司に反対の意思を示すには、勇気が必要だ。", "target_word": "意思", "complexity_tier": "T3", "furigana": "上司[じょうし]に反対[はんたい]の意思[いし]を示[しめ]すには、勇気[ゆうき]が必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意思", "label": "基本形"}, {"form": "意思の", "label": "連体修飾"}, {"form": "意思を", "label": "目的語"}], "register": "neutral", "sense_fingerprint": "行動を実現しようとする心の働き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b24d15-9ff0-4e3d-8f40-83d3e5a40e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38295, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意思", "is_correct": true, "explanation": "正解。「自分の意思を変えなかった」で、自分の考えを変えないという意味になる。"}, {"text": "天気", "is_correct": false, "explanation": "「自分の天気を変えなかった」は意味が通らない。"}, {"text": "湿度", "is_correct": false, "explanation": "「自分の湿度を変えなかった」は文脈に合わず、成り立たない。"}, {"text": "星座", "is_correct": false, "explanation": "「自分の星座を変えなかった」は成り立たない。"}], "explanations": {"意思": "正解。「自分の意思を変えなかった」で、自分の考えを変えないという意味になる。", "天気": "「自分の天気を変えなかった」は意味が通らない。", "湿度": "「自分の湿度を変えなかった」は文脈に合わず、成り立たない。", "星座": "「自分の星座を変えなかった」は成り立たない。"}, "sentence_index": 0, "correct_answer": "意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この古い単語の意思が、辞書を引いてもわからなかった。", "explanation": "ここは〈意味〉の意味。言葉の意味は「意味」と言い、「意思」は人の心の働きを指すので合わない。"}, {"text": "彼は意思が高く、どんな難題にも挑みたいと話した。", "explanation": "ここは〈意欲〉の意味。意欲は高い・低いと言えるが、意思は強い・固いと言うので「高い」は合わない。"}, {"text": "この扇風機は意思が強く、スイッチを入れると勝手に止まる。", "explanation": "ここは〈性能〉の意味。機械の働きは性能で言い表すが、「意思」は人の心の働きを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38295, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意思", "is_correct": true, "explanation": "正解。「本人の意思に反して」で、本人の考えや望みに逆らうという意味になる。"}, {"text": "財産", "is_correct": false, "explanation": "「本人の財産に反して」では意味が通らず、契約の文脈にも合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "「本人の年齢に反して」は文脈に合わず、意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "「本人の体重に反して」は意味が通らない。"}], "explanations": {"意思": "正解。「本人の意思に反して」で、本人の考えや望みに逆らうという意味になる。", "財産": "「本人の財産に反して」では意味が通らず、契約の文脈にも合わない。", "年齢": "「本人の年齢に反して」は文脈に合わず、意味が通らない。", "体重": "「本人の体重に反して」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は意思が明るく、いつも周りを笑わせる。", "explanation": "ここは〈性格〉の意味。性格は明るい・暗いと言えるが、意思を「明るい」と言うのは誤り。"}, {"text": "この薬は意思がよく効いて、すぐに熱が下がった。", "explanation": "ここは〈効き目〉の意味。薬は効き目が効くが、意思が薬のように効くとは言わない。"}, {"text": "明日は意思が晴れるでしょう。", "explanation": "ここは〈天気〉の意味。天気は晴れると言うが、意思が晴れるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38295, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は自分の意思に行動するつもりだ。", "corrected_sentence": "彼女は自分の意思で行動するつもりだ。", "error_description": "誤り：「意思に行動する」。正しくは「意思で行動する」。「自分の意思で」は、自分の考えを根拠・手段として行動するという意味で、「に」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38295, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は周りに流されず、自分の意思を立てて進んだ。", "corrected_sentence": "彼は周りに流されず、自分の意思を貫いて進んだ。", "error_description": "誤り：「意思を立てて」。正しくは「意思を貫いて」。「立てる」は計画や目標に使い、意思と結びつくのは「貫く」なので、ここは「貫いて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
