INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38296, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「決定は先に延ばされた」の主題を示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "「決定を先に延ばされた」は受け身の主語にならず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「決定に先に延ばされた」は「に」の働きが合わず、文が壊れる。"}, {"text": "と", "is_correct": false, "explanation": "「決定と先に延ばされた」は並列の意味になり、文脈に合わない。"}], "correct_answer": "は", "explanations": {"は": "正解。「決定は先に延ばされた」の主題を示す「は」。", "を": "「決定を先に延ばされた」は受け身の主語にならず、文が成り立たない。", "に": "「決定に先に延ばされた」は「に」の働きが合わず、文が壊れる。", "と": "「決定と先に延ばされた」は並列の意味になり、文脈に合わない。"}, "error_tags": {"を": "対象（目的語）", "に": "変化・結果", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38296, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを、これにする、と決めること。", "primary_collocate": null, "pronunciation": "けってい", "ipa": "kettei", "syllable_count": 4, "sentences": [{"text": "家族で話し合い、犬を飼うことを決定した。", "target_word": "決定", "complexity_tier": "T2", "furigana": "家族[かぞく]で話[はな]し合[あ]い、犬[いぬ]を飼[か]うことを決定[けってい]した。", "sentence_source": "generated"}, {"text": "学校は、運動会を来週に延期する決定をした。", "target_word": "決定", "complexity_tier": "T3", "furigana": "学校[がっこう]は、運動会[うんどうかい]を来週[らいしゅう]に延期[えんき]する決定[けってい]をした。", "sentence_source": "generated"}, {"text": "決定を急がずに、もう少し考えてみよう。", "target_word": "決定", "complexity_tier": "T2", "furigana": "決定[けってい]を急[いそ]がずに、もう少[すこ]し考[かんが]えてみよう。", "sentence_source": "generated"}, {"text": "優勝チームの決定は、最後の試合まで持ち越された。", "target_word": "決定", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]チームの決定[けってい]は、最後[さいご]の試合[しあい]まで持[も]ち越[こ]された。", "sentence_source": "generated"}, {"text": "新しい店の名前が決定し、看板の準備が始まった。", "target_word": "決定", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]の名前[なまえ]が決定[けってい]し、看板[かんばん]の準備[じゅんび]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "彼女は決定を下すのが早く、メニューを見て三秒で注文した。", "target_word": "決定", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は決定[けってい]を下[くだ]すのが早[はや]く、メニューを見[み]て三秒[さんびょう]で注文[ちゅうもん]した。", "sentence_source": "generated"}, {"text": "市長は、橋を建て直す決定を市民に説明した。", "target_word": "決定", "complexity_tier": "T3", "furigana": "市長[しちょう]は、橋[はし]を建[た]て直[なお]す決定[けってい]を市民[しみん]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "全員が納得するまで、決定は先に延ばされた。", "target_word": "決定", "complexity_tier": "T3", "furigana": "全員[ぜんいん]が納得[なっとく]するまで、決定[けってい]は先[さき]に延[の]ばされた。", "sentence_source": "generated"}, {"text": "日程の決定には、みんなの都合を聞く必要がある。", "target_word": "決定", "complexity_tier": "T3", "furigana": "日程[にってい]の決定[けってい]には、みんなの都合[つごう]を聞[き]く必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "引っ越しを決定してから、荷造りに一か月かかった。", "target_word": "決定", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しを決定[けってい]してから、荷造[にづく]りに一[いっ]か月[げつ]かかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "決定", "label": "基本形"}, {"form": "決定する", "label": "終止形"}, {"form": "決定した", "label": "過去形"}, {"form": "決定して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "何かをこれにすると決める行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: contains vocabulary far above tier T1: 持ち越さ (Zipf 2.28)','sentence 6 above tier T1: contains vocabulary far above tier T1: 建て直す (Zipf 2.21)','sentence 7 above tier T1: contains vocabulary far above tier T1: 延ばさ (Zipf 2.08)']::text[], '13b24d15-9ff0-4e3d-8f40-83d3e5a40e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38296, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "決定", "is_correct": true, "explanation": "正解。「犬を飼うことを決定した」で、飼うと決めたという意味になる。"}, {"text": "撮影", "is_correct": false, "explanation": "「飼うことを撮影した」は成り立たず、文の意味が通らない。"}, {"text": "解散", "is_correct": false, "explanation": "「飼うことを解散した」は意味が通らない。"}, {"text": "修理", "is_correct": false, "explanation": "「飼うことを修理した」は意味が通らない。"}], "explanations": {"決定": "正解。「犬を飼うことを決定した」で、飼うと決めたという意味になる。", "撮影": "「飼うことを撮影した」は成り立たず、文の意味が通らない。", "解散": "「飼うことを解散した」は意味が通らない。", "修理": "「飼うことを修理した」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "決定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この川の水は決定が澄んでいて、魚がよく見える。", "explanation": "ここは〈透明〉の意味。水の澄み具合は透明で言い表すが、「決定」は物事を決めることなので合わない。"}, {"text": "彼は決定が荒く、階段を上るのがつらそうだった。", "explanation": "ここは〈呼吸〉の意味。呼吸は荒いと言うが、決定が荒いとは言わない。"}, {"text": "彼は会議の前にみんなへ名刺を配ったあと、決定も配って回った。", "explanation": "ここは〈資料〉の意味。人に配れるのは資料などの物だが、「決定」は物事を決めることを指すので配るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38296, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "決定", "is_correct": true, "explanation": "正解。「橋を建て直す決定を説明した」で、建て直すと決めた内容を伝えるという意味になる。"}, {"text": "合唱", "is_correct": false, "explanation": "「建て直す合唱を説明した」は意味が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "「建て直す散歩を説明した」は文脈に合わず、意味が通らない。"}, {"text": "翻訳", "is_correct": false, "explanation": "「建て直す翻訳を説明した」は意味が通らない。"}], "explanations": {"決定": "正解。「橋を建て直す決定を説明した」で、建て直すと決めた内容を伝えるという意味になる。", "合唱": "「建て直す合唱を説明した」は意味が通らない。", "散歩": "「建て直す散歩を説明した」は文脈に合わず、意味が通らない。", "翻訳": "「建て直す翻訳を説明した」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "決定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議室の決定を予約した。", "explanation": "ここは〈確保〉の意味。会議室は確保すると言うが、「決定」は物事をはっきり決めることなので合わない。"}, {"text": "友達は野菜を買うために、決定を買いに行った。", "explanation": "ここは〈品物〉の意味。店で買えるのは品物だが、「決定」は物事を決めることなので売り買いの対象にならない。"}, {"text": "今日は朝から決定が降っている。", "explanation": "ここは〈雨〉の意味。空から落ちてくるのは雨だが、「決定」は物事を決めることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38296, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来年の旅行先について、クラスは決定を払った。", "corrected_sentence": "来年の旅行先について、クラスは決定を下した。", "error_description": "誤り：「決定を払った」。正しくは「決定を下した」。「払う」は代金や責任に使う動詞で、決定には「下す」を使うのが自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38296, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は引っ越しの決定を断って、街を離れた。", "corrected_sentence": "彼女は引っ越しの決定を下して、街を離れた。", "error_description": "誤り：「決定を断って」。正しくは「決定を下して」。「断る」は申し出に使い、決定には「下す」を使うのが自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
