INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38297, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事をはっきりと決めること。また、その決めた内容。", "primary_collocate": null, "pronunciation": "けってい", "ipa": "kettei", "syllable_count": 4, "sentences": [{"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "決定", "complexity_tier": "T5", "furigana": "グローバルな金融[きんゆう]市場[しじょう]やサプライチェーンといった社会[しゃかい]経済的[けいざいてき]文脈[ぶんみゃく]において、個々[ここ]の企業[きぎょう]や投資家[とうしか]といったミクロな主体[しゅたい]による局所的[きょくしょてき]な意思[いし]決定[けってい]は、決[けっ]して単純[たんじゅん]な線形[せんけい]モデルでは捉[とら]えきれない。", "sentence_source": "mined"}, {"text": "会議の結果、来月から新しい制度を始めることが決定した。", "target_word": "決定", "complexity_tier": "T3", "furigana": "会議[かいぎ]の結果[けっか]、来月[らいげつ]から新[あたら]しい制度[せいど]を始[はじ]めることが決定[けってい]した。", "sentence_source": "generated"}, {"text": "社長の決定に従って、全員が新しい計画を進めた。", "target_word": "決定", "complexity_tier": "T3", "furigana": "社長[しゃちょう]の決定[けってい]に従[したが]って、全員[ぜんいん]が新[あたら]しい計画[けいかく]を進[すす]めた。", "sentence_source": "generated"}, {"text": "最終的な決定は、来週の委員会で行われる。", "target_word": "決定", "complexity_tier": "T3", "furigana": "最終的[さいしゅうてき]な決定[けってい]は、来週[らいしゅう]の委員会[いいんかい]で行[おこな]われる。", "sentence_source": "generated"}, {"text": "彼は悩んだ末に、大学をやめるという決定を下した。", "target_word": "決定", "complexity_tier": "T3", "furigana": "彼[かれ]は悩[なや]んだ末[すえ]に、大学[だいがく]をやめるという決定[けってい]を下[くだ]した。", "sentence_source": "generated"}, {"text": "審判の決定に不満があっても、選手は従わなければならない。", "target_word": "決定", "complexity_tier": "T3", "furigana": "審判[しんぱん]の決定[けってい]に不満[ふまん]があっても、選手[せんしゅ]は従[したが]わなければならない。", "sentence_source": "generated"}, {"text": "旅行の行き先が決定したので、さっそく宿を予約した。", "target_word": "決定", "complexity_tier": "T3", "furigana": "旅行[りょこう]の行[い]き先[さき]が決定[けってい]したので、さっそく宿[やど]を予約[よやく]した。", "sentence_source": "generated"}, {"text": "一度出た決定は、簡単には取り消せない。", "target_word": "決定", "complexity_tier": "T2", "furigana": "一度[いちど]出[で]た決定[けってい]は、簡単[かんたん]には取[と]り消[け]せない。", "sentence_source": "generated"}, {"text": "選考の決定は、今週の金曜日に発表される。", "target_word": "決定", "complexity_tier": "T3", "furigana": "選考[せんこう]の決定[けってい]は、今週[こんしゅう]の金曜日[きんようび]に発表[はっぴょう]される。", "sentence_source": "generated"}, {"text": "その決定を聞いて、社員たちは驚いた様子だった。", "target_word": "決定", "complexity_tier": "T3", "furigana": "その決定[けってい]を聞[き]いて、社員[しゃいん]たちは驚[おどろ]いた様子[ようす]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "決定", "label": "基本形"}, {"form": "決定する", "label": "終止形"}, {"form": "決定した", "label": "過去形"}, {"form": "決定して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "はっきり決めること、またその決めた内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 6 words above tier T1 (max 2): サプライ (Zipf 3.19), 文脈 (Zipf 3.63), 個々 (Zipf 3.92), ミクロ (Zipf 3.34), 局所 (Zipf 3.35), 線形 (Zipf 2.97)','sentence 7 above tier T1: contains vocabulary far above tier T1: 取り消せ (Zipf 2.23)']::text[], '13b24d15-9ff0-4e3d-8f40-83d3e5a40e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38297, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "決定", "is_correct": true, "explanation": "正解。「意思決定」の後半で、「物事を決めること」の意味を表す。"}, {"text": "天気", "is_correct": false, "explanation": "「意思天気」は成り立たず、文脈にも合わない。"}, {"text": "運賃", "is_correct": false, "explanation": "「意思運賃」は意味が通らず、文の流れにも合わない。"}, {"text": "花火", "is_correct": false, "explanation": "「意思花火」は意味が通らない。"}], "explanations": {"決定": "正解。「意思決定」の後半で、「物事を決めること」の意味を表す。", "天気": "「意思天気」は成り立たず、文脈にも合わない。", "運賃": "「意思運賃」は意味が通らず、文の流れにも合わない。", "花火": "「意思花火」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "決定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この機械は昨日から決定して、動かなくなった。", "explanation": "ここは〈故障〉の意味。機械が動かなくなる場合は「故障する」と言い、「決定する」とは言わない。"}, {"text": "悩みは友達の一言で、すっかり決定した。", "explanation": "ここは〈解決〉の意味。悩みは解決すると言い、決定するとは言わない。"}, {"text": "彼は決定が高く、チームの中でも特に目立つ。", "explanation": "ここは〈能力〉の意味。人の能力は高いと言うが、決定を「高い」と言うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38297, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "決定", "is_correct": true, "explanation": "正解。「行き先が決定したので」で、行き先が決まったという意味になる。"}, {"text": "故障", "is_correct": false, "explanation": "「行き先が故障したので」は成り立たず、文脈にも合わない。"}, {"text": "出発", "is_correct": false, "explanation": "「行き先が出発した」は意味が通らず、文脈にも合わない。"}, {"text": "返信", "is_correct": false, "explanation": "「行き先が返信したので」は意味が通らず、文脈にも合わない。"}], "explanations": {"決定": "正解。「行き先が決定したので」で、行き先が決まったという意味になる。", "故障": "「行き先が故障したので」は成り立たず、文脈にも合わない。", "出発": "「行き先が出発した」は意味が通らず、文脈にも合わない。", "返信": "「行き先が返信したので」は意味が通らず、文脈にも合わない。"}, "sentence_index": 6, "correct_answer": "決定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この道は決定が安全で、夜でも安心して歩ける。", "explanation": "ここは〈治安〉の意味。夜道の状態は治安で言い表すが、「決定」は物事を決めることなので合わない。"}, {"text": "頭痛が決定して、薬を飲んでもなかなか治らない。", "explanation": "ここは〈おさまる〉の意味。頭痛は落ち着く・おさまると言い、「決定」は物事を決めることなので合わない。"}, {"text": "このスープは決定が濃くて、少しずつ飲むのが向いている。", "explanation": "ここは〈味〉の意味。スープは味が濃いと言うが、決定が濃いとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38297, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "そのチームは監督の決定を従って、練習を続けた。", "corrected_sentence": "そのチームは監督の決定に従って、練習を続けた。", "error_description": "誤り：「決定を従って」。正しくは「決定に従って」。「従う」は「に」を取る動詞なので、「を」ではなく「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38297, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私たちは話し合いの末に、郊外へ引っ越す決定を飲んだ。", "corrected_sentence": "私たちは話し合いの末に、郊外へ引っ越す決定を下した。", "error_description": "誤り：「決定を飲んだ」。正しくは「決定を下した」。決定は「下す」で表すのが自然で、「飲む」は決定の動詞として使わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38298, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「町内会の運営がうまくいく」の主語で、うまくいく対象を示す「が」です。"}, {"text": "を", "is_correct": false, "explanation": "「運営をうまくいく」は目的語になり、うまくいくという動詞とは成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「運営へうまくいく」は方向を示し、うまくいく主体の形として合いません。"}, {"text": "から", "is_correct": false, "explanation": "「運営からうまくいく」は起点を示すため、ここでは意味が通りません。"}], "correct_answer": "が", "explanations": {"が": "「町内会の運営がうまくいく」の主語で、うまくいく対象を示す「が」です。", "を": "「運営をうまくいく」は目的語になり、うまくいくという動詞とは成り立ちません。", "へ": "「運営へうまくいく」は方向を示し、うまくいく主体の形として合いません。", "から": "「運営からうまくいく」は起点を示すため、ここでは意味が通りません。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38298, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「運営がしっかりしている」の主語で、しっかりしている対象を示す「が」です。"}, {"text": "に", "is_correct": false, "explanation": "「運営にしっかりしている」は帰属として読まれ、状態を述べる主語にはなりません。"}, {"text": "へ", "is_correct": false, "explanation": "「運営へしっかりしている」は方向を示す形で、状態の主語にはなりません。"}, {"text": "と", "is_correct": false, "explanation": "「運営としっかりしている」は並列になり、主語として成り立ちません。"}], "correct_answer": "が", "explanations": {"が": "「運営がしっかりしている」の主語で、しっかりしている対象を示す「が」です。", "に": "「運営にしっかりしている」は帰属として読まれ、状態を述べる主語にはなりません。", "へ": "「運営へしっかりしている」は方向を示す形で、状態の主語にはなりません。", "と": "「運営としっかりしている」は並列になり、主語として成り立ちません。"}, "error_tags": {"に": "位置・帰属", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38298, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かをうまく動かすこと。", "primary_collocate": null, "pronunciation": "うんえい", "ipa": "ɯɴeː", "syllable_count": 4, "sentences": [{"text": "駅前のカフェは、若い夫婦が二人で運営しています。", "target_word": "運営", "complexity_tier": "T3", "furigana": "駅前[えきまえ]のカフェは、若[わか]い夫婦[ふうふ]が二人[ふたり]で運営[うんえい]しています。", "sentence_source": "generated"}, {"text": "町内会の運営がうまくいって、祭りは大成功でした。", "target_word": "運営", "complexity_tier": "T3", "furigana": "町内会[ちょうないかい]の運営[うんえい]がうまくいって、祭[まつ]りは大成功[だいせいこう]でした。", "sentence_source": "generated"}, {"text": "店の運営には、お金の管理が大切です。", "target_word": "運営", "complexity_tier": "T3", "furigana": "店[みせ]の運営[うんえい]には、お金[かね]の管理[かんり]が大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "彼は図書館の運営を手伝うボランティアをしています。", "target_word": "運営", "complexity_tier": "T3", "furigana": "彼[かれ]は図書館[としょかん]の運営[うんえい]を手伝[てつだ]うボランティアをしています。", "sentence_source": "generated"}, {"text": "運営が下手だったため、その店は一年でつぶれました。", "target_word": "運営", "complexity_tier": "T3", "furigana": "運営[うんえい]が下手[へた]だったため、その店[みせ]は一年[いちねん]でつぶれました。", "sentence_source": "generated"}, {"text": "学校の運営は、先生だけでなく保護者も協力しています。", "target_word": "運営", "complexity_tier": "T3", "furigana": "学校[がっこう]の運営[うんえい]は、先生[せんせい]だけでなく保護者[ほごしゃ]も協力[きょうりょく]しています。", "sentence_source": "generated"}, {"text": "大会の運営を担当する人は、前の日から会場に入ります。", "target_word": "運営", "complexity_tier": "T3", "furigana": "大会[たいかい]の運営[うんえい]を担当[たんとう]する人[ひと]は、前[まえ]の日[ひ]から会場[かいじょう]に入[はい]ります。", "sentence_source": "generated"}, {"text": "運営がしっかりしているので、安心して利用できます。", "target_word": "運営", "complexity_tier": "T3", "furigana": "運営[うんえい]がしっかりしているので、安心[あんしん]して利用[りよう]できます。", "sentence_source": "generated"}, {"text": "このクラブは、会員が交代で運営しています。", "target_word": "運営", "complexity_tier": "T3", "furigana": "このクラブは、会員[かいいん]が交代[こうたい]で運営[うんえい]しています。", "sentence_source": "generated"}, {"text": "無理のない運営を続けるために、仕事を分けました。", "target_word": "運営", "complexity_tier": "T3", "furigana": "無理[むり]のない運営[うんえい]を続[つづ]けるために、仕事[しごと]を分[わ]けました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "運営する", "label": "辞書形"}, {"form": "運営した", "label": "過去形"}, {"form": "運営して", "label": "て形"}, {"form": "運営される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "店や会などをうまく動かしていくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd1d8776-9703-44ca-b7cd-08292b44c2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38298, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "運営", "is_correct": true, "explanation": "店などをうまく動かして続けることを表す「運営」が、ここに入ります。"}, {"text": "感激", "is_correct": false, "explanation": "感激は心が強く動く状態で、カフェを動かす行為の意味にはなりません。"}, {"text": "絶句", "is_correct": false, "explanation": "絶句は言葉が出なくなる状態で、カフェの仕事を表す動詞としては合いません。"}, {"text": "放心", "is_correct": false, "explanation": "放心は気が抜けた状態で、店を動かすという文脈には合いません。"}], "explanations": {"運営": "店などをうまく動かして続けることを表す「運営」が、ここに入ります。", "感激": "感激は心が強く動く状態で、カフェを動かす行為の意味にはなりません。", "絶句": "絶句は言葉が出なくなる状態で、カフェの仕事を表す動詞としては合いません。", "放心": "放心は気が抜けた状態で、店を動かすという文脈には合いません。"}, "sentence_index": 0, "correct_answer": "運営"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は毎晩、家族の夕食を運営しています。", "explanation": "ここは〈調理〉の意味です。料理を作るのは調理で、運営は組織や事業を動かす意味です。"}, {"text": "父は毎朝、車を洗って会社へ行きます。", "explanation": "ここは〈洗車〉の意味です。車を洗うことは洗車で、運営は店や会などをうまく動かす意味です。"}, {"text": "毎日、英語を運営しています。", "explanation": "ここは〈学習〉の意味です。言語を身につけるのは学習で、運営は組織や事業を動かす意味です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38298, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "運営", "is_correct": true, "explanation": "大会を動かす仕事を指す「運営」が、担当の対象として入ります。"}, {"text": "満喫", "is_correct": false, "explanation": "満喫は十分に楽しむことで、大会の仕事を担当するという文脈にはなりません。"}, {"text": "感嘆", "is_correct": false, "explanation": "感嘆は感心する気持ちで、担当する対象にはならず意味が通りません。"}, {"text": "飽和", "is_correct": false, "explanation": "飽和は満ちて限界になる状態で、大会を担当する対象としては成り立ちません。"}], "explanations": {"運営": "大会を動かす仕事を指す「運営」が、担当の対象として入ります。", "満喫": "満喫は十分に楽しむことで、大会の仕事を担当するという文脈にはなりません。", "感嘆": "感嘆は感心する気持ちで、担当する対象にはならず意味が通りません。", "飽和": "飽和は満ちて限界になる状態で、大会を担当する対象としては成り立ちません。"}, "sentence_index": 6, "correct_answer": "運営"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日、論文の運営を続けています。", "explanation": "ここは〈研究〉の意味です。論文を調べ考えるのは研究で、運営は組織や事業を動かす意味です。"}, {"text": "毎朝三十分、健康を運営するために散歩しています。", "explanation": "ここは〈管理〉との混同です。健康の状態を保ち見守るのは管理と言い、運営は組織や事業を動かす意味です。"}, {"text": "毎晩、ピアノを運営しています。", "explanation": "ここは〈演奏〉の意味です。楽器を弾いて音を出すのは演奏で、運営は組織や事業を動かす意味です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38298, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "図書館の運営が市が担当しています。", "corrected_sentence": "図書館の運営を市が担当しています。", "error_description": "「担当する」の対象は「を」で示します。「が」にすると運営が主語になり、担当の対象を表す形が崩れます。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38298, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会の運営を、会員が交代で弾いています。", "corrected_sentence": "会の運営を、会員が交代で担っています。", "error_description": "「運営」と組み合わせる動詞は「担う」です。「弾く」は楽器を演奏する動詞なので、運営の仕事には合いません。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38299, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「市が運営する」の主語で、運営する主体を示す「が」です。"}, {"text": "を", "is_correct": false, "explanation": "「市を運営する」は市を目的語にする形になり、市が運営するという意味になりません。"}, {"text": "へ", "is_correct": false, "explanation": "「市へ運営する」は方向を示す形で、運営の主体にはなりません。"}, {"text": "より", "is_correct": false, "explanation": "「市より運営する」は比較の意味になり、運営の主体としては成り立ちません。"}], "correct_answer": "が", "explanations": {"が": "「市が運営する」の主語で、運営する主体を示す「が」です。", "を": "「市を運営する」は市を目的語にする形になり、市が運営するという意味になりません。", "へ": "「市へ運営する」は方向を示す形で、運営の主体にはなりません。", "より": "「市より運営する」は比較の意味になり、運営の主体としては成り立ちません。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38299, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「運営を任された」の目的語を示す「を」で、任された対象になります。"}, {"text": "で", "is_correct": false, "explanation": "「運営で任された」は手段を示し、任される対象を表す形にはなりません。"}, {"text": "へ", "is_correct": false, "explanation": "「運営へ任された」は方向を示し、任される対象の形として不自然です。"}, {"text": "に", "is_correct": false, "explanation": "「運営に任された」は帰属として読まれ、任される対象は「を」で示します。"}], "correct_answer": "を", "explanations": {"を": "「運営を任された」の目的語を示す「を」で、任された対象になります。", "で": "「運営で任された」は手段を示し、任される対象を表す形にはなりません。", "へ": "「運営へ任された」は方向を示し、任される対象の形として不自然です。", "に": "「運営に任された」は帰属として読まれ、任される対象は「を」で示します。"}, "error_tags": {"で": "手段", "へ": "方向", "に": "位置・帰属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38299, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "組織や事業、システムなどを管理し、動かしていくこと。", "primary_collocate": null, "pronunciation": "うんえい", "ipa": "ɯɴeː", "syllable_count": 4, "sentences": [{"text": "この会社はホテルを三つ運営しています。", "target_word": "運営", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]はホテルを三[みっ]つ運営[うんえい]しています。", "sentence_source": "generated"}, {"text": "市が運営する体育館は、料金が安くて人気です。", "target_word": "運営", "complexity_tier": "T3", "furigana": "市[し]が運営[うんえい]する体育館[たいいくかん]は、料金[りょうきん]が安[やす]くて人気[にんき]です。", "sentence_source": "generated"}, {"text": "このサイトの運営について、利用者から意見が集まりました。", "target_word": "運営", "complexity_tier": "T3", "furigana": "このサイトの運営[うんえい]について、利用者[りようしゃ]から意見[いけん]が集[あつ]まりました。", "sentence_source": "generated"}, {"text": "非営利団体は、寄付金で事業を運営しています。", "target_word": "運営", "complexity_tier": "T3", "furigana": "非営利団体[ひえいりだんたい]は、寄付金[きふきん]で事業[じぎょう]を運営[うんえい]しています。", "sentence_source": "generated"}, {"text": "夜中にシステムの運営を担当する人が、問題を直しました。", "target_word": "運営", "complexity_tier": "T3", "furigana": "夜中[よなか]にシステムの運営[うんえい]を担当[たんとう]する人[ひと]が、問題[もんだい]を直[なお]しました。", "sentence_source": "generated"}, {"text": "新しい社長は、会社の運営を大きく変えました。", "target_word": "運営", "complexity_tier": "T3", "furigana": "新[あたら]しい社長[しゃちょう]は、会社[かいしゃ]の運営[うんえい]を大[おお]きく変[か]えました。", "sentence_source": "generated"}, {"text": "病院の運営には、国からの補助金も使われています。", "target_word": "運営", "complexity_tier": "T3", "furigana": "病院[びょういん]の運営[うんえい]には、国[くに]からの補助金[ほじょきん]も使[つか]われています。", "sentence_source": "generated"}, {"text": "劇場の運営を任された彼は、まず赤字を減らしました。", "target_word": "運営", "complexity_tier": "T3", "furigana": "劇場[げきじょう]の運営[うんえい]を任[まか]された彼[かれ]は、まず赤字[あかじ]を減[へ]らしました。", "sentence_source": "generated"}, {"text": "組織を円滑に運営するには、ルールが必要です。", "target_word": "運営", "complexity_tier": "T3", "furigana": "組織[そしき]を円滑[えんかつ]に運営[うんえい]するには、ルールが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "運営を始めて三年で、その事業は黒字になりました。", "target_word": "運営", "complexity_tier": "T3", "furigana": "運営[うんえい]を始[はじ]めて三年[さんねん]で、その事業[じぎょう]は黒字[くろじ]になりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "運営する", "label": "辞書形"}, {"form": "運営した", "label": "過去形"}, {"form": "運営して", "label": "て形"}, {"form": "運営される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "組織や事業、システムを管理して動かし続けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd1d8776-9703-44ca-b7cd-08292b44c2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38299, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "運営", "is_correct": true, "explanation": "ホテルという事業を動かし続けることを表す「運営」が、ここに入ります。"}, {"text": "解答", "is_correct": false, "explanation": "解答は問題への答えを指し、ホテルを対象にする動詞としては成り立ちません。"}, {"text": "絶句", "is_correct": false, "explanation": "絶句は言葉が出なくなる状態で、ホテルを対象にする行為ではありません。"}, {"text": "放心", "is_correct": false, "explanation": "放心は気が抜けた状態を表し、ホテルを動かす行為の意味にはなりません。"}], "explanations": {"運営": "ホテルという事業を動かし続けることを表す「運営」が、ここに入ります。", "解答": "解答は問題への答えを指し、ホテルを対象にする動詞としては成り立ちません。", "絶句": "絶句は言葉が出なくなる状態で、ホテルを対象にする行為ではありません。", "放心": "放心は気が抜けた状態を表し、ホテルを動かす行為の意味にはなりません。"}, "sentence_index": 0, "correct_answer": "運営"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、愛犬を運営して近くの公園を歩きます。", "explanation": "ここは〈散歩〉の意味です。犬を連れて歩くのは散歩で、運営は組織や事業、システムなどを管理して動かす意味です。"}, {"text": "パイロットは、毎日飛行機を運営しています。", "explanation": "ここは〈操縦〉の意味です。飛行機や船を操るのは操縦で、運営は組織や事業を動かす意味です。"}, {"text": "この小説を、英語に運営しています。", "explanation": "ここは〈翻訳〉の意味です。ある言語の文章を別の言語に置き換えるのは翻訳で、運営は事業を動かす意味です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38299, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "運営", "is_correct": true, "explanation": "病院という組織を動かす意味の「運営」が、補助金が使われる文脈に合います。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩く行為で、病院の何かを表す語として補助金の文脈には合いません。"}, {"text": "注目", "is_correct": false, "explanation": "注目は関心を向けることで、補助金の使い道を述べる文脈には合いません。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は寝過ごすことで、病院に補助金を使う話としては成り立ちません。"}], "explanations": {"運営": "病院という組織を動かす意味の「運営」が、補助金が使われる文脈に合います。", "散歩": "散歩は歩く行為で、病院の何かを表す語として補助金の文脈には合いません。", "注目": "注目は関心を向けることで、補助金の使い道を述べる文脈には合いません。", "寝坊": "寝坊は寝過ごすことで、病院に補助金を使う話としては成り立ちません。"}, "sentence_index": 6, "correct_answer": "運営"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は毎週、生徒を運営しています。", "explanation": "ここは〈指導〉の意味です。生徒に教え導くのは指導で、運営は組織や事業を動かす意味です。"}, {"text": "毎晩、英単語を運営して覚えています。", "explanation": "ここは〈暗記〉の意味です。単語を覚えるのは暗記で、運営は組織や事業を動かす意味です。"}, {"text": "彼は新しい曲を運営しました。", "explanation": "ここは〈作曲〉の意味です。曲を作るのは作曲で、運営は組織や事業を動かす意味です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38299, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この施設の運営を、地元の団体が協力しています。", "corrected_sentence": "この施設の運営に、地元の団体が協力しています。", "error_description": "「協力する」の対象は「に」で示します。「を」にすると運営が目的語になり、協力するという文として不自然になります。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38299, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この劇場は、市の文化課が運営を飲んでいます。", "corrected_sentence": "この劇場は、市の文化課が運営を担当しています。", "error_description": "「運営を」と組み合わせる動詞は「担当する」などです。「飲む」は飲み物にしか使えず、運営には合いません。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
