INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38300, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空気の中に混じっている、目に見えないガスです。体に悪いものです。", "primary_collocate": null, "pronunciation": "しーおー", "ipa": "ɕiːoː", "syllable_count": 4, "sentences": [{"text": "CO は色もにおいもないので、気づきにくいガスです。", "target_word": "CO", "complexity_tier": "T3", "furigana": "CO は色[いろ]もにおいもないので、気[き]づきにくいガスです。", "sentence_source": "generated"}, {"text": "古いストーブを使うと、部屋に CO がたまることがあります。", "target_word": "CO", "complexity_tier": "T3", "furigana": "古[ふる]いストーブを使[つか]うと、部屋[へや]に CO がたまることがあります。", "sentence_source": "generated"}, {"text": "CO を吸うと、頭が痛くなったり、気分が悪くなったりします。", "target_word": "CO", "complexity_tier": "T3", "furigana": "CO を吸[す]うと、頭[あたま]が痛[いた]くなったり、気分[きぶん]が悪[わる]くなったりします。", "sentence_source": "generated"}, {"text": "車の排気ガスには、CO が含まれています。", "target_word": "CO", "complexity_tier": "T3", "furigana": "車[くるま]の排気[はいき]ガスには、CO が含[ふく]まれています。", "sentence_source": "generated"}, {"text": "窓を閉めたまま火を使うと、CO が出て危険です。", "target_word": "CO", "complexity_tier": "T3", "furigana": "窓[まど]を閉[し]めたまま火[ひ]を使[つか]うと、CO が出[で]て危険[きけん]です。", "sentence_source": "generated"}, {"text": "空気中の CO を調べる機械が、台所に置いてあります。", "target_word": "CO", "complexity_tier": "T3", "furigana": "空気中[くうきちゅう]の CO を調[しら]べる機械[きかい]が、台所[だいどころ]に置[お]いてあります。", "sentence_source": "generated"}, {"text": "キャンプで炭を使うときは、CO に気をつけてください。", "target_word": "CO", "complexity_tier": "T3", "furigana": "キャンプで炭[すみ]を使[つか]うときは、CO に気[き]をつけてください。", "sentence_source": "generated"}, {"text": "換気をしないと、CO で具合が悪くなる人もいます。", "target_word": "CO", "complexity_tier": "T3", "furigana": "換気[かんき]をしないと、CO で具合[ぐあい]が悪[わる]くなる人[ひと]もいます。", "sentence_source": "generated"}, {"text": "CO は目に見えないため、警報器で知らせます。", "target_word": "CO", "complexity_tier": "T3", "furigana": "CO は目[め]に見[み]えないため、警報器[けいほうき]で知[し]らせます。", "sentence_source": "generated"}, {"text": "冬は部屋を閉め切るので、CO の事故が増えます。", "target_word": "CO", "complexity_tier": "T3", "furigana": "冬[ふゆ]は部屋[へや]を閉[し]め切[き]るので、CO の事故[じこ]が増[ふ]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "CO", "label": "基本形"}], "register": "polite", "sense_fingerprint": "空気に混じる目に見えない、体に悪いガス", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd1d8776-9703-44ca-b7cd-08292b44c2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38300, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "CO", "is_correct": true, "explanation": "正解。主語に CO を入れると、色もにおいもない目に見えないガスの説明になる。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は白い固体で、ガスではないので「ガスです」と合わない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は部屋のことで、ガスではないので「ガスです」と合わない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は液体の水で、気体ではないので「ガスです」と合わない。"}], "explanations": {"CO": "正解。主語に CO を入れると、色もにおいもない目に見えないガスの説明になる。", "砂糖": "砂糖は白い固体で、ガスではないので「ガスです」と合わない。", "教室": "教室は部屋のことで、ガスではないので「ガスです」と合わない。", "雨": "雨は液体の水で、気体ではないので「ガスです」と合わない。"}, "sentence_index": 0, "correct_answer": "CO"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "植物は光合成のときに CO を吸収して、酸素を出します。", "explanation": "ここは〈二酸化炭素〉の意味。光合成で植物が吸うのは二酸化炭素で、CO は有毒な一酸化炭素なので合わない。"}, {"text": "CO が目にしみて、涙が出ました。", "explanation": "ここは〈煙〉の意味。煙は目にしみるが、CO は無色で目に見えず、目を刺激しないので合わない。"}, {"text": "体の細胞は CO を使ってエネルギーを作るので、CO をたくさん吸うと元気になります。", "explanation": "ここは〈酸素〉の意味。細胞のエネルギーに使うのは酸素で、CO は吸うと体に害がある毒なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38300, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "CO", "is_correct": true, "explanation": "正解。炭を使うときに注意すべき対象は CO なので、「CO に気をつけて」と自然につながる。"}, {"text": "自転車", "is_correct": false, "explanation": "自転車は乗り物で、炭の使用時に気をつける対象としては合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は本で、炭を使うときの注意対象として合わない。"}, {"text": "絵の具", "is_correct": false, "explanation": "絵の具は絵をかく道具で、炭を使うときの注意対象として合わない。"}], "explanations": {"CO": "正解。炭を使うときに注意すべき対象は CO なので、「CO に気をつけて」と自然につながる。", "自転車": "自転車は乗り物で、炭の使用時に気をつける対象としては合わない。", "教科書": "教科書は本で、炭を使うときの注意対象として合わない。", "絵の具": "絵の具は絵をかく道具で、炭を使うときの注意対象として合わない。"}, "sentence_index": 6, "correct_answer": "CO"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "CO は卵が腐ったようなにおいがするので、すぐに気づきます。", "explanation": "ここは〈硫化水素〉の意味。硫化水素は腐った卵のようなにおいがするが、CO は無色無臭なので合わない。"}, {"text": "レントゲン検査では、CO が体を通り抜けて写真を撮ります。", "explanation": "ここは〈放射線〉の意味。写真を撮るために体を通り抜けるのは放射線で、CO は気体の毒なので合わない。"}, {"text": "やかんの口から CO が白く出ています。", "explanation": "ここは〈水蒸気〉の意味。水蒸気は白く見えるが、CO は無色で目に見えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38300, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を閉めたまま炭を使うと、CO を部屋にたまると危険です。", "corrected_sentence": "窓を閉めたまま炭を使うと、CO が部屋にたまると危険です。", "error_description": "誤りは「CO を」。「たまる」は目的語を取らない自動詞なので、主語の CO には「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38300, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "空気中の CO を食べる機械が、教室に置いてあります。", "corrected_sentence": "空気中の CO を測る機械が、教室に置いてあります。", "error_description": "誤りは「食べる」。CO は気体なので「食べる」とは組み合わない。「測る」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
