INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38301, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "一酸化炭素の略語。無色無臭の有毒ガスであり、不完全燃焼によって発生します。", "primary_collocate": null, "pronunciation": "しーおー", "ipa": "ɕiːoː", "syllable_count": 4, "sentences": [{"text": "CO は一酸化炭素の略で、不完全燃焼のときに発生します。", "target_word": "CO", "complexity_tier": "T3", "furigana": "CO は一酸化炭素[いっさんかたんそ]の略[りゃく]で、不完全燃焼[ふかんぜんねんしょう]のときに発生[はっせい]します。", "sentence_source": "generated"}, {"text": "CO は無色無臭なので、人間の感覚では発見できません。", "target_word": "CO", "complexity_tier": "T3", "furigana": "CO は無色無臭[むしょくむしゅう]なので、人間[にんげん]の感覚[かんかく]では発見[はっけん]できません。", "sentence_source": "generated"}, {"text": "ガス機器が不完全燃焼を起こすと、CO が大量に出ます。", "target_word": "CO", "complexity_tier": "T3", "furigana": "ガス機器[きき]が不完全燃焼[ふかんぜんねんしょう]を起[お]こすと、CO が大量[たいりょう]に出[で]ます。", "sentence_source": "generated"}, {"text": "実験室では、CO の濃度を機械で測っています。", "target_word": "CO", "complexity_tier": "T3", "furigana": "実験室[じっけんしつ]では、CO の濃度[のうど]を機械[きかい]で測[はか]っています。", "sentence_source": "generated"}, {"text": "CO は有毒ガスなので、少量でも長く吸うと危険です。", "target_word": "CO", "complexity_tier": "T3", "furigana": "CO は有毒[ゆうどく]ガスなので、少量[しょうりょう]でも長[なが]く吸[す]うと危険[きけん]です。", "sentence_source": "generated"}, {"text": "一酸化炭素中毒を防ぐため、CO の警報器を設置しました。", "target_word": "CO", "complexity_tier": "T3", "furigana": "一酸化炭素中毒[いっさんかたんそちゅうどく]を防[ふせ]ぐため、CO の警報器[けいほうき]を設置[せっち]しました。", "sentence_source": "generated"}, {"text": "排気ガスに含まれる CO の量は、法律で決められています。", "target_word": "CO", "complexity_tier": "T3", "furigana": "排気[はいき]ガスに含[ふく]まれる CO の量[りょう]は、法律[ほうりつ]で決[き]められています。", "sentence_source": "generated"}, {"text": "火災の現場では、煙に混じった CO で亡くなる人が多いです。", "target_word": "CO", "complexity_tier": "T3", "furigana": "火災[かさい]の現場[げんば]では、煙[けむり]に混[ま]じった CO で亡[な]くなる人[ひと]が多[おお]いです。", "sentence_source": "generated"}, {"text": "技師は、CO の発生源を調べるために、配管を点検しました。", "target_word": "CO", "complexity_tier": "T3", "furigana": "技師[ぎし]は、CO の発生源[はっせいげん]を調[しら]べるために、配管[はいかん]を点検[てんけん]しました。", "sentence_source": "generated"}, {"text": "教科書には「CO は血液中の酸素の運びを邪魔する」と書いてあります。", "target_word": "CO", "complexity_tier": "T3", "furigana": "教科書[きょうかしょ]には「CO は血液中[けつえきちゅう]の酸素[さんそ]の運[はこ]びを邪魔[じゃま]する」と書[か]いてあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "CO", "label": "基本形"}], "register": "polite", "sense_fingerprint": "一酸化炭素の略語、不完全燃焼で出る無色無臭の有毒ガス", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd1d8776-9703-44ca-b7cd-08292b44c2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38301, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "CO", "is_correct": true, "explanation": "正解。CO は一酸化炭素の略なので、「CO は一酸化炭素の略で」と自然に続く。"}, {"text": "酸素", "is_correct": false, "explanation": "酸素は別の気体で、一酸化炭素の略ではないので「略で」と合わない。"}, {"text": "二酸化炭素", "is_correct": false, "explanation": "二酸化炭素は別の気体で、一酸化炭素の略ではないので合わない。"}, {"text": "水素", "is_correct": false, "explanation": "水素は別の気体で、一酸化炭素の略ではないので合わない。"}], "explanations": {"CO": "正解。CO は一酸化炭素の略なので、「CO は一酸化炭素の略で」と自然に続く。", "酸素": "酸素は別の気体で、一酸化炭素の略ではないので「略で」と合わない。", "二酸化炭素": "二酸化炭素は別の気体で、一酸化炭素の略ではないので合わない。", "水素": "水素は別の気体で、一酸化炭素の略ではないので合わない。"}, "sentence_index": 0, "correct_answer": "CO"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ソーダ水の泡は、CO が作っています。", "explanation": "ここは〈二酸化炭素〉の意味。ソーダ水の泡は二酸化炭素なので、有毒な CO とは合わない。"}, {"text": "隣の工事の CO で、昼寝ができません。", "explanation": "ここは〈騒音〉の意味。工事の音で眠れないのは騒音で、CO は無色無臭の気体なので合わない。"}, {"text": "この花は、CO がとても良い香りがします。", "explanation": "ここは〈香り〉の意味。花がいい香りを放つのは香りで、CO は無臭の気体なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38301, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "CO", "is_correct": true, "explanation": "正解。排気ガスに含まれて量が決められるのは CO なので、文として自然に続く。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は排気ガスに含まれないので、「排気ガスに含まれる砂糖の量」は成り立たない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所で、排気ガスに含まれるものではないので合わない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は排気ガスに含まれるものではなく、量を法律で決める対象としても合わない。"}], "explanations": {"CO": "正解。排気ガスに含まれて量が決められるのは CO なので、文として自然に続く。", "砂糖": "砂糖は排気ガスに含まれないので、「排気ガスに含まれる砂糖の量」は成り立たない。", "教室": "教室は場所で、排気ガスに含まれるものではないので合わない。", "雨": "雨は排気ガスに含まれるものではなく、量を法律で決める対象としても合わない。"}, "sentence_index": 6, "correct_answer": "CO"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "プールの消毒には、CO を入れます。", "explanation": "ここは〈塩素〉の意味。プールの消毒に使うのは塩素で、CO にはその働きがないので合わない。"}, {"text": "手術の前に、CO を注射します。", "explanation": "ここは〈麻酔薬〉の意味。手術の前に注射するのは麻酔薬で、CO は毒性のある気体なので合わない。"}, {"text": "湿った場所では CO がさびやすいです。", "explanation": "ここは〈金属〉の意味。さびるのは金属で、気体の CO はさびないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38301, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空気中の CO に検出する装置を使いました。", "corrected_sentence": "空気中の CO を検出する装置を使いました。", "error_description": "誤りは「に」。「検出する」は目的語に「を」を取るので、CO には「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38301, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "CO を飲む機械が、工場に置かれています。", "corrected_sentence": "CO を測る機械が、工場に置かれています。", "error_description": "誤りは「飲む」。CO は気体なので「飲む」とは組み合わない。「測る」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38304, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「美術部門があります」と、存在を表す「が」が続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「ある」は目的語を取らないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐが、「美術部門のあります」と動詞に続けられないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、存在を表す主語の位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「美術部門があります」と、存在を表す「が」が続く。", "を": "「を」は目的語を示すが、「ある」は目的語を取らないので合わない。", "の": "「の」は名詞どうしをつなぐが、「美術部門のあります」と動詞に続けられないので合わない。", "へ": "「へ」は方向を示すが、存在を表す主語の位置には入らない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38304, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「部門が違う」と、部門を主語にして違いを述べる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は対象を示すが、「部門に違う」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる基準を示すが、「部門より違う」では比較の文にならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「部門から違う」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「部門が違う」と、部門を主語にして違いを述べる。", "に": "「に」は対象を示すが、「部門に違う」は成り立たない。", "より": "「より」は比べる基準を示すが、「部門より違う」では比較の文にならない。", "から": "「から」は起点を示すが、「部門から違う」は意味が通らない。"}, "error_tags": {"に": "対象", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38304, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "仕事や学校などの中で、いくつかに分けられたまとまりのことです。", "primary_collocate": null, "pronunciation": "ぶもん", "ipa": "bɯmoɴ", "syllable_count": 3, "sentences": [{"text": "私は会社の営業部門で働いています。", "target_word": "部門", "complexity_tier": "T3", "furigana": "私[わたし]は会社[かいしゃ]の営業[えいぎょう]部門[ぶもん]で働[はたら]いています。", "sentence_source": "generated"}, {"text": "この学校には音楽部門と美術部門があります。", "target_word": "部門", "complexity_tier": "T3", "furigana": "この学校[がっこう]には音楽[おんがく]部門[ぶもん]と美術[びじゅつ]部門[ぶもん]があります。", "sentence_source": "generated"}, {"text": "新しい商品を作る部門は、とても忙しいです。", "target_word": "部門", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]を作[つく]る部門[ぶもん]は、とても忙[いそが]しいです。", "sentence_source": "generated"}, {"text": "経理部門の人に、領収書を出してください。", "target_word": "部門", "complexity_tier": "T3", "furigana": "経理[けいり]部門[ぶもん]の人[ひと]に、領収書[りょうしゅうしょ]を出[だ]してください。", "sentence_source": "generated"}, {"text": "彼は去年、開発部門から広報部門に移りました。", "target_word": "部門", "complexity_tier": "T3", "furigana": "彼[かれ]は去年[きょねん]、開発[かいはつ]部門[ぶもん]から広報[こうほう]部門[ぶもん]に移[うつ]りました。", "sentence_source": "generated"}, {"text": "この部門の人たちは、毎朝八時に集まります。", "target_word": "部門", "complexity_tier": "T3", "furigana": "この部門[ぶもん]の人[ひと]たちは、毎朝[まいあさ]八時[はちじ]に集[あつ]まります。", "sentence_source": "generated"}, {"text": "人数が増えたので、会社を三つの部門に分けました。", "target_word": "部門", "complexity_tier": "T3", "furigana": "人数[にんずう]が増[ふ]えたので、会社[かいしゃ]を三[みっ]つの部門[ぶもん]に分[わ]けました。", "sentence_source": "generated"}, {"text": "部門が違うので、あの人とはあまり話したことがありません。", "target_word": "部門", "complexity_tier": "T3", "furigana": "部門[ぶもん]が違[ちが]うので、あの人[ひと]とはあまり話[はな]したことがありません。", "sentence_source": "generated"}, {"text": "売り上げが下がった部門は、来月から計画を見直します。", "target_word": "部門", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが下[さ]がった部門[ぶもん]は、来月[らいげつ]から計画[けいかく]を見直[みなお]します。", "sentence_source": "generated"}, {"text": "パソコンが壊れたので、情報部門に電話しました。", "target_word": "部門", "complexity_tier": "T3", "furigana": "パソコンが壊[こわ]れたので、情報[じょうほう]部門[ぶもん]に電話[でんわ]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "部門", "label": "基本形"}, {"form": "部門別", "label": "接尾形"}], "register": "polite", "sense_fingerprint": "会社や学校の中で分けられた、仕事上のまとまり（営業部門・開発部門など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd1d8776-9703-44ca-b7cd-08292b44c2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38304, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部門", "is_correct": true, "explanation": "正解。「営業部門で働く」と会社の区切りを表し、自然に続く。"}, {"text": "製品", "is_correct": false, "explanation": "製品は会社が作る物で、「営業製品で働く」とは言えない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の状態で、働く場所を表さないので合わない。"}, {"text": "機械", "is_correct": false, "explanation": "機械は道具で、働く場所の名前にはならないので合わない。"}], "explanations": {"部門": "正解。「営業部門で働く」と会社の区切りを表し、自然に続く。", "製品": "製品は会社が作る物で、「営業製品で働く」とは言えない。", "天気": "天気は空の状態で、働く場所を表さないので合わない。", "機械": "機械は道具で、働く場所の名前にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "部門"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "車の部門が壊れたので、交換しました。", "explanation": "ここは〈部品〉の意味。壊れて交換するのは部品で、組織の区切りである部門は壊れないので合わない。"}, {"text": "この本の最後の部門は、とても面白いです。", "explanation": "ここは〈部分〉の意味。本の一部を指すのは部分で、部門は組織の区切りなので合わない。"}, {"text": "手の部門が痛くて、物が握れません。", "explanation": "ここは〈部位〉の意味。手の一部を指すのは部位で、組織の区切りの部門ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38304, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部門", "is_correct": true, "explanation": "正解。「会社を三つの部門に分けた」と自然に続く。"}, {"text": "花", "is_correct": false, "explanation": "花は植物で、会社を分ける単位にはならないので合わない。"}, {"text": "魚", "is_correct": false, "explanation": "魚は生き物で、会社を分ける単位にはならないので合わない。"}, {"text": "夜", "is_correct": false, "explanation": "夜は時間で、会社を分ける単位にはならないので合わない。"}], "explanations": {"部門": "正解。「会社を三つの部門に分けた」と自然に続く。", "花": "花は植物で、会社を分ける単位にはならないので合わない。", "魚": "魚は生き物で、会社を分ける単位にはならないので合わない。", "夜": "夜は時間で、会社を分ける単位にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "部門"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜の部門で、ニュースを見ました。", "explanation": "ここは〈番組〉の意味。ニュースを流すのは番組で、組織の区切りである部門ではないので合わない。"}, {"text": "転んで、腕に部門ができました。", "explanation": "ここは〈傷〉の意味。転んでできるのは傷で、部門は組織の区切りなので意味が合わない。"}, {"text": "この表には、名前という部門があります。", "explanation": "ここは〈項目〉の意味。表の中の一つの欄を指すのは項目で、組織の区切りの部門とは合わないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38304, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい部門を食べました。", "corrected_sentence": "新しい部門を立ち上げました。", "error_description": "誤りは「食べる」。部門とは組み合わない。「立ち上げる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38304, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社を二つの部門の分けました。", "corrected_sentence": "会社を二つの部門に分けました。", "error_description": "誤りは「の」。「分ける」は分け先を「に」で示すので、「部門に」が正しい。「の」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38305, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "正解。「診察の部門と検査の部門」と、二つを並べる働きをする。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「ある」の前に目的語を置くと文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、二つの部門を並べる働きはないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、二つの部門を並べる働きはないので合わない。"}], "correct_answer": "と", "explanations": {"と": "正解。「診察の部門と検査の部門」と、二つを並べる働きをする。", "を": "「を」は目的語を示すが、「ある」の前に目的語を置くと文が成り立たない。", "へ": "「へ」は方向を示すが、二つの部門を並べる働きはないので合わない。", "から": "「から」は起点を示すが、二つの部門を並べる働きはないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38305, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「設計部門の仕事」と、部門と仕事の所属関係を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「設計部門が仕事」では名詞どうしの関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や対象を示すが、名詞どうしを結ぶことができないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「設計部門へ仕事が好き」とは成り立たないので合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「設計部門の仕事」と、部門と仕事の所属関係を示す。", "が": "「が」は主語を示すが、「設計部門が仕事」では名詞どうしの関係が成り立たない。", "に": "「に」は場所や対象を示すが、名詞どうしを結ぶことができないので合わない。", "へ": "「へ」は方向を示すが、「設計部門へ仕事が好き」とは成り立たないので合わない。"}, "error_tags": {"が": "主語", "に": "対象", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38305, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "組織や会社・学校の中で、役割や仕事の種類によって分けられた区切りのこと。", "primary_collocate": null, "pronunciation": "ぶもん", "ipa": "bɯmoɴ", "syllable_count": 3, "sentences": [{"text": "会社の人事部門は、新しい社員を探しています。", "target_word": "部門", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の人事[じんじ]部門[ぶもん]は、新[あたら]しい社員[しゃいん]を探[さが]しています。", "sentence_source": "generated"}, {"text": "病院には、診察の部門と検査の部門があります。", "target_word": "部門", "complexity_tier": "T3", "furigana": "病院[びょういん]には、診察[しんさつ]の部門[ぶもん]と検査[けんさ]の部門[ぶもん]があります。", "sentence_source": "generated"}, {"text": "彼女は研究部門のリーダーに選ばれました。", "target_word": "部門", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は研究[けんきゅう]部門[ぶもん]のリーダーに選[えら]ばれました。", "sentence_source": "generated"}, {"text": "部門ごとに会議を開いて、意見をまとめます。", "target_word": "部門", "complexity_tier": "T3", "furigana": "部門[ぶもん]ごとに会議[かいぎ]を開[ひら]いて、意見[いけん]をまとめます。", "sentence_source": "generated"}, {"text": "工場の品質管理部門が、毎日商品を調べています。", "target_word": "部門", "complexity_tier": "T3", "furigana": "工場[こうじょう]の品質[ひんしつ]管理[かんり]部門[ぶもん]が、毎日[まいにち]商品[しょうひん]を調[しら]べています。", "sentence_source": "generated"}, {"text": "売り上げが伸びたので、海外販売の部門を大きくします。", "target_word": "部門", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが伸[の]びたので、海外[かいがい]販売[はんばい]の部門[ぶもん]を大[おお]きくします。", "sentence_source": "generated"}, {"text": "市役所の福祉部門に、相談の電話をかけました。", "target_word": "部門", "complexity_tier": "T3", "furigana": "市役所[しやくしょ]の福祉[ふくし]部門[ぶもん]に、相談[そうだん]の電話[でんわ]をかけました。", "sentence_source": "generated"}, {"text": "彼は設計部門の仕事が好きで、十年も続けています。", "target_word": "部門", "complexity_tier": "T3", "furigana": "彼[かれ]は設計[せっけい]部門[ぶもん]の仕事[しごと]が好[す]きで、十年[じゅうねん]も続[つづ]けています。", "sentence_source": "generated"}, {"text": "役割が重なるので、総務と人事を一つの部門にまとめる予定です。", "target_word": "部門", "complexity_tier": "T3", "furigana": "役割[やくわり]が重[かさ]なるので、総務[そうむ]と人事[じんじ]を一[ひと]つの部門[ぶもん]にまとめる予定[よてい]です。", "sentence_source": "generated"}, {"text": "新しい工場を作るので、製造と検査の部門に人を増やす計画です。", "target_word": "部門", "complexity_tier": "T3", "furigana": "新[あたら]しい工場[こうじょう]を作[つく]るので、製造[せいぞう]と検査[けんさ]の部門[ぶもん]に人[ひと]を増[ふ]やす計画[けいかく]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "部門", "label": "基本形"}, {"form": "部門別", "label": "接尾形"}], "register": "polite", "sense_fingerprint": "組織の中で、役割や仕事の種類ごとに分けた区切り（人事部門・品質管理部門など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd1d8776-9703-44ca-b7cd-08292b44c2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38305, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部門", "is_correct": true, "explanation": "正解。「会社の人事部門」と組織の区切りを表し、自然に続く。"}, {"text": "製品", "is_correct": false, "explanation": "製品は会社が作る物で、「人事製品」とは言えないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の状態で、「人事天気」とは組み合わないので合わない。"}, {"text": "機械", "is_correct": false, "explanation": "機械は道具で、「人事機械」とは組み合わないので合わない。"}], "explanations": {"部門": "正解。「会社の人事部門」と組織の区切りを表し、自然に続く。", "製品": "製品は会社が作る物で、「人事製品」とは言えないので合わない。", "天気": "天気は空の状態で、「人事天気」とは組み合わないので合わない。", "機械": "機械は道具で、「人事機械」とは組み合わないので合わない。"}, "sentence_index": 0, "correct_answer": "部門"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "定規の部門が細かくて、読みにくいです。", "explanation": "ここは〈目盛り〉の意味。定規の細かい線を指すのは目盛りで、部門は組織の区切りなので合わない。"}, {"text": "この本は全部で十部門あります。", "explanation": "ここは〈章〉の意味。本の区切りは章で、部門は本の区切りとしては使わないので合わない。"}, {"text": "部門ごとに天気が違います。", "explanation": "ここは〈地域〉の意味。天気が違うのは場所（地域）で、組織の区切りの部門には天気がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38305, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部門", "is_correct": true, "explanation": "正解。「市役所の福祉部門に電話をかけた」と組織の区切りとして自然に続く。"}, {"text": "花", "is_correct": false, "explanation": "花は植物で、「市役所の福祉花」とは組み合わないので合わない。"}, {"text": "魚", "is_correct": false, "explanation": "魚は生き物で、「市役所の福祉魚」とは組み合わないので合わない。"}, {"text": "夜", "is_correct": false, "explanation": "夜は時間で、「市役所の福祉夜」とは組み合わないので合わない。"}], "explanations": {"部門": "正解。「市役所の福祉部門に電話をかけた」と組織の区切りとして自然に続く。", "花": "花は植物で、「市役所の福祉花」とは組み合わないので合わない。", "魚": "魚は生き物で、「市役所の福祉魚」とは組み合わないので合わない。", "夜": "夜は時間で、「市役所の福祉夜」とは組み合わないので合わない。"}, "sentence_index": 6, "correct_answer": "部門"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "世界の部門ごとに、食べ物の習慣が違います。", "explanation": "ここは〈国〉の意味。食べ物の習慣が違う単位は国で、組織の区切りの部門では表せないので合わない。"}, {"text": "部門の改札で、切符を見せます。", "explanation": "ここは〈駅〉の意味。改札があるのは駅で、組織の区切りの部門にはないので合わない。"}, {"text": "夜空に部門が光っています。", "explanation": "ここは〈星〉の意味。夜空で光るのは星で、部門は光らないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38305, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "売り上げを伸ばすため、海外販売の部門に大きくします。", "corrected_sentence": "売り上げを伸ばすため、海外販売の部門を大きくします。", "error_description": "誤りは「に」。「大きくする」は目的語に「を」を取るので、部門には「を」が正しい。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38305, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不採算の部門を飲むことにしました。", "corrected_sentence": "不採算の部門を閉鎖することにしました。", "error_description": "誤りは「飲む」。「飲む」は液体や食べ物に使う動詞で、部門とは組み合わない。「閉鎖する」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38306, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「民間」と「会社」をつなぎ、会社の性質を表す。「民間の会社」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」。「民間を会社が作りました」では主語と目的語が合わず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "相手や帰着点を示す「に」。「民間に会社が作りました」では、会社が何かを作るという文に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」。「民間から会社が作りました」では、起点としての意味が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「民間」と「会社」をつなぎ、会社の性質を表す。「民間の会社」が正しい。", "を": "目的語を示す「を」。「民間を会社が作りました」では主語と目的語が合わず、文が成り立たない。", "に": "相手や帰着点を示す「に」。「民間に会社が作りました」では、会社が何かを作るという文に合わない。", "から": "起点を示す「から」。「民間から会社が作りました」では、起点としての意味が成り立たない。"}, "error_tags": {"を": "目的語", "に": "帰着点・相手", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "官", "is_correct": true, "explanation": "「官」は国や役所を指し、民間の対義語。文中の「公務員から民間に」とも対応する。"}, {"text": "個人", "is_correct": false, "explanation": "「個人」は一人ひとりを指す語で、国や役所との対義語ではない。"}, {"text": "私立", "is_correct": false, "explanation": "「私立」は設立主体による区別の語で、国や役所との対義語ではない。"}, {"text": "外国", "is_correct": false, "explanation": "「外国」は国の区別を表す語で、国や役所ではない民間の対義語ではない。"}], "correct_answer": "官", "explanations": {"官": "「官」は国や役所を指し、民間の対義語。文中の「公務員から民間に」とも対応する。", "個人": "「個人」は一人ひとりを指す語で、国や役所との対義語ではない。", "私立": "「私立」は設立主体による区別の語で、国や役所との対義語ではない。", "外国": "「外国」は国の区別を表す語で、国や役所ではない民間の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38306, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す「が」。「民間が運営しています」で、運営するのは民間である。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「民間を運営しています」では運営の対象にならない。"}, {"text": "に", "is_correct": false, "explanation": "相手や帰着点を示すが、「民間に運営しています」は主語の位置に合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を示すが、「民間と運営しています」は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す「が」。「民間が運営しています」で、運営するのは民間である。", "を": "目的語を示すが、「民間を運営しています」では運営の対象にならない。", "に": "相手や帰着点を示すが、「民間に運営しています」は主語の位置に合わない。", "と": "並列や共同を示すが、「民間と運営しています」は文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "相手・帰着点", "と": "並列・共同"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "官", "is_correct": true, "explanation": "「官」は国や役所を指し、民間の対義語。市の駐車場（公営）と対比される関係にある。"}, {"text": "企業", "is_correct": false, "explanation": "「企業」は民間の中に含まれる組織を指す語で、対義語ではない。"}, {"text": "家庭", "is_correct": false, "explanation": "「家庭」は家族の生活の場を指す語で、国や役所との対義語ではない。"}, {"text": "団体", "is_correct": false, "explanation": "「団体」は人の集まりを指す語で、国や役所との対義語ではない。"}], "correct_answer": "官", "explanations": {"官": "「官」は国や役所を指し、民間の対義語。市の駐車場（公営）と対比される関係にある。", "企業": "「企業」は民間の中に含まれる組織を指す語で、対義語ではない。", "家庭": "「家庭」は家族の生活の場を指す語で、国や役所との対義語ではない。", "団体": "「団体」は人の集まりを指す語で、国や役所との対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38306, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "会社やお店など、国や市役所ではない人たちのことを言います。", "primary_collocate": null, "pronunciation": "みんかん", "ipa": "miŋkaɴ", "syllable_count": 4, "sentences": [{"text": "兄は役所をやめて、民間の会社に入りました。", "target_word": "民間", "complexity_tier": "T3", "furigana": "兄[あに]は役所[やくしょ]をやめて、民間[みんかん]の会社[かいしゃ]に入[はい]りました。", "sentence_source": "generated"}, {"text": "この道路は、民間の会社が作りました。", "target_word": "民間", "complexity_tier": "T3", "furigana": "この道路[どうろ]は、民間[みんかん]の会社[かいしゃ]が作[つく]りました。", "sentence_source": "generated"}, {"text": "民間の病院は、国の病院より予約が取りやすいです。", "target_word": "民間", "complexity_tier": "T3", "furigana": "民間[みんかん]の病院[びょういん]は、国[くに]の病院[びょういん]より予約[よやく]が取[と]りやすいです。", "sentence_source": "generated"}, {"text": "公務員から民間に移る人が、最近は増えています。", "target_word": "民間", "complexity_tier": "T3", "furigana": "公務員[こうむいん]から民間[みんかん]に移[うつ]る人[ひと]が、最近[さいきん]は増[ふ]えています。", "sentence_source": "generated"}, {"text": "民間の力を借りて、町の古い駅をきれいにしました。", "target_word": "民間", "complexity_tier": "T3", "furigana": "民間[みんかん]の力[ちから]を借[か]りて、町[まち]の古[ふる]い駅[えき]をきれいにしました。", "sentence_source": "generated"}, {"text": "大学を出てから、民間で五年働きました。", "target_word": "民間", "complexity_tier": "T3", "furigana": "大学[だいがく]を出[で]てから、民間[みんかん]で五年[ごねん]働[はたら]きました。", "sentence_source": "generated"}, {"text": "民間の学童保育は、料金が高いところもあります。", "target_word": "民間", "complexity_tier": "T3", "furigana": "民間[みんかん]の学童[がくどう]保育[ほいく]は、料金[りょうきん]が高[たか]いところもあります。", "sentence_source": "generated"}, {"text": "この水族館は、市ではなく民間が運営しています。", "target_word": "民間", "complexity_tier": "T3", "furigana": "この水族館[すいぞくかん]は、市[し]ではなく民間[みんかん]が運営[うんえい]しています。", "sentence_source": "generated"}, {"text": "民間の宇宙旅行会社が、来年の旅行客を募集しています。", "target_word": "民間", "complexity_tier": "T3", "furigana": "民間[みんかん]の宇宙[うちゅう]旅行[りょこう]会社[がいしゃ]が、来年[らいねん]の旅行客[りょこうきゃく]を募集[ぼしゅう]しています。", "sentence_source": "generated"}, {"text": "市の駐車場が満車だったので、民間の駐車場に車を止めました。", "target_word": "民間", "complexity_tier": "T3", "furigana": "市[し]の駐車場[ちゅうしゃじょう]が満車[まんしゃ]だったので、民間[みんかん]の駐車場[ちゅうしゃじょう]に車[くるま]を止[と]めました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "民間", "label": "基本形"}, {"form": "民間の", "label": "連体形"}], "register": "中立", "sense_fingerprint": "国や市役所ではない、会社やお店など一般の人たちの側", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 満車 (Zipf 2.29)']::text[], 'cd1d8776-9703-44ca-b7cd-08292b44c2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38306, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民間", "is_correct": true, "explanation": "「民間の会社」で、国や役所ではない会社を表す。前文の「役所をやめて」と対応する。"}, {"text": "役所", "is_correct": false, "explanation": "「役所の会社」は意味が通らない。役所は会社の種類ではないので、この位置には入らない。"}, {"text": "病院", "is_correct": false, "explanation": "「病院の会社」は成り立たない。病院は会社の種類を表す語ではない。"}, {"text": "学校", "is_correct": false, "explanation": "「学校の会社」は意味が通らない。学校は会社を修飾する種類の語ではない。"}], "explanations": {"民間": "「民間の会社」で、国や役所ではない会社を表す。前文の「役所をやめて」と対応する。", "役所": "「役所の会社」は意味が通らない。役所は会社の種類ではないので、この位置には入らない。", "病院": "「病院の会社」は成り立たない。病院は会社の種類を表す語ではない。", "学校": "「学校の会社」は意味が通らない。学校は会社を修飾する種類の語ではない。"}, "sentence_index": 0, "correct_answer": "民間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町の図書館は、民間の教育委員会が管理しています。", "explanation": "ここは〈公的〉の意味。教育委員会は役所の一部なので、国や役所ではない「民間」とは合わない。"}, {"text": "彼は民間の判断で、会議を欠席しました。", "explanation": "ここは〈個人〉の意味。一人の判断は「個人の判断」と言い、組織や活動を指す「民間」は合わない。"}, {"text": "母は民間の弁当を持たせてくれました。", "explanation": "ここは〈手作り〉の意味。家庭で作った品を指す語で、「民間」は組織や活動に関わる語なので弁当には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38306, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民間", "is_correct": true, "explanation": "「民間の学童保育」で、公営ではない一般の事業者が運営する保育を表す。"}, {"text": "劇場", "is_correct": false, "explanation": "「劇場の学童保育」は意味が通らない。劇場は学童保育を運営する主体ではない。"}, {"text": "美術館", "is_correct": false, "explanation": "「美術館の学童保育」は成り立たない。美術館は学童保育と結びつく施設ではない。"}, {"text": "遊園地", "is_correct": false, "explanation": "「遊園地の学童保育」は意味が通らない。遊園地は学童保育の運営主体を表さない。"}], "explanations": {"民間": "「民間の学童保育」で、公営ではない一般の事業者が運営する保育を表す。", "劇場": "「劇場の学童保育」は意味が通らない。劇場は学童保育を運営する主体ではない。", "美術館": "「美術館の学童保育」は成り立たない。美術館は学童保育と結びつく施設ではない。", "遊園地": "「遊園地の学童保育」は意味が通らない。遊園地は学童保育の運営主体を表さない。"}, "sentence_index": 6, "correct_answer": "民間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "民間の事情で、会議を休みました。", "explanation": "ここは〈私的〉の意味（個人の事情）。個人の事情は「私的」と言い、組織や活動を指す「民間」は使わない。"}, {"text": "姉は民間のパンを焼いています。", "explanation": "ここは〈自家製〉の意味。家庭で作る品を指す語で、「民間」は組織や活動の意味なので食べ物には使わない。"}, {"text": "市の計画は、民間の省庁が決めました。", "explanation": "ここは〈公的〉の意味。省庁は国の機関なので、国や役所ではない「民間」とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38306, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の公園は、民間を寄付で整備されました。", "corrected_sentence": "町の公園は、民間の寄付で整備されました。", "error_description": "「民間」に続く助詞は「の」で、「民間の寄付」と寄付を修飾する。「を」は目的語を示すため、「民間を寄付で」は文として成り立たない。正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38306, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この施設の掃除は、民間で任されています。", "corrected_sentence": "この施設の掃除は、民間に任されています。", "error_description": "「任せる」「任される」の相手は「に」で示す。「民間で」は場所を示すので、「民間に任されています」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
