INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38307, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「民間に任せる」で、任せる相手を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」。「民間を任せる」では、任せる相手を表せない。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を示す「と」。「民間と任せる」では、任せる相手にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」。「民間から任せる」では、任せる相手を表せない。"}], "correct_answer": "に", "explanations": {"に": "「民間に任せる」で、任せる相手を示す「に」。", "を": "目的語を示す「を」。「民間を任せる」では、任せる相手を表せない。", "と": "並列や共同を示す「と」。「民間と任せる」では、任せる相手にならない。", "から": "起点を示す「から」。「民間から任せる」では、任せる相手を表せない。"}, "error_tags": {"を": "目的語", "と": "並列・共同", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "官", "is_correct": true, "explanation": "「官」は国や役所を指し、民間の対義語。新しい薬の開発を行う民間研究所と対比される。"}, {"text": "個人", "is_correct": false, "explanation": "「個人」は一人ひとりを指す語で、国や役所との対義語ではない。"}, {"text": "外国", "is_correct": false, "explanation": "「外国」は国の区別を表す語で、国や役所ではない民間の対義語ではない。"}, {"text": "団体", "is_correct": false, "explanation": "「団体」は人の集まりを指す語で、国や役所との対義語ではない。"}], "correct_answer": "官", "explanations": {"官": "「官」は国や役所を指し、民間の対義語。新しい薬の開発を行う民間研究所と対比される。", "個人": "「個人」は一人ひとりを指す語で、国や役所との対義語ではない。", "外国": "「外国」は国の区別を表す語で、国や役所ではない民間の対義語ではない。", "団体": "「団体」は人の集まりを指す語で、国や役所との対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38307, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国や地方公共団体ではなく、一般の人々や企業が運営する組織や活動に関わること。", "primary_collocate": null, "pronunciation": "みんかん", "ipa": "miŋkaɴ", "syllable_count": 4, "sentences": [{"text": "民間の団体が、地域の清掃を手伝っています。", "target_word": "民間", "complexity_tier": "T3", "furigana": "民間[みんかん]の団体[だんたい]が、地域[ちいき]の清掃[せいそう]を手伝[てつだ]っています。", "sentence_source": "generated"}, {"text": "民間の力で、地域の祭りを続けています。", "target_word": "民間", "complexity_tier": "T3", "furigana": "民間[みんかん]の力[ちから]で、地域[ちいき]の祭[まつ]りを続[つづ]けています。", "sentence_source": "generated"}, {"text": "災害のあとは、民間の支援が大きな助けになります。", "target_word": "民間", "complexity_tier": "T3", "furigana": "災害[さいがい]のあとは、民間[みんかん]の支援[しえん]が大[おお]きな助[たす]けになります。", "sentence_source": "generated"}, {"text": "民間の調査によると、若い人の読書時間は減っています。", "target_word": "民間", "complexity_tier": "T3", "furigana": "民間[みんかん]の調査[ちょうさ]によると、若[わか]い人[ひと]の読書[どくしょ]時間[じかん]は減[へ]っています。", "sentence_source": "generated"}, {"text": "国は民間と協力して、新しい電車を走らせる予定です。", "target_word": "民間", "complexity_tier": "T3", "furigana": "国[くに]は民間[みんかん]と協力[きょうりょく]して、新[あたら]しい電車[でんしゃ]を走[はし]らせる予定[よてい]です。", "sentence_source": "generated"}, {"text": "この番組は、民間のテレビ局が作りました。", "target_word": "民間", "complexity_tier": "T3", "furigana": "この番組[ばんぐみ]は、民間[みんかん]のテレビ局[きょく]が作[つく]りました。", "sentence_source": "generated"}, {"text": "この資格は国の資格ではなく、民間の資格です。", "target_word": "民間", "complexity_tier": "T3", "furigana": "この資格[しかく]は国[くに]の資格[しかく]ではなく、民間[みんかん]の資格[しかく]です。", "sentence_source": "generated"}, {"text": "公共の施設を、民間に任せる町が増えています。", "target_word": "民間", "complexity_tier": "T3", "furigana": "公共[こうきょう]の施設[しせつ]を、民間[みんかん]に任[まか]せる町[まち]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "民間の保険に入っておくと、病気のとき安心です。", "target_word": "民間", "complexity_tier": "T3", "furigana": "民間[みんかん]の保険[ほけん]に入[はい]っておくと、病気[びょうき]のとき安心[あんしん]です。", "sentence_source": "generated"}, {"text": "民間の研究所が、新しい薬の開発に成功しました。", "target_word": "民間", "complexity_tier": "T3", "furigana": "民間[みんかん]の研究所[けんきゅうじょ]が、新[あたら]しい薬[くすり]の開発[かいはつ]に成功[せいこう]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "民間", "label": "基本形"}, {"form": "民間の", "label": "連体形"}], "register": "中立", "sense_fingerprint": "国や自治体ではなく、一般の人々や企業が運営する組織・活動に関わること（民間企業・民間団体など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd1d8776-9703-44ca-b7cd-08292b44c2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38307, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民間", "is_correct": true, "explanation": "「民間の団体」で、国や自治体ではなく一般の人々が運営する団体を表す。"}, {"text": "機械", "is_correct": false, "explanation": "「機械の団体」は意味が通らない。機械は団体を表す語ではない。"}, {"text": "果物", "is_correct": false, "explanation": "「果物の団体」は成り立たない。果物は団体を表す語ではない。"}, {"text": "季節", "is_correct": false, "explanation": "「季節の団体」は意味が通らない。季節は団体を表さない。"}], "explanations": {"民間": "「民間の団体」で、国や自治体ではなく一般の人々が運営する団体を表す。", "機械": "「機械の団体」は意味が通らない。機械は団体を表す語ではない。", "果物": "「果物の団体」は成り立たない。果物は団体を表す語ではない。", "季節": "「季節の団体」は意味が通らない。季節は団体を表さない。"}, "sentence_index": 0, "correct_answer": "民間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は民間の役所に勤めています。", "explanation": "ここは〈公的機関〉の意味。役所は国や地方公共団体なので、国や役所ではない「民間」とは両立しない。"}, {"text": "民間の感情で判断しました。", "explanation": "ここは〈私的〉の意味。個人の感情や事情に使う語で、「民間の感情」と書くと組織や活動の意味になり不自然。"}, {"text": "祖父は民間の梅酒を漬けています。", "explanation": "ここは〈自家製〉の意味。家庭で作る品を指す語で、「民間」は組織や活動に関わる語なので食べ物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38307, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民間", "is_correct": true, "explanation": "「民間の資格」で、国の資格ではない一般の団体が認める資格を表す。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の資格」は意味が通らない。天気は資格の種類を表す語ではない。"}, {"text": "野菜", "is_correct": false, "explanation": "「野菜の資格」は成り立たない。野菜は資格の種類を表さない。"}, {"text": "電車", "is_correct": false, "explanation": "「電車の資格」は意味が通らない。電車は資格の性質を表す語ではない。"}], "explanations": {"民間": "「民間の資格」で、国の資格ではない一般の団体が認める資格を表す。", "天気": "「天気の資格」は意味が通らない。天気は資格の種類を表す語ではない。", "野菜": "「野菜の資格」は成り立たない。野菜は資格の種類を表さない。", "電車": "「電車の資格」は意味が通らない。電車は資格の性質を表す語ではない。"}, "sentence_index": 6, "correct_answer": "民間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国は、民間の省庁を新しく作る予定です。", "explanation": "ここは〈公的〉の意味。省庁は国の機関なので、国や役所ではない「民間」とは両立しない。"}, {"text": "友人は民間の考えで進路を決めました。", "explanation": "ここは〈個人〉の意味。一人の考えは「個人の考え」と言い、組織や活動を指す「民間」は合わない。"}, {"text": "姉は民間の菓子を配ってくれました。", "explanation": "ここは〈手作り〉の意味。家庭で作った菓子を指す語で、「民間」は組織や活動に関わる語なので菓子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38307, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の清掃は、民間に団体が担っています。", "corrected_sentence": "町の清掃は、民間の団体が担っています。", "error_description": "「民間」に続く助詞は「の」で、「民間の団体」と団体を修飾する。「に」は相手を示すため、「民間に団体が」では文が成り立たない。正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38307, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "道路の補修は、民間と委託されています。", "corrected_sentence": "道路の補修は、民間に委託されています。", "error_description": "「委託される」の相手は「に」で示す。「民間と」は並列や共同を表すため、「民間と委託されています」は文が成り立たない。正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c2bc4f7-e32f-4da4-9890-b60cf38652d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38308, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「資本で」は元手を使って始めるという手段の意味で、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「資本が」だと資本が主語になり、会社を始めたのが資本になってしまう。"}, {"text": "を", "is_correct": false, "explanation": "「資本を」だと資本を始めるという意味になり、文が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「資本に」は手段を表せず、「資本に会社を始めた」は不自然。"}], "correct_answer": "で", "explanations": {"で": "「資本で」は元手を使って始めるという手段の意味で、文に合う。", "が": "「資本が」だと資本が主語になり、会社を始めたのが資本になってしまう。", "を": "「資本を」だと資本を始めるという意味になり、文が通らない。", "に": "「資本に」は手段を表せず、「資本に会社を始めた」は不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "場所・対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38308, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「資本が」で資本が入ってくる主語になり、文の流れに合う。"}, {"text": "と", "is_correct": false, "explanation": "「資本と入って」は並べる働きになり、「入って」と合わない。"}, {"text": "より", "is_correct": false, "explanation": "「資本より入って」は比べる意味になり、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「資本の」は連体修飾になり、「入って」の主語にならず文が続かない。"}], "correct_answer": "が", "explanations": {"が": "「資本が」で資本が入ってくる主語になり、文の流れに合う。", "と": "「資本と入って」は並べる働きになり、「入って」と合わない。", "より": "「資本より入って」は比べる意味になり、不自然。", "の": "「資本の」は連体修飾になり、「入って」の主語にならず文が続かない。"}, "error_tags": {"と": "並列", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38308, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お金や物を、仕事や事業のために使うための元手のことです。", "primary_collocate": null, "pronunciation": "しほん", "ipa": "ɕihoɴ", "syllable_count": 3, "sentences": [{"text": "資本が足りなくて、新しい店を開けなかった。", "target_word": "資本", "complexity_tier": "T3", "furigana": "資本[しほん]が足[た]りなくて、新[あたら]しい店[みせ]を開[ひら]けなかった。", "sentence_source": "generated"}, {"text": "彼は少ない資本で小さな会社を始めた。", "target_word": "資本", "complexity_tier": "T3", "furigana": "彼[かれ]は少[すく]ない資本[しほん]で小[ちい]さな会社[かいしゃ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "その会社は外国の資本を受け入れた。", "target_word": "資本", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]は外国[がいこく]の資本[しほん]を受[う]け入[い]れた。", "sentence_source": "generated"}, {"text": "事業を広げるために、資本を集めている。", "target_word": "資本", "complexity_tier": "T3", "furigana": "事業[じぎょう]を広[ひろ]げるために、資本[しほん]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "資本の大きい会社は、工場を何か所も持っている。", "target_word": "資本", "complexity_tier": "T3", "furigana": "資本[しほん]の大[おお]きい会社[かいしゃ]は、工場[こうじょう]を何[なん]か所[しょ]も持[も]っている。", "sentence_source": "generated"}, {"text": "資本がなければ、商売は始められない。", "target_word": "資本", "complexity_tier": "T3", "furigana": "資本[しほん]がなければ、商売[しょうばい]は始[はじ]められない。", "sentence_source": "generated"}, {"text": "友人が資本を出してくれて、パン屋を開いた。", "target_word": "資本", "complexity_tier": "T3", "furigana": "友人が資本[しほん]を出[だ]してくれて、パン屋[や]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "大きな資本が入って、町の店は新しくなった。", "target_word": "資本", "complexity_tier": "T3", "furigana": "大[おお]きな資本[しほん]が入[はい]って、町[まち]の店[みせ]は新[あたら]しくなった。", "sentence_source": "generated"}, {"text": "資本を増やすため、株主から出資を募った。", "target_word": "資本", "complexity_tier": "T3", "furigana": "資本[しほん]を増[ふ]やすため、株主[かぶぬし]から出資[しゅっし]を募[つの]った。", "sentence_source": "generated"}, {"text": "この計画には、三千万円の資本が必要だ。", "target_word": "資本", "complexity_tier": "T3", "furigana": "この計画[けいかく]には、三千万円[さんぜんまんえん]の資本[しほん]が必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "資本", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "事業を始めたり続けたりするための元手となるお金や財産", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8104bb-358f-42db-9a79-a76080280153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38308, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "資本", "is_correct": true, "explanation": "元手となるお金が足りず、店を開けなかったという文脈に合う。"}, {"text": "季節", "is_correct": false, "explanation": "「季節が足りない」は意味をなさず、店を開けなかった理由にもならない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は店を開く元手にならず、「足りない」とも合わない。"}, {"text": "礼儀", "is_correct": false, "explanation": "礼儀が足りないことは店を開けない理由にならず、文が通らない。"}], "explanations": {"資本": "元手となるお金が足りず、店を開けなかったという文脈に合う。", "季節": "「季節が足りない」は意味をなさず、店を開けなかった理由にもならない。", "手紙": "手紙は店を開く元手にならず、「足りない」とも合わない。", "礼儀": "礼儀が足りないことは店を開けない理由にならず、文が通らない。"}, "sentence_index": 0, "correct_answer": "資本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は資本の日に、家族と温泉へ出かけた。", "explanation": "ここは日付の名前としての誤用。資本は事業の元手のことで、催しや記念日の名には使わない。"}, {"text": "この畑は資本が強く、野菜がよく育つ。", "explanation": "ここは〈地力〉の意味。資本は事業の元手で、土地の肥沃さには使わない。"}, {"text": "彼は資本を取って、看護師として働いている。", "explanation": "ここは〈資格〉の意味。資本は事業に使うお金や物で、免許や資格は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38308, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "資本", "is_correct": true, "explanation": "友人が元手のお金を出し、パン屋を開けた、という流れに合う。"}, {"text": "海藻", "is_correct": false, "explanation": "「海藻を出す」とは言わず、パン屋の元手の話にならない。"}, {"text": "機嫌", "is_correct": false, "explanation": "機嫌は出すものではなく、パン屋を開く支援の話に合わない。"}, {"text": "風景", "is_correct": false, "explanation": "「風景を出す」とは言わず、文が通らない。"}], "explanations": {"資本": "友人が元手のお金を出し、パン屋を開けた、という流れに合う。", "海藻": "「海藻を出す」とは言わず、パン屋の元手の話にならない。", "機嫌": "機嫌は出すものではなく、パン屋を開く支援の話に合わない。", "風景": "「風景を出す」とは言わず、文が通らない。"}, "sentence_index": 6, "correct_answer": "資本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は資本が深くて、友人の悩みをよく聞いてくれる。", "explanation": "ここは〈思いやり〉の意味。資本は事業の元手で、人の心の深さには使わない。"}, {"text": "この店は資本が広まり、遠くからも客が来る。", "explanation": "ここは〈評判〉の意味。資本は事業の元手で、評判が広まるという意味では使わない。"}, {"text": "窓を開けると、資本の香りが広がった。", "explanation": "ここは〈におい〉の意味。資本は事業の元手のことで、においを表す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38308, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社を始めるには、まず資本を必要だ。", "corrected_sentence": "会社を始めるには、まず資本が必要だ。", "error_description": "「必要だ」は「〜が必要だ」と主語に「が」を取る。資本の後は「が」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38308, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三千万円の資本を集まるのに、一年かかった。", "corrected_sentence": "三千万円の資本を集めるのに、一年かかった。", "error_description": "「資本を集める」は他動詞「集める」が正しい。自動詞「集まる」は目的語の「を」を取れない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
