INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38310, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38310, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "官民が一緒に仕事をすること。", "primary_collocate": null, "pronunciation": "ぴーぴーぴー", "ipa": "piːpiːpiː", "syllable_count": 6, "sentences": [{"text": "新しい図書館は、PPP の方式で市と会社が共同で運営しています。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "新[あたら]しい図書館[としょかん]は、PPP の方式で市[し]と会社[かいしゃ]が共同[きょうどう]で運営[うんえい]しています。", "sentence_source": "generated"}, {"text": "この町では、PPP で古い駅の前を新しくしました。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "この町[まち]では、PPP で古[ふる]い駅[えき]の前[まえ]を新[あたら]しくしました。", "sentence_source": "generated"}, {"text": "PPP なら、市だけでなく会社の力も使えるので、早く工事が終わります。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "PPP なら、市[し]だけでなく会社[かいしゃ]の力[ちから]も使[つか]えるので、早[はや]く工事[こうじ]が終[お]わります。", "sentence_source": "generated"}, {"text": "市長は、お金が足りないので、PPP で学校を建てたいと話しました。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "市長[しちょう]は、お金[かね]が足[た]りないので、PPP で学校[がっこう]を建[た]てたいと話[はな]しました。", "sentence_source": "generated"}, {"text": "PPP では、市と会社が仕事を分けて、お互いに協力します。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "PPP では、市[し]と会社[かいしゃ]が仕事[しごと]を分[わ]けて、お互[たが]いに協力[きょうりょく]します。", "sentence_source": "generated"}, {"text": "水道の仕事を PPP で行う町が、少しずつ増えています。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "水道[すいどう]の仕事[しごと]を PPP で行[おこな]う町[まち]が、少[すこ]しずつ増[ふ]えています。", "sentence_source": "generated"}, {"text": "PPP がうまくいったのは、市と会社が毎月話し合ったからです。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "PPP がうまくいったのは、市[し]と会社[かいしゃ]が毎月[まいつき]話[はな]し合[あ]ったからです。", "sentence_source": "generated"}, {"text": "彼は大学で PPP について勉強していて、将来は市役所で働きたいそうです。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]で PPP について勉強[べんきょう]していて、将来[しょうらい]は市役所[しやくしょ]で働[はたら]きたいそうです。", "sentence_source": "generated"}, {"text": "公園の管理を PPP にしたら、きれいな花がいつも咲くようになりました。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "公園[こうえん]の管理[かんり]を PPP にしたら、きれいな花[はな]がいつも咲[さ]くようになりました。", "sentence_source": "generated"}, {"text": "PPP は便利ですが、役割をはっきり決めないと、問題が起こります。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "PPP は便利[べんり]ですが、役割[やくわり]をはっきり決[き]めないと、問題[もんだい]が起[お]こります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "PPP", "label": "基本形"}], "register": "やや硬い書き言葉（です・ます体）", "sense_fingerprint": "市や国と会社が一緒に一つの仕事や事業を進めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1c8c83-1c1f-4ce4-8526-69429b5ec9c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38310, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "PPP", "is_correct": true, "explanation": "「PPP の方式」は、官民が共同で運営する仕組みの名前として自然に入る。"}, {"text": "補助金", "is_correct": false, "explanation": "補助金は国や市が出す資金のことで、共同運営の方式を表す語ではないので合わない。"}, {"text": "税金", "is_correct": false, "explanation": "税金は国や市が集めるお金で、事業の運営の仕組みを表さないので合わない。"}, {"text": "予算", "is_correct": false, "explanation": "予算は使う金額の計画で、「予算の方式で共同で運営」とは言えないので合わない。"}], "explanations": {"PPP": "「PPP の方式」は、官民が共同で運営する仕組みの名前として自然に入る。", "補助金": "補助金は国や市が出す資金のことで、共同運営の方式を表す語ではないので合わない。", "税金": "税金は国や市が集めるお金で、事業の運営の仕組みを表さないので合わない。", "予算": "予算は使う金額の計画で、「予算の方式で共同で運営」とは言えないので合わない。"}, "sentence_index": 0, "correct_answer": "PPP"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夫婦がPPPで家事を分担した。", "explanation": "ここは〈協力〉の意味。PPP は公共と民間が組む仕組みを指すので、夫婦の間の分担には使わない。"}, {"text": "二つの店がPPPで祭りを開いた。", "explanation": "ここは〈合同〉の意味。PPP は公共と民間の組み合わせを指すので、民間の店どうしの共同には使わない。"}, {"text": "友人二人がPPPで旅行の計画を立てた。", "explanation": "ここは〈相談〉の意味。PPP は官民の仕組みを指すので、友人どうしの相談には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38310, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "PPP", "is_correct": true, "explanation": "「PPP がうまくいった」の主語として、仕組みの名前が自然に入る。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、「うまくいった」の主語にはならないので合わない。"}, {"text": "住民票", "is_correct": false, "explanation": "住民票は役所が発行する書類で、事業の成否を表す主語にはならない。"}, {"text": "通行料", "is_correct": false, "explanation": "通行料は道や橋を使うときに払うお金で、「うまくいった」の主語としては不自然。"}], "explanations": {"PPP": "「PPP がうまくいった」の主語として、仕組みの名前が自然に入る。", "天気": "天気は空模様のことで、「うまくいった」の主語にはならないので合わない。", "住民票": "住民票は役所が発行する書類で、事業の成否を表す主語にはならない。", "通行料": "通行料は道や橋を使うときに払うお金で、「うまくいった」の主語としては不自然。"}, "sentence_index": 6, "correct_answer": "PPP"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市長は、PPPで市民の意見を集めた。", "explanation": "ここは〈対話〉の意味。PPP は公共と民間が組む仕組みを指すので、市長と市民の意見交換には使わない。"}, {"text": "市は、図書館の建設に PPP を出した。", "explanation": "ここは〈補助金〉の意味。PPP はお金ではなく仕組みなので、「出す」とは言えない。"}, {"text": "市民が PPP を寄付して、図書館が建った。", "explanation": "ここは〈寄付金〉の意味。PPP は仕組みで、お金のように渡せるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38310, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町では、PPP に古い駅前の広場を整えました。", "corrected_sentence": "この町では、PPP で古い駅前の広場を整えました。", "error_description": "方法を表す「で」が正しい。「PPP に」では、仕組みを使って整えたという意味にならず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38310, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は図書館の運営に PPP を導入されました。", "corrected_sentence": "市は図書館の運営に PPP を導入しました。", "error_description": "「導入する」は能動形で使うので「導入しました」が正しい。「PPP を」の目的語をとる文で受け身の「導入されました」にすると、文の形が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
