INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38311, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "Public-Private Partnershipの略で、公共と民間が協力して事業を行う仕組み。", "primary_collocate": null, "pronunciation": "ぴーぴーぴー", "ipa": "piːpiːpiː", "syllable_count": 6, "sentences": [{"text": "PPP は、公共と民間が協力して事業を行う仕組みです。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "PPP は、公共[こうきょう]と民間[みんかん]が協力[きょうりょく]して事業[じぎょう]を行[おこな]う仕組[しく]みです。", "sentence_source": "generated"}, {"text": "政府は、道路の整備に PPP という仕組みを取り入れました。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "政府[せいふ]は、道路[どうろ]の整備[せいび]に PPP という仕組[しく]みを取[と]り入[い]れました。", "sentence_source": "generated"}, {"text": "PPP を使うと、市の負担が減り、会社も利益を得られます。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "PPP を使[つか]うと、市[し]の負担[ふたん]が減[へ]り、会社[かいしゃ]も利益[りえき]を得[え]られます。", "sentence_source": "generated"}, {"text": "この病院は、PPP の仕組みで建てられたため、市の費用が少なくてすみました。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "この病院[びょういん]は、PPP の仕組[しく]みで建[た]てられたため、市[し]の費用[ひよう]が少[すく]なくてすみました。", "sentence_source": "generated"}, {"text": "新しい制度ができて、PPP に参加する会社が増えました。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]ができて、PPP に参加[さんか]する会社[かいしゃ]が増[ふ]えました。", "sentence_source": "generated"}, {"text": "PPP の契約は長く続くので、計画をていねいに作る必要があります。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "PPP の契約[けいやく]は長[なが]く続[つづ]くので、計画[けいかく]をていねいに作[つく]る必要[ひつよう]があります。", "sentence_source": "generated"}, {"text": "海外でも、鉄道を作るときに PPP がよく使われています。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "海外[かいがい]でも、鉄道[てつどう]を作[つく]るときに PPP がよく使[つか]われています。", "sentence_source": "generated"}, {"text": "先生は授業で PPP の例として、空港の運営を紹介しました。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "先生[せんせい]は授業[じゅぎょう]で PPP の例[れい]として、空港[くうこう]の運営[うんえい]を紹介[しょうかい]しました。", "sentence_source": "generated"}, {"text": "予算が少ない町は、PPP の仕組みを使って体育館を直しました。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "予算[よさん]が少[すく]ない町[まち]は、PPP の仕組[しく]みを使[つか]って体育館[たいいくかん]を直[なお]しました。", "sentence_source": "generated"}, {"text": "PPP には利点も多いですが、責任の分け方が難しいという課題もあります。", "target_word": "PPP", "complexity_tier": "T3", "furigana": "PPP には利点[りてん]も多[おお]いですが、責任[せきにん]の分[わ]け方[かた]が難[むずか]しいという課題[かだい]もあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "PPP", "label": "基本形"}], "register": "硬い書き言葉（です・ます体）", "sense_fingerprint": "公共と民間が費用や責任を分けて事業を行う制度・仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1c8c83-1c1f-4ce4-8526-69429b5ec9c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38311, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "PPP", "is_correct": true, "explanation": "PPP は公共と民間が協力する仕組みの名称で、この文の主語に入る。"}, {"text": "寄付", "is_correct": false, "explanation": "寄付は金品を贈る行為で、仕組みを説明する文の主語にはならない。"}, {"text": "税金", "is_correct": false, "explanation": "税金は国や市が集めるお金で、事業の仕組みを表さないので合わない。"}, {"text": "予算", "is_correct": false, "explanation": "予算は使う金額の計画で、「公共と民間が協力して事業を行う仕組み」とは言えない。"}], "explanations": {"PPP": "PPP は公共と民間が協力する仕組みの名称で、この文の主語に入る。", "寄付": "寄付は金品を贈る行為で、仕組みを説明する文の主語にはならない。", "税金": "税金は国や市が集めるお金で、事業の仕組みを表さないので合わない。", "予算": "予算は使う金額の計画で、「公共と民間が協力して事業を行う仕組み」とは言えない。"}, "sentence_index": 0, "correct_answer": "PPP"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの会社がPPPで新商品を作った。", "explanation": "ここは〈業務提携〉の意味。PPP は公共と民間の組み合わせを指すので、会社どうしの提携には使わない。"}, {"text": "市と市民がPPPで予算を決めた。", "explanation": "ここは〈話し合い〉の意味。PPP は公共と民間が事業を組む仕組みを指すので、市と市民の話し合いには使わない。"}, {"text": "市は、図書館の建設に PPP を出した。", "explanation": "ここは〈補助金〉の意味。PPP はお金ではなく仕組みなので、「出す」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38311, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "PPP", "is_correct": true, "explanation": "「鉄道を作るときに PPP がよく使われる」の主語として、仕組みの名称が自然に入る。"}, {"text": "住民票", "is_correct": false, "explanation": "住民票は役所が発行する書類で、「鉄道を作るときによく使われる」とは言えない。"}, {"text": "通行料", "is_correct": false, "explanation": "通行料は道や橋を使うときに払うお金で、鉄道の建設方法の説明には合わない。"}, {"text": "観光", "is_correct": false, "explanation": "観光は旅行や見物のことで、鉄道を作る方法として使われるものではない。"}], "explanations": {"PPP": "「鉄道を作るときに PPP がよく使われる」の主語として、仕組みの名称が自然に入る。", "住民票": "住民票は役所が発行する書類で、「鉄道を作るときによく使われる」とは言えない。", "通行料": "通行料は道や橋を使うときに払うお金で、鉄道の建設方法の説明には合わない。", "観光": "観光は旅行や見物のことで、鉄道を作る方法として使われるものではない。"}, "sentence_index": 6, "correct_answer": "PPP"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人の画家がPPPで絵を描いた。", "explanation": "ここは〈共同制作〉の意味。PPP は公共と民間の仕組みを指すので、画家どうしの制作には使わない。"}, {"text": "町の人たちがPPPで公園をきれいにした。", "explanation": "ここは〈ボランティア〉の意味。PPP は公共と民間の事業の仕組みを指すので、個人の奉仕活動には使わない。"}, {"text": "市民が PPP を寄付して、公園が新しくなった。", "explanation": "ここは〈寄付金〉の意味。PPP は仕組みで、お金のように渡せるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38311, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、この事業に PPP で取り入れることにしました。", "corrected_sentence": "市は、この事業に PPP を取り入れることにしました。", "error_description": "「取り入れる」の目的語は「PPP」なので「を」が正しい。「で」では目的語が欠け、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38311, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は、PPP で使って水道事業を見直しました。", "corrected_sentence": "市は、PPP を使って水道事業を見直しました。", "error_description": "「使う」の目的語は「PPP」なので「を」が必要。「で」にすると目的語がなくなり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
