INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38312, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "国や町の仕事をする人たちと、会社やお店の人たちのこと。", "primary_collocate": null, "pronunciation": "かんみん", "ipa": "kammiɴ", "syllable_count": 4, "sentences": [{"text": "町を元気にするために、官民が協力しています。", "target_word": "官民", "complexity_tier": "T3", "furigana": "町[まち]を元気[げんき]にするために、官民[かんみん]が協力[きょうりょく]しています。", "sentence_source": "generated"}, {"text": "官民の話し合いは、来週の月曜日に市役所で行われます。", "target_word": "官民", "complexity_tier": "T3", "furigana": "官民[かんみん]の話[はな]し合[あ]いは、来週[らいしゅう]の月曜日[げつようび]に市役所[しやくしょ]で行[おこな]われます。", "sentence_source": "generated"}, {"text": "災害のときは、官民が力を合わせて助け合います。", "target_word": "官民", "complexity_tier": "T3", "furigana": "災害[さいがい]のときは、官民[かんみん]が力[ちから]を合[あ]わせて助[たす]け合[あ]います。", "sentence_source": "generated"}, {"text": "官民の意見が合わず、計画はなかなか進みませんでした。", "target_word": "官民", "complexity_tier": "T3", "furigana": "官民[かんみん]の意見[いけん]が合[あ]わず、計画[けいかく]はなかなか進[すす]みませんでした。", "sentence_source": "generated"}, {"text": "この祭りは、官民で準備をするので、毎年とても大きくなります。", "target_word": "官民", "complexity_tier": "T3", "furigana": "この祭[まつ]りは、官民[かんみん]で準備[じゅんび]をするので、毎年[まいとし]とても大[おお]きくなります。", "sentence_source": "generated"}, {"text": "市役所の人と会社の人が集まる官民の会議が、先月から始まりました。", "target_word": "官民", "complexity_tier": "T3", "furigana": "市役所[しやくしょ]の人[ひと]と会社[かいしゃ]の人[ひと]が集[あつ]まる官民[かんみん]の会議[かいぎ]が、先月[せんげつ]から始[はじ]まりました。", "sentence_source": "generated"}, {"text": "官民の両方が責任を持たないと、大きな工事は成功しません。", "target_word": "官民", "complexity_tier": "T3", "furigana": "官民[かんみん]の両方[りょうほう]が責任[せきにん]を持[も]たないと、大[おお]きな工事[こうじ]は成功[せいこう]しません。", "sentence_source": "generated"}, {"text": "官民が情報を分け合えば、問題を早く見つけられます。", "target_word": "官民", "complexity_tier": "T3", "furigana": "官民[かんみん]が情報[じょうほう]を分[わ]け合[あ]えば、問題[もんだい]を早[はや]く見[み]つけられます。", "sentence_source": "generated"}, {"text": "市長は、官民が同じ目標を持つことが大切だと話しました。", "target_word": "官民", "complexity_tier": "T3", "furigana": "市長[しちょう]は、官民[かんみん]が同[おな]じ目標[もくひょう]を持[も]つことが大切[たいせつ]だと話[はな]しました。", "sentence_source": "generated"}, {"text": "昔は官民の間に大きな壁がありましたが、今は話しやすくなりました。", "target_word": "官民", "complexity_tier": "T3", "furigana": "昔[むかし]は官民[かんみん]の間[あいだ]に大[おお]きな壁[かべ]がありましたが、今[いま]は話[はな]しやすくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "官民", "label": "基本形"}], "register": "やや硬い書き言葉（です・ます体）", "sense_fingerprint": "役所で働く人たちと会社・お店の人たち、その両方の立場", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T4: contains vocabulary far above tier T4: 分け合え (Zipf 1.39)']::text[], '5d1c8c83-1c1f-4ce4-8526-69429b5ec9c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38312, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "官民", "is_correct": true, "explanation": "「官民が協力」は、役所と会社・お店の人たちが主語として入る自然な形。"}, {"text": "公園", "is_correct": false, "explanation": "公園は場所を表す語で、人が協力する主語にはならないので合わない。"}, {"text": "税金", "is_correct": false, "explanation": "税金は国や町が集めるお金で、協力する人たちを表さないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、人が協力するという文の主語にはならない。"}], "explanations": {"官民": "「官民が協力」は、役所と会社・お店の人たちが主語として入る自然な形。", "公園": "公園は場所を表す語で、人が協力する主語にはならないので合わない。", "税金": "税金は国や町が集めるお金で、協力する人たちを表さないので合わない。", "天気": "天気は空模様のことで、人が協力するという文の主語にはならない。"}, "sentence_index": 0, "correct_answer": "官民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ある官民は、町の祭りの準備を一人で任された。", "explanation": "官民は集まりを指す語なので、「ある官民は」と一人を指す文には合わない。"}, {"text": "官民が、古い店を一人で新しくした。", "explanation": "官民は集まりや組織を指す語なので、一人で店を直す人には使わない。"}, {"text": "官民は、来年の春に大学を卒業した。", "explanation": "官民は集まりや組織を指す語なので、一人の学生の卒業には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38312, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "官民", "is_correct": true, "explanation": "「官民の両方が責任を持つ」の主語として、役所と会社・お店の人たちを表す語が自然に入る。"}, {"text": "花火", "is_correct": false, "explanation": "花火は夜空に打ち上げるもので、責任を持つ主語にはならない。"}, {"text": "地震", "is_correct": false, "explanation": "地震は自然現象で、責任を持つ主体にはならないので合わない。"}, {"text": "猫", "is_correct": false, "explanation": "猫は動物で、「責任を持つ」という文の主語としては不自然。"}], "explanations": {"官民": "「官民の両方が責任を持つ」の主語として、役所と会社・お店の人たちを表す語が自然に入る。", "花火": "花火は夜空に打ち上げるもので、責任を持つ主語にはならない。", "地震": "地震は自然現象で、責任を持つ主体にはならないので合わない。", "猫": "猫は動物で、「責任を持つ」という文の主語としては不自然。"}, "sentence_index": 6, "correct_answer": "官民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "官民は、町の川にかかる古い橋の名前です。", "explanation": "ここは〈固有名詞〉の意味。官民は人の集まりを指す言葉で、名前には使わない。"}, {"text": "官民が、来年の予算を可決した。", "explanation": "ここは〈議会〉の意味。官民は組織の集まりを指すので、予算を可決する主体にはならない。"}, {"text": "官民は、一人で二つの会社を経営している。", "explanation": "ここは〈社長〉の意味。官民は一人の経営者を指す言葉ではないので、経営の主体にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38312, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の祭りは、官民を一緒に準備しています。", "corrected_sentence": "町の祭りは、官民が一緒に準備しています。", "error_description": "主語を表す「が」が正しい。「を」だと「準備する」の目的語になり、文の意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38312, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "官民を話し合いで、町の計画が決まりました。", "corrected_sentence": "官民の話し合いで、町の計画が決まりました。", "error_description": "「官民の」の「の」が正しい。「を」だと「話し合い」が目的語を取るような形になり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
