INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38313, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "政府や自治体などの公的な組織と、民間の企業や個人のこと。", "primary_collocate": null, "pronunciation": "かんみん", "ipa": "kammiɴ", "syllable_count": 4, "sentences": [{"text": "政府は、官民で協力してデジタル化を進める方針です。", "target_word": "官民", "complexity_tier": "T3", "furigana": "政府[せいふ]は、官民[かんみん]で協力[きょうりょく]してデジタル化[か]を進[すす]める方針[ほうしん]です。", "sentence_source": "generated"}, {"text": "官民の投資が増えたため、地方の経済は少しずつ回復しています。", "target_word": "官民", "complexity_tier": "T3", "furigana": "官民[かんみん]の投資[とうし]が増[ふ]えたため、地方[ちほう]の経済[けいざい]は少[すこ]しずつ回復[かいふく]しています。", "sentence_source": "generated"}, {"text": "官民が連携して、新しい産業を育てる必要があります。", "target_word": "官民", "complexity_tier": "T3", "furigana": "官民[かんみん]が連携[れんけい]して、新[あたら]しい産業[さんぎょう]を育[そだ]てる必要[ひつよう]があります。", "sentence_source": "generated"}, {"text": "官民の役割を整理することが、改革の第一歩になります。", "target_word": "官民", "complexity_tier": "T3", "furigana": "官民[かんみん]の役割[やくわり]を整理[せいり]することが、改革[かいかく]の第一歩[だいいっぽ]になります。", "sentence_source": "generated"}, {"text": "官民の人材の交流が進み、役所で働く専門家が増えました。", "target_word": "官民", "complexity_tier": "T3", "furigana": "官民[かんみん]の人材[じんざい]の交流[こうりゅう]が進[すす]み、役所[やくしょ]で働[はたら]く専門家[せんもんか]が増[ふ]えました。", "sentence_source": "generated"}, {"text": "空港の運営では、官民の責任の分け方が議論になりました。", "target_word": "官民", "complexity_tier": "T3", "furigana": "空港[くうこう]の運営[うんえい]では、官民[かんみん]の責任[せきにん]の分[わ]け方[かた]が議論[ぎろん]になりました。", "sentence_source": "generated"}, {"text": "大地震のあと、官民が一体となって復旧作業を行いました。", "target_word": "官民", "complexity_tier": "T3", "furigana": "大地震[おおじしん]のあと、官民[かんみん]が一体[いったい]となって復旧[ふっきゅう]作業[さぎょう]を行[おこな]いました。", "sentence_source": "generated"}, {"text": "官民の代表が集まり、来年の予算について意見を交わしました。", "target_word": "官民", "complexity_tier": "T3", "furigana": "官民[かんみん]の代表[だいひょう]が集[あつ]まり、来年[らいねん]の予算[よさん]について意見[いけん]を交[か]わしました。", "sentence_source": "generated"}, {"text": "官民を問わず、情報の管理にはきびしい注意が必要です。", "target_word": "官民", "complexity_tier": "T3", "furigana": "官民[かんみん]を問[と]わず、情報[じょうほう]の管理[かんり]にはきびしい注意[ちゅうい]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "官民のあいだで情報を共有する仕組みが、ようやく整いました。", "target_word": "官民", "complexity_tier": "T3", "furigana": "官民[かんみん]のあいだで情報[じょうほう]を共有[きょうゆう]する仕組[しく]みが、ようやく整[ととの]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "官民", "label": "基本形"}], "register": "硬い書き言葉（ニュース・公文書調）", "sense_fingerprint": "政府・自治体などの公的組織と民間の企業・個人、その両方の組織", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1c8c83-1c1f-4ce4-8526-69429b5ec9c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38313, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "官民", "is_correct": true, "explanation": "「官民で協力してデジタル化を進める」の「官民」は、公的組織と民間が協力する主体として自然に入る。"}, {"text": "地図", "is_correct": false, "explanation": "地図は場所を示す資料で、協力してデジタル化を進める主体にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、協力する主体としては合わない。"}, {"text": "寿司", "is_correct": false, "explanation": "寿司は食べ物で、「寿司で協力してデジタル化を進める」とは言えない。"}], "explanations": {"官民": "「官民で協力してデジタル化を進める」の「官民」は、公的組織と民間が協力する主体として自然に入る。", "地図": "地図は場所を示す資料で、協力してデジタル化を進める主体にはならない。", "天気": "天気は空模様のことで、協力する主体としては合わない。", "寿司": "寿司は食べ物で、「寿司で協力してデジタル化を進める」とは言えない。"}, "sentence_index": 0, "correct_answer": "官民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "官民は、市が新しく作った会社の名前です。", "explanation": "ここは〈社名〉の意味。官民は政府と民間をまとめて指す言葉で、社名にはならない。"}, {"text": "官民は、一人で新しい製品を発表した。", "explanation": "官民は組織や仕組みを指す語で、一人の発明者を表すことはない。"}, {"text": "官民の大臣が、一人で来年の予算を決めた。", "explanation": "官民は組織や集まりを指す語で、一人の大臣が一人で決める文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38313, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "官民", "is_correct": true, "explanation": "「官民が一体となって復旧作業を行った」の主語として、組織の集まりを表す語が自然に入る。"}, {"text": "花火", "is_correct": false, "explanation": "花火は夜空に打ち上げるもので、復旧作業を行う主体にはならない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は学ぶための本で、復旧作業を行う主語としては合わない。"}, {"text": "猫", "is_correct": false, "explanation": "猫は動物で、「一体となって復旧作業を行う」の主語としては不自然。"}], "explanations": {"官民": "「官民が一体となって復旧作業を行った」の主語として、組織の集まりを表す語が自然に入る。", "花火": "花火は夜空に打ち上げるもので、復旧作業を行う主体にはならない。", "教科書": "教科書は学ぶための本で、復旧作業を行う主語としては合わない。", "猫": "猫は動物で、「一体となって復旧作業を行う」の主語としては不自然。"}, "sentence_index": 6, "correct_answer": "官民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "官民のお客さまが、店で大きな買い物をした。", "explanation": "官民は組織や仕組みを指す語で、お客さまの集まりには使わない。"}, {"text": "官民は、毎朝一人で会社に出社した。", "explanation": "官民は組織や仕組みを指す語で、一人の社員として会社に通うことは表せない。"}, {"text": "官民は、町内会の長を一人で務めた。", "explanation": "官民は集まりを指す語なので、町内会の長を一人で務める文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38313, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、官民に結ぶ新しい仕組みを作りました。", "corrected_sentence": "市は、官民を結ぶ新しい仕組みを作りました。", "error_description": "「結ぶ」は目的語に「を」をとるので「を」が正しい。「に」では「〜に結ぶ」の形になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38313, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "官民を代表が、会議で新しい方針をまとめました。", "corrected_sentence": "官民の代表が、会議で新しい方針をまとめました。", "error_description": "「官民の代表」の「の」が正しい。「を」にすると「代表」の前に目的語が来る形になり、文の形が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38314, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「短期の旅行」と名詞を修飾する正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「短期を旅行なら」では、短期が旅行の目的語になってしまい、修飾の形として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「短期が旅行なら」は短期を旅行の主語にしてしまい、期間を表す語として意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「短期に旅行なら」は時間・相手を示す「に」が旅行とつながらず、不自然。"}], "correct_answer": "の", "explanations": {"の": "「短期の旅行」と名詞を修飾する正しい助詞。", "を": "「短期を旅行なら」では、短期が旅行の目的語になってしまい、修飾の形として成り立たない。", "が": "「短期が旅行なら」は短期を旅行の主語にしてしまい、期間を表す語として意味が通らない。", "に": "「短期に旅行なら」は時間・相手を示す「に」が旅行とつながらず、不自然。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "時間・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "長期", "is_correct": true, "explanation": "時間の長さで対になる語（対義語）。期間の意味の「短期」の反対。"}, {"text": "機会", "is_correct": false, "explanation": "時間の長さとは関係のない名詞で、「短期」の対義語ではない。"}, {"text": "予算", "is_correct": false, "explanation": "金額の枠を表す名詞で、期間の長さの対義語にはならない。"}, {"text": "気候", "is_correct": false, "explanation": "天候の傾向を表す名詞で、「短期」と対になる関係はない。"}], "correct_answer": "長期", "explanations": {"長期": "時間の長さで対になる語（対義語）。期間の意味の「短期」の反対。", "機会": "時間の長さとは関係のない名詞で、「短期」の対義語ではない。", "予算": "金額の枠を表す名詞で、期間の長さの対義語にはならない。", "気候": "天候の傾向を表す名詞で、「短期」と対になる関係はない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38314, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「短期の滞在」と期間を修飾する正しい助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「短期へ滞在」は方向を示す「へ」が名詞修飾に合わず、意味も通らない。"}, {"text": "と", "is_correct": false, "explanation": "「短期と滞在」は並列の「と」で、短期が滞在を修飾する関係にならない。"}, {"text": "より", "is_correct": false, "explanation": "「短期より滞在」は比較の「より」で、「滞在でも」に続く形として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「短期の滞在」と期間を修飾する正しい助詞。", "へ": "「短期へ滞在」は方向を示す「へ」が名詞修飾に合わず、意味も通らない。", "と": "「短期と滞在」は並列の「と」で、短期が滞在を修飾する関係にならない。", "より": "「短期より滞在」は比較の「より」で、「滞在でも」に続く形として成り立たない。"}, "error_tags": {"へ": "方向", "と": "並列", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "長期", "is_correct": true, "explanation": "時間の長さで対になる語（対義語）。期間の意味の「短期」の反対。"}, {"text": "距離", "is_correct": false, "explanation": "空間の隔たりを表す名詞で、期間の長さの対義語にはならない。"}, {"text": "年齢", "is_correct": false, "explanation": "人の年数を表す名詞で、「短期」と対になる関係はない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す名詞で、期間の対義語にはならない。"}], "correct_answer": "長期", "explanations": {"長期": "時間の長さで対になる語（対義語）。期間の意味の「短期」の反対。", "距離": "空間の隔たりを表す名詞で、期間の長さの対義語にはならない。", "年齢": "人の年数を表す名詞で、「短期」と対になる関係はない。", "体重": "体の重さを表す名詞で、期間の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38314, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みじかい時間のこと。", "primary_collocate": null, "pronunciation": "たんき", "ipa": "taŋki", "syllable_count": 3, "sentences": [{"text": "夏休みに、短期のアルバイトを探しています。", "target_word": "短期", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、短期[たんき]のアルバイトを探[さが]しています。", "sentence_source": "generated"}, {"text": "短期の旅行なら、小さいかばん一つで足ります。", "target_word": "短期", "complexity_tier": "T3", "furigana": "短期[たんき]の旅行[りょこう]なら、小[ちい]さいかばん一[ひと]つで足[た]ります。", "sentence_source": "generated"}, {"text": "この会社は、短期の契約で働く人を募集しています。", "target_word": "短期", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、短期[たんき]の契約[けいやく]で働[はたら]く人[ひと]を募集[ぼしゅう]しています。", "sentence_source": "generated"}, {"text": "長期の計画は立てにくいので、まず短期の目標を決めました。", "target_word": "短期", "complexity_tier": "T3", "furigana": "長期[ちょうき]の計画[けいかく]は立[た]てにくいので、まず短期[たんき]の目標[もくひょう]を決[き]めました。", "sentence_source": "generated"}, {"text": "短期の語学コースに通って、基本の会話を身につけました。", "target_word": "短期", "complexity_tier": "T3", "furigana": "短期[たんき]の語学[ごがく]コースに通[かよ]って、基本[きほん]の会話[かいわ]を身[み]につけました。", "sentence_source": "generated"}, {"text": "短期の出張だったので、荷物は少しだけにしました。", "target_word": "短期", "complexity_tier": "T3", "furigana": "短期[たんき]の出張[しゅっちょう]だったので、荷物[にもつ]は少[すこ]しだけにしました。", "sentence_source": "generated"}, {"text": "短期の留学でも、現地の生活に慣れるには時間がかかります。", "target_word": "短期", "complexity_tier": "T3", "furigana": "短期[たんき]の留学[りゅうがく]でも、現地[げんち]の生活[せいかつ]に慣[な]れるには時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "短期の滞在でも、ビザが必要な国があります。", "target_word": "短期", "complexity_tier": "T3", "furigana": "短期[たんき]の滞在[たいざい]でも、ビザが必要[ひつよう]な国[くに]があります。", "sentence_source": "generated"}, {"text": "彼は、短期の研修で東京に来ています。", "target_word": "短期", "complexity_tier": "T3", "furigana": "彼[かれ]は、短期[たんき]の研修[けんしゅう]で東京[とうきょう]に来[き]ています。", "sentence_source": "generated"}, {"text": "短期の仕事ばかりで、安定した収入がありません。", "target_word": "短期", "complexity_tier": "T3", "furigana": "短期[たんき]の仕事[しごと]ばかりで、安定[あんてい]した収入[しゅうにゅう]がありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "短期", "label": "基本形"}], "register": "中立（です・ます体）", "sense_fingerprint": "期間が短いこと。長期の反対で、アルバイト・留学・契約などの期間を言う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1c8c83-1c1f-4ce4-8526-69429b5ec9c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38314, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短期", "is_correct": true, "explanation": "「夏休みに、___のアルバイト」の空欄に入る名詞で、期間の長さを表す。正解。"}, {"text": "短く", "is_correct": false, "explanation": "副詞なので「の」で名詞を修飾できず、「短くのアルバイト」は成り立たない。"}, {"text": "短い", "is_correct": false, "explanation": "い形容詞は「短いアルバイト」の形で名詞に直接かかるため、「短いのアルバイト」は不自然。"}, {"text": "短かった", "is_correct": false, "explanation": "過去形の活用形で名詞を修飾しない。「短かったのアルバイト」は成り立たない。"}], "explanations": {"短期": "「夏休みに、___のアルバイト」の空欄に入る名詞で、期間の長さを表す。正解。", "短く": "副詞なので「の」で名詞を修飾できず、「短くのアルバイト」は成り立たない。", "短い": "い形容詞は「短いアルバイト」の形で名詞に直接かかるため、「短いのアルバイト」は不自然。", "短かった": "過去形の活用形で名詞を修飾しない。「短かったのアルバイト」は成り立たない。"}, "sentence_index": 0, "correct_answer": "短期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は短期なので、ちょっとしたことですぐに怒ってしまいます。", "explanation": "ここは〈短気〉の意味。短期は期間の長さを表す語で、せっかちな性格には使わないので合わない。"}, {"text": "このラーメンは、短期で茹で上がります。", "explanation": "ここは〈短時間〉の意味。短期は数週間から数か月の期間を指すので、数分で茹で上がる料理には合わない。"}, {"text": "寝不足のせいで、彼は短期の気分に流されてしまいました。", "explanation": "ここは〈一時〉の意味。短期は期間の長さのことで、気分が一時的に変わる様子には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38314, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短期", "is_correct": true, "explanation": "「___の留学でも」の空欄に入る名詞で、期間の長さを表す。正解。"}, {"text": "短縮", "is_correct": false, "explanation": "時間などを縮めることを表す名詞で、「短縮の留学」は成り立たない。"}, {"text": "短さ", "is_correct": false, "explanation": "長さの程度を表す名詞で、「短さの留学」では留学を修飾する意味が通らない。"}, {"text": "短文", "is_correct": false, "explanation": "短い文章を指す名詞で、留学とは結びつかず「短文の留学」は成り立たない。"}], "explanations": {"短期": "「___の留学でも」の空欄に入る名詞で、期間の長さを表す。正解。", "短縮": "時間などを縮めることを表す名詞で、「短縮の留学」は成り立たない。", "短さ": "長さの程度を表す名詞で、「短さの留学」では留学を修飾する意味が通らない。", "短文": "短い文章を指す名詞で、留学とは結びつかず「短文の留学」は成り立たない。"}, "sentence_index": 6, "correct_answer": "短期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "百メートル走は、短期の種目です。", "explanation": "ここは〈短距離〉の意味。短期は期間の長さを表すので、走る距離の短い種目を表す「短距離」の代わりにはならない。"}, {"text": "この歌は短期の調で、どこか悲しい響きがあります。", "explanation": "ここは〈短調〉の意味。短期は期間の長さの語で、曲の調を表す語ではないので合わない。"}, {"text": "この鉛筆は短期で、書きにくいです。", "explanation": "ここは〈短い〉の意味。短期は期間の長さを表す語で、物の長さには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38314, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏は、短期を留学に行きます。", "corrected_sentence": "夏は、短期の留学に行きます。", "error_description": "「短期」は名詞で、後ろの「留学」を修飾するには「の」が必要。「を」は動詞の目的語を示す助詞なので、「短期を」には付けられない。誤りは「を」、正しくは「の」（短期の留学）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38314, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その夏、彼は短期な研修を受けて帰ってきました。", "corrected_sentence": "その夏、彼は短期の研修を受けて帰ってきました。", "error_description": "「短期」は名詞なので、後ろの名詞を修飾するには「の」を使う。「な」は形容動詞の語尾なので、「短期な研修」は誤り。正しくは「短期の研修」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
