INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38315, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "時間の長さが短いこと。長く続かない様子。", "primary_collocate": null, "pronunciation": "たんき", "ipa": "taŋki", "syllable_count": 3, "sentences": [{"text": "人気は短期で終わり、半年後には誰も話さなくなりました。", "target_word": "短期", "complexity_tier": "T3", "furigana": "人気[にんき]は短期[たんき]で終[お]わり、半年後[はんとしご]には誰[だれ]も話[はな]さなくなりました。", "sentence_source": "generated"}, {"text": "短期の流行なので、すぐに飽きられるでしょう。", "target_word": "短期", "complexity_tier": "T3", "furigana": "短期[たんき]の流行[りゅうこう]なので、すぐに飽[あ]きられるでしょう。", "sentence_source": "generated"}, {"text": "このブームは短期に終わると、専門家は見ています。", "target_word": "短期", "complexity_tier": "T3", "furigana": "このブームは短期[たんき]に終[お]わると、専門家[せんもんか]は見[み]ています。", "sentence_source": "generated"}, {"text": "彼のやる気は短期で終わり、宿題はいつも途中です。", "target_word": "短期", "complexity_tier": "T3", "furigana": "彼[かれ]のやる気[き]は短期[たんき]で終[お]わり、宿題[しゅくだい]はいつも途中[とちゅう]です。", "sentence_source": "generated"}, {"text": "短期の好景気に喜んでも、長い目で見ることが大切です。", "target_word": "短期", "complexity_tier": "T3", "furigana": "短期[たんき]の好景気[こうけいき]に喜[よろこ]んでも、長[なが]い目[め]で見[み]ることが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "この電池は短期で切れやすいので、予備を持っていきましょう。", "target_word": "短期", "complexity_tier": "T3", "furigana": "この電池[でんち]は短期[たんき]で切[き]れやすいので、予備[よび]を持[も]っていきましょう。", "sentence_source": "generated"}, {"text": "短期で終わる工事だと思ったのに、半年もかかりました。", "target_word": "短期", "complexity_tier": "T3", "furigana": "短期[たんき]で終[お]わる工事[こうじ]だと思[おも]ったのに、半年[はんとし]もかかりました。", "sentence_source": "generated"}, {"text": "景気の回復が短期で終わり、また不況になりました。", "target_word": "短期", "complexity_tier": "T3", "furigana": "景気[けいき]の回復[かいふく]が短期[たんき]で終[お]わり、また不況[ふきょう]になりました。", "sentence_source": "generated"}, {"text": "株で短期の利益ばかり追うと、大きな失敗をしやすいです。", "target_word": "短期", "complexity_tier": "T3", "furigana": "株[かぶ]で短期[たんき]の利益[りえき]ばかり追[お]うと、大[おお]きな失敗[しっぱい]をしやすいです。", "sentence_source": "generated"}, {"text": "短期で消える話題が多く、ニュースはすぐに変わります。", "target_word": "短期", "complexity_tier": "T3", "furigana": "短期[たんき]で消[き]える話題[わだい]が多[おお]く、ニュースはすぐに変[か]わります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "短期", "label": "基本形"}], "register": "中立（です・ます体）", "sense_fingerprint": "物事が長く続かず、すぐに終わってしまう様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1c8c83-1c1f-4ce4-8526-69429b5ec9c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38315, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短期", "is_correct": true, "explanation": "「人気は___で終わり」の空欄に入り、物事がすぐ終わる様子を表す。正解。"}, {"text": "短い", "is_correct": false, "explanation": "い形容詞は「で終わり」に続く形にならず、「人気は短いで終わり」は不自然。"}, {"text": "短さ", "is_correct": false, "explanation": "「人気は短さで終わり」は、短さが終わりの手段のように読まれ、意味が通らない。"}, {"text": "短縮", "is_correct": false, "explanation": "「人気は短縮で終わり」は、縮めることを表す語として文の意味に合わない。"}], "explanations": {"短期": "「人気は___で終わり」の空欄に入り、物事がすぐ終わる様子を表す。正解。", "短い": "い形容詞は「で終わり」に続く形にならず、「人気は短いで終わり」は不自然。", "短さ": "「人気は短さで終わり」は、短さが終わりの手段のように読まれ、意味が通らない。", "短縮": "「人気は短縮で終わり」は、縮めることを表す語として文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "短期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この服は袖が短期なので、腕が寒いです。", "explanation": "ここは〈短い〉の意味。袖の長さは期間ではないので、「短期」は物の長さには使わないため合わない。"}, {"text": "あの人は短期なので、ちょっとした言葉にもすぐ食ってかかります。", "explanation": "ここは〈短気〉の意味。短期は期間の長さを表すので、気の短い性格には合わない。"}, {"text": "彼女の短期は、約束をすぐ忘れてしまうことです。", "explanation": "ここは〈短所〉の意味。短期は続く時間の長さを表す語で、人の欠点を指すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38315, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短期", "is_correct": true, "explanation": "「___で終わる工事」の空欄に入り、物事がすぐ終わる様子を表す。正解。"}, {"text": "短かった", "is_correct": false, "explanation": "過去形の活用形で、「短かったで終わる工事」は文として成り立たない。"}, {"text": "短距離", "is_correct": false, "explanation": "距離の短さを表す名詞で、「短距離で終わる工事」は意味が通らない。"}, {"text": "短文", "is_correct": false, "explanation": "短い文章を指す名詞で、工事の終わり方を表す語にはならない。"}], "explanations": {"短期": "「___で終わる工事」の空欄に入り、物事がすぐ終わる様子を表す。正解。", "短かった": "過去形の活用形で、「短かったで終わる工事」は文として成り立たない。", "短距離": "距離の短さを表す名詞で、「短距離で終わる工事」は意味が通らない。", "短文": "短い文章を指す名詞で、工事の終わり方を表す語にはならない。"}, "sentence_index": 6, "correct_answer": "短期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "時計の短期が十二を指しています。", "explanation": "ここは〈短針〉の意味。時計の短い針を指す語で、時間の長さを表す「短期」は合わない。"}, {"text": "その選手は短期が得意で、百メートル走では誰にも負けません。", "explanation": "ここは〈短距離〉の意味。走る距離の短さを指す語で、期間の長さを表す「短期」は得意な種目を表さない。"}, {"text": "この曲は短期の調で始まり、どこか悲しい響きがあります。", "explanation": "ここは〈短調〉の意味。短期は期間の長さの語で、曲の調を表す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38315, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この流行は短期が終わって、もう誰も着ません。", "corrected_sentence": "この流行は短期で終わって、もう誰も着ません。", "error_description": "「短期」は「で終わる」の形で、物事がすぐ終わる様子を表す。「が」を付けると主語になり、「短期が終わる」は不自然。誤りは「が」、正しくは「で」（短期で終わって）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38315, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "次々に現れる短期な流行に、店は振り回されています。", "corrected_sentence": "次々に現れる短期の流行に、店は振り回されています。", "error_description": "「短期」は名詞なので、後ろの名詞を修飾するには「の」を使う。「な」は形容動詞の語尾なので、「短期な流行」は誤り。正しくは「短期の流行」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38316, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『利益で』は手段を表し、もうけを使って自転車を買ったという意味になる。"}, {"text": "に", "is_correct": false, "explanation": "時点や結果を表すため、ここでは意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表すため、ここでは文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を表し文法的には成立するが、もうけが自転車を買うことになり意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "『利益で』は手段を表し、もうけを使って自転車を買ったという意味になる。", "に": "時点や結果を表すため、ここでは意味が通らない。", "を": "目的語を表すため、ここでは文が成り立たない。", "が": "主語を表し文法的には成立するが、もうけが自転車を買うことになり意味が通らない。"}, "error_tags": {"に": "時点や結果を表すため、ここでは意味が通らない", "を": "目的語を表すため、ここでは文が成り立たない", "が": "主語になるが、もうけは買い物をしないので意味が通らない"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "損失", "is_correct": true, "explanation": "利益の反対で、商売などで損をしてお金を失うこと。"}, {"text": "利息", "is_correct": false, "explanation": "お金を借りたときに支払う金銭で、利益の反対語ではない。"}, {"text": "給料", "is_correct": false, "explanation": "働いた対価として受け取るお金で、利益の反対語ではない。"}, {"text": "寄付", "is_correct": false, "explanation": "お金や物を無償で提供することで、利益の反対語ではない。"}], "correct_answer": "損失", "explanations": {"損失": "利益の反対で、商売などで損をしてお金を失うこと。", "利息": "お金を借りたときに支払う金銭で、利益の反対語ではない。", "給料": "働いた対価として受け取るお金で、利益の反対語ではない。", "寄付": "お金や物を無償で提供することで、利益の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38316, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『利益が』は主語を表し、『なくなる』の主語として文を成り立たせる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表すが、なくなるは自動詞なので目的語を取れず不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表すため、ここでは意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、ここでは意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "『利益が』は主語を表し、『なくなる』の主語として文を成り立たせる。", "を": "目的語を表すが、なくなるは自動詞なので目的語を取れず不自然。", "と": "並列や相手を表すため、ここでは意味が通らない。", "へ": "方向を表すため、ここでは意味が通らない。"}, "error_tags": {"を": "目的語を表すが、なくなるは自動詞なので目的語を取れず不自然", "と": "並列や相手を表すため、ここでは意味が通らない", "へ": "方向を表すため、ここでは意味が通らない"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "損失", "is_correct": true, "explanation": "利益の反対で、商売などで損をしてお金を失うこと。"}, {"text": "経費", "is_correct": false, "explanation": "事業で使ったお金で、利益の反対語ではない。"}, {"text": "元金", "is_correct": false, "explanation": "預けたりお金を借りたりする元になる金額で、利益の反対語ではない。"}, {"text": "手数料", "is_correct": false, "explanation": "取引や手続きの際に支払う費用で、利益の反対語ではない。"}], "correct_answer": "損失", "explanations": {"損失": "利益の反対で、商売などで損をしてお金を失うこと。", "経費": "事業で使ったお金で、利益の反対語ではない。", "元金": "預けたりお金を借りたりする元になる金額で、利益の反対語ではない。", "手数料": "取引や手続きの際に支払う費用で、利益の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38316, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "もうけ。お金が増えること。", "primary_collocate": null, "pronunciation": "りえき", "ipa": "ɾieki", "syllable_count": 3, "sentences": [{"text": "この店は、安く買った品物を高く売って利益を得ている。", "target_word": "利益", "complexity_tier": "T3", "furigana": "この店(みせ)は、安(やす)く買(か)った品物(しなもの)を高(たか)く売(う)って利益(りえき)を得(え)ている。", "sentence_source": "generated"}, {"text": "野菜を売った利益で、新しい自転車を買った。", "target_word": "利益", "complexity_tier": "T3", "furigana": "野菜(やさい)を売(う)った利益(りえき)で、新(あたら)しい自転車(じてんしゃ)を買(か)った。", "sentence_source": "generated"}, {"text": "一個百円で作って百五十円で売れば、五十円の利益になる。", "target_word": "利益", "complexity_tier": "T3", "furigana": "一個(いっこ)百円(ひゃくえん)で作(つく)って百五十円(ひゃくごじゅうえん)で売(う)れば、五十円(ごじゅうえん)の利益(りえき)になる。", "sentence_source": "generated"}, {"text": "今月は客が少なくて、ほとんど利益が出なかった。", "target_word": "利益", "complexity_tier": "T3", "furigana": "今月(こんげつ)は客(きゃく)が少(すく)なくて、ほとんど利益(りえき)が出(で)なかった。", "sentence_source": "generated"}, {"text": "姉は小さな店を開いて、一年目から利益を出した。", "target_word": "利益", "complexity_tier": "T3", "furigana": "姉(あね)は小(ちい)さな店(みせ)を開(ひら)いて、一年目(いちねんめ)から利益(りえき)を出(だ)した。", "sentence_source": "generated"}, {"text": "利益が増えたので、店員の給料を上げることにした。", "target_word": "利益", "complexity_tier": "T3", "furigana": "利益(りえき)が増(ふ)えたので、店員(てんいん)の給料(きゅうりょう)を上(あ)げることにした。", "sentence_source": "generated"}, {"text": "祖父は米を売った利益を、少しずつ貯金していた。", "target_word": "利益", "complexity_tier": "T3", "furigana": "祖父(そふ)は米(こめ)を売(う)った利益(りえき)を、少(すこ)しずつ貯金(ちょきん)していた。", "sentence_source": "generated"}, {"text": "品物を安く売りすぎて、利益がなくなってしまった。", "target_word": "利益", "complexity_tier": "T3", "furigana": "品物(しなもの)を安(やす)く売(う)りすぎて、利益(りえき)がなくなってしまった。", "sentence_source": "generated"}, {"text": "学園祭のパン屋は、利益を全部寄付することにした。", "target_word": "利益", "complexity_tier": "T3", "furigana": "学園祭(がくえんさい)のパン屋(や)は、利益(りえき)を全部(ぜんぶ)寄付(きふ)することにした。", "sentence_source": "generated"}, {"text": "商売では、売り上げから費用を引いた残りが利益だ。", "target_word": "利益", "complexity_tier": "T3", "furigana": "商売(しょうばい)では、売(う)り上(あ)げから費用(ひよう)を引(ひ)いた残(のこ)りが利益(りえき)だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "利益", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "商売などで売り上げから費用を引いて手元に残るお金のもうけ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866b1129-2e8c-4bbb-8e31-7d683a7aed2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38316, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利益", "is_correct": true, "explanation": "『利益を得る』で、売り買いによってお金がもうかることを表し、文脈に合う。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている時の呼吸の音で、得るという動詞と結べない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さの意味で、得るという動詞と結べない。"}, {"text": "湿気", "is_correct": false, "explanation": "空気中の水分の意味で、得るという動詞と結べない。"}], "explanations": {"利益": "『利益を得る』で、売り買いによってお金がもうかることを表し、文脈に合う。", "寝息": "眠っている時の呼吸の音で、得るという動詞と結べない。", "体重": "体の重さの意味で、得るという動詞と結べない。", "湿気": "空気中の水分の意味で、得るという動詞と結べない。"}, "sentence_index": 0, "correct_answer": "利益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姉は利益を一キロ量って、袋に詰めた。", "explanation": "ここは〈商品〉の意味。利益は事業で得たもうけで、量って袋に詰める物ではないので合わない。"}, {"text": "仕事の利益は、成果に応じて支払われる。", "explanation": "ここは〈報酬〉の意味。働いた対価は報酬と言い、事業のもうけを指す利益は合わない。"}, {"text": "店を開くために、利益を用意した。", "explanation": "ここは〈元手〉の意味。開業の資金は元手で、利益は事業後に得るもうけなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38316, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利益", "is_correct": true, "explanation": "米を売ってもうけたお金という意味で、貯金の対象として合う。"}, {"text": "眠気", "is_correct": false, "explanation": "眠たい感覚の意味。貯金の対象にはならない。"}, {"text": "寝言", "is_correct": false, "explanation": "眠っている間に言う言葉の意味。貯金の対象にはならない。"}, {"text": "足音", "is_correct": false, "explanation": "歩く音の意味。貯金の対象にはならない。"}], "explanations": {"利益": "米を売ってもうけたお金という意味で、貯金の対象として合う。", "眠気": "眠たい感覚の意味。貯金の対象にはならない。", "寝言": "眠っている間に言う言葉の意味。貯金の対象にはならない。", "足音": "歩く音の意味。貯金の対象にはならない。"}, "sentence_index": 6, "correct_answer": "利益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は、客に配る利益の箱で有名だ。", "explanation": "ここは〈景品〉の意味。利益は事業で得たもうけで、客に配って渡せる物ではないので合わない。"}, {"text": "父は家の利益を売って、借金を返した。", "explanation": "ここは〈資産〉の意味。利益は事業で得たもうけで、売り渡せる物ではないので合わない。"}, {"text": "車に利益を入れてから出発した。", "explanation": "ここは〈燃料〉の意味。車に入れるのは燃料で、利益は入れられるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38316, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店の利益を、毎月の売り上げで決まる。", "corrected_sentence": "店の利益は、毎月の売り上げで決まる。", "error_description": "『決まる』は自動詞で、主語の『利益』は『は』で示す。『を』は不自然で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38316, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎月の利益が増やした。", "corrected_sentence": "毎月の利益が増えた。", "error_description": "『増える』は自動詞なので、主語の『利益が』と結ぶ。『増やした』は他動詞で、目的語がないため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38318, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「耐久を重視して」の「を」。「重視する」は目的語を取る動詞なので、正しい。"}, {"text": "が", "is_correct": false, "explanation": "「耐久が重視して」は不自然。「重視する」は主語ではなく目的語を取るので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「耐久に重視して」は文が成り立たない。「に」では重視する対象が示せない。"}, {"text": "と", "is_correct": false, "explanation": "「耐久と重視して」は並列の意味になり、文の構造が合わない。"}], "correct_answer": "を", "explanations": {"を": "「耐久を重視して」の「を」。「重視する」は目的語を取る動詞なので、正しい。", "が": "「耐久が重視して」は不自然。「重視する」は主語ではなく目的語を取るので合わない。", "に": "「耐久に重視して」は文が成り立たない。「に」では重視する対象が示せない。", "と": "「耐久と重視して」は並列の意味になり、文の構造が合わない。"}, "error_tags": {"が": "主格", "に": "相手・方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38318, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「耐久を考えて」の「を」。「考える」は対象を目的語に取るので、正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「耐久へ考えて」は方向の「へ」になり、考える対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「耐久が考えて」は主語が動詞に続かず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「耐久より考えて」は比較の意味になり、考える対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「耐久を考えて」の「を」。「考える」は対象を目的語に取るので、正しい。", "へ": "「耐久へ考えて」は方向の「へ」になり、考える対象を示せない。", "が": "「耐久が考えて」は主語が動詞に続かず、文が成り立たない。", "より": "「耐久より考えて」は比較の意味になり、考える対象を示せない。"}, "error_tags": {"へ": "方向", "が": "主格", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38318, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものや体が、長い間こわれずに使えること。", "primary_collocate": null, "pronunciation": "たいきゅう", "ipa": "taikʲɯː", "syllable_count": 4, "sentences": [{"text": "この靴は、耐久に優れているので、三年はけます。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "この靴[くつ]は、耐久[たいきゅう]に優[すぐ]れているので、三年[さんねん]はけます。", "sentence_source": "generated"}, {"text": "値段より耐久を重視して、鞄を選びました。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "値段[ねだん]より耐久[たいきゅう]を重視[じゅうし]して、鞄[かばん]を選[えら]びました。", "sentence_source": "generated"}, {"text": "このおもちゃは、耐久に不安があるので、すぐ壊れそうです。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "このおもちゃは、耐久[たいきゅう]に不安[ふあん]があるので、すぐ壊[こわ]れそうです。", "sentence_source": "generated"}, {"text": "毎日使う道具なので、耐久の高さが大切です。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "毎日[まいにち]使[つか]う道具[どうぐ]なので、耐久[たいきゅう]の高[たか]さが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "スマートフォンの耐久は、画面の強さで変わります。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "スマートフォンの耐久[たいきゅう]は、画面[がめん]の強[つよ]さで変[か]わります。", "sentence_source": "generated"}, {"text": "マラソン用の靴は、耐久が特に大切です。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "マラソン用[よう]の靴[くつ]は、耐久[たいきゅう]が特[とく]に大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "この傘は軽いですが、耐久の面では弱いです。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "この傘[かさ]は軽[かる]いですが、耐久[たいきゅう]の面[めん]では弱[よわ]いです。", "sentence_source": "generated"}, {"text": "耐久を考えて、机は木ではなく鉄で作りました。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "耐久[たいきゅう]を考[かんが]えて、机[つくえ]は木[き]ではなく鉄[てつ]で作[つく]りました。", "sentence_source": "generated"}, {"text": "古い車でも耐久が高いので、まだ十分走れます。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "古[ふる]い車[くるま]でも耐久[たいきゅう]が高[たか]いので、まだ十分[じゅうぶん]走[はし]れます。", "sentence_source": "generated"}, {"text": "長く使う家具は、デザインより耐久が大切です。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "長[なが]く使[つか]う家具[かぐ]は、デザインより耐久[たいきゅう]が大切[たいせつ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "耐久", "label": "名詞形"}, {"form": "耐久の", "label": "連体（の）"}, {"form": "耐久に", "label": "に格"}, {"form": "耐久が", "label": "が格"}], "register": "中立（丁寧体）", "sense_fingerprint": "ものや体が長い間こわれずに使えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '438a3813-d323-450c-8344-633dda48e388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38318, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐久", "is_correct": true, "explanation": "「耐久に優れている」は、長く壊れずに使える点で優れていることを表し、文脈に合う。"}, {"text": "郵便", "is_correct": false, "explanation": "「郵便に優れている」は意味が通らない。郵便は郵送の仕組みで、優れるという評価の対象にならない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気に優れている」は不自然。天気は空模様で、優劣を言う対象ではない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気に優れている」は合わない。眠気は眠くなる感覚で、優れるという評価の対象にならない。"}], "explanations": {"耐久": "「耐久に優れている」は、長く壊れずに使える点で優れていることを表し、文脈に合う。", "郵便": "「郵便に優れている」は意味が通らない。郵便は郵送の仕組みで、優れるという評価の対象にならない。", "天気": "「天気に優れている」は不自然。天気は空模様で、優劣を言う対象ではない。", "眠気": "「眠気に優れている」は合わない。眠気は眠くなる感覚で、優れるという評価の対象にならない。"}, "sentence_index": 0, "correct_answer": "耐久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この絵は、音の耐久が際立っています。", "explanation": "ここは〈音の響き〉の意味。耐久は長く壊れずに使えることで、音の響きは表さないので合わない。"}, {"text": "この店は、値段の耐久が魅力です。", "explanation": "ここは〈安さ〉の意味。耐久は長持ちすることで、値段が低いことは表さないので合わない。"}, {"text": "このパンは、味の耐久が評判です。", "explanation": "ここは〈味の良さ〉の意味。耐久は壊れずに使えることで、味わいの評価には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38318, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐久", "is_correct": true, "explanation": "「耐久の面では弱い」は、長く使えるかという点で弱いことを表し、文脈に合う。"}, {"text": "歓声", "is_correct": false, "explanation": "歓声は喜びの声で、傘の性能を比べる面を表す語ではないので合わない。"}, {"text": "湿疹", "is_correct": false, "explanation": "皮膚にできる炎症で、傘の性能を比べる面には当てはまらない。"}, {"text": "午後", "is_correct": false, "explanation": "時間帯を表す語で、「午後の面では弱い」は意味が通らない。"}], "explanations": {"耐久": "「耐久の面では弱い」は、長く使えるかという点で弱いことを表し、文脈に合う。", "歓声": "歓声は喜びの声で、傘の性能を比べる面を表す語ではないので合わない。", "湿疹": "皮膚にできる炎症で、傘の性能を比べる面には当てはまらない。", "午後": "時間帯を表す語で、「午後の面では弱い」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "耐久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このお茶は、耐久の良さが特徴です。", "explanation": "ここは〈香り〉の意味。耐久は長く壊れずに使えることで、お茶の香りの良さは表さないので合わない。"}, {"text": "このタオルは、手触りの耐久が人気です。", "explanation": "ここは〈手触り〉の意味。耐久は長く壊れずに使えることで、肌で感じる触り心地は表さないので合わない。"}, {"text": "このイヤホンは、音質の耐久が魅力です。", "explanation": "ここは〈音質〉の意味。耐久は使い続けられる力で、音の澄み具合や良し悪しは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38318, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この棚は、耐久を高さが大切です。", "corrected_sentence": "この棚は、耐久の高さが大切です。", "error_description": "「耐久」と「高さ」をつなぐには「の」が必要。「を」は動詞の目的語に付くので、名詞「耐久」の後では誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38318, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この機械は、耐久が高いくて長く動きます。", "corrected_sentence": "この機械は、耐久が高くて長く動きます。", "error_description": "「耐久が高い」の「高い」を連用形にすると「高くて」になる。「高いくて」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38319, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「寒さへの耐久」の「の」。「へ」と名詞「耐久」をつなぐ連体修飾の「の」で、正しい。"}, {"text": "が", "is_correct": false, "explanation": "「寒さへが耐久」は文が成り立たない。「が」は主語を示すので、ここでは合わない。"}, {"text": "を", "is_correct": false, "explanation": "「寒さへを耐久」は、目的語の「を」が名詞の結びつきとして合わない。"}, {"text": "で", "is_correct": false, "explanation": "「寒さへで耐久」は手段の「で」になり、名詞どうしの結びつきとして成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「寒さへの耐久」の「の」。「へ」と名詞「耐久」をつなぐ連体修飾の「の」で、正しい。", "が": "「寒さへが耐久」は文が成り立たない。「が」は主語を示すので、ここでは合わない。", "を": "「寒さへを耐久」は、目的語の「を」が名詞の結びつきとして合わない。", "で": "「寒さへで耐久」は手段の「で」になり、名詞どうしの結びつきとして成り立たない。"}, "error_tags": {"が": "主格", "を": "目的語", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38319, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「耐久を保てる」の「を」。「保つ」は対象を目的語に取るので、正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「耐久へ保てる」は方向の「へ」になり、保つ対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「耐久から保てる」は起点の意味になり、保つ対象として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「耐久より保てる」は比較の意味になり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「耐久を保てる」の「を」。「保つ」は対象を目的語に取るので、正しい。", "へ": "「耐久へ保てる」は方向の「へ」になり、保つ対象を示せない。", "から": "「耐久から保てる」は起点の意味になり、保つ対象として成り立たない。", "より": "「耐久より保てる」は比較の意味になり、文が成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38319, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事や物体が、長期間の使用や、厳しい条件に耐えられる能力。", "primary_collocate": null, "pronunciation": "たいきゅう", "ipa": "taikʲɯː", "syllable_count": 4, "sentences": [{"text": "この時計は、水や寒さに対する耐久が高いです。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "この時計[とけい]は、水[みず]や寒[さむ]さに対[たい]する耐久[たいきゅう]が高[たか]いです。", "sentence_source": "generated"}, {"text": "宇宙で使う部品は、強い寒さへの耐久が求められます。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]で使[つか]う部品[ぶひん]は、強[つよ]い寒[さむ]さへの耐久[たいきゅう]が求[もと]められます。", "sentence_source": "generated"}, {"text": "工場では、機械の耐久を調べるために何日も動かします。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、機械[きかい]の耐久[たいきゅう]を調[しら]べるために何日[なんにち]も動[うご]かします。", "sentence_source": "generated"}, {"text": "この橋は、風や雨に対する耐久を考えて作られました。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "この橋[はし]は、風[かぜ]や雨[あめ]に対[たい]する耐久[たいきゅう]を考[かんが]えて作[つく]られました。", "sentence_source": "generated"}, {"text": "電池の耐久が高ければ、旅行でも安心です。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "電池[でんち]の耐久[たいきゅう]が高[たか]ければ、旅行[りょこう]でも安心[あんしん]です。", "sentence_source": "generated"}, {"text": "耐久に問題があるので、この部品は売れません。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "耐久[たいきゅう]に問題[もんだい]があるので、この部品[ぶひん]は売[う]れません。", "sentence_source": "generated"}, {"text": "新しい素材は、熱への耐久が古い素材の二倍です。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "新[あたら]しい素材[そざい]は、熱[ねつ]への耐久[たいきゅう]が古[ふる]い素材[そざい]の二倍[にばい]です。", "sentence_source": "generated"}, {"text": "毎日の厳しい使い方でも、耐久を保てる製品を作っています。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "毎日[まいにち]の厳[きび]しい使[つか]い方[かた]でも、耐久[たいきゅう]を保[たも]てる製品[せいひん]を作[つく]っています。", "sentence_source": "generated"}, {"text": "雪の多い地域の家は、重さへの耐久が必要です。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "雪[ゆき]の多[おお]い地域[ちいき]の家[いえ]は、重[おも]さへの耐久[たいきゅう]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "この塗料は、雨に対する耐久が高いと評判です。", "target_word": "耐久", "complexity_tier": "T3", "furigana": "この塗料[とりょう]は、雨[あめ]に対[たい]する耐久[たいきゅう]が高[たか]いと評判[ひょうばん]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "耐久", "label": "名詞形"}, {"form": "耐久の", "label": "連体（の）"}, {"form": "耐久に", "label": "に格"}, {"form": "耐久が", "label": "が格"}], "register": "中立（丁寧体）", "sense_fingerprint": "長期間の使用や厳しい条件に耐える能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '438a3813-d323-450c-8344-633dda48e388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38319, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐久", "is_correct": true, "explanation": "「水や寒さに対する耐久が高い」は、水や寒さに耐えられる力の高さを表し、文脈に合う。"}, {"text": "郵便", "is_correct": false, "explanation": "「水や寒さに対する郵便が高い」は意味が通らない。郵便は郵送の仕組みで、高さを比べる対象ではない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は感覚を表す語で、「眠気が高い」は性能の高さを表す文に合わない。"}, {"text": "湿疹", "is_correct": false, "explanation": "皮膚の病気を表す語で、時計の性能の高さとは結びつかない。"}], "explanations": {"耐久": "「水や寒さに対する耐久が高い」は、水や寒さに耐えられる力の高さを表し、文脈に合う。", "郵便": "「水や寒さに対する郵便が高い」は意味が通らない。郵便は郵送の仕組みで、高さを比べる対象ではない。", "眠気": "眠気は感覚を表す語で、「眠気が高い」は性能の高さを表す文に合わない。", "湿疹": "皮膚の病気を表す語で、時計の性能の高さとは結びつかない。"}, "sentence_index": 0, "correct_answer": "耐久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は、人気の耐久が魅力です。", "explanation": "ここは〈人気〉の意味。耐久は厳しい条件に耐えて使い続けられる力で、評判の高さは表さないので合わない。"}, {"text": "このバッグは、値段の耐久が魅力です。", "explanation": "ここは〈値段〉の意味。耐久は長く使えることで、代金の額は表さないので合わない。"}, {"text": "この地方は、天気の耐久が魅力です。", "explanation": "ここは〈天気〉の意味。耐久は厳しい条件に耐える力で、空模様は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38319, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐久", "is_correct": true, "explanation": "「熱への耐久が古い素材の二倍」は、熱に耐えられる力が比べられることを表し、文脈に合う。"}, {"text": "外出", "is_correct": false, "explanation": "「熱への外出が古い素材の二倍」は意味が通らない。外出は家を出る行為で、比べる対象にならない。"}, {"text": "出発", "is_correct": false, "explanation": "「熱への出発」は不自然。出発は出かけることで、素材の性能の比較には使わない。"}, {"text": "順番", "is_correct": false, "explanation": "「熱への順番」は意味が通らない。順番は並ぶ順序で、素材の性能を表さない。"}], "explanations": {"耐久": "「熱への耐久が古い素材の二倍」は、熱に耐えられる力が比べられることを表し、文脈に合う。", "外出": "「熱への外出が古い素材の二倍」は意味が通らない。外出は家を出る行為で、比べる対象にならない。", "出発": "「熱への出発」は不自然。出発は出かけることで、素材の性能の比較には使わない。", "順番": "「熱への順番」は意味が通らない。順番は並ぶ順序で、素材の性能を表さない。"}, "sentence_index": 6, "correct_answer": "耐久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このお菓子は、甘さの耐久が評判です。", "explanation": "ここは〈甘さ〉の意味。耐久は長く壊れずに使えることで、味の甘さは表さないので合わない。"}, {"text": "このイヤホンは、静けさの耐久が評判です。", "explanation": "ここは〈静けさ〉の意味。耐久は使い続けられる力で、音のない状態は表さないので合わない。"}, {"text": "このかばんは、速さの耐久が評判です。", "explanation": "ここは〈速さ〉の意味。耐久は厳しい条件に耐える力で、動く速度は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38319, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この鍋は、熱への耐久を高いです。", "corrected_sentence": "この鍋は、熱への耐久が高いです。", "error_description": "「耐久が高い」の主語は「が」で示す。「を」は他動詞の目的語に付くので、形容詞「高い」の前では誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38319, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この壁は、火への耐久な強さが魅力です。", "corrected_sentence": "この壁は、火への耐久の強さが魅力です。", "error_description": "名詞「耐久」と「強さ」をつなぐ連体修飾は「の」を使う。「な」は形容動詞などに付くので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38320, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「雇用が安定していれば」と、安定する主体の「雇用」を示す主語の「が」。自然な文。"}, {"text": "を", "is_correct": false, "explanation": "「雇用を安定していれば」では雇用が目的語になるが、「安定する」は目的語を取らないので文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「雇用に安定していれば」では相手や対象を示す「に」になり、安定の主語として働かない。"}, {"text": "へ", "is_correct": false, "explanation": "「雇用へ安定していれば」では方向を示す「へ」になり、「安定する」の主語にならず不自然。"}], "correct_answer": "が", "explanations": {"が": "「雇用が安定していれば」と、安定する主体の「雇用」を示す主語の「が」。自然な文。", "を": "「雇用を安定していれば」では雇用が目的語になるが、「安定する」は目的語を取らないので文が成り立たない。", "に": "「雇用に安定していれば」では相手や対象を示す「に」になり、安定の主語として働かない。", "へ": "「雇用へ安定していれば」では方向を示す「へ」になり、「安定する」の主語にならず不自然。"}, "error_tags": {"を": "対象", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出勤", "is_correct": false, "explanation": "「出勤」は職場へ行く動作で、「雇用」の対義語ではない。"}, {"text": "解雇", "is_correct": true, "explanation": "「解雇」は雇用を打ち切ることで、この文の「雇用を失う」と対になる。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩」は雇用とは関係のない語で、対義語にはならない。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題」は課された勉強や作業で、雇用の対義語ではない。"}], "correct_answer": "解雇", "explanations": {"出勤": "「出勤」は職場へ行く動作で、「雇用」の対義語ではない。", "解雇": "「解雇」は雇用を打ち切ることで、この文の「雇用を失う」と対になる。", "散歩": "「散歩」は雇用とは関係のない語で、対義語にはならない。", "宿題": "「宿題」は課された勉強や作業で、雇用の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38320, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「雇用が不安定な」と、不安定である主体の「雇用」を示す主語の「が」。自然な文。"}, {"text": "で", "is_correct": false, "explanation": "「雇用で不安定な時代」では手段や場所の「で」になり、不安定である主語として続かない。"}, {"text": "と", "is_correct": false, "explanation": "「雇用と不安定な時代」では並列の「と」になるが、後ろの「不安定な時代」と並ぶ形になり、主語として続かない。"}, {"text": "から", "is_correct": false, "explanation": "「雇用から不安定な時代」では起点の「から」になり、「不安定」の主語にならず文の意味が変わる。"}], "correct_answer": "が", "explanations": {"が": "「雇用が不安定な」と、不安定である主体の「雇用」を示す主語の「が」。自然な文。", "で": "「雇用で不安定な時代」では手段や場所の「で」になり、不安定である主語として続かない。", "と": "「雇用と不安定な時代」では並列の「と」になるが、後ろの「不安定な時代」と並ぶ形になり、主語として続かない。", "から": "「雇用から不安定な時代」では起点の「から」になり、「不安定」の主語にならず文の意味が変わる。"}, "error_tags": {"で": "手段・場所", "と": "並列", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旅行", "is_correct": false, "explanation": "「旅行」は出かけて過ごすことで、雇用の対義語ではない。"}, {"text": "解雇", "is_correct": true, "explanation": "「解雇」は雇用を打ち切ることで、「雇用されて働く」と対になる。"}, {"text": "掃除", "is_correct": false, "explanation": "「掃除」は汚れを取ることで、雇用とは対になる関係にない。"}, {"text": "採掘", "is_correct": false, "explanation": "「採掘」は地下の資源を掘り出すことで、雇用の対義語ではない。"}], "correct_answer": "解雇", "explanations": {"旅行": "「旅行」は出かけて過ごすことで、雇用の対義語ではない。", "解雇": "「解雇」は雇用を打ち切ることで、「雇用されて働く」と対になる。", "掃除": "「掃除」は汚れを取ることで、雇用とは対になる関係にない。", "採掘": "「採掘」は地下の資源を掘り出すことで、雇用の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38320, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "お金をもらって働くことです。", "primary_collocate": null, "pronunciation": "こよう", "ipa": "kojoː", "syllable_count": 3, "sentences": [{"text": "彼は三月から、小さな会社に雇用されて働いている。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "彼[かれ]は三月[さんがつ]から、小[ちい]さな会社[かいしゃ]に雇用[こよう]されて働[はたら]いている。", "sentence_source": "generated"}, {"text": "雇用が安定していれば、毎月の給料の心配が少ない。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "雇用[こよう]が安定[あんてい]していれば、毎月[まいつき]の給料[きゅうりょう]の心配[しんぱい]が少[すく]ない。", "sentence_source": "generated"}, {"text": "留学生は、決められた時間内であれば、アルバイトとして雇用される。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "留学生[りゅうがくせい]は、決[き]められた時間内[じかんない]であれば、アルバイトとして雇用[こよう]される。", "sentence_source": "generated"}, {"text": "突然会社が倒産して、彼は雇用を失ってしまった。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "突然[とつぜん]会社[かいしゃ]が倒産[とうさん]して、彼[かれ]は雇用[こよう]を失[うしな]ってしまった。", "sentence_source": "generated"}, {"text": "彼女は正社員ではなく、一年ごとの更新で雇用されている。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は正社員[せいしゃいん]ではなく、一年[いちねん]ごとの更新[こうしん]で雇用[こよう]されている。", "sentence_source": "generated"}, {"text": "父は定年後も、同じ会社に雇用されて週三日働いている。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "父[ちち]は定年後[ていねんご]も、同[おな]じ会社[かいしゃ]に雇用[こよう]されて週[しゅう]三日[みっか]働[はたら]いている。", "sentence_source": "generated"}, {"text": "大学を出たばかりの兄は、やっと銀行に雇用された。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "大学[だいがく]を出[で]たばかりの兄[あに]は、やっと銀行[ぎんこう]に雇用[こよう]された。", "sentence_source": "generated"}, {"text": "雇用が不安定な時代なので、若者は資格を取りたがる。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "雇用[こよう]が不安定[ふあんてい]な時代[じだい]なので、若者[わかもの]は資格[しかく]を取[と]りたがる。", "sentence_source": "generated"}, {"text": "彼は病院に雇用され、事務の仕事を任された。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "彼[かれ]は病院[びょういん]に雇用[こよう]され、事務[じむ]の仕事[しごと]を任[まか]された。", "sentence_source": "generated"}, {"text": "雇用されて働くより、自分で店を持ちたいと彼は考えている。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "雇用[こよう]されて働[はたら]くより、自分[じぶん]で店[みせ]を持[も]ちたいと彼[かれ]は考[かんが]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雇用する", "label": "辞書形"}, {"form": "雇用した", "label": "過去形"}, {"form": "雇用される", "label": "受身形"}, {"form": "雇用されない", "label": "受身否定形"}], "register": "neutral", "sense_fingerprint": "雇用:雇われて給料をもらいながら働くこと(働く側の視点が中心)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a842f311-b815-4a39-bf38-8799be70a7cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38320, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出勤", "is_correct": false, "explanation": "「出勤」は自分から職場へ行く動作で、「会社に出勤されて働いている」とは言わないので合わない。"}, {"text": "寝坊", "is_correct": false, "explanation": "「寝坊」は寝過ごすことで、「会社に寝坊されて」は文として成り立たない。"}, {"text": "雇用", "is_correct": true, "explanation": "「会社に雇用されて働いている」の形で、雇われて働く状態を表すので合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩」は歩くことで、「会社に散歩されて」は意味をなさない。"}], "explanations": {"出勤": "「出勤」は自分から職場へ行く動作で、「会社に出勤されて働いている」とは言わないので合わない。", "寝坊": "「寝坊」は寝過ごすことで、「会社に寝坊されて」は文として成り立たない。", "雇用": "「会社に雇用されて働いている」の形で、雇われて働く状態を表すので合う。", "散歩": "「散歩」は歩くことで、「会社に散歩されて」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "雇用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会社は新しい方針を雇用することにした。", "explanation": "ここは〈採用〉（方針や方法を取り入れる）の意味。雇用は人を雇うことなので、方針を対象にはできない。"}, {"text": "彼は毎月の雇用で家計をやりくりしている。", "explanation": "ここは〈給料〉（もらうお金）の意味。雇用は働く仕組みのことで、受け取る金額を指さないので合わない。"}, {"text": "彼女は去年、大きな会社を雇用した。", "explanation": "ここは〈就職〉（自分が職に就く）の意味。雇用は雇う側が人を雇う行為で、会社を対象にはしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38320, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寝坊", "is_correct": false, "explanation": "「寝坊」は寝過ごすことで、「銀行に寝坊された」とは言わない。"}, {"text": "遠慮", "is_correct": false, "explanation": "「遠慮」は控えることで、「銀行に遠慮された」は文として成り立たない。"}, {"text": "雇用", "is_correct": true, "explanation": "「銀行に雇用された」の形で、やっと銀行で働けるようになった意味に合う。"}, {"text": "立候補", "is_correct": false, "explanation": "「立候補」は自分から名乗り出ることで、「銀行に立候補された」とは言わない。"}], "explanations": {"寝坊": "「寝坊」は寝過ごすことで、「銀行に寝坊された」とは言わない。", "遠慮": "「遠慮」は控えることで、「銀行に遠慮された」は文として成り立たない。", "雇用": "「銀行に雇用された」の形で、やっと銀行で働けるようになった意味に合う。", "立候補": "「立候補」は自分から名乗り出ることで、「銀行に立候補された」とは言わない。"}, "sentence_index": 6, "correct_answer": "雇用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は雇用として、社員の給料を毎月上げている。", "explanation": "ここは〈雇用主〉（雇う側の人）の意味。雇用は人を指さないので、主語には立てられない。"}, {"text": "彼は三月から、小さな会社を雇用して働いている。", "explanation": "ここは〈就業〉（働く側が仕事に就く）の意味。雇用は雇う側の行為で、働く本人が会社を雇用するとは言わないので合わない。"}, {"text": "彼は雇用して、新しい会社に入った。", "explanation": "ここは〈転職〉（勤め先を変える）の意味。雇用は雇う側の行為で、働く本人が勤め先を変える意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38320, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は去年、その会社に雇用されない。", "corrected_sentence": "彼は去年、その会社に雇用された。", "error_description": "「去年」は過去を示すので、現在形の否定「雇用されない」は誤り。過去形「雇用された」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38320, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は来月から、その会社を雇用されるつもりだ。", "corrected_sentence": "兄は来月から、その会社に雇用されるつもりだ。", "error_description": "「雇用される」は雇う側を「に」で示す。「を」は誤りで、「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
