INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38321, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "仕事をすること。または、仕事をしてもらうこと。", "primary_collocate": null, "pronunciation": "こよう", "ipa": "kojoː", "syllable_count": 3, "sentences": [{"text": "現在、オフィスでの定型業務の自動化が進み、AIがホワイトカラーの雇用を代替する時代となっている。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "現在[げんざい]、オフィスでの定型[ていけい]業務[ぎょうむ]の自動化[じどうか]が進[すす]み、AIがホワイトカラーの雇用[こよう]を代替[だいたい]する時代[じだい]となっている。", "sentence_source": "mined"}, {"text": "会社は来年、新しい店のために十人を雇用する予定だ。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は来年[らいねん]、新[あたら]しい店[みせ]のために十人[じゅうにん]を雇用[こよう]する予定[よてい]だ。", "sentence_source": "generated"}, {"text": "市は地元の若者の雇用を増やすため、工場の誘致を進めている。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "市[し]は地元[じもと]の若者[わかもの]の雇用[こよう]を増[ふ]やすため、工場[こうじょう]の誘致[ゆうち]を進[すす]めている。", "sentence_source": "generated"}, {"text": "人手不足の農家が、外国人を雇用して収穫を乗り切った。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "人手不足[ひとでぶそく]の農家[のうか]が、外国人[がいこくじん]を雇用[こよう]して収穫[しゅうかく]を乗[の]り切[き]った。", "sentence_source": "generated"}, {"text": "景気が悪くなると、企業は新しい雇用を控える傾向がある。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]くなると、企業[きぎょう]は新[あたら]しい雇用[こよう]を控[ひか]える傾向[けいこう]がある。", "sentence_source": "generated"}, {"text": "障害のある人を雇用する会社には、国から補助金が出る。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "障害[しょうがい]のある人[ひと]を雇用[こよう]する会社[かいしゃ]には、国[くに]から補助金[ほじょきん]が出[で]る。", "sentence_source": "generated"}, {"text": "この店は、経験のない人でも雇用してくれる。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "この店[みせ]は、経験[けいけん]のない人[ひと]でも雇用[こよう]してくれる。", "sentence_source": "generated"}, {"text": "社長は「長く働いてもらえる人を雇用したい」と話した。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は「長[なが]く働[はたら]いてもらえる人[ひと]を雇用[こよう]したい」と話[はな]した。", "sentence_source": "generated"}, {"text": "工場が閉鎖されて、町の雇用が大きく減った。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "工場[こうじょう]が閉鎖[へいさ]されて、町[まち]の雇用[こよう]が大[おお]きく減[へ]った。", "sentence_source": "generated"}, {"text": "彼女は自分の事務所を開き、初めて二人を雇用した。", "target_word": "雇用", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]の事務所[じむしょ]を開[ひら]き、初[はじ]めて二人[ふたり]を雇用[こよう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雇用する", "label": "辞書形"}, {"form": "雇用した", "label": "過去形"}, {"form": "雇用される", "label": "受身形"}, {"form": "雇用しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "雇用:人を雇って仕事をしてもらうこと、また雇われて働くこと(雇う側の視点が中心)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a842f311-b815-4a39-bf38-8799be70a7cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38321, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雇用", "is_correct": true, "explanation": "Fits: AIがホワイトカラーの雇用を代替する means AI replacing white-collar jobs."}, {"text": "人口", "is_correct": false, "explanation": "Means population. 人口を代替する does not make sense as AI replacing something."}, {"text": "国籍", "is_correct": false, "explanation": "Means nationality. It cannot be the object of 代替する here."}, {"text": "税率", "is_correct": false, "explanation": "Means tax rate. Replacing a tax rate with AI does not fit the sentence."}], "explanations": {"雇用": "Fits: AIがホワイトカラーの雇用を代替する means AI replacing white-collar jobs.", "人口": "Means population. 人口を代替する does not make sense as AI replacing something.", "国籍": "Means nationality. It cannot be the object of 代替する here.", "税率": "Means tax rate. Replacing a tax rate with AI does not fit the sentence."}, "sentence_index": 0, "correct_answer": "雇用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "農家は、トラクターを雇用して畑を耕した。", "explanation": "Here 〈利用〉 (use) is meant. 雇用 applies to hiring people, not machines; machines are 利用."}, {"text": "不景気で、会社は社員を雇用して人数を減らした。", "explanation": "Here 〈解雇〉 (dismissal) is meant. 雇用 means hiring, so it cannot express cutting staff."}, {"text": "会社は隣の空き部屋を一年間雇用した。", "explanation": "Here 〈賃借〉 (renting) is meant. Renting a room is 賃借; 雇用 is for employing people, not renting property."}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38321, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雇用", "is_correct": true, "explanation": "Fits: この店は…人でも雇用してくれる means the store employs people even without experience."}, {"text": "解散", "is_correct": false, "explanation": "Means dissolving a group. A store cannot 解散してくれる people in this sense."}, {"text": "結婚", "is_correct": false, "explanation": "Means marriage. It does not describe a store''s action toward job seekers."}, {"text": "脱線", "is_correct": false, "explanation": "Means derailing or going off topic. It cannot be the store''s action here."}], "explanations": {"雇用": "Fits: この店は…人でも雇用してくれる means the store employs people even without experience.", "解散": "Means dissolving a group. A store cannot 解散してくれる people in this sense.", "結婚": "Means marriage. It does not describe a store''s action toward job seekers.", "脱線": "Means derailing or going off topic. It cannot be the store''s action here."}, "sentence_index": 6, "correct_answer": "雇用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は初めて、二人の意見を雇用した。", "explanation": "Here 〈採用〉 (adopting an idea) is meant. Taking up an opinion is 採用, not 雇用."}, {"text": "彼女は初めて、二人を養子に雇用した。", "explanation": "Here 〈養子〉 (adopting as a child) is meant. Taking someone into a family is 養子, not hiring."}, {"text": "彼女は初めて、大会に二人を雇用した。", "explanation": "Here 〈参加〉 (taking part) is meant. Sending people to an event is 参加; 雇用 refers to employment."}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38321, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "AIが人の雇用が奪う時代となっている。", "corrected_sentence": "AIが人の雇用を奪う時代となっている。", "error_description": "Wrong particle on 雇用. が is used, but 雇用 is the object of 奪う and needs を. Right form: 雇用を奪う.", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38321, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店は来月から五人を雇用した予定だ。", "corrected_sentence": "店は来月から五人を雇用する予定だ。", "error_description": "Wrong tense on 雇用. 予定 (plan) with a past form is unnatural. Right form: 雇用する予定だ.", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38322, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「犯罪をした人」で、する行為の目的語を「を」で示す。"}, {"text": "で", "is_correct": false, "explanation": "「犯罪でした人」は行為の目的語を示せず、「した」の形として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「犯罪へした人」はする行為の対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、「犯罪よりした人」は行為の目的語として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「犯罪をした人」で、する行為の目的語を「を」で示す。", "で": "「犯罪でした人」は行為の目的語を示せず、「した」の形として成り立たない。", "へ": "「へ」は方向を表すので、「犯罪へした人」はする行為の対象を示せない。", "より": "「より」は比較を表すため、「犯罪よりした人」は行為の目的語として成り立たない。"}, "error_tags": {"で": "手段の誤り", "へ": "方向の誤り", "より": "比較の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38322, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「犯罪のない暮らし」で、「犯罪の」が「ない」を修飾する正しい形。"}, {"text": "を", "is_correct": false, "explanation": "「犯罪をない暮らし」は「ない」に続かず、目的語の形として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「犯罪にない暮らし」は位置や対象の関係が成り立たず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「犯罪とない暮らし」は並列の意味にならず、「ない」を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "正解。「犯罪のない暮らし」で、「犯罪の」が「ない」を修飾する正しい形。", "を": "「犯罪をない暮らし」は「ない」に続かず、目的語の形として成り立たない。", "に": "「犯罪にない暮らし」は位置や対象の関係が成り立たず、不自然。", "と": "「犯罪とない暮らし」は並列の意味にならず、「ない」を修飾できない。"}, "error_tags": {"を": "格の誤り", "に": "位置の誤り", "と": "並列の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38322, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "法律で罰せられるような、悪い行いをすること。", "primary_collocate": null, "pronunciation": "はんざい", "ipa": "handzai", "syllable_count": 4, "sentences": [{"text": "人のものを盗むのは犯罪です。", "target_word": "犯罪", "complexity_tier": "T2", "furigana": "人[ひと]のものを盗[ぬす]むのは犯罪[はんざい]です。", "sentence_source": "generated"}, {"text": "犯罪をした人は、法律によって裁かれる。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "犯罪[はんざい]をした人[ひと]は、法律[ほうりつ]によって裁[さば]かれる。", "sentence_source": "generated"}, {"text": "町で犯罪が起きたと聞いて、母は心配した。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "町[まち]で犯罪[はんざい]が起[お]きたと聞[き]いて、母[はは]は心配[しんぱい]した。", "sentence_source": "generated"}, {"text": "犯罪のニュースを見るたびに、悲しい気持ちになる。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "犯罪[はんざい]のニュースを見[み]るたびに、悲[かな]しい気持[きも]ちになる。", "sentence_source": "generated"}, {"text": "子どもを犯罪から守るため、学校の周りに見守り隊がいる。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "子[こ]どもを犯罪[はんざい]から守[まも]るため、学校[がっこう]の周[まわ]りに見守[みまも]り隊[たい]がいる。", "sentence_source": "generated"}, {"text": "小さな犯罪でも、見逃してはいけない。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "小[ちい]さな犯罪[はんざい]でも、見逃[みのが]してはいけない。", "sentence_source": "generated"}, {"text": "犯罪が減って、夜でも安心して歩ける町になった。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "犯罪[はんざい]が減[へ]って、夜[よる]でも安心[あんしん]して歩[ある]ける町[まち]になった。", "sentence_source": "generated"}, {"text": "犯罪のない暮らしを、みんなが望んでいる。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "犯罪[はんざい]のない暮[く]らしを、みんなが望[のぞ]んでいる。", "sentence_source": "generated"}, {"text": "犯罪に巻き込まれないよう、知らない人についていってはいけません。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "犯罪[はんざい]に巻[ま]き込[こ]まれないよう、知[し]らない人[ひと]についていってはいけません。", "sentence_source": "generated"}, {"text": "彼は昔、犯罪をしたが、今は真面目に働いている。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "彼[かれ]は昔[むかし]、犯罪[はんざい]をしたが、今[いま]は真面目[まじめ]に働[はたら]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯罪", "label": "base noun"}, {"form": "犯罪者", "label": "derived noun (person)"}, {"form": "犯罪的", "label": "derived na-adjective"}], "register": "neutral", "sense_fingerprint": "盗みなど、してはいけない悪いことをする行い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bf4c2f4-d106-46cc-9bb1-e6df9b77d143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38322, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "犯罪", "is_correct": true, "explanation": "正解。「人のものを盗むのは犯罪です」で、盗みという行為を指す。"}, {"text": "音楽", "is_correct": false, "explanation": "「人のものを盗むのは音楽です」は意味が成り立たず、文の内容に合わない。"}, {"text": "星座", "is_correct": false, "explanation": "「人のものを盗むのは星座です」は意味が通らず、盗みの説明にならない。"}, {"text": "帽子", "is_correct": false, "explanation": "「人のものを盗むのは帽子です」は文として成り立たず、盗みを指さない。"}], "explanations": {"犯罪": "正解。「人のものを盗むのは犯罪です」で、盗みという行為を指す。", "音楽": "「人のものを盗むのは音楽です」は意味が成り立たず、文の内容に合わない。", "星座": "「人のものを盗むのは星座です」は意味が通らず、盗みの説明にならない。", "帽子": "「人のものを盗むのは帽子です」は文として成り立たず、盗みを指さない。"}, "sentence_index": 0, "correct_answer": "犯罪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は去年から重い犯罪を患っている。", "explanation": "ここは〈病気〉の意味。患うは病気にかかっている状態を表すので、犯罪は体の不調には使わない。"}, {"text": "友達に犯罪をして笑われた。", "explanation": "ここは〈悪ふざけ〉の意味。悪ふざけは場を盛り上げる軽いいたずらで、犯罪とは言わない。"}, {"text": "犯罪が遅れて、会議に間に合わなかった。", "explanation": "ここは〈遅延〉の意味。犯罪は人の行為なので、電車の遅れのような出来事の主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38322, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "犯罪", "is_correct": true, "explanation": "正解。「犯罪が減って、夜でも安心して歩ける町になった」で、治安の改善を表す。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気が減って、夜でも安心して歩ける町になった」は文の意味がつながらない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「洗濯が減って」は意味が通らず、治安の話と結びつかない。"}, {"text": "食器", "is_correct": false, "explanation": "「食器が減って」は不自然で、夜道の安心という文脈に合わない。"}], "explanations": {"犯罪": "正解。「犯罪が減って、夜でも安心して歩ける町になった」で、治安の改善を表す。", "眠気": "「眠気が減って、夜でも安心して歩ける町になった」は文の意味がつながらない。", "洗濯": "「洗濯が減って」は意味が通らず、治安の話と結びつかない。", "食器": "「食器が減って」は不自然で、夜道の安心という文脈に合わない。"}, "sentence_index": 6, "correct_answer": "犯罪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "休日は家族と犯罪に行って過ごした。", "explanation": "ここは〈ピクニック〉の意味。犯罪は法や社会のきまりに反する行為で、家族で出かけて楽しむ行事には使わない。"}, {"text": "彼は毎朝、犯罪を分別している。", "explanation": "ここは〈ごみ〉の意味。犯罪は法や社会のきまりに反する行為で、分別する対象にはならない。"}, {"text": "彼女は毎朝、犯罪を練習している。", "explanation": "ここは〈練習〉の意味。犯罪は法や社会のきまりに反する行為で、技能を身につける反復練習には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38322, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その男は犯罪と認められ、刑務所に入った。", "corrected_sentence": "その男は犯罪者と認められ、刑務所に入った。", "error_description": "人を指す場合は「犯罪者」を使う。「犯罪」は行為を指すので、人には使えない。正しくは「犯罪者」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
