INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38323, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "法律や社会のきまりに反する行為。特に、他人に害を与える行為。", "primary_collocate": null, "pronunciation": "はんざい", "ipa": "handzai", "syllable_count": 4, "sentences": [{"text": "犯罪の現場という苛烈な情報の奔流の中から、科学捜査の担い手は微細な痕跡を拾い上げる。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "犯罪[はんざい]の現場[げんば]という苛烈[かれつ]な情報[じょうほう]の奔流[ほんりゅう]の中[なか]から、科学[かがく]捜査[そうさ]の担[にな]い手[て]は微細[びさい]な痕跡[こんせき]を拾[ひろ]い上[あ]げる。", "sentence_source": "generated"}, {"text": "警察は、犯罪を防ぐために夜の見回りを強化した。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "警察[けいさつ]は、犯罪[はんざい]を防[ふせ]ぐために夜[よる]の見回[みまわ]りを強化[きょうか]した。", "sentence_source": "generated"}, {"text": "犯罪の多い地域では、防犯カメラの設置が進んでいる。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "犯罪[はんざい]の多[おお]い地域[ちいき]では、防犯[ぼうはん]カメラの設置[せっち]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "彼は犯罪に手を染めたことを深く後悔している。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "彼[かれ]は犯罪[はんざい]に手[て]を染[そ]めたことを深[ふか]く後悔[こうかい]している。", "sentence_source": "generated"}, {"text": "少年による犯罪が増えていると報じられた。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "少年[しょうねん]による犯罪[はんざい]が増[ふ]えていると報[ほう]じられた。", "sentence_source": "generated"}, {"text": "法律は、犯罪から市民を守るために存在する。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "法律[ほうりつ]は、犯罪[はんざい]から市民[しみん]を守[まも]るために存在[そんざい]する。", "sentence_source": "generated"}, {"text": "インターネット上の犯罪は、手口が年々巧妙になっている。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "インターネット上[じょう]の犯罪[はんざい]は、手口[てぐち]が年々[ねんねん]巧妙[こうみょう]になっている。", "sentence_source": "generated"}, {"text": "犯罪を見かけたら、すぐに警察に通報してください。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "犯罪[はんざい]を見[み]かけたら、すぐに警察[けいさつ]に通報[つうほう]してください。", "sentence_source": "generated"}, {"text": "生活が苦しいことは、犯罪を正当化する理由にはならない。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "生活[せいかつ]が苦[くる]しいことは、犯罪[はんざい]を正当化[せいとうか]する理由[りゆう]にはならない。", "sentence_source": "generated"}, {"text": "この映画は、実際に起きた犯罪をもとに作られた。", "target_word": "犯罪", "complexity_tier": "T3", "furigana": "この映画[えいが]は、実際[じっさい]に起[お]きた犯罪[はんざい]をもとに作[つく]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯罪", "label": "base noun"}, {"form": "犯罪者", "label": "derived noun (person)"}, {"form": "犯罪的", "label": "derived na-adjective"}], "register": "neutral", "sense_fingerprint": "法律や社会の決まりに背き、他人に害を与える行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 奔流 (Zipf 2.32), 拾い上げる (Zipf 2.14)']::text[], '0bf4c2f4-d106-46cc-9bb1-e6df9b77d143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38323, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "犯罪", "is_correct": true, "explanation": "正解。「犯罪の現場」の犯罪。捜査の文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の現場」は成り立たず、捜査の現場という文脈に合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気の現場」は意味が通らず、科学捜査の文脈に合わない。"}, {"text": "朝食", "is_correct": false, "explanation": "「朝食の現場」は不自然で、痕跡を拾う捜査の場面と結びつかない。"}], "explanations": {"犯罪": "正解。「犯罪の現場」の犯罪。捜査の文脈に合う。", "天気": "「天気の現場」は成り立たず、捜査の現場という文脈に合わない。", "眠気": "「眠気の現場」は意味が通らず、科学捜査の文脈に合わない。", "朝食": "「朝食の現場」は不自然で、痕跡を拾う捜査の場面と結びつかない。"}, "sentence_index": 0, "correct_answer": "犯罪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は朝、隣の人に笑顔で犯罪をした。", "explanation": "ここは〈挨拶〉の意味。犯罪は法や社会のきまりに反する行為で、人にあいさつする行動には使わない。"}, {"text": "うっかり犯罪で書類をなくしてしまった。", "explanation": "ここは〈過失〉の意味。犯罪は故意に法を破る行為で、うっかりした不注意には使わない。"}, {"text": "試合で犯罪を取られ、退場になった。", "explanation": "ここは〈反則〉の意味。スポーツの決まりに違反した場合は反則と言い、犯罪とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38323, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "犯罪", "is_correct": true, "explanation": "正解。「手口が年々巧妙になっている」という内容に合う。"}, {"text": "星座", "is_correct": false, "explanation": "「星座の手口」は意味が成り立たず、文の前提に合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "「帽子の手口」は意味が通らず、文の内容と結びつかない。"}, {"text": "野菜", "is_correct": false, "explanation": "「野菜の手口」は不自然で、巧妙になるという文脈に合わない。"}], "explanations": {"犯罪": "正解。「手口が年々巧妙になっている」という内容に合う。", "星座": "「星座の手口」は意味が成り立たず、文の前提に合わない。", "帽子": "「帽子の手口」は意味が通らず、文の内容と結びつかない。", "野菜": "「野菜の手口」は不自然で、巧妙になるという文脈に合わない。"}, "sentence_index": 6, "correct_answer": "犯罪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台風で大きな犯罪が起きた。", "explanation": "ここは〈災害〉の意味。犯罪は人が法律に反して害を与える行為で、台風による被害には使わない。"}, {"text": "新しい店は、客が来ずに犯罪した。", "explanation": "ここは〈閉店〉の意味。犯罪は法や社会のきまりに反する行為で、店をたたむことには使わない。"}, {"text": "彼は母の誕生日に、犯罪を贈った。", "explanation": "ここは〈贈り物〉の意味。犯罪は法や社会のきまりに反する行為で、人に渡すものとしては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38323, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町は、犯罪を増えている。", "corrected_sentence": "この町は、犯罪が増えている。", "error_description": "「増える」は自動詞なので、主語には「が」を使う。「を」は誤りで、正しくは「犯罪が増えている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38323, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その女性は、大きな犯罪を作ったが、すぐに捕まった。", "corrected_sentence": "その女性は、大きな犯罪を犯したが、すぐに捕まった。", "error_description": "「犯罪」と組み合わせる動詞は「犯す」。「作る」は物や作品を生み出す動詞で、法に反する行為とは合わない。正しくは「犯罪を犯した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38324, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「サービスがある」で、「ある」の主語を示す「が」。サービスに付く助詞として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「サービスをある」は「ある」が他動詞ではないため成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「サービスへある」は文として不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「サービスからある」は意味をなさない。"}], "correct_answer": "が", "explanations": {"が": "「サービスがある」で、「ある」の主語を示す「が」。サービスに付く助詞として正しい。", "を": "「サービスをある」は「ある」が他動詞ではないため成り立たない。", "へ": "「へ」は方向を示すが、「サービスへある」は文として不自然。", "から": "「から」は起点を示すが、「サービスからある」は意味をなさない。"}, "error_tags": {"を": "目的語・対象", "へ": "方向", "から": "起点・理由"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38324, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38324, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "サービスは、人のために何かをすることです。", "primary_collocate": null, "pronunciation": "さーびす", "ipa": "saːbisɯ", "syllable_count": 4, "sentences": [{"text": "店員さんが、重い荷物を運ぶサービスをしてくれた。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "店員[てんいん]さんが、重[おも]い荷物[にもつ]を運[はこ]ぶサービスをしてくれた。", "sentence_source": "generated"}, {"text": "お客さんのために、無料でお茶を出すサービスがある。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "お客[きゃく]さんのために、無料[むりょう]でお茶[ちゃ]を出[だ]すサービスがある。", "sentence_source": "generated"}, {"text": "このホテルはサービスがよくて、気持ちよく過ごせた。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "このホテルはサービスがよくて、気持[きも]ちよく過[す]ごせた。", "sentence_source": "generated"}, {"text": "親切なサービスを受けて、うれしくなった。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "親切[しんせつ]なサービスを受[う]けて、うれしくなった。", "sentence_source": "generated"}, {"text": "休みの日は、家族へのサービスとして父が料理をする。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、家族[かぞく]へのサービスとして父[ちち]が料理[りょうり]をする。", "sentence_source": "generated"}, {"text": "駅員のサービスのおかげで、迷わず乗り場に着けた。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "駅員[えきいん]のサービスのおかげで、迷[まよ]わず乗[の]り場[ば]に着[つ]けた。", "sentence_source": "generated"}, {"text": "店は、客を待たせないようにサービスを工夫している。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "店[みせ]は、客[きゃく]を待[ま]たせないようにサービスを工夫[くふう]している。", "sentence_source": "generated"}, {"text": "親切にするのがサービスの基本だと、先生は教えてくれた。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "親切[しんせつ]にするのがサービスの基本[きほん]だと、先生[せんせい]は教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "あのレストランは、サービスが早くて助かる。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "あのレストランは、サービスが早[はや]くて助[たす]かる。", "sentence_source": "generated"}, {"text": "犬の散歩を手伝うサービスを、近所の人が始めた。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "犬[いぬ]の散歩[さんぽ]を手伝[てつだ]うサービスを、近所[きんじょ]の人[ひと]が始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サービス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人のために何かをしてあげること、接客や手助けの行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 駅員 (Zipf 3.47), 迷わ (Zipf 3.68), 乗り場 (Zipf 3.25)']::text[], 'fb3fb64f-2b7d-47f2-a572-4d369e136007') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38324, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サービス", "is_correct": true, "explanation": "「運ぶサービス」は、人のために荷物を運ぶ行為を指し、「サービスをしてくれた」と自然に続く。"}, {"text": "ノート", "is_correct": false, "explanation": "「重い荷物を運ぶノート」は意味をなさず、文が成り立たない。"}, {"text": "リボン", "is_correct": false, "explanation": "「荷物を運ぶリボン」は意味が通らず、「リボンをしてくれた」も重い荷物を運ぶ文脈に合わない。"}, {"text": "ゲーム", "is_correct": false, "explanation": "「荷物を運ぶゲーム」の形で文が成り立たず、「運ぶ」の目的語として不自然。"}], "explanations": {"サービス": "「運ぶサービス」は、人のために荷物を運ぶ行為を指し、「サービスをしてくれた」と自然に続く。", "ノート": "「重い荷物を運ぶノート」は意味をなさず、文が成り立たない。", "リボン": "「荷物を運ぶリボン」は意味が通らず、「リボンをしてくれた」も重い荷物を運ぶ文脈に合わない。", "ゲーム": "「荷物を運ぶゲーム」の形で文が成り立たず、「運ぶ」の目的語として不自然。"}, "sentence_index": 0, "correct_answer": "サービス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テニスの試合で、彼は速いサービスを打った。", "explanation": "ここは〈サーブ〉の意味。球を打つ動作を指す語で、人のために何かをする行為の意味では使わないので合わない。"}, {"text": "お世話になった先生に、サービスの手紙を書いた。", "explanation": "ここは〈お礼〉の意味。サービスは人のために行うことや提供される便益を指し、感謝を伝える手紙の意味では使わないので合わない。"}, {"text": "いたずらをした弟は、サービスを受けて反省した。", "explanation": "ここは〈罰〉の意味。サービスは親切な行為や提供される便益で、いたずらへの罰の意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38324, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サービス", "is_correct": true, "explanation": "「客を待たせないようにサービスを工夫している」で、客への配慮の工夫の対象として自然。"}, {"text": "天気", "is_correct": false, "explanation": "「天気を工夫している」は工夫の対象として不自然で、客を待たせない文脈に合わない。"}, {"text": "ゴミ", "is_correct": false, "explanation": "「ゴミを工夫している」は客を待たせない工夫とは結びつかず、文の流れに合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気を工夫している」は意味をなさず、店の工夫の対象にならない。"}], "explanations": {"サービス": "「客を待たせないようにサービスを工夫している」で、客への配慮の工夫の対象として自然。", "天気": "「天気を工夫している」は工夫の対象として不自然で、客を待たせない文脈に合わない。", "ゴミ": "「ゴミを工夫している」は客を待たせない工夫とは結びつかず、文の流れに合わない。", "眠気": "「眠気を工夫している」は意味をなさず、店の工夫の対象にならない。"}, "sentence_index": 6, "correct_answer": "サービス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "貧しい人々に、サービスを施した。", "explanation": "ここは〈施し〉（金品や恵みを与えること）の意味。サービスは人のために行う行為や提供される便益を指し、物や恵みを与える施しの意味では使わないので合わない。"}, {"text": "誕生日に、母にサービスを渡した。", "explanation": "ここは〈贈り物〉の意味。サービスは形のない行為や便益で、手渡すものではないので合わない。"}, {"text": "先生に、サービスを提出した。", "explanation": "ここは〈宿題〉の意味。サービスは提出するものではなく、「提出」と結びつかないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38324, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅員さんが、迷っている客を出口まで案内するサービスを食べてくれた。", "corrected_sentence": "駅員さんが、迷っている客を出口まで案内するサービスをしてくれた。", "error_description": "誤りは「食べてくれた」。サービスは食べられないので、「する」を使って「サービスをしてくれた」とするのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38324, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店員さんは、雨の日にお客さんへ傘を貸すサービスを食べている。", "corrected_sentence": "店員さんは、雨の日にお客さんへ傘を貸すサービスをしている。", "error_description": "誤りは「食べている」。サービスは食べられないので、「する」を使って「サービスをしている」とするのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38325, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「サービスの料金」で、「サービス」と「料金」をつなぐ「の」。"}, {"text": "を", "is_correct": false, "explanation": "「サービスを料金」は目的語の「を」を置いても名詞同士が結びつかず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「サービスに料金」は位置や相手を示す「に」を置いても、料金の関係を表せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「サービスへ料金」は方向の「へ」を置いても意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「サービスの料金」で、「サービス」と「料金」をつなぐ「の」。", "を": "「サービスを料金」は目的語の「を」を置いても名詞同士が結びつかず、文が成り立たない。", "に": "「サービスに料金」は位置や相手を示す「に」を置いても、料金の関係を表せず不自然。", "へ": "「サービスへ料金」は方向の「へ」を置いても意味が通らない。"}, "error_tags": {"を": "目的語・対象", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38325, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「地域のサービスが充実している」で、「充実している」の主語を示す「が」。"}, {"text": "と", "is_correct": false, "explanation": "「地域のサービスと充実している」は並列の「と」になり、充実している主体が文中に立たないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「充実している」は目的語を取らないため、「サービスを」では文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「地域のサービスから充実している」は起点の意味になり、充実している主語を示す形としては合わない。"}], "correct_answer": "が", "explanations": {"が": "「地域のサービスが充実している」で、「充実している」の主語を示す「が」。", "と": "「地域のサービスと充実している」は並列の「と」になり、充実している主体が文中に立たないので合わない。", "を": "「充実している」は目的語を取らないため、「サービスを」では文が成り立たない。", "から": "「地域のサービスから充実している」は起点の意味になり、充実している主語を示す形としては合わない。"}, "error_tags": {"と": "並列", "を": "目的語・対象", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38325, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人や社会のために提供される仕事や機能。特に、顧客に対して提供される便益や援助。", "primary_collocate": null, "pronunciation": "さーびす", "ipa": "saːbisɯ", "syllable_count": 4, "sentences": [{"text": "この会社は、お客様に二十四時間対応のサービスを提供している。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、お客様[きゃくさま]に二十四時間対応[にじゅうよじかんたいおう]のサービスを提供[ていきょう]している。", "sentence_source": "generated"}, {"text": "動画を見られるサービスの料金が、来月から上がる。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "動画[どうが]を見[み]られるサービスの料金[りょうきん]が、来月[らいげつ]から上[あ]がる。", "sentence_source": "generated"}, {"text": "銀行は、利用者のために新しいサービスを始めた。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]は、利用者[りようしゃ]のために新[あたら]しいサービスを始[はじ]めた。", "sentence_source": "generated"}, {"text": "サービスの内容に不満がある客は、窓口に連絡する。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "サービスの内容[ないよう]に不満[ふまん]がある客[きゃく]は、窓口[まどぐち]に連絡[れんらく]する。", "sentence_source": "generated"}, {"text": "引っ越しの手続きを代行するサービスが、人気を集めている。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの手続[てつづ]きを代行[だいこう]するサービスが、人気[にんき]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "無料で使えるサービスでも、個人情報には注意が必要だ。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "無料[むりょう]で使[つか]えるサービスでも、個人情報[こじんじょうほう]には注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "荷物を届けるサービスのおかげで、買い物に出かけなくて済む。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "荷物[にもつ]を届[とど]けるサービスのおかげで、買い物[かいもの]に出[で]かけなくて済[す]む。", "sentence_source": "generated"}, {"text": "地域のサービスが充実している町は、住みやすい。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "地域[ちいき]のサービスが充実[じゅうじつ]している町[まち]は、住[す]みやすい。", "sentence_source": "generated"}, {"text": "会社は顧客に合わせて、サービスを細かく変えている。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は顧客[こきゃく]に合[あ]わせて、サービスを細[こま]かく変[か]えている。", "sentence_source": "generated"}, {"text": "電話が混み合い、サービスの質が下がったと客が怒った。", "target_word": "サービス", "complexity_tier": "T3", "furigana": "電話[でんわ]が混[こ]み合[あ]い、サービスの質[しつ]が下[さ]がったと客[きゃく]が怒[おこ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サービス", "label": "基本形"}], "register": "business", "sense_fingerprint": "顧客や社会に提供される仕事・機能・便益(事業としての提供物)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fb64f-2b7d-47f2-a572-4d369e136007') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38325, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サービス", "is_correct": true, "explanation": "「二十四時間対応のサービス」は、顧客に提供される事業上の提供物を指し、「提供している」と自然につながる。"}, {"text": "雑草", "is_correct": false, "explanation": "「二十四時間対応の雑草」は意味をなさず、「提供している」とも結びつかない。"}, {"text": "虫歯", "is_correct": false, "explanation": "「二十四時間対応の虫歯」は意味が通らず、「提供している」の目的語として不自然。"}, {"text": "マナー", "is_correct": false, "explanation": "「マナーを提供している」は事業の提供物として不自然で、「二十四時間対応の」とも合わない。"}], "explanations": {"サービス": "「二十四時間対応のサービス」は、顧客に提供される事業上の提供物を指し、「提供している」と自然につながる。", "雑草": "「二十四時間対応の雑草」は意味をなさず、「提供している」とも結びつかない。", "虫歯": "「二十四時間対応の虫歯」は意味が通らず、「提供している」の目的語として不自然。", "マナー": "「マナーを提供している」は事業の提供物として不自然で、「二十四時間対応の」とも合わない。"}, "sentence_index": 0, "correct_answer": "サービス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テニスの試合で、彼はサービスを強く打った。", "explanation": "ここは〈サーブ〉の意味。球を打つ動作を指す語で、提供される仕事や機能の意味では使わないので合わない。"}, {"text": "新しいサービスを棚に並べて、店員が値段を書いた。", "explanation": "ここは〈商品〉の意味。サービスは形がないので棚に並べられず、商品の意味で使うと合わない。"}, {"text": "体調が悪いので、サービスを服用した。", "explanation": "ここは〈薬〉の意味。服用は薬に使う語で、サービスは飲むものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38325, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サービス", "is_correct": true, "explanation": "「荷物を届けるサービスのおかげで」は、事業として提供される便益を指し、文の流れに自然に合う。"}, {"text": "ペンキ", "is_correct": false, "explanation": "「荷物を届けるペンキ」は意味をなさず、「おかげで」の文脈にも合わない。"}, {"text": "手袋", "is_correct": false, "explanation": "「荷物を届ける手袋」は意味が通らず、買い物に出かけなくて済む理由にならない。"}, {"text": "風鈴", "is_correct": false, "explanation": "「荷物を届ける風鈴」は意味をなさず、文の理由として成り立たない。"}], "explanations": {"サービス": "「荷物を届けるサービスのおかげで」は、事業として提供される便益を指し、文の流れに自然に合う。", "ペンキ": "「荷物を届けるペンキ」は意味をなさず、「おかげで」の文脈にも合わない。", "手袋": "「荷物を届ける手袋」は意味が通らず、買い物に出かけなくて済む理由にならない。", "風鈴": "「荷物を届ける風鈴」は意味をなさず、文の理由として成り立たない。"}, "sentence_index": 6, "correct_answer": "サービス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "レジで店員がサービスを袋に詰めた。", "explanation": "ここは〈品物〉の意味。サービスは形がなく袋に詰められないので、品物の意味で使うと合わない。"}, {"text": "洗剤で服のサービスを落とした。", "explanation": "ここは〈汚れ〉の意味。洗剤で落とすのは汚れで、サービスは落とせないので合わない。"}, {"text": "締め切り前は、サービスを捨てる作業が続いて疲れた。", "explanation": "ここは〈ごみ〉の意味。サービスは形がなく、ごみのように捨てる対象にはならないので、ごみを捨てる作業の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38325, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "携帯会社は、通信料を無料にする新しいサービスに発表した。", "corrected_sentence": "携帯会社は、通信料を無料にする新しいサービスを発表した。", "error_description": "誤りは「サービスに」。正しくは「サービスを発表した」で、「発表する」の対象を示す「を」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38325, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "銀行は、夜間も使えるサービスを読んだ。", "corrected_sentence": "銀行は、夜間も使えるサービスを用意した。", "error_description": "誤りは「読んだ」。サービスは読むものではないので、「用意した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38326, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「負担になる」の「に」は、なる（結果・変化）と結ぶ正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「負担がなる」は、「なる」が結果を示す「に」を必要とするので不自然。"}, {"text": "を", "is_correct": false, "explanation": "「負担をなる」は、「なる」を他動詞として扱うことになり誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「負担へなる」は方向を示す「へ」で、結果を表す「なる」とは結べない。"}], "correct_answer": "に", "explanations": {"に": "「負担になる」の「に」は、なる（結果・変化）と結ぶ正しい助詞。", "が": "「負担がなる」は、「なる」が結果を示す「に」を必要とするので不自然。", "を": "「負担をなる」は、「なる」を他動詞として扱うことになり誤り。", "へ": "「負担へなる」は方向を示す「へ」で、結果を表す「なる」とは結べない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38326, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「負担を軽くする」の「を」は、軽くするの目的語を示す正しい助詞。"}, {"text": "で", "is_correct": false, "explanation": "「負担で軽くしよう」は手段を示す「で」が、軽くするに合わず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「負担と軽くしよう」は並列の「と」で、動詞の目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「負担の軽くしよう」は名詞同士をつなぐ「の」で、「軽くしよう」に続かない。"}], "correct_answer": "を", "explanations": {"を": "「負担を軽くする」の「を」は、軽くするの目的語を示す正しい助詞。", "で": "「負担で軽くしよう」は手段を示す「で」が、軽くするに合わず不自然。", "と": "「負担と軽くしよう」は並列の「と」で、動詞の目的語にならない。", "の": "「負担の軽くしよう」は名詞同士をつなぐ「の」で、「軽くしよう」に続かない。"}, "error_tags": {"で": "手段", "と": "並列", "の": "所有"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38326, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをしなければならないと感じる重さや苦しさのこと。", "primary_collocate": null, "pronunciation": "ふたん", "ipa": "ɸɯtaɴ", "syllable_count": 3, "sentences": [{"text": "仕事が増えすぎて、毎日の負担が重く感じられる。", "target_word": "負担", "complexity_tier": "T3", "furigana": "仕事[しごと]が増[ふ]えすぎて、毎日[まいにち]の負担[ふたん]が重[おも]く感[かん]じられる。", "sentence_source": "generated"}, {"text": "家族の世話を一人でするのは、大きな負担になる。", "target_word": "負担", "complexity_tier": "T3", "furigana": "家族[かぞく]の世話[せわ]を一人[ひとり]でするのは、大[おお]きな負担[ふたん]になる。", "sentence_source": "generated"}, {"text": "彼女は責任という負担に押しつぶされそうだった。", "target_word": "負担", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は責任[せきにん]という負担[ふたん]に押[お]しつぶされそうだった。", "sentence_source": "generated"}, {"text": "宿題が多いと、子どもにとって負担が大きい。", "target_word": "負担", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が多[おお]いと、子[こ]どもにとって負担[ふたん]が大[おお]きい。", "sentence_source": "generated"}, {"text": "引っ越しの準備は思ったより負担で、疲れてしまった。", "target_word": "負担", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの準備[じゅんび]は思[おも]ったより負担[ふたん]で、疲[つか]れてしまった。", "sentence_source": "generated"}, {"text": "毎週の会議が負担になり、会社を辞めたいと思った。", "target_word": "負担", "complexity_tier": "T3", "furigana": "毎週[まいしゅう]の会議[かいぎ]が負担[ふたん]になり、会社[かいしゃ]を辞[や]めたいと思[おも]った。", "sentence_source": "generated"}, {"text": "新しい係を引き受けたら、気持ちの負担が急に増えた。", "target_word": "負担", "complexity_tier": "T3", "furigana": "新[あたら]しい係[かかり]を引[ひ]き受[う]けたら、気持[きも]ちの負担[ふたん]が急[きゅう]に増[ふ]えた。", "sentence_source": "generated"}, {"text": "みんなで分けて、一人の負担を軽くしよう。", "target_word": "負担", "complexity_tier": "T3", "furigana": "みんなで分[わ]けて、一人[ひとり]の負担[ふたん]を軽[かる]くしよう。", "sentence_source": "generated"}, {"text": "毎日の長い通勤は、年を取るほど負担に感じる。", "target_word": "負担", "complexity_tier": "T3", "furigana": "毎日[まいにち]の長[なが]い通勤[つうきん]は、年[とし]を取[と]るほど負担[ふたん]に感[かん]じる。", "sentence_source": "generated"}, {"text": "心の負担を減らすために、少し休むことにした。", "target_word": "負担", "complexity_tier": "T3", "furigana": "心[こころ]の負担[ふたん]を減[へ]らすために、少[すこ]し休[やす]むことにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "負担", "label": "基本形"}, {"form": "負担する", "label": "サ変動詞形"}, {"form": "負担した", "label": "サ変動詞過去形"}], "register": "neutral", "sense_fingerprint": "しなければならないことから生じる、心や体への重さ・苦しさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1c8c83-1c1f-4ce4-8526-69429b5ec9c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38326, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "負担", "is_correct": true, "explanation": "「毎日の___が重く感じられる」の空欄に入る名詞で、重さや苦しさを表す。正解。"}, {"text": "負担する", "is_correct": false, "explanation": "動詞の形で、「毎日の負担する」は名詞句として成り立たない。"}, {"text": "負担した", "is_correct": false, "explanation": "過去形の動詞で、「毎日の負担した」は名詞句として成り立たない。"}, {"text": "負担なし", "is_correct": false, "explanation": "「負担がないこと」を表す名詞句で、「毎日の負担なし重く」は意味が通らない。"}], "explanations": {"負担": "「毎日の___が重く感じられる」の空欄に入る名詞で、重さや苦しさを表す。正解。", "負担する": "動詞の形で、「毎日の負担する」は名詞句として成り立たない。", "負担した": "過去形の動詞で、「毎日の負担した」は名詞句として成り立たない。", "負担なし": "「負担がないこと」を表す名詞句で、「毎日の負担なし重く」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "負担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い負担を両手で運んで、階段を上った。", "explanation": "ここは〈荷物〉の意味。「荷物」は手で運ぶものを指すが、「負担」は感じる重さなので、運ぶ対象にはならないので合わない。"}, {"text": "彼は与えられた負担をきちんと果たした。", "explanation": "ここは〈責任〉の意味。「果たす」は責任や役割に使う語で、「負担」は感じる重さを指すので合わない。"}, {"text": "試合中に足を負担した。", "explanation": "ここは〈負傷〉の意味。「負担」は重さや苦しさの気持ちを表し、体の怪我には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38326, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "負担", "is_correct": true, "explanation": "「気持ちの___が急に増えた」の空欄に入る名詞で、重い気持ちを表す。正解。"}, {"text": "負担して", "is_correct": false, "explanation": "て形の動詞で、「気持ちの負担して」は名詞句として成り立たない。"}, {"text": "負担せず", "is_correct": false, "explanation": "否定の動詞形で、「気持ちの負担せず」は名詞句にならない。"}, {"text": "負担できる", "is_correct": false, "explanation": "可能の動詞形で、「気持ちの負担できる」は名詞句として成り立たない。"}], "explanations": {"負担": "「気持ちの___が急に増えた」の空欄に入る名詞で、重い気持ちを表す。正解。", "負担して": "て形の動詞で、「気持ちの負担して」は名詞句として成り立たない。", "負担せず": "否定の動詞形で、「気持ちの負担せず」は名詞句にならない。", "負担できる": "可能の動詞形で、「気持ちの負担できる」は名詞句として成り立たない。"}, "sentence_index": 6, "correct_answer": "負担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早めに寝て、風邪を負担することにした。", "explanation": "ここは〈治す〉の意味。「負担」は重さを感じることで、病気を対象にして使うとは言わないので合わない。"}, {"text": "友達に、長い負担を書いて送った。", "explanation": "ここは〈手紙〉の意味。「書く」の対象は手紙で、「負担」は書くものではないので合わない。"}, {"text": "昨日、懐かしい負担を見た。", "explanation": "ここは〈夢〉の意味。「見る」の対象は夢や景色で、「負担」は見るものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38326, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この練習量は、子どもに負担を大きい。", "corrected_sentence": "この練習量は、子どもに負担が大きい。", "error_description": "「負担」は主語として「が大きい」と結ぶ。「を」は動詞の目的語を示すので、形容詞「大きい」とは結べない。誤りは「を」、正しくは「が」（負担が大きい）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38326, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "忙しい時期は、まず自分の負担を減る方法を考えよう。", "corrected_sentence": "忙しい時期は、まず自分の負担を減らす方法を考えよう。", "error_description": "「負担」は他動詞「減らす」と結ぶ。「減る」は自動詞なので「負担を減る」は誤り。誤りは「減る」、正しくは「減らす」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
