INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38327, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人に何かをお願いしたり、頼んだりしたときに、その人が感じる重い気持ちやつらい気持ち。", "primary_collocate": null, "pronunciation": "ふたん", "ipa": "ɸɯtaɴ", "syllable_count": 3, "sentences": [{"text": "忙しい先輩に何度も頼むのは、相手の負担になる気がして言えなかった。", "target_word": "負担", "complexity_tier": "T3", "furigana": "忙[いそが]しい先輩[せんぱい]に何度[なんど]も頼[たの]むのは、相手[あいて]の負担[ふたん]になる気[き]がして言[い]えなかった。", "sentence_source": "generated"}, {"text": "友達に引っ越しを手伝ってもらうのは、負担ではないかと心配だった。", "target_word": "負担", "complexity_tier": "T3", "furigana": "友達[ともだち]に引[ひ]っ越[こ]しを手伝[てつだ]ってもらうのは、負担[ふたん]ではないかと心配[しんぱい]だった。", "sentence_source": "generated"}, {"text": "急なお願いが相手の負担にならないよう、早めに連絡した。", "target_word": "負担", "complexity_tier": "T3", "furigana": "急[きゅう]なお願[ねが]いが相手[あいて]の負担[ふたん]にならないよう、早[はや]めに連絡[れんらく]した。", "sentence_source": "generated"}, {"text": "「無理なら断ってね。負担に思わなくていいよ」と先生は言った。", "target_word": "負担", "complexity_tier": "T3", "furigana": "「無理[むり]なら断[ことわ]ってね。負担[ふたん]に思[おも]わなくていいよ」と先生[せんせい]は言[い]った。", "sentence_source": "generated"}, {"text": "何度も送り迎えを頼むと、母に負担をかけてしまう。", "target_word": "負担", "complexity_tier": "T3", "furigana": "何度[なんど]も送[おく]り迎[むか]えを頼[たの]むと、母[はは]に負担[ふたん]をかけてしまう。", "sentence_source": "generated"}, {"text": "彼は人に頼まれると、負担を感じても断れない性格だ。", "target_word": "負担", "complexity_tier": "T3", "furigana": "彼[かれ]は人[ひと]に頼[たの]まれると、負担[ふたん]を感[かん]じても断[ことわ]れない性格[せいかく]だ。", "sentence_source": "generated"}, {"text": "遠くまで来てもらうと相手の負担が大きいので、こちらから行くことにした。", "target_word": "負担", "complexity_tier": "T3", "furigana": "遠[とお]くまで来[き]てもらうと相手[あいて]の負担[ふたん]が大[おお]きいので、こちらから行[い]くことにした。", "sentence_source": "generated"}, {"text": "隣の人に荷物を預けたら、負担だったかもしれないと後で気になった。", "target_word": "負担", "complexity_tier": "T3", "furigana": "隣[となり]の人[ひと]に荷物[にもつ]を預[あず]けたら、負担[ふたん]だったかもしれないと後[あと]で気[き]になった。", "sentence_source": "generated"}, {"text": "小さなお願いでも、相手に負担を感じさせたくない。", "target_word": "負担", "complexity_tier": "T3", "furigana": "小[ちい]さなお願[ねが]いでも、相手[あいて]に負担[ふたん]を感[かん]じさせたくない。", "sentence_source": "generated"}, {"text": "頼みごとを引き受けた友人の負担を思うと、申し訳なくなった。", "target_word": "負担", "complexity_tier": "T3", "furigana": "頼[たの]みごとを引[ひ]き受[う]けた友人[ゆうじん]の負担[ふたん]を思[おも]うと、申[もう]し訳[わけ]なくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "負担", "label": "基本形"}, {"form": "負担する", "label": "サ変動詞形"}, {"form": "負担した", "label": "サ変動詞過去形"}], "register": "neutral", "sense_fingerprint": "頼みごとをされた相手が感じる、重い・つらいという気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1c8c83-1c1f-4ce4-8526-69429b5ec9c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38327, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "負担", "is_correct": true, "explanation": "「相手の___になる」の空欄に入り、相手が感じる重い気持ちを表す。正解。"}, {"text": "負担する", "is_correct": false, "explanation": "動詞の形で、「相手の負担するになる」は成り立たない。"}, {"text": "負担した", "is_correct": false, "explanation": "過去形の動詞で、「相手の負担したになる」は成り立たない。"}, {"text": "負担なく", "is_correct": false, "explanation": "副詞的な形で、「相手の負担なくになる」は名詞句として成り立たない。"}], "explanations": {"負担": "「相手の___になる」の空欄に入り、相手が感じる重い気持ちを表す。正解。", "負担する": "動詞の形で、「相手の負担するになる」は成り立たない。", "負担した": "過去形の動詞で、「相手の負担したになる」は成り立たない。", "負担なく": "副詞的な形で、「相手の負担なくになる」は名詞句として成り立たない。"}, "sentence_index": 0, "correct_answer": "負担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜道は、負担して運転してください。", "explanation": "ここは〈注意〉の意味。「注意して運転する」の文脈だが、「負担」は相手が感じる重さで、運転の仕方には使わないので合わない。"}, {"text": "負担を取らせてしまい、すみません。", "explanation": "ここは〈手間〉の意味。「負担」は重い気持ちを表し、時間や労力を取らせる意味には使わないので合わない。"}, {"text": "頼みたいことがあったが、負担して言い出せなかった。", "explanation": "ここは〈遠慮〉の意味。「遠慮して言い出せない」の文脈だが、「負担」は相手が感じる重さで、控えめに振る舞う気持ちとは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38327, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "負担", "is_correct": true, "explanation": "「相手の___が大きい」の空欄に入り、相手が感じる重い気持ちを表す。正解。"}, {"text": "負担して", "is_correct": false, "explanation": "て形の動詞で、「相手の負担して」は名詞句として成り立たない。"}, {"text": "負担せず", "is_correct": false, "explanation": "否定の動詞形で、「相手の負担せず」は名詞句にならない。"}, {"text": "負担できる", "is_correct": false, "explanation": "可能の動詞形で、「相手の負担できる」は名詞句として成り立たない。"}], "explanations": {"負担": "「相手の___が大きい」の空欄に入り、相手が感じる重い気持ちを表す。正解。", "負担して": "て形の動詞で、「相手の負担して」は名詞句として成り立たない。", "負担せず": "否定の動詞形で、「相手の負担せず」は名詞句にならない。", "負担できる": "可能の動詞形で、「相手の負担できる」は名詞句として成り立たない。"}, "sentence_index": 6, "correct_answer": "負担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は負担を見せて、皆を安心させた。", "explanation": "ここは〈笑顔〉の意味。「笑顔を見せる」の表情の場面で、「負担」は見せるものではないので合わない。"}, {"text": "育ててくれた負担を、ようやく返せた。", "explanation": "ここは〈恩〉の意味。「返す」の対象は恩で、「負担」は返すものではないので合わない。"}, {"text": "旅先で、景色の負担を撮った。", "explanation": "ここは〈写真〉の意味。「撮る」の対象は写真で、「負担」は撮る対象にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38327, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "忙しい人に頼むのは、相手の負担がなる気がする。", "corrected_sentence": "忙しい人に頼むのは、相手の負担になる気がする。", "error_description": "「負担」に続けて「なる」と結ぶには、結果を示す「に」が必要。「が」を使うと「負担がなる」となり不自然。誤りは「が」、正しくは「に」（負担になる）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38327, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "急な残業を頼むと、同僚に負担をつけてしまう。", "corrected_sentence": "急な残業を頼むと、同僚に負担をかけてしまう。", "error_description": "「負担」と結ぶ動詞は「かける」。「つける」は負担には使わず、「負担をつける」は不自然。誤りは「つける」、正しくは「かける」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38328, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「便益」は「もたらす」の目的語なので「を」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「もたらす」の相手を表す「に」は「利用者に」で既に使われており、便益の後ろに置くと目的語が成立しない。"}, {"text": "が", "is_correct": false, "explanation": "「便益が」とすると便益が主語になり、もたらす主体が不明で文が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "「便益で」は手段や場所を表すが、ここでは対象を示す必要があり意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「便益」は「もたらす」の目的語なので「を」が正しい。", "に": "「もたらす」の相手を表す「に」は「利用者に」で既に使われており、便益の後ろに置くと目的語が成立しない。", "が": "「便益が」とすると便益が主語になり、もたらす主体が不明で文が崩れる。", "で": "「便益で」は手段や場所を表すが、ここでは対象を示す必要があり意味が通らない。"}, "error_tags": {"に": "相手・対象", "が": "主語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38328, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「便益」は「受ける」の目的語なので「を」が正しい。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表し、「受けられない」の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、受けるという動作の対象を示せないので文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、ここでは受ける対象を示す役割を果たさない。"}], "correct_answer": "を", "explanations": {"を": "「便益」は「受ける」の目的語なので「を」が正しい。", "と": "「と」は並列や相手を表し、「受けられない」の対象にはならない。", "へ": "「へ」は方向を表すが、受けるという動作の対象を示せないので文が成り立たない。", "より": "「より」は比較を表し、ここでは受ける対象を示す役割を果たさない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38328, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときに、人にとって役に立つこと。", "primary_collocate": null, "pronunciation": "べんえき", "ipa": "beɴeki", "syllable_count": 4, "sentences": [{"text": "新しい道路ができて、住民は通勤時間の短縮という便益を得た。", "target_word": "便益", "complexity_tier": "T3", "furigana": "新[あたら]しい道路[どうろ]ができて、住民[じゅうみん]は通勤[つうきん]時間[じかん]の短縮[たんしゅく]という便益[べんえき]を得[え]た。", "sentence_source": "generated"}, {"text": "この制度は利用者に大きな便益をもたらすと期待されている。", "target_word": "便益", "complexity_tier": "T3", "furigana": "この制度[せいど]は利用者[りようしゃ]に大[おお]きな便益[べんえき]をもたらすと期待[きたい]されている。", "sentence_source": "generated"}, {"text": "便益が少ないと感じた人は、サービスの利用をやめてしまった。", "target_word": "便益", "complexity_tier": "T3", "furigana": "便益[べんえき]が少[すく]ないと感[かん]じた人[ひと]は、サービスの利用[りよう]をやめてしまった。", "sentence_source": "generated"}, {"text": "駅の近くに店が集まると、買い物客の便益が高まる。", "target_word": "便益", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに店[みせ]が集[あつ]まると、買[か]い物[もの]客[きゃく]の便益[べんえき]が高[たか]まる。", "sentence_source": "generated"}, {"text": "自分の便益だけを考えて行動すると、周りの人に迷惑がかかる。", "target_word": "便益", "complexity_tier": "T3", "furigana": "自分[じぶん]の便益[べんえき]だけを考[かんが]えて行動[こうどう]すると、周[まわ]りの人[ひと]に迷惑[めいわく]がかかる。", "sentence_source": "generated"}, {"text": "調査では、図書館の延長開館が学生に便益を与えたことが分かった。", "target_word": "便益", "complexity_tier": "T3", "furigana": "調査[ちょうさ]では、図書館[としょかん]の延長[えんちょう]開館[かいかん]が学生[がくせい]に便益[べんえき]を与[あた]えたことが分[わ]かった。", "sentence_source": "generated"}, {"text": "新しい機械は高価だが、現場の作業員にとって便益が大きい。", "target_word": "便益", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]は高価[こうか]だが、現場[げんば]の作業員[さぎょういん]にとって便益[べんえき]が大[おお]きい。", "sentence_source": "generated"}, {"text": "病院が遠いため、村の人々は医療の便益を十分に受けられない。", "target_word": "便益", "complexity_tier": "T3", "furigana": "病院[びょういん]が遠[とお]いため、村[むら]の人々[ひとびと]は医療[いりょう]の便益[べんえき]を十分[じゅうぶん]に受[う]けられない。", "sentence_source": "generated"}, {"text": "企業は顧客に便益を提供することで、信頼を得る。", "target_word": "便益", "complexity_tier": "T3", "furigana": "企業[きぎょう]は顧客[こきゃく]に便益[べんえき]を提供[ていきょう]することで、信頼[しんらい]を得[え]る。", "sentence_source": "generated"}, {"text": "小さな工夫でも、使う人の便益になるなら取り入れるべきだ。", "target_word": "便益", "complexity_tier": "T3", "furigana": "小[ちい]さな工夫[くふう]でも、使[つか]う人[ひと]の便益[べんえき]になるなら取[と]り入[い]れるべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "便益", "label": "基本形"}], "register": "formal", "sense_fingerprint": "ある行為やサービスが人にとって役に立つこと、使う人が受ける便利さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1c8c83-1c1f-4ce4-8526-69429b5ec9c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38328, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便益", "is_correct": true, "explanation": "役に立つことという意味で、通勤時間が短くなる利点を指すので文に合う。"}, {"text": "負担", "is_correct": false, "explanation": "負担は重荷や苦労の意味で、短縮という良い結果とは逆になる。"}, {"text": "手間", "is_correct": false, "explanation": "手間は余計な労力のことで、短縮によって得るものとしては文脈に合わない。"}, {"text": "規則", "is_correct": false, "explanation": "規則は決まりごとで、通勤時間の短縮を得るという内容とつながらない。"}], "explanations": {"便益": "役に立つことという意味で、通勤時間が短くなる利点を指すので文に合う。", "負担": "負担は重荷や苦労の意味で、短縮という良い結果とは逆になる。", "手間": "手間は余計な労力のことで、短縮によって得るものとしては文脈に合わない。", "規則": "規則は決まりごとで、通勤時間の短縮を得るという内容とつながらない。"}, "sentence_index": 0, "correct_answer": "便益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "社長は決算で、大きな便益を上げたと説明した。", "explanation": "ここは〈利益〉の意味。会社の儲けには利益を使い、便益は人や社会の役立ちを指すので「上げる」とは合わない。"}, {"text": "銀行に預けると、便益がつく。", "explanation": "預金に付くのは利息で、便益は人や社会の役立ちを指すので「つく」とは合わない。"}, {"text": "明日の便益は晴れでしょう。", "explanation": "便益は人や社会の役立ちを指すので、明日の空模様の予報には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38328, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便益", "is_correct": true, "explanation": "役立ちや効果を表す語で、作業員にとって効果が大きいという文に合う。"}, {"text": "手順", "is_correct": false, "explanation": "手順は作業の順序のことで、「大きい」と続けても作業員にとっての効果を表さない。"}, {"text": "形式", "is_correct": false, "explanation": "形式は型や様式のことで、役立ちの大きさを表す文脈では意味が通らない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は色合いのことで、機械の作業効果の大きさとしては合わない。"}], "explanations": {"便益": "役立ちや効果を表す語で、作業員にとって効果が大きいという文に合う。", "手順": "手順は作業の順序のことで、「大きい」と続けても作業員にとっての効果を表さない。", "形式": "形式は型や様式のことで、役立ちの大きさを表す文脈では意味が通らない。", "色彩": "色彩は色合いのことで、機械の作業効果の大きさとしては合わない。"}, "sentence_index": 6, "correct_answer": "便益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "思わぬ台風で、農家は大きな便益を被った。", "explanation": "被るのは損害や損失で、役立ちを表す便益は被るものではない。"}, {"text": "会社は、事故の被害者に十分な便益を払った。", "explanation": "払うのは損害を償うお金で、便益は払うものではないので合わない。"}, {"text": "犯人の便益が見つかった。", "explanation": "見つかるのは証拠で、人や社会の役立ちを表す便益は見つかるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38328, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "自治体はこの制度で、住民に多くの便益を開いた。", "corrected_sentence": "自治体はこの制度で、住民に多くの便益を与えた。", "error_description": "誤: 便益を開いた。正: 便益を与えた。「与える」が正しい動詞で、「開く」は便益と結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38328, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この新しい仕組みは、利用者に便益の届ける。", "corrected_sentence": "この新しい仕組みは、利用者に便益を届ける。", "error_description": "誤: 便益の届ける。正: 便益を届ける。「届ける」の目的語には「を」が必要で、「の」では動詞に続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38329, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38329, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「便益が生まれた」の主語を表す「が」が正しい。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表し、「生まれた」の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、生まれるものの主語にはならないので文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「生まれた」は目的語を取らないので、「便益を」は続かない。"}], "correct_answer": "が", "explanations": {"が": "「便益が生まれた」の主語を表す「が」が正しい。", "と": "「と」は並列や相手を表し、「生まれた」の主語にはならない。", "へ": "「へ」は方向を表すが、生まれるものの主語にはならないので文が成り立たない。", "を": "「生まれた」は目的語を取らないので、「便益を」は続かない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38329, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある行動や物事が、人や社会にとってプラスになる利益や効果のこと。", "primary_collocate": null, "pronunciation": "べんえき", "ipa": "beɴeki", "syllable_count": 4, "sentences": [{"text": "公園の整備は、地域の人々に健康という便益をもたらす。", "target_word": "便益", "complexity_tier": "T3", "furigana": "公園[こうえん]の整備[せいび]は、地域[ちいき]の人々[ひとびと]に健康[けんこう]という便益[べんえき]をもたらす。", "sentence_source": "generated"}, {"text": "新しい橋の建設費は高いが、長い目で見れば社会に大きな便益がある。", "target_word": "便益", "complexity_tier": "T3", "furigana": "新[あたら]しい橋[はし]の建設費[けんせつひ]は高[たか]いが、長[なが]い目[め]で見[み]れば社会[しゃかい]に大[おお]きな便益[べんえき]がある。", "sentence_source": "generated"}, {"text": "計画を進める前に、費用と便益をよく比べて決めるべきだ。", "target_word": "便益", "complexity_tier": "T3", "furigana": "計画[けいかく]を進[すす]める前[まえ]に、費用[ひよう]と便益[べんえき]をよく比[くら]べて決[き]めるべきだ。", "sentence_source": "generated"}, {"text": "この研究から生まれる便益は、将来の世代にも及ぶだろう。", "target_word": "便益", "complexity_tier": "T3", "furigana": "この研究[けんきゅう]から生[う]まれる便益[べんえき]は、将来[しょうらい]の世代[せだい]にも及[およ]ぶだろう。", "sentence_source": "generated"}, {"text": "ワクチンの接種は、個人だけでなく社会全体の便益につながる。", "target_word": "便益", "complexity_tier": "T3", "furigana": "ワクチンの接種[せっしゅ]は、個人[こじん]だけでなく社会[しゃかい]全体[ぜんたい]の便益[べんえき]につながる。", "sentence_source": "generated"}, {"text": "事業の便益が費用を下回るなら、計画は見直すべきだ。", "target_word": "便益", "complexity_tier": "T3", "furigana": "事業[じぎょう]の便益[べんえき]が費用[ひよう]を下回[したまわ]るなら、計画[けいかく]は見直[みなお]すべきだ。", "sentence_source": "generated"}, {"text": "緑化事業の便益を数字で示すことは、思ったより難しい。", "target_word": "便益", "complexity_tier": "T3", "furigana": "緑化[りょくか]事業[じぎょう]の便益[べんえき]を数字[すうじ]で示[しめ]すことは、思[おも]ったより難[むずか]しい。", "sentence_source": "generated"}, {"text": "自転車道の整備により、環境と経済の両面で便益が生まれた。", "target_word": "便益", "complexity_tier": "T3", "furigana": "自転車道[じてんしゃどう]の整備[せいび]により、環境[かんきょう]と経済[けいざい]の両面[りょうめん]で便益[べんえき]が生[う]まれた。", "sentence_source": "generated"}, {"text": "省エネの取り組みは、企業にも地域にも便益を与える。", "target_word": "便益", "complexity_tier": "T3", "furigana": "省[しょう]エネの取[と]り組[く]みは、企業[きぎょう]にも地域[ちいき]にも便益[べんえき]を与[あた]える。", "sentence_source": "generated"}, {"text": "便益を受ける人が増えるほど、その政策の価値は高まる。", "target_word": "便益", "complexity_tier": "T3", "furigana": "便益[べんえき]を受[う]ける人[ひと]が増[ふ]えるほど、その政策[せいさく]の価値[かち]は高[たか]まる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "便益", "label": "基本形"}], "register": "formal", "sense_fingerprint": "事業や政策などが人や社会にもたらすプラスの利益・効果（費用と比べるもの）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1c8c83-1c1f-4ce4-8526-69429b5ec9c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38329, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便益", "is_correct": true, "explanation": "公園の整備がもたらす効果や利益を表し、健康をもたらすという文に合う。"}, {"text": "手順", "is_correct": false, "explanation": "手順は作業の順序のことで、健康をもたらすものではない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は色合いのことで、健康をもたらすという文脈とはつながらない。"}, {"text": "規模", "is_correct": false, "explanation": "規模は大きさの程度で、健康という効果をもたらすとは言えない。"}], "explanations": {"便益": "公園の整備がもたらす効果や利益を表し、健康をもたらすという文に合う。", "手順": "手順は作業の順序のことで、健康をもたらすものではない。", "色彩": "色彩は色合いのことで、健康をもたらすという文脈とはつながらない。", "規模": "規模は大きさの程度で、健康という効果をもたらすとは言えない。"}, "sentence_index": 0, "correct_answer": "便益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は届いた小包の便益を開けた。", "explanation": "開けるのは荷物や箱で、便益は人や社会の役立ちを指すので「開けた」とは合わない。"}, {"text": "母は娘のワンピースの便益を縫った。", "explanation": "縫うのは布地で、便益は縫うものではないので合わない。"}, {"text": "業者が屋根の便益を直した。", "explanation": "直すのは不具合で、役立ちを表す便益は直す対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38329, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便益", "is_correct": true, "explanation": "事業や政策がもたらす利益を表し、緑化事業の効果を示すという文に合う。"}, {"text": "香り", "is_correct": false, "explanation": "香りは匂いのことで、緑化事業の効果を数字で示すという文脈には合わない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時期のことで、数字で示す対象としては文に合わない。"}, {"text": "音色", "is_correct": false, "explanation": "音色は音の質のことで、緑化事業を数字で示すという内容とはつながらない。"}], "explanations": {"便益": "事業や政策がもたらす利益を表し、緑化事業の効果を示すという文に合う。", "香り": "香りは匂いのことで、緑化事業の効果を数字で示すという文脈には合わない。", "季節": "季節は時期のことで、数字で示す対象としては文に合わない。", "音色": "音色は音の質のことで、緑化事業を数字で示すという内容とはつながらない。"}, "sentence_index": 6, "correct_answer": "便益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨で、町は多くの便益を被った。", "explanation": "被るのは損害や損失で、役立ちを表す便益は被るものではない。"}, {"text": "会社は、事故の被害者に便益を払った。", "explanation": "払うのは損害を償うお金で、便益は払うものではないので合わない。"}, {"text": "父は庭の便益を耕した。", "explanation": "耕すのは畑や田で、便益は人や社会の役立ちを指すので耕す対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38329, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この計画は、住民に多くの便益にもたらす。", "corrected_sentence": "この計画は、住民に多くの便益をもたらす。", "error_description": "誤: 便益にもたらす。正: 便益をもたらす。「もたらす」の目的語には「を」が必要で、「に」では便益が目的語にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38329, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この事業は地域に便益を生まれる。", "corrected_sentence": "この事業は地域に便益を生む。", "error_description": "誤: 生まれる。正: 生む。「便益を」と結ぶのは他動詞の「生む」で、「生まれる」は「便益が生まれる」の形でしか使えないので合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38330, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有形", "is_correct": true, "explanation": "形があり触れられるという意味で、無形の対義語。"}, {"text": "有名", "is_correct": false, "explanation": "名前が知られているという意味。形の有無とは対義関係にない。"}, {"text": "無礼", "is_correct": false, "explanation": "礼儀を欠くこと。無形とは対義関係にない。"}, {"text": "無限", "is_correct": false, "explanation": "限りがないという意味。形がないこととは対義関係にない。"}], "correct_answer": "有形", "explanations": {"有形": "形があり触れられるという意味で、無形の対義語。", "有名": "名前が知られているという意味。形の有無とは対義関係にない。", "無礼": "礼儀を欠くこと。無形とは対義関係にない。", "無限": "限りがないという意味。形がないこととは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38330, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有形", "is_correct": true, "explanation": "形があり目で見えるという意味で、無形の対義語。"}, {"text": "有料", "is_correct": false, "explanation": "料金がかかること。形の有無とは対義関係にない。"}, {"text": "無事", "is_correct": false, "explanation": "問題なく安全なこと。無形とは対義関係にない。"}, {"text": "無罪", "is_correct": false, "explanation": "罪に問われないこと。形の有無とは対義関係にない。"}], "correct_answer": "有形", "explanations": {"有形": "形があり目で見えるという意味で、無形の対義語。", "有料": "料金がかかること。形の有無とは対義関係にない。", "無事": "問題なく安全なこと。無形とは対義関係にない。", "無罪": "罪に問われないこと。形の有無とは対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38330, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "かたちがないことです。目に見えません。", "primary_collocate": null, "pronunciation": "むけい", "ipa": "mɯkeː", "syllable_count": 3, "sentences": [{"text": "空気は無形なので、手でつかむことができません。", "target_word": "無形", "complexity_tier": "T3", "furigana": "空気[くうき]は無形[むけい]なので、手[て]でつかむことができません。", "sentence_source": "generated"}, {"text": "心の中の思いは無形で、目に見えません。", "target_word": "無形", "complexity_tier": "T3", "furigana": "心[こころ]の中[なか]の思[おも]いは無形[むけい]で、目[め]に見[み]えません。", "sentence_source": "generated"}, {"text": "風は無形だが、木の葉が揺れると、そこにあるとわかる。", "target_word": "無形", "complexity_tier": "T3", "furigana": "風[かぜ]は無形[むけい]だが、木[き]の葉[は]が揺[ゆ]れると、そこにあるとわかる。", "sentence_source": "generated"}, {"text": "無形のものは、写真に撮ることができない。", "target_word": "無形", "complexity_tier": "T3", "furigana": "無形[むけい]のものは、写真[しゃしん]に撮[と]ることができない。", "sentence_source": "generated"}, {"text": "愛や信頼のような無形のものは、お金では買えません。", "target_word": "無形", "complexity_tier": "T3", "furigana": "愛[あい]や信頼[しんらい]のような無形[むけい]のものは、お金[かね]では買[か]えません。", "sentence_source": "generated"}, {"text": "音は無形ですが、耳で聞くことができます。", "target_word": "無形", "complexity_tier": "T3", "furigana": "音[おと]は無形[むけい]ですが、耳[みみ]で聞[き]くことができます。", "sentence_source": "generated"}, {"text": "この会社の一番の財産は、無形の信用です。", "target_word": "無形", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の一番[いちばん]の財産[ざいさん]は、無形[むけい]の信用[しんよう]です。", "sentence_source": "generated"}, {"text": "形のある物と違って、無形のものは壊れることがありません。", "target_word": "無形", "complexity_tier": "T3", "furigana": "形[かたち]のある物[もの]と違[ちが]って、無形[むけい]のものは壊[こわ]れることがありません。", "sentence_source": "generated"}, {"text": "神様は無形だと考える人もいます。", "target_word": "無形", "complexity_tier": "T3", "furigana": "神様[かみさま]は無形[むけい]だと考[かんが]える人[ひと]もいます。", "sentence_source": "generated"}, {"text": "電気そのものは無形ですが、明かりがつけば、そこにあるとわかります。", "target_word": "無形", "complexity_tier": "T3", "furigana": "電気[でんき]そのものは無形[むけい]ですが、明[あか]りがつけば、そこにあるとわかります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無形", "label": "基本形"}, {"form": "無形の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "かたちがなく目で見えないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9d837e-9b28-4e2f-9d20-c846059db583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38330, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無形", "is_correct": true, "explanation": "形がなく目に見えないという意味で、手でつかめない理由として合う。"}, {"text": "有形", "is_correct": false, "explanation": "形があって触れられるという意味。空気の性質として矛盾し、理由にならない。"}, {"text": "有名", "is_correct": false, "explanation": "名前が広く知られているという意味。空気の性質を説明できない。"}, {"text": "無料", "is_correct": false, "explanation": "お金がかからないという意味。手でつかめないことの理由にならない。"}], "explanations": {"無形": "形がなく目に見えないという意味で、手でつかめない理由として合う。", "有形": "形があって触れられるという意味。空気の性質として矛盾し、理由にならない。", "有名": "名前が広く知られているという意味。空気の性質を説明できない。", "無料": "お金がかからないという意味。手でつかめないことの理由にならない。"}, "sentence_index": 0, "correct_answer": "無形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ガラス窓は無形で、向こうの景色がよく見える。", "explanation": "ここは〈透明〉の意味。無形は形がないことで、透き通って見えるという意味はない。ガラスには形があるので使えない。"}, {"text": "この地図は無形で、道や建物が一つずつ描かれている。", "explanation": "ここは〈具体的〉の意味。道や建物が描かれた地図は形があり、無形とは言わない。"}, {"text": "この切符は期限が切れて、無形になった。", "explanation": "ここは〈無効〉の意味。無形は形がないことで、使えなくなるという意味は持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38330, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無形", "is_correct": true, "explanation": "形のない財産、つまり目に見えない信用の性質を表し、財産の説明として合う。"}, {"text": "有利", "is_correct": false, "explanation": "都合がよいという意味。「の信用」とつながらず、財産の性質を表せない。"}, {"text": "無断", "is_correct": false, "explanation": "許可を得ないで行うこと。信用の性質を説明する語ではない。"}, {"text": "有償", "is_correct": false, "explanation": "対価を払うという意味。「の信用」と続かず、財産の性質を表さない。"}], "explanations": {"無形": "形のない財産、つまり目に見えない信用の性質を表し、財産の説明として合う。", "有利": "都合がよいという意味。「の信用」とつながらず、財産の性質を表せない。", "無断": "許可を得ないで行うこと。信用の性質を説明する語ではない。", "有償": "対価を払うという意味。「の信用」と続かず、財産の性質を表さない。"}, "sentence_index": 6, "correct_answer": "無形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "証拠が足りず、彼は無形になった。", "explanation": "ここは〈無罪〉の意味。無形は形がないことで、罪がないという意味は持たない。"}, {"text": "彼は試合の結果に無形だった。", "explanation": "ここは〈無関心〉の意味。無形は形がないことで、結果を気にかけない態度は表さない。"}, {"text": "彼女は無形で、何も言わなかった。", "explanation": "ここは〈無表情〉の意味。無形は形がないことで、表情がないという意味は持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38330, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "無形ものは、写真に撮れない。", "corrected_sentence": "無形のものは、写真に撮れない。", "error_description": "「無形」は名詞なので、後ろの名詞を修飾するには「の」が必要。「の」が抜けているので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38330, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "無形を財産は、お金で数えられない。", "corrected_sentence": "無形の財産は、お金で数えられない。", "error_description": "「無形」は後ろの名詞「財産」を修飾するので「の」が必要。「を」は目的語を示すため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
