INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38332, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お金を出すときに、会社が環境や人やルールを大切にしているかを見ることです。", "primary_collocate": null, "pronunciation": "いーえすじー", "ipa": "iːesɯdʑiː", "syllable_count": 6, "sentences": [{"text": "投資家は、会社が環境を大切にしているかを見るために、ESG を調べる。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "投資家[とうしか]は、会社[かいしゃ]が環境[かんきょう]を大切[たいせつ]にしているかを見[み]るために、ESG を調[しら]べる。", "sentence_source": "generated"}, {"text": "この銀行はお金を貸すとき、相手の会社の ESG も確認する。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "この銀行[ぎんこう]はお金[かね]を貸[か]すとき、相手[あいて]の会社[かいしゃ]の ESG も確認[かくにん]する。", "sentence_source": "generated"}, {"text": "環境に悪い工場を持つ会社は、ESG の評価が低くなりやすい。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "環境[かんきょう]に悪[わる]い工場[こうじょう]を持[も]つ会社[かいしゃ]は、ESG の評価[ひょうか]が低[ひく]くなりやすい。", "sentence_source": "generated"}, {"text": "社員を大切にしない会社は、ESG の面で信頼されない。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "社員[しゃいん]を大切[たいせつ]にしない会社[かいしゃ]は、ESG の面[めん]で信頼[しんらい]されない。", "sentence_source": "generated"}, {"text": "若い人にも、ESG を考えてお金を使う人が増えている。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "若[わか]い人[ひと]にも、ESG を考[かんが]えてお金[かね]を使[つか]う人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "ルールを守らなかった会社は、ESG を重視する投資家に避けられた。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "ルールを守[まも]らなかった会社[かいしゃ]は、ESG を重視[じゅうし]する投資家[とうしか]に避[さ]けられた。", "sentence_source": "generated"}, {"text": "ESG の点数が高い会社には、多くのお金が集まる。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "ESG の点数[てんすう]が高[たか]い会社[かいしゃ]には、多[おお]くのお金[かね]が集[あつ]まる。", "sentence_source": "generated"}, {"text": "年金基金は、ESG を見て投資先を選ぶようになった。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "年金[ねんきん]基金[ききん]は、ESG を見[み]て投資先[とうしさき]を選[えら]ぶようになった。", "sentence_source": "generated"}, {"text": "古い運用方針を続けてきた投資家も、ESG を基準に投資先を見直し始めた。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "古[ふる]い運用方針[うんようほうしん]を続[つづ]けてきた投資家[とうしか]も、ESG を基準[きじゅん]に投資先[とうしさき]を見直[みなお]し始[はじ]めた。", "sentence_source": "generated"}, {"text": "投資の相談で、担当者が ESG とは何かをやさしく説明してくれた。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "投資[とうし]の相談[そうだん]で、担当者[たんとうしゃ]が ESG とは何[なに]かをやさしく説明[せつめい]してくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ESG", "label": "基本形"}], "register": "formal", "sense_fingerprint": "お金を出す前に、会社が環境・人・ルールを大切にしているかを確かめる見方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1c8c83-1c1f-4ce4-8526-69429b5ec9c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38332, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ESG", "is_correct": true, "explanation": "投資の判断で会社の環境・人・ルールを確かめる見方を表し、調べる対象として文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は調べる対象として文脈に合わず、会社の環境配慮を見る文とはつながらない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は投資の判断と関係がなく、ここで調べるものとしては合わない。"}, {"text": "献立", "is_correct": false, "explanation": "献立は食事の計画で、会社の環境配慮を調べる文脈には合わない。"}], "explanations": {"ESG": "投資の判断で会社の環境・人・ルールを確かめる見方を表し、調べる対象として文に合う。", "天気": "天気は調べる対象として文脈に合わず、会社の環境配慮を見る文とはつながらない。", "宿題": "宿題は投資の判断と関係がなく、ここで調べるものとしては合わない。", "献立": "献立は食事の計画で、会社の環境配慮を調べる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "ESG"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場の ESG は、一日に千個です。", "explanation": "工場の生産量は生産能力で表すもので、ESG は投資の見方を指すので合わない。"}, {"text": "このお菓子は、ESG を確かめてから食べてください。", "explanation": "食べ物の期限は賞味期限で確かめ、ESG は投資の見方なので合わない。"}, {"text": "子どもの ESG が三十九度まで上がった。", "explanation": "体温の高さは熱で表し、ESG は数値として上がるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38332, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ESG", "is_correct": true, "explanation": "ESG の点数が高いという文に合い、会社の取り組みを評価する枠組みを表す。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉は植物の粉で、評価機関の文脈には合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の色で、評価機関の主語にはならない。"}, {"text": "交通費", "is_correct": false, "explanation": "交通費は移動の費用で、会社の取り組みを点数で比べる評価機関とはつながらない。"}], "explanations": {"ESG": "ESG の点数が高いという文に合い、会社の取り組みを評価する枠組みを表す。", "花粉": "花粉は植物の粉で、評価機関の文脈には合わない。", "夕焼け": "夕焼けは空の色で、評価機関の主語にはならない。", "交通費": "交通費は移動の費用で、会社の取り組みを点数で比べる評価機関とはつながらない。"}, "sentence_index": 6, "correct_answer": "ESG"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父の ESG は、高校生の頃から変わらない。", "explanation": "人の背の高さを表すので、ESG という投資の見方には使えない。"}, {"text": "祖父は今でも ESG を話す。", "explanation": "方言は話す言葉なので、ESG を話すとは言わない。"}, {"text": "夏休みに、ESG を捕まえた。", "explanation": "捕まえるのは虫などの生き物で、ESG は投資の考え方なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38332, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "多くの投資家が ESG を抑えている。", "corrected_sentence": "多くの投資家が ESG を重視している。", "error_description": "誤: 抑えている。正: 重視している。「ESG を重視する」が正しい組み合わせで、「抑える」は ESG と結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38332, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年金基金は ESG で基準に投資先を選んでいる。", "corrected_sentence": "年金基金は ESG を基準に投資先を選んでいる。", "error_description": "誤: ESG で基準に。正: ESG を基準に。「基準」の対象を示す「を」が必要で、「で」では ESG が基準の対象として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
