INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38333, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "環境（Environment）・社会（Social）・企業統治（Governance）の三つの要素を考慮した投資の考え方。", "primary_collocate": null, "pronunciation": "いーえすじー", "ipa": "iːesɯdʑiː", "syllable_count": 6, "sentences": [{"text": "ESG は、環境・社会・企業統治の三つを考える投資の考え方だ。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "ESG は、環境[かんきょう]・社会[しゃかい]・企業[きぎょう]統治[とうち]の三[みっ]つを考[かんが]える投資[とうし]の考[かんが]え方[かた]だ。", "sentence_source": "generated"}, {"text": "この会社は、ESG の報告書で二酸化炭素の削減目標を示した。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、ESG の報告書[ほうこくしょ]で二酸化炭素[にさんかたんそ]の削減[さくげん]目標[もくひょう]を示[しめ]した。", "sentence_source": "generated"}, {"text": "ESG のGは、会社が正しく運営されているかという企業統治を表す。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "ESG のGは、会社[かいしゃ]が正[ただ]しく運営[うんえい]されているかという企業[きぎょう]統治[とうち]を表[あらわ]す。", "sentence_source": "generated"}, {"text": "ESG を重視する運用会社が、石炭関連の株を手放した。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "ESG を重視[じゅうし]する運用[うんよう]会社[がいしゃ]が、石炭[せきたん]関連[かんれん]の株[かぶ]を手放[てばな]した。", "sentence_source": "generated"}, {"text": "ESG の観点から見ると、この企業は人権への配慮が足りない。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "ESG の観点[かんてん]から見[み]ると、この企業[きぎょう]は人権[じんけん]への配慮[はいりょ]が足[た]りない。", "sentence_source": "generated"}, {"text": "日本でも ESG を取り入れる機関投資家が年々増えている。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "日本[にほん]でも ESG を取[と]り入[い]れる機関[きかん]投資家[とうしか]が年々[ねんねん]増[ふ]えている。", "sentence_source": "generated"}, {"text": "ESG の評価機関は、各社の取り組みを点数で比べている。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "ESG の評価[ひょうか]機関[きかん]は、各社[かくしゃ]の取[と]り組[く]みを点数[てんすう]で比[くら]べている。", "sentence_source": "generated"}, {"text": "利益だけでなく ESG にも配慮することが、長期的な成長につながる。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "利益[りえき]だけでなく ESG にも配慮[はいりょ]することが、長期的[ちょうきてき]な成長[せいちょう]につながる。", "sentence_source": "generated"}, {"text": "新聞は、ESG の流れが世界の金融市場を変えていると伝えた。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "新聞[しんぶん]は、ESG の流[なが]れが世界[せかい]の金融[きんゆう]市場[しじょう]を変[か]えていると伝[つた]えた。", "sentence_source": "generated"}, {"text": "ESG の考え方は、企業の社会的責任という発想から広がった。", "target_word": "ESG", "complexity_tier": "T3", "furigana": "ESG の考[かんが]え方[かた]は、企業[きぎょう]の社会的[しゃかいてき]責任[せきにん]という発想[はっそう]から広[ひろ]がった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ESG", "label": "基本形"}], "register": "formal", "sense_fingerprint": "環境・社会・企業統治の三要素を考慮する投資の考え方・評価の枠組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1c8c83-1c1f-4ce4-8526-69429b5ec9c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38333, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ESG", "is_correct": true, "explanation": "環境・社会・企業統治の三つを考える投資の考え方を指し、文の主語として合う。"}, {"text": "座標", "is_correct": false, "explanation": "座標は位置を示す数値のことで、投資の考え方を説明する文には合わない。"}, {"text": "食卓", "is_correct": false, "explanation": "食卓は食事をする台のことで、投資の考え方を表す文とはつながらない。"}, {"text": "天候", "is_correct": false, "explanation": "天候は空模様のことで、三つの要素を考える投資の考え方とは関係がない。"}], "explanations": {"ESG": "環境・社会・企業統治の三つを考える投資の考え方を指し、文の主語として合う。", "座標": "座標は位置を示す数値のことで、投資の考え方を説明する文には合わない。", "食卓": "食卓は食事をする台のことで、投資の考え方を表す文とはつながらない。", "天候": "天候は空模様のことで、三つの要素を考える投資の考え方とは関係がない。"}, "sentence_index": 0, "correct_answer": "ESG"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この棚は、ESG を使って組み立てる。", "explanation": "組み立てる道具は工具で、ESG は投資の考え方なので道具として使えない。"}, {"text": "彼は夏休みの ESG を最後まで終えた。", "explanation": "終えるのは宿題や仕事で、ESG は投資の考え方なので合わない。"}, {"text": "鍋に ESG を入れる。", "explanation": "鍋に入れるのは食材で、ESG は料理の材料ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38333, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ESG", "is_correct": true, "explanation": "ESG の評価機関という文に合い、会社の取り組みを評価する枠組みを表す。"}, {"text": "砂時計", "is_correct": false, "explanation": "砂時計は時間を計る道具で、評価機関の文脈には合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の色で、評価機関の主語にはならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、会社の取り組みを点数で比べる評価機関とは関係がない。"}], "explanations": {"ESG": "ESG の評価機関という文に合い、会社の取り組みを評価する枠組みを表す。", "砂時計": "砂時計は時間を計る道具で、評価機関の文脈には合わない。", "夕焼け": "夕焼けは空の色で、評価機関の主語にはならない。", "冷蔵庫": "冷蔵庫は家電で、会社の取り組みを点数で比べる評価機関とは関係がない。"}, "sentence_index": 6, "correct_answer": "ESG"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この ESG は、若い頃の恋を描いた名曲だ。", "explanation": "名曲は歌に対して言うもので、ESG は投資の考え方なので合わない。"}, {"text": "家族で ESG に出かけた。", "explanation": "出かける先は温泉などの場所で、ESG は行き先になり得ないので合わない。"}, {"text": "コーヒーで ESG を覚ました。", "explanation": "覚ますのは眠気などの感覚で、ESG は投資の考え方なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38333, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "多くの企業が ESG を取り組んでいる。", "corrected_sentence": "多くの企業が ESG に取り組んでいる。", "error_description": "誤: ESG を取り組んでいる。正: ESG に取り組んでいる。「取り組む」は「に」で対象を示すので、「を」では不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38333, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい基準では、ESG を評価に加わる。", "corrected_sentence": "新しい基準では、ESG を評価に加える。", "error_description": "誤: 加わる。正: 加える。「ESG を評価に加える」は目的語を取る他動詞の形が必要で、「加わる」は自動詞なので「を」の目的語と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5beee8a2-c979-4209-a055-8059cb8b950b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38334, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「軸にする」の「に」。愛情を中心に据えて物語が進むという「〜を軸に」の用法に合う。"}, {"text": "を", "is_correct": false, "explanation": "「愛情を軸を物語が進む」は「を」が二つになり、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「軸が物語が進む」は「が」が二つになり不自然で、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「軸へ物語が進む」は方向を示すが、「〜を軸に」の用法に合わない。"}], "correct_answer": "に", "explanations": {"に": "「軸にする」の「に」。愛情を中心に据えて物語が進むという「〜を軸に」の用法に合う。", "を": "「愛情を軸を物語が進む」は「を」が二つになり、文が成り立たない。", "が": "「軸が物語が進む」は「が」が二つになり不自然で、文が成り立たない。", "へ": "「軸へ物語が進む」は方向を示すが、「〜を軸に」の用法に合わない。"}, "error_tags": {"を": "対象", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38334, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「軸のない」の「の」。「〜のない」で、軸を持たない政策を表す名詞修飾の形。"}, {"text": "に", "is_correct": false, "explanation": "「軸にない政策」は、「に」が名詞を修飾する形として成り立たず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「軸とない政策」は並列の形で、「ない」に続かず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「軸からない政策」は起点を示すが、否定の形に合わない。"}], "correct_answer": "の", "explanations": {"の": "「軸のない」の「の」。「〜のない」で、軸を持たない政策を表す名詞修飾の形。", "に": "「軸にない政策」は、「に」が名詞を修飾する形として成り立たず不自然。", "と": "「軸とない政策」は並列の形で、「ない」に続かず不自然。", "から": "「軸からない政策」は起点を示すが、否定の形に合わない。"}, "error_tags": {"に": "相手・対象", "と": "並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38334, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を考えるときや決めるときの、もとになる考えの線のこと。", "primary_collocate": null, "pronunciation": "じく", "ipa": "[dʑikɯ]", "syllable_count": 2, "sentences": [{"text": "迷ったときは、自分の軸に立ち返って決めることにしている。", "target_word": "軸", "complexity_tier": "T3", "furigana": "迷[まよ]ったときは、自分[じぶん]の軸[じく]に立[た]ち返[かえ]って決[き]めることにしている。", "sentence_source": "generated"}, {"text": "この小説は親子の愛情を軸に物語が進む。", "target_word": "軸", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は親子[おやこ]の愛情[あいじょう]を軸[じく]に物語[ものがたり]が進[すす]む。", "sentence_source": "generated"}, {"text": "彼女は軸のある人で、どんな状況でも考えを変えない。", "target_word": "軸", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は軸[じく]のある人[ひと]で、どんな状況[じょうきょう]でも考[かんが]えを変[か]えない。", "sentence_source": "generated"}, {"text": "議論の軸を最初にはっきりさせておこう。", "target_word": "軸", "complexity_tier": "T3", "furigana": "議論[ぎろん]の軸[じく]を最初[さいしょ]にはっきりさせておこう。", "sentence_source": "generated"}, {"text": "研究の軸が定まらず、先生に相談した。", "target_word": "軸", "complexity_tier": "T3", "furigana": "研究[けんきゅう]の軸[じく]が定[さだ]まらず、先生[せんせい]に相談[そうだん]した。", "sentence_source": "generated"}, {"text": "環境保護を軸にして、町の将来を考える。", "target_word": "軸", "complexity_tier": "T3", "furigana": "環境[かんきょう]保護[ほご]を軸[じく]にして、町[まち]の将来[しょうらい]を考[かんが]える。", "sentence_source": "generated"}, {"text": "判断の軸を一つ持つと、決めるのが楽になる。", "target_word": "軸", "complexity_tier": "T3", "furigana": "判断[はんだん]の軸[じく]を一[ひと]つ持[も]つと、決[き]めるのが楽[らく]になる。", "sentence_source": "generated"}, {"text": "軸のない政策では、市民の信頼は得られない。", "target_word": "軸", "complexity_tier": "T3", "furigana": "軸[じく]のない政策[せいさく]では、市民[しみん]の信頼[しんらい]は得[え]られない。", "sentence_source": "generated"}, {"text": "彼の意見はいつも軸がぶれていて、信用できない。", "target_word": "軸", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]はいつも軸[じく]がぶれていて、信用[しんよう]できない。", "sentence_source": "generated"}, {"text": "授業は「話す力」を軸に組み立てられている。", "target_word": "軸", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]は「話[はな]す力[ちから]」を軸[じく]に組[く]み立[た]てられている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "軸", "label": "基本形"}], "register": "書き言葉（普通体）", "sense_fingerprint": "考えや決定のもとになる一本の筋・方針（比喩的な軸）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 立ち返っ (Zipf 2.27)']::text[], 'babc5005-4b09-4076-ab17-d13e22e3c839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38334, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "軸", "is_correct": true, "explanation": "もとになる考えの線に立ち返って決める、という文脈に合う。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は考えに立ち返るものではなく、決める根拠にならない。"}, {"text": "原稿", "is_correct": false, "explanation": "原稿は書かれた文書で、立ち返って判断の根拠にする対象としては合わない。"}, {"text": "指輪", "is_correct": false, "explanation": "指輪は決める根拠にならず、立ち返る対象ではない。"}], "explanations": {"軸": "もとになる考えの線に立ち返って決める、という文脈に合う。", "椅子": "椅子は考えに立ち返るものではなく、決める根拠にならない。", "原稿": "原稿は書かれた文書で、立ち返って判断の根拠にする対象としては合わない。", "指輪": "指輪は決める根拠にならず、立ち返る対象ではない。"}, "sentence_index": 0, "correct_answer": "軸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "授業の前に、軸を配った。", "explanation": "ここは〈資料〉の意味。資料は配るものだが、軸は配るものではなく、もとになる考えの線を指すので合わない。"}, {"text": "試合のあと、コーチは選手に軸を渡した。", "explanation": "ここは〈バトン〉の意味。バトンは次の走者に渡すものだが、軸は渡すものではなく、もとになる考えの線を指すので合わない。"}, {"text": "登山道に軸を付けた。", "explanation": "ここは〈目印〉の意味。軸は道に付けるものではなく、考えの筋を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38334, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "軸", "is_correct": true, "explanation": "判断のもとになる考えの線を一つ持つ、という文脈に合う。"}, {"text": "財布", "is_correct": false, "explanation": "財布は判断を支える考えではなく、持つと決めやすくなる文脈に合わない。"}, {"text": "傘", "is_correct": false, "explanation": "傘は判断の根拠にならず、決めるのが楽になる理由にならない。"}, {"text": "歌", "is_correct": false, "explanation": "歌は判断の根拠にならず、持つと決めやすくなるとは言えない。"}], "explanations": {"軸": "判断のもとになる考えの線を一つ持つ、という文脈に合う。", "財布": "財布は判断を支える考えではなく、持つと決めやすくなる文脈に合わない。", "傘": "傘は判断の根拠にならず、決めるのが楽になる理由にならない。", "歌": "歌は判断の根拠にならず、持つと決めやすくなるとは言えない。"}, "sentence_index": 6, "correct_answer": "軸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本の最初に軸をつけた。", "explanation": "ここは〈目次〉の意味。目次は本の最初につけるものだが、軸は本に付けるものではなく、考えの線を指すので合わない。"}, {"text": "窓を開けて、軸を送った。", "explanation": "ここは〈合図〉の意味。知らせるために送るもので、軸は送るものではないので合わない。"}, {"text": "壁を白い軸に塗った。", "explanation": "ここは〈色〉の意味。塗る対象の色を指すもので、軸は壁を塗る材料ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38334, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "考えの軸を見失うないように、メモを残す。", "corrected_sentence": "考えの軸を見失わないように、メモを残す。", "error_description": "活用の誤り。「見失う」は五段動詞なので否定形は「見失わない」。「見失うない」は活用が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38334, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "軸に持って判断すると、ぶれにくくなる。", "corrected_sentence": "軸を持って判断すると、ぶれにくくなる。", "error_description": "助詞の誤り。「持つ」は持つ対象を「を」で示すので「軸を」が正しい。「軸に持つ」では軸が持つ相手になり、意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38335, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「軸がぶれる」の主語を示す。考えの軸が揺れないという意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「軸をぶれる」とは言わず、「ぶれる」は対象を取れないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「軸にぶれない」は不自然で、「ぶれる」は「に」を取らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「軸へぶれない」は方向を示すが、「ぶれる」の形に合わない。"}], "correct_answer": "が", "explanations": {"が": "「軸がぶれる」の主語を示す。考えの軸が揺れないという意味になる。", "を": "「軸をぶれる」とは言わず、「ぶれる」は対象を取れないので合わない。", "に": "「軸にぶれない」は不自然で、「ぶれる」は「に」を取らないので合わない。", "へ": "「軸へぶれない」は方向を示すが、「ぶれる」の形に合わない。"}, "error_tags": {"を": "対象", "に": "相手・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38335, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「軸が定まらず」の主語を示す。定まるのは軸なので「が」が正しい。"}, {"text": "と", "is_correct": false, "explanation": "「軸と定まらず」は、軸が何かと一緒に定まる意味になり、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「軸から定まらず」は起点を示すが、定まる主体が成り立たず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「軸の定まらず」は名詞に続く形として不完全で、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「軸が定まらず」の主語を示す。定まるのは軸なので「が」が正しい。", "と": "「軸と定まらず」は、軸が何かと一緒に定まる意味になり、文が成り立たない。", "から": "「軸から定まらず」は起点を示すが、定まる主体が成り立たず不自然。", "の": "「軸の定まらず」は名詞に続く形として不完全で、文が成り立たない。"}, "error_tags": {"と": "並列", "から": "起点", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38335, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を判断したり評価したりするときの基準や中心となる考え。", "primary_collocate": null, "pronunciation": "じく", "ipa": "[dʑikɯ]", "syllable_count": 2, "sentences": [{"text": "この件の判断の軸は、まだはっきりしていない。", "target_word": "軸", "complexity_tier": "T5", "furigana": "この件[けん]の判断[はんだん]の軸[じく]は、まだはっきりしていない。", "sentence_source": "generated"}, {"text": "彼は自分の考えの軸がぶれないので、周りに流されない。", "target_word": "軸", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の考[かんが]えの軸[じく]がぶれないので、周[まわ]りに流[なが]されない。", "sentence_source": "generated"}, {"text": "新しい制度を評価する軸として、公平さを最も重く見た。", "target_word": "軸", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]を評価[ひょうか]する軸[じく]として、公平[こうへい]さを最[もっと]も重[おも]く見[み]た。", "sentence_source": "generated"}, {"text": "私は仕事を選ぶとき、成長できるかどうかを軸にしている。", "target_word": "軸", "complexity_tier": "T3", "furigana": "私[わたし]は仕事[しごと]を選[えら]ぶとき、成長[せいちょう]できるかどうかを軸[じく]にしている。", "sentence_source": "generated"}, {"text": "判断の軸がないと、人の意見に振り回されてしまう。", "target_word": "軸", "complexity_tier": "T3", "furigana": "判断[はんだん]の軸[じく]がないと、人[ひと]の意見[いけん]に振[ふ]り回[まわ]されてしまう。", "sentence_source": "generated"}, {"text": "この会社は環境への配慮を経営の軸に据えている。", "target_word": "軸", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は環境[かんきょう]への配慮[はいりょ]を経営[けいえい]の軸[じく]に据[す]えている。", "sentence_source": "generated"}, {"text": "評価の軸が人によって違うので、議論がかみ合わなかった。", "target_word": "軸", "complexity_tier": "T3", "furigana": "評価[ひょうか]の軸[じく]が人[ひと]によって違[ちが]うので、議論[ぎろん]がかみ合[あ]わなかった。", "sentence_source": "generated"}, {"text": "話の軸が定まらず、会議は何度も脱線した。", "target_word": "軸", "complexity_tier": "T3", "furigana": "話[はなし]の軸[じく]が定[さだ]まらず、会議[かいぎ]は何度[なんど]も脱線[だっせん]した。", "sentence_source": "generated"}, {"text": "価格だけでなく品質も軸に入れて、商品を比べてみよう。", "target_word": "軸", "complexity_tier": "T3", "furigana": "価格[かかく]だけでなく品質[ひんしつ]も軸[じく]に入[い]れて、商品[しょうひん]を比[くら]べてみよう。", "sentence_source": "generated"}, {"text": "軸となる考え方を決めてから、計画を立てた。", "target_word": "軸", "complexity_tier": "T3", "furigana": "軸[じく]となる考[かんが]え方[かた]を決[き]めてから、計画[けいかく]を立[た]てた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "軸", "label": "基本形"}], "register": "書き言葉（普通体）", "sense_fingerprint": "判断や評価の基準・中心となる考え方（比喩的な軸）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babc5005-4b09-4076-ab17-d13e22e3c839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38335, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "軸", "is_correct": true, "explanation": "判断の拠り所となる考えの線を指し、「判断の軸」として文が成り立つ。"}, {"text": "椅子", "is_correct": false, "explanation": "判断の拠り所にならず、「判断の椅子」は意味が通らない。"}, {"text": "原稿", "is_correct": false, "explanation": "判断の基準にはならず、「判断の原稿」は成り立たない。"}, {"text": "指輪", "is_correct": false, "explanation": "判断の基準にはならず、「判断の指輪」は文が成り立たない。"}], "explanations": {"軸": "判断の拠り所となる考えの線を指し、「判断の軸」として文が成り立つ。", "椅子": "判断の拠り所にならず、「判断の椅子」は意味が通らない。", "原稿": "判断の基準にはならず、「判断の原稿」は成り立たない。", "指輪": "判断の基準にはならず、「判断の指輪」は文が成り立たない。"}, "sentence_index": 0, "correct_answer": "軸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の前に、出席者に軸を配った。", "explanation": "ここは〈名簿〉の意味。名簿は配るものだが、軸は配るものではなく、判断の基準となる考えを指すので合わない。"}, {"text": "壊れた自転車の軸を交換した。", "explanation": "ここは〈車軸〉の意味。回転する機械の部品を指し、判断の基準の意味では使わないので合わない。"}, {"text": "グラフの横の軸に月を書き入れた。", "explanation": "ここは〈座標軸〉の意味。目盛りの基準線を指し、判断の基準の意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38335, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "軸", "is_correct": true, "explanation": "評価の基準として人によって違うという、議論の食い違いの文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は評価の基準にはならず、人によって違うという文脈に合わない。"}, {"text": "靴", "is_correct": false, "explanation": "靴は評価の基準にならず、「評価の靴」は文が成り立たない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは評価の基準として文脈に合わず、議論のかみ合わなさの説明にならない。"}], "explanations": {"軸": "評価の基準として人によって違うという、議論の食い違いの文脈に合う。", "天気": "天気は評価の基準にはならず、人によって違うという文脈に合わない。", "靴": "靴は評価の基準にならず、「評価の靴」は文が成り立たない。", "香り": "香りは評価の基準として文脈に合わず、議論のかみ合わなさの説明にならない。"}, "sentence_index": 6, "correct_answer": "軸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅の掲示板に、軸を貼った。", "explanation": "ここは〈ポスター〉の意味。ポスターは掲示板に貼るものだが、軸は貼るものではなく、判断の基準となる考えを指すので合わない。"}, {"text": "家の軸をコンクリートで固めた。", "explanation": "ここは〈土台〉の意味。建物を支える基礎を指すが、軸は判断の基準を指すので固める対象にはならない。"}, {"text": "経済の状態を示す軸を発表した。", "explanation": "ここは〈指標〉の意味。数値などで状態を示すものを指し、軸は発表するものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38335, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "まず判断の軸が定めてから、話し合いを始めよう。", "corrected_sentence": "まず判断の軸を定めてから、話し合いを始めよう。", "error_description": "助詞の誤り。「定める」は決める対象を「を」で示すので「軸を」が正しい。「軸が」では軸が自ら定める主体になり、文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38335, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "判断の軸を持いていれば、迷いが減る。", "corrected_sentence": "判断の軸を持っていれば、迷いが減る。", "error_description": "活用の誤り。「持つ」の音便形は「持って」で、「持いて」は誤り。「持っていれば」と言う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
