INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38336, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「忘れる」は対象に「を」を取るので、「重みを」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「忘れる」は「が」で対象を示さないので、「重みが忘れないで」は文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「重みに」は方向や相手を表すが、「忘れる」の対象を示すには「を」が必要で合わない。"}, {"text": "から", "is_correct": false, "explanation": "「重みから」は起点を表し、「忘れる」の対象にはならないので文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「忘れる」は対象に「を」を取るので、「重みを」が正しい。", "が": "「忘れる」は「が」で対象を示さないので、「重みが忘れないで」は文が成り立たない。", "に": "「重みに」は方向や相手を表すが、「忘れる」の対象を示すには「を」が必要で合わない。", "から": "「重みから」は起点を表し、「忘れる」の対象にはならないので文に合わない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38336, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たいせつなこと。", "primary_collocate": null, "pronunciation": "おもみ", "ipa": "omomi", "syllable_count": 3, "sentences": [{"text": "命の重みを知ることは、とてもたいせつです。", "target_word": "重み", "complexity_tier": "T3", "furigana": "命[いのち]の重[おも]みを知[し]ることは、とてもたいせつです。", "sentence_source": "generated"}, {"text": "祖母の言葉には、長い人生が生んだ重みがある。", "target_word": "重み", "complexity_tier": "T3", "furigana": "祖母[そぼ]の言葉[ことば]には、長[なが]い人生[じんせい]が生[う]んだ重[おも]みがある。", "sentence_source": "generated"}, {"text": "約束の重みを考えて、軽い気持ちでは返事をしなかった。", "target_word": "重み", "complexity_tier": "T3", "furigana": "約束[やくそく]の重[おも]みを考[かんが]えて、軽[かる]い気持[きも]ちでは返事[へんじ]をしなかった。", "sentence_source": "generated"}, {"text": "彼は一つ一つの仕事の重みを感じながら、ていねいに働いた。", "target_word": "重み", "complexity_tier": "T3", "furigana": "彼[かれ]は一[ひと]つ一[ひと]つの仕事[しごと]の重[おも]みを感[かん]じながら、ていねいに働[はたら]いた。", "sentence_source": "generated"}, {"text": "小さな子どもにも、友だちとの約束の重みを教えたい。", "target_word": "重み", "complexity_tier": "T3", "furigana": "小[ちい]さな子[こ]どもにも、友[とも]だちとの約束[やくそく]の重[おも]みを教[おし]えたい。", "sentence_source": "generated"}, {"text": "この手紙には、家族の思いの重みがあるので、捨てられない。", "target_word": "重み", "complexity_tier": "T3", "furigana": "この手紙[てがみ]には、家族[かぞく]の思[おも]いの重[おも]みがあるので、捨[す]てられない。", "sentence_source": "generated"}, {"text": "自由には責任という重みがついてくる。", "target_word": "重み", "complexity_tier": "T3", "furigana": "自由[じゆう]には責任[せきにん]という重[おも]みがついてくる。", "sentence_source": "generated"}, {"text": "先生は「一度の失敗の重みを忘れないで」と言った。", "target_word": "重み", "complexity_tier": "T3", "furigana": "先生[せんせい]は「一度[いちど]の失敗[しっぱい]の重[おも]みを忘[わす]れないで」と言[い]った。", "sentence_source": "generated"}, {"text": "昔の写真を見ると、過ぎた時間の重みを感じる。", "target_word": "重み", "complexity_tier": "T3", "furigana": "昔[むかし]の写真[しゃしん]を見[み]ると、過[す]ぎた時間[じかん]の重[おも]みを感[かん]じる。", "sentence_source": "generated"}, {"text": "賞をもらった人の話には、努力の重みがあった。", "target_word": "重み", "complexity_tier": "T3", "furigana": "賞[しょう]をもらった人[ひと]の話[はなし]には、努力[どりょく]の重[おも]みがあった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重み", "label": "基本形"}, {"form": "重みが", "label": "主格"}, {"form": "重みを", "label": "目的格"}, {"form": "重みのある", "label": "連体形"}], "register": "一般", "sense_fingerprint": "命・約束・言葉などが持つ、軽く扱えないたいせつさ（価値の重さ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97a8239-3cf4-4e80-8342-64a5a5f3c741') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38336, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重み", "is_correct": true, "explanation": "ここは「命の重み」として、命の大切さを表す名詞。文脈に合う。"}, {"text": "順番", "is_correct": false, "explanation": "「命の順番を知る」は文として成り立たない。順序を表す語で、大切さの文には入らない。"}, {"text": "天気", "is_correct": false, "explanation": "「命の天気を知る」は意味をなさない。空模様を表す語で、ここは合わない。"}, {"text": "手順", "is_correct": false, "explanation": "「命の手順を知る」は不自然。作業の順序を表す語で、命の大切さを述べる文には合わない。"}], "explanations": {"重み": "ここは「命の重み」として、命の大切さを表す名詞。文脈に合う。", "順番": "「命の順番を知る」は文として成り立たない。順序を表す語で、大切さの文には入らない。", "天気": "「命の天気を知る」は意味をなさない。空模様を表す語で、ここは合わない。", "手順": "「命の手順を知る」は不自然。作業の順序を表す語で、命の大切さを述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "重み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この授業は説明に重みを置いて進める。", "explanation": "ここは〈重点〉の意味。力を入れる所は「重点を置く」と言うので、重みを置くとは言わない。"}, {"text": "この本は重みが五センチある。", "explanation": "ここは〈厚み〉の意味。重みは厚さを表さないので、厚さを述べるこの文には合わない。"}, {"text": "この山の重みは三千メートルある。", "explanation": "ここは〈高さ〉の意味。重みは標高を表さないので、高さを述べるこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38336, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重み", "is_correct": true, "explanation": "ここは責任の重さ、つまり重大さを表す「重み」。文に合う。"}, {"text": "季節", "is_correct": false, "explanation": "「責任という季節がついてくる」は意味をなさない。時期を表す語で、ここは合わない。"}, {"text": "星座", "is_correct": false, "explanation": "「責任という星座がついてくる」は意味をなさない。天体の名称で、ここは合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「責任という夕焼けがついてくる」は文として成り立たない。空に見える現象の名称で、ここには入らない。"}], "explanations": {"重み": "ここは責任の重さ、つまり重大さを表す「重み」。文に合う。", "季節": "「責任という季節がついてくる」は意味をなさない。時期を表す語で、ここは合わない。", "星座": "「責任という星座がついてくる」は意味をなさない。天体の名称で、ここは合わない。", "夕焼け": "「責任という夕焼けがついてくる」は文として成り立たない。空に見える現象の名称で、ここには入らない。"}, "sentence_index": 6, "correct_answer": "重み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この車の重みは時速百キロも出た。", "explanation": "ここは〈速さ〉の意味。重みは速度を表さないので、速さを述べるこの文には合わない。"}, {"text": "この部屋は重みが明るいので、電気がいらない。", "explanation": "ここは〈明るさ〉の意味。重みは光の度合いを表さないので、明るさを述べるこの文には合わない。"}, {"text": "この庭の重みは十坪ある。", "explanation": "ここは〈広さ〉の意味。重みは面積を表さないので、広さを述べるこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38336, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちとの約束の重みに忘れずに、時間を守った。", "corrected_sentence": "友だちとの約束の重みを忘れずに、時間を守った。", "error_description": "「忘れる」は「を」を取る。「重みに」は誤りで、正しくは「重みを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38336, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その言葉の重みへ増して、会議が静かになった。", "corrected_sentence": "その言葉の重みが増して、会議が静かになった。", "error_description": "「増す」は「が」を取る。「重みへ」は誤りで、正しくは「重みが」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38337, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「重み」の後の「が」は「ある」の主語を示す。ここで正しい。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らないので、「重みを」に続けると文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「重みと」は並列を表すが、「ある」と結びつかず文が完成しない。"}, {"text": "から", "is_correct": false, "explanation": "「重みから」は起点を表し、「ある」と続けても意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「重み」の後の「が」は「ある」の主語を示す。ここで正しい。", "を": "「ある」は目的語を取らないので、「重みを」に続けると文が成り立たない。", "と": "「重みと」は並列を表すが、「ある」と結びつかず文が完成しない。", "から": "「重みから」は起点を表し、「ある」と続けても意味が通らない。"}, "error_tags": {"を": "目的語", "と": "相手・並列", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38337, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "「重みも」は、言葉の重みも弱くなると添える。文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「重みを弱くなる」は文が成り立たない。「弱くなる」は主語を取る。"}, {"text": "に", "is_correct": false, "explanation": "「重みに」は方向・結果を表すが、「弱くなる」と結びつかず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「重みと」は並列を表すが、「弱くなる」とは続かないので文脈に合わない。"}], "correct_answer": "も", "explanations": {"も": "「重みも」は、言葉の重みも弱くなると添える。文に合う。", "を": "「重みを弱くなる」は文が成り立たない。「弱くなる」は主語を取る。", "に": "「重みに」は方向・結果を表すが、「弱くなる」と結びつかず不自然。", "と": "「重みと」は並列を表すが、「弱くなる」とは続かないので文脈に合わない。"}, "error_tags": {"を": "目的語", "に": "方向・結果", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38337, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "重要性や影響力の度合い。", "primary_collocate": null, "pronunciation": "おもみ", "ipa": "omomi", "syllable_count": 3, "sentences": [{"text": "社長の発言は、ほかの社員よりも重みがある。", "target_word": "重み", "complexity_tier": "T3", "furigana": "社長[しゃちょう]の発言[はつげん]は、ほかの社員[しゃいん]よりも重[おも]みがある。", "sentence_source": "generated"}, {"text": "専門家の意見には重みがあるので、みんなが耳を傾けた。", "target_word": "重み", "complexity_tier": "T3", "furigana": "専門家[せんもんか]の意見[いけん]には重[おも]みがあるので、みんなが耳[みみ]を傾[かたむ]けた。", "sentence_source": "generated"}, {"text": "彼は新人なので、会議での発言の重みがまだ小さい。", "target_word": "重み", "complexity_tier": "T3", "furigana": "彼[かれ]は新人[しんじん]なので、会議[かいぎ]での発言[はつげん]の重[おも]みがまだ小[ちい]さい。", "sentence_source": "generated"}, {"text": "一票の重みは、どの人でも同じです。", "target_word": "重み", "complexity_tier": "T3", "furigana": "一票[いっぴょう]の重[おも]みは、どの人[ひと]でも同[おな]じです。", "sentence_source": "generated"}, {"text": "有名な先生がほめたことで、この本の評価に重みが増した。", "target_word": "重み", "complexity_tier": "T3", "furigana": "有名[ゆうめい]な先生[せんせい]がほめたことで、この本[ほん]の評価[ひょうか]に重[おも]みが増[ま]した。", "sentence_source": "generated"}, {"text": "この条件は点数への重みが大きいから、先に準備しよう。", "target_word": "重み", "complexity_tier": "T3", "furigana": "この条件[じょうけん]は点数[てんすう]への重[おも]みが大[おお]きいから、先[さき]に準備[じゅんび]しよう。", "sentence_source": "generated"}, {"text": "実績のある人が言うと、同じ言葉でも重みが違う。", "target_word": "重み", "complexity_tier": "T3", "furigana": "実績[じっせき]のある人[ひと]が言[い]うと、同[おな]じ言葉[ことば]でも重[おも]みが違[ちが]う。", "sentence_source": "generated"}, {"text": "投票率が低いと、選ばれた人の言葉の重みも弱くなる。", "target_word": "重み", "complexity_tier": "T3", "furigana": "投票率[とうひょうりつ]が低[ひく]いと、選[えら]ばれた人[ひと]の言葉[ことば]の重[おも]みも弱[よわ]くなる。", "sentence_source": "generated"}, {"text": "証拠が加わって、彼女の説明に重みが出てきた。", "target_word": "重み", "complexity_tier": "T3", "furigana": "証拠[しょうこ]が加[くわ]わって、彼女[かのじょ]の説明[せつめい]に重[おも]みが出[で]てきた。", "sentence_source": "generated"}, {"text": "試験では、作文に重みがあるので、いちばん時間をかけて書いた。", "target_word": "重み", "complexity_tier": "T3", "furigana": "試験[しけん]では、作文[さくぶん]に重[おも]みがあるので、いちばん時間[じかん]をかけて書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重み", "label": "基本形"}, {"form": "重みが", "label": "主格"}, {"form": "重みを", "label": "目的格"}, {"form": "重みの", "label": "連体格"}], "register": "一般", "sense_fingerprint": "発言・意見・条件などが持つ、重要さや影響力の大きさの度合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97a8239-3cf4-4e80-8342-64a5a5f3c741') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38337, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重み", "is_correct": true, "explanation": "ここは発言の影響力の度合いを表す「重み」。文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「発言に天気がある」は意味をなさない。空模様を表す語で、ここは合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「発言に季節がある」は不自然で、影響力の比較を述べる文には入らない。"}, {"text": "手順", "is_correct": false, "explanation": "「発言に手順がある」は作業の順序を表す語で、発言の影響力を述べる文には合わない。"}], "explanations": {"重み": "ここは発言の影響力の度合いを表す「重み」。文に合う。", "天気": "「発言に天気がある」は意味をなさない。空模様を表す語で、ここは合わない。", "季節": "「発言に季節がある」は不自然で、影響力の比較を述べる文には入らない。", "手順": "「発言に手順がある」は作業の順序を表す語で、発言の影響力を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "重み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は重みが深く、とてもおいしい。", "explanation": "ここは〈深み〉の意味。味わいの奥行きは「深み」と言い、重みは大切さの度合いなので、料理の味を述べるこの文には合わない。"}, {"text": "この山の重みは千メートルある。", "explanation": "ここは〈高さ〉の意味。重みは標高を表さないので、高さを述べるこの文には合わない。"}, {"text": "この会の重みは三十人だった。", "explanation": "ここは〈人数〉の意味。重みは人の数を表さないので、人数を述べるこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38337, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重み", "is_correct": true, "explanation": "ここは言葉の影響力や説得力の度合いを表す「重み」。文に合う。"}, {"text": "星座", "is_correct": false, "explanation": "「同じ言葉でも星座が違う」は意味をなさない。天体の名称で、ここは合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「同じ言葉でも夕焼けが違う」は意味をなさない。空に見える現象で、言葉の説得力には入らない。"}, {"text": "段差", "is_correct": false, "explanation": "「同じ言葉でも段差が違う」は文として成り立たない。道の高低差を表す語で、ここには入らない。"}], "explanations": {"重み": "ここは言葉の影響力や説得力の度合いを表す「重み」。文に合う。", "星座": "「同じ言葉でも星座が違う」は意味をなさない。天体の名称で、ここは合わない。", "夕焼け": "「同じ言葉でも夕焼けが違う」は意味をなさない。空に見える現象で、言葉の説得力には入らない。", "段差": "「同じ言葉でも段差が違う」は文として成り立たない。道の高低差を表す語で、ここには入らない。"}, "sentence_index": 6, "correct_answer": "重み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この車は重みが時速百キロ出た。", "explanation": "ここは〈速さ〉の意味。重みは速度を表さないので、速さを述べるこの文には合わない。"}, {"text": "この部屋の重みは明るく、電気がいらない。", "explanation": "ここは〈明るさ〉の意味。重みは光の度合いを表さないので、明るさを述べるこの文には合わない。"}, {"text": "この庭の重みは十坪ある。", "explanation": "ここは〈広さ〉の意味。重みは面積を表さないので、広さを述べるこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38337, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生の助言の重みが、生徒たちはよく理解した。", "corrected_sentence": "先生の助言の重みを、生徒たちはよく理解した。", "error_description": "「理解する」は「を」を取る。「重みが」は誤りで、正しくは「重みを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38337, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その言葉の重みへ増して、会議が静かになった。", "corrected_sentence": "その言葉の重みが増して、会議が静かになった。", "error_description": "「増す」は「が」を取る。「重みへ」は誤りで、正しくは「重みが」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38338, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「誘致に成功する」の「に」。成功する対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「成功する」は「に」を取るので、「誘致を成功して」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、成功の対象には使わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「誘致と成功して」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「誘致に成功する」の「に」。成功する対象を示す。", "を": "「成功する」は「に」を取るので、「誘致を成功して」は不自然。", "へ": "「へ」は方向を表すが、成功の対象には使わない。", "と": "「と」は並列や相手を示すが、「誘致と成功して」は意味が通らない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "と": "並列・相手の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38338, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「工場を誘致した」の「を」。誘致の対象である工場を示す。"}, {"text": "が", "is_correct": false, "explanation": "「工場が誘致した」では工場が誘致する主体になり、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「工場の誘致した」は文として続かない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「工場と誘致した」は誘致の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「工場を誘致した」の「を」。誘致の対象である工場を示す。", "が": "「工場が誘致した」では工場が誘致する主体になり、意味が通らない。", "の": "「工場の誘致した」は文として続かない。", "と": "「と」は並列や相手を示すが、「工場と誘致した」は誘致の対象にならない。"}, "error_tags": {"が": "主語の誤り", "の": "連体修飾の誤り", "と": "並列・相手の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38338, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や会社を、ある場所に来るようにすること。", "primary_collocate": null, "pronunciation": "ゆうち", "ipa": "jɯːtɕi", "syllable_count": 3, "sentences": [{"text": "市は新しい工場を誘致するために、土地を安く貸すことにした。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "市[し]は新[あたら]しい工場[こうじょう]を誘致[ゆうち]するために、土地[とち]を安[やす]く貸[か]すことにした。", "sentence_source": "generated"}, {"text": "町は大きな会社の誘致に成功して、働く場所が増えた。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "町[まち]は大[おお]きな会社[かいしゃ]の誘致[ゆうち]に成功[せいこう]して、働[はたら]く場所[ばしょ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "駅の近くに大学を誘致する計画が、市議会で話し合われた。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに大学[だいがく]を誘致[ゆうち]する計画[けいかく]が、市議会[しぎかい]で話[はな]し合[あ]われた。", "sentence_source": "generated"}, {"text": "人口が減っているので、村は若い家族の誘致に力を入れている。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "人口[じんこう]が減[へ]っているので、村[むら]は若[わか]い家族[かぞく]の誘致[ゆうち]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "税金を安くしたのに、会社の誘致はなかなかうまくいかなかった。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "税金[ぜいきん]を安[やす]くしたのに、会社[かいしゃ]の誘致[ゆうち]はなかなかうまくいかなかった。", "sentence_source": "generated"}, {"text": "知事は外国の企業を誘致するため、毎年海外へ出かけている。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "知事[ちじ]は外国[がいこく]の企業[きぎょう]を誘致[ゆうち]するため、毎年[まいとし]海外[かいがい]へ出[で]かけている。", "sentence_source": "generated"}, {"text": "病院の誘致を求める住民が、署名を集めて市に出した。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "病院[びょういん]の誘致[ゆうち]を求[もと]める住民[じゅうみん]が、署名[しょめい]を集[あつ]めて市[し]に出[だ]した。", "sentence_source": "generated"}, {"text": "工場を誘致した結果、町には新しい店やアパートが増えた。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "工場[こうじょう]を誘致[ゆうち]した結果[けっか]、町[まち]には新[あたら]しい店[みせ]やアパートが増[ふ]えた。", "sentence_source": "generated"}, {"text": "誘致に反対する人もいたが、市長は計画を進めた。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "誘致[ゆうち]に反対[はんたい]する人[ひと]もいたが、市長[しちょう]は計画[けいかく]を進[すす]めた。", "sentence_source": "generated"}, {"text": "研究所を誘致することは決まったが、場所はまだ決まっていない。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "研究所[けんきゅうじょ]を誘致[ゆうち]することは決[き]まったが、場所[ばしょ]はまだ決[き]まっていない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "誘致", "label": "基本形"}, {"form": "誘致する", "label": "辞書形"}, {"form": "誘致した", "label": "過去形"}, {"form": "誘致して", "label": "て形"}, {"form": "誘致される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "自治体などが、会社・施設・人をある土地に来させること（する名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c92b57b-6e70-433b-a166-7450a2630a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38338, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "誘致", "is_correct": true, "explanation": "「工場を誘致する」は、工場を地域に来させるという意味で、空欄に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "「工場を翻訳する」は成り立たない。翻訳は言葉を別の言語に移すことで、工場は対象にならない。"}, {"text": "採点", "is_correct": false, "explanation": "「工場を採点する」は不自然。採点は答案などに点数をつけることで、工場には使わない。"}, {"text": "演奏", "is_correct": false, "explanation": "「工場を演奏する」は意味が通らない。演奏は楽器や曲を奏でることで、工場は対象にならない。"}], "explanations": {"誘致": "「工場を誘致する」は、工場を地域に来させるという意味で、空欄に合う。", "翻訳": "「工場を翻訳する」は成り立たない。翻訳は言葉を別の言語に移すことで、工場は対象にならない。", "採点": "「工場を採点する」は不自然。採点は答案などに点数をつけることで、工場には使わない。", "演奏": "「工場を演奏する」は意味が通らない。演奏は楽器や曲を奏でることで、工場は対象にならない。"}, "sentence_index": 0, "correct_answer": "誘致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "係員が来場者を出口へ誘致した。", "explanation": "ここは〈誘導〉の意味。誘致は人や会社をある場所に来させる意味で、出口へ導く場面には使わない。"}, {"text": "新入生を部活に誘致するため、先輩がビラを配った。", "explanation": "ここは〈勧誘〉の意味。誘致は地域や企業などを対象に来させる言い方で、個人を仲間に誘うときには使わない。"}, {"text": "寝不足が頭痛を誘致する。", "explanation": "ここは〈誘発〉の意味。誘致は人や会社を来させる意味で、頭痛などを引き起こす意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38338, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誘致", "is_correct": true, "explanation": "「病院の誘致を求める」は、病院を地域に来させるよう求める意味で、空欄に合う。"}, {"text": "暗記", "is_correct": false, "explanation": "「病院の暗記を求める」は意味が通らない。暗記は内容を覚えることで、病院は対象にならない。"}, {"text": "操縦", "is_correct": false, "explanation": "「病院の操縦を求める」は不自然。操縦は機械や乗り物を動かすことで、病院には使わない。"}, {"text": "点火", "is_correct": false, "explanation": "「病院の点火を求める」は成り立たない。点火は火をつけることで、病院は対象にならない。"}], "explanations": {"誘致": "「病院の誘致を求める」は、病院を地域に来させるよう求める意味で、空欄に合う。", "暗記": "「病院の暗記を求める」は意味が通らない。暗記は内容を覚えることで、病院は対象にならない。", "操縦": "「病院の操縦を求める」は不自然。操縦は機械や乗り物を動かすことで、病院には使わない。", "点火": "「病院の点火を求める」は成り立たない。点火は火をつけることで、病院は対象にならない。"}, "sentence_index": 6, "correct_answer": "誘致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "甘い言葉で若者を誘致して、高額な商品を売った。", "explanation": "ここは〈誘惑〉の意味。誘致は人や会社を来させる意味で、相手の心を惑わせる意味はない。"}, {"text": "大雨が災害を誘致した。", "explanation": "ここは〈招く〉の意味。誘致は人や会社を来させる意味で、災害のような望ましくない事態を引き起こす言い方には合わない。"}, {"text": "夜道で子どもを誘致して、連れ去った。", "explanation": "ここは〈誘拐〉の意味。誘致は場所や組織に来させる言い方で、人を連れ去る行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38338, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "県は海外の企業の誘致を成功して、雇用が増えた。", "corrected_sentence": "県は海外の企業の誘致に成功して、雇用が増えた。", "error_description": "「成功する」は「〜に成功する」の形で使う。誤りは「誘致を」の「を」で、正しくは「誘致に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38338, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は大型店を誘致する、駅前がにぎやかになった。", "corrected_sentence": "市は大型店を誘致して、駅前がにぎやかになった。", "error_description": "「誘致する」は終止形なので、後ろに文を続けるには「誘致して」（て形）が必要。誤りは「する」で、正しくは「して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38339, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「誘致に力を入れる」の「に」。力を入れる対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「誘致が力を入れる」では主語と動詞が合わない。"}, {"text": "の", "is_correct": false, "explanation": "「誘致の、広告を出して」は文として続かない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「力を入れる」の対象にはならない。"}], "correct_answer": "に", "explanations": {"に": "「誘致に力を入れる」の「に」。力を入れる対象を示す。", "が": "「誘致が力を入れる」では主語と動詞が合わない。", "の": "「誘致の、広告を出して」は文として続かない。", "から": "「から」は起点を示すが、「力を入れる」の対象にはならない。"}, "error_tags": {"が": "主語の誤り", "の": "連体修飾の誤り", "から": "起点の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38339, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38339, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "企業や観光客などを特定の地域に引き寄せること。", "primary_collocate": null, "pronunciation": "ゆうち", "ipa": "jɯːtɕi", "syllable_count": 3, "sentences": [{"text": "観光客を誘致するために、町は桜祭りを毎年開いている。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]を誘致[ゆうち]するために、町[まち]は桜祭[さくらまつ]りを毎年[まいとし]開[ひら]いている。", "sentence_source": "generated"}, {"text": "県は海外からの観光客の誘致に、広告を出して力を入れている。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "県[けん]は海外[かいがい]からの観光客[かんこうきゃく]の誘致[ゆうち]に、広告[こうこく]を出[だ]して力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "地方の町は、新しい企業を誘致して、若い人の仕事を作ろうとしている。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "地方[ちほう]の町[まち]は、新[あたら]しい企業[きぎょう]を誘致[ゆうち]して、若[わか]い人[ひと]の仕事[しごと]を作[つく]ろうとしている。", "sentence_source": "generated"}, {"text": "温泉地は外国人客を誘致するため、案内板を英語でも書いた。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "温泉地[おんせんち]は外国人客[がいこくじんきゃく]を誘致[ゆうち]するため、案内板[あんないばん]を英語[えいご]でも書[か]いた。", "sentence_source": "generated"}, {"text": "企業の誘致が進み、この地域の経済は少しずつよくなった。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "企業[きぎょう]の誘致[ゆうち]が進[すす]み、この地域[ちいき]の経済[けいざい]は少[すこ]しずつよくなった。", "sentence_source": "generated"}, {"text": "空港ができたことで、海外の企業の誘致もしやすくなった。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "空港[くうこう]ができたことで、海外[かいがい]の企業[きぎょう]の誘致[ゆうち]もしやすくなった。", "sentence_source": "generated"}, {"text": "市は大型ショッピングモールを誘致し、周辺の道路も新しくした。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "市[し]は大型[おおがた]ショッピングモールを誘致[ゆうち]し、周辺[しゅうへん]の道路[どうろ]も新[あたら]しくした。", "sentence_source": "generated"}, {"text": "雪が少ない年は、スキー客の誘致が難しくなる。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "雪[ゆき]が少[すく]ない年[とし]は、スキー客[きゃく]の誘致[ゆうち]が難[むずか]しくなる。", "sentence_source": "generated"}, {"text": "観光客を誘致しても、宿が足りなければ意味がない。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]を誘致[ゆうち]しても、宿[やど]が足[た]りなければ意味[いみ]がない。", "sentence_source": "generated"}, {"text": "町長は新しい会社を誘致したいと考えて、補助金の制度を作った。", "target_word": "誘致", "complexity_tier": "T3", "furigana": "町長[ちょうちょう]は新[あたら]しい会社[かいしゃ]を誘致[ゆうち]したいと考[かんが]えて、補助金[ほじょきん]の制度[せいど]を作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "誘致", "label": "基本形"}, {"form": "誘致する", "label": "辞書形"}, {"form": "誘致した", "label": "過去形"}, {"form": "誘致して", "label": "て形"}, {"form": "誘致される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "地域の活性化のため、企業や観光客を呼び込み引き寄せること（する名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c92b57b-6e70-433b-a166-7450a2630a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38339, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "誘致", "is_correct": true, "explanation": "「観光客を誘致する」は、観光客を町に来させる意味で、空欄に合う。"}, {"text": "暗記", "is_correct": false, "explanation": "「観光客を暗記する」は成り立たない。暗記は内容を覚えることで、人は対象にならない。"}, {"text": "作曲", "is_correct": false, "explanation": "「観光客を作曲する」は意味が通らない。作曲は曲を作ることで、人は対象にならない。"}, {"text": "点火", "is_correct": false, "explanation": "「観光客を点火する」は成り立たない。点火は火をつけることで、人は対象にならない。"}], "explanations": {"誘致": "「観光客を誘致する」は、観光客を町に来させる意味で、空欄に合う。", "暗記": "「観光客を暗記する」は成り立たない。暗記は内容を覚えることで、人は対象にならない。", "作曲": "「観光客を作曲する」は意味が通らない。作曲は曲を作ることで、人は対象にならない。", "点火": "「観光客を点火する」は成り立たない。点火は火をつけることで、人は対象にならない。"}, "sentence_index": 0, "correct_answer": "誘致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "非常時には係員が来場者を非常口へ誘致する。", "explanation": "ここは〈誘導〉の意味。誘致は人や会社をある場所に来させる意味で、非常口へ導く場面には使わない。"}, {"text": "薬の副作用が発疹を誘致することもある。", "explanation": "ここは〈誘発〉の意味。誘致は来させる意味で、発疹などを引き起こす意味では使えない。"}, {"text": "甘い言葉で若者を誘致し、高額な契約を結ばせた。", "explanation": "ここは〈誘惑〉の意味。誘致は場所や組織に来させる言い方で、相手を惑わせて契約させる意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38339, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誘致", "is_correct": true, "explanation": "「大型ショッピングモールを誘致し」は、モールを地域に来させる意味で、空欄に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "「大型ショッピングモールを翻訳し」は成り立たない。翻訳は言葉を移すことで、建物は対象にならない。"}, {"text": "採点", "is_correct": false, "explanation": "「大型ショッピングモールを採点し」は不自然。採点は答案などに点数をつけることで、建物には使わない。"}, {"text": "演奏", "is_correct": false, "explanation": "「大型ショッピングモールを演奏し」は意味が通らない。演奏は楽器や曲を奏でることで、建物は対象にならない。"}], "explanations": {"誘致": "「大型ショッピングモールを誘致し」は、モールを地域に来させる意味で、空欄に合う。", "翻訳": "「大型ショッピングモールを翻訳し」は成り立たない。翻訳は言葉を移すことで、建物は対象にならない。", "採点": "「大型ショッピングモールを採点し」は不自然。採点は答案などに点数をつけることで、建物には使わない。", "演奏": "「大型ショッピングモールを演奏し」は意味が通らない。演奏は楽器や曲を奏でることで、建物は対象にならない。"}, "sentence_index": 6, "correct_answer": "誘致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "油断が事故を誘致した。", "explanation": "ここは〈招く〉の意味。誘致は人や会社を来させる意味で、事故を引き起こす言い方には合わない。"}, {"text": "新しい会員を誘致するため、説明会を開いた。", "explanation": "ここは〈勧誘〉の意味。誘致は地域や企業を対象に来させる言い方で、個人を会員に誘うときには使わない。"}, {"text": "夜道で子どもを誘致して、連れ去った。", "explanation": "ここは〈誘拐〉の意味。誘致は場所や組織に来させる言い方で、人を連れ去る行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38339, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町は外国人客の誘致を成功して、ホテルが増えた。", "corrected_sentence": "町は外国人客の誘致に成功して、ホテルが増えた。", "error_description": "「成功する」は「〜に成功する」の形で使う。誤りは「誘致を」の「を」で、正しくは「誘致に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38339, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "県は観光客を誘致する、宿が増えた。", "corrected_sentence": "県は観光客を誘致して、宿が増えた。", "error_description": "「誘致する」は終止形なので、後ろに文を続けるには「誘致して」（て形）が必要。誤りは「する」で、正しくは「して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38340, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38340, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「恐竜の生存」で、恐竜が生きているという対象を示し、文が通る。"}, {"text": "を", "is_correct": false, "explanation": "「恐竜を生存について」と言うと、恐竜を目的語にする形で文が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "「恐竜で生存について」は手段の意味になり、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「恐竜へ生存について」は方向を示すが、文の意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「恐竜の生存」で、恐竜が生きているという対象を示し、文が通る。", "を": "「恐竜を生存について」と言うと、恐竜を目的語にする形で文が崩れる。", "で": "「恐竜で生存について」は手段の意味になり、不自然。", "へ": "「恐竜へ生存について」は方向を示すが、文の意味が通らない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38340, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生き続けること。", "primary_collocate": null, "pronunciation": "せいぞん", "ipa": "seizoɴ", "syllable_count": 4, "sentences": [{"text": "事故のあと、行方不明の男性の生存が確認された。", "target_word": "生存", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、行方不明[ゆくえふめい]の男性[だんせい]の生存[せいぞん]が確認[かくにん]された。", "sentence_source": "generated"}, {"text": "動物は水と食べ物がなければ生存できない。", "target_word": "生存", "complexity_tier": "T3", "furigana": "動物[どうぶつ]は水[みず]と食[た]べ物[もの]がなければ生存[せいぞん]できない。", "sentence_source": "generated"}, {"text": "医師は、患者の生存に希望を持っている。", "target_word": "生存", "complexity_tier": "T3", "furigana": "医師[いし]は、患者[かんじゃ]の生存[せいぞん]に希望[きぼう]を持[も]っている。", "sentence_source": "generated"}, {"text": "その鳥は山の奥で今も生存している。", "target_word": "生存", "complexity_tier": "T3", "furigana": "その鳥[とり]は山[やま]の奥[おく]で今[いま]も生存[せいぞん]している。", "sentence_source": "generated"}, {"text": "生存の条件は、水と空気と食べ物だ。", "target_word": "生存", "complexity_tier": "T3", "furigana": "生存[せいぞん]の条件[じょうけん]は、水[みず]と空気[くうき]と食[た]べ物[もの]だ。", "sentence_source": "generated"}, {"text": "地震から三日後、一人の生存が分かった。", "target_word": "生存", "complexity_tier": "T3", "furigana": "地震[じしん]から三日後[みっかご]、一人[ひとり]の生存[せいぞん]が分[わ]かった。", "sentence_source": "generated"}, {"text": "この魚の生存には、きれいな水が必要だ。", "target_word": "生存", "complexity_tier": "T3", "furigana": "この魚[さかな]の生存[せいぞん]には、きれいな水[みず]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "古い本に、恐竜の生存について書いてあった。", "target_word": "生存", "complexity_tier": "T3", "furigana": "古[ふる]い本[ほん]に、恐竜[きょうりゅう]の生存[せいぞん]について書[か]いてあった。", "sentence_source": "generated"}, {"text": "彼の生存を信じて、家族は待ち続けた。", "target_word": "生存", "complexity_tier": "T3", "furigana": "彼[かれ]の生存[せいぞん]を信[しん]じて、家族[かぞく]は待[ま]ち続[つづ]けた。", "sentence_source": "generated"}, {"text": "生存の可能性は低いと、医者は話した。", "target_word": "生存", "complexity_tier": "T3", "furigana": "生存[せいぞん]の可能性[かのうせい]は低[ひく]いと、医者[いしゃ]は話[はな]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生存", "label": "基本形"}, {"form": "生存する", "label": "サ変動詞"}, {"form": "生存している", "label": "ている形"}], "register": "neutral", "sense_fingerprint": "人や生き物が生きて存在し続けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8104bb-358f-42db-9a79-a76080280153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38340, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生存", "is_correct": true, "explanation": "行方不明の男性が生きていたかどうかが確認された、という意味に合う。"}, {"text": "運賃", "is_correct": false, "explanation": "運賃は確認の対象にならず、男性の話として不自然。"}, {"text": "時給", "is_correct": false, "explanation": "「男性の時給が確認された」は意味をなさず、生死の話にならない。"}, {"text": "寝癖", "is_correct": false, "explanation": "寝癖が確認されたという文は、行方不明の話に合わない。"}], "explanations": {"生存": "行方不明の男性が生きていたかどうかが確認された、という意味に合う。", "運賃": "運賃は確認の対象にならず、男性の話として不自然。", "時給": "「男性の時給が確認された」は意味をなさず、生死の話にならない。", "寝癖": "寝癖が確認されたという文は、行方不明の話に合わない。"}, "sentence_index": 0, "correct_answer": "生存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町には、百年前の寺が生存している。", "explanation": "ここは〈存在〉の意味。生存は生き物が生き続けることで、寺には使わない。"}, {"text": "この遺跡では、古い城の生存が確認された。", "explanation": "ここは〈残存〉の意味。生存は生き物について使い、建物が残っている状態には言わない。"}, {"text": "この工場では、毎日千台の車を生存している。", "explanation": "ここは〈生産〉の意味。生存は生き物が生き続けることで、車を作る意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38340, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生存", "is_correct": true, "explanation": "この魚が生き続けるために水が必要だ、という文脈に合う。"}, {"text": "値段", "is_correct": false, "explanation": "「この魚の値段には、きれいな水が必要だ」は意味をなさず、生き続ける話にならない。"}, {"text": "鱗", "is_correct": false, "explanation": "鱗に水が必要だという文は、生き続ける話にならない。"}, {"text": "体重", "is_correct": false, "explanation": "「体重には水が必要」という言い方は意味をなさない。"}], "explanations": {"生存": "この魚が生き続けるために水が必要だ、という文脈に合う。", "値段": "「この魚の値段には、きれいな水が必要だ」は意味をなさず、生き続ける話にならない。", "鱗": "鱗に水が必要だという文は、生き続ける話にならない。", "体重": "「体重には水が必要」という言い方は意味をなさない。"}, "sentence_index": 6, "correct_answer": "生存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は、静かな生存を送っている。", "explanation": "ここは〈生活〉の意味。「静かな生活を送る」と言うところで、生存は使わない。"}, {"text": "彼は生存を通して、ずっと音楽に打ち込んだ。", "explanation": "ここは〈生涯〉の意味。「生涯を通して」と言うところで、生存は使わない。"}, {"text": "この町では、新しい祭りが毎年生存している。", "explanation": "ここは〈誕生〉の意味。祭りは生まれるもので、生存とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38340, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渡り鳥の生存を、この森にかかっている。", "corrected_sentence": "渡り鳥の生存が、この森にかかっている。", "error_description": "「生存が〜にかかっている」では生存が主語になる。「を」は誤りで、「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38340, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、この虫の生存を発明した。", "corrected_sentence": "研究者は、この虫の生存を証明した。", "error_description": "「生存を証明する」が正しい。「発明する」は生存を目的語に取れず、文が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38342, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38342, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「検索機能が実装される」の「が」。実装される対象が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「実装されていない」は受け身なので、「検索機能を実装されていない」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「検索機能の実装されていない」は文の形が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すが、受け身の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「検索機能が実装される」の「が」。実装される対象が主語になる。", "を": "「実装されていない」は受け身なので、「検索機能を実装されていない」は成り立たない。", "の": "「検索機能の実装されていない」は文の形が合わない。", "と": "「と」は並列を示すが、受け身の主語にはならない。"}, "error_tags": {"を": "目的語の誤り", "の": "連体修飾の誤り", "と": "並列の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38342, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "計画や考えを、本当に使える形にすること。", "primary_collocate": null, "pronunciation": "じっそう", "ipa": "d͡ʑisːoː", "syllable_count": 4, "sentences": [{"text": "新しい機能の実装は、来月の初めまでに終わる予定です。", "target_word": "実装", "complexity_tier": "T3", "furigana": "新[あたら]しい機能[きのう]の実装[じっそう]は、来月[らいげつ]の初[はじ]めまでに終[お]わる予定[よてい]です。", "sentence_source": "generated"}, {"text": "会議で出たアイデアを、すぐに実装するのは難しい。", "target_word": "実装", "complexity_tier": "T3", "furigana": "会議[かいぎ]で出[で]たアイデアを、すぐに実装[じっそう]するのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "このアプリは、顔で開ける機能を実装している。", "target_word": "実装", "complexity_tier": "T3", "furigana": "このアプリは、顔[かお]で開[あ]ける機能[きのう]を実装[じっそう]している。", "sentence_source": "generated"}, {"text": "計画は立派だったが、実装する人が足りなかった。", "target_word": "実装", "complexity_tier": "T3", "furigana": "計画[けいかく]は立派[りっぱ]だったが、実装[じっそう]する人[ひと]が足[た]りなかった。", "sentence_source": "generated"}, {"text": "実装の前に、まず小さな試作品で確かめましょう。", "target_word": "実装", "complexity_tier": "T3", "furigana": "実装[じっそう]の前[まえ]に、まず小[ちい]さな試作品[しさくひん]で確[たし]かめましょう。", "sentence_source": "generated"}, {"text": "先月実装した機能にミスが見つかり、元に戻した。", "target_word": "実装", "complexity_tier": "T3", "furigana": "先月[せんげつ]実装[じっそう]した機能[きのう]にミスが見[み]つかり、元[もと]に戻[もど]した。", "sentence_source": "generated"}, {"text": "設計の通りに実装したのに、画面が正しく動かなかった。", "target_word": "実装", "complexity_tier": "T3", "furigana": "設計[せっけい]の通[とお]りに実装[じっそう]したのに、画面[がめん]が正[ただ]しく動[うご]かなかった。", "sentence_source": "generated"}, {"text": "このサービスには、まだ検索機能が実装されていない。", "target_word": "実装", "complexity_tier": "T3", "furigana": "このサービスには、まだ検索[けんさく]機能[きのう]が実装[じっそう]されていない。", "sentence_source": "generated"}, {"text": "実装に時間がかかるので、今回は見送ることにした。", "target_word": "実装", "complexity_tier": "T3", "furigana": "実装[じっそう]に時間[じかん]がかかるので、今回[こんかい]は見送[みおく]ることにした。", "sentence_source": "generated"}, {"text": "彼は考えを話すだけでなく、自分で実装して見せてくれた。", "target_word": "実装", "complexity_tier": "T3", "furigana": "彼[かれ]は考[かんが]えを話[はな]すだけでなく、自分[じぶん]で実装[じっそう]して見[み]せてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実装", "label": "基本形"}, {"form": "実装する", "label": "辞書形"}, {"form": "実装した", "label": "過去形"}, {"form": "実装して", "label": "て形"}, {"form": "実装される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "設計や構想を、実際に動いて使えるものに作り上げること（する名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c92b57b-6e70-433b-a166-7450a2630a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38342, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実装", "is_correct": true, "explanation": "「新しい機能の実装は、来月の初めまでに終わる」は、機能を使える形にする作業の意味で、空欄に合う。"}, {"text": "暗記", "is_correct": false, "explanation": "「新しい機能の暗記は」は意味が通らない。暗記は覚えることで、機能は対象にならない。"}, {"text": "作曲", "is_correct": false, "explanation": "「新しい機能の作曲は」は成り立たない。作曲は曲を作ることで、機能には使わない。"}, {"text": "点火", "is_correct": false, "explanation": "「新しい機能の点火は」は意味が通らない。点火は火をつけることで、機能には使わない。"}], "explanations": {"実装": "「新しい機能の実装は、来月の初めまでに終わる」は、機能を使える形にする作業の意味で、空欄に合う。", "暗記": "「新しい機能の暗記は」は意味が通らない。暗記は覚えることで、機能は対象にならない。", "作曲": "「新しい機能の作曲は」は成り立たない。作曲は曲を作ることで、機能には使わない。", "点火": "「新しい機能の点火は」は意味が通らない。点火は火をつけることで、機能には使わない。"}, "sentence_index": 0, "correct_answer": "実装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月の試験を実装する予定です。", "explanation": "ここは〈実施〉の意味。実施は行事や試験を行うことで、計画を使える形にする意味ではない。"}, {"text": "報告書を実装して、上司に提出した。", "explanation": "ここは〈作成〉の意味。作成は文書などを作ることで、計画を使える形にする意味ではない。"}, {"text": "古い家具を実装して、部屋に置いた。", "explanation": "ここは〈組み立て〉の意味。組み立ては部品をつなげて完成させることで、計画を使える形にする意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38342, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実装", "is_correct": true, "explanation": "「設計の通りに実装したのに、画面が正しく動かなかった」は、設計を使える形にした意味で、空欄に合う。"}, {"text": "採点", "is_correct": false, "explanation": "「設計の通りに採点したのに」は意味が通らない。採点は点数をつけることで、設計には使わない。"}, {"text": "演奏", "is_correct": false, "explanation": "「設計の通りに演奏したのに」は成り立たない。演奏は楽器や曲を奏でることで、設計は対象にならない。"}, {"text": "操縦", "is_correct": false, "explanation": "「設計の通りに操縦したのに」は不自然。操縦は機械や乗り物を動かすことで、設計には使わない。"}], "explanations": {"実装": "「設計の通りに実装したのに、画面が正しく動かなかった」は、設計を使える形にした意味で、空欄に合う。", "採点": "「設計の通りに採点したのに」は意味が通らない。採点は点数をつけることで、設計には使わない。", "演奏": "「設計の通りに演奏したのに」は成り立たない。演奏は楽器や曲を奏でることで、設計は対象にならない。", "操縦": "「設計の通りに操縦したのに」は不自然。操縦は機械や乗り物を動かすことで、設計には使わない。"}, "sentence_index": 6, "correct_answer": "実装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ついに長編映画を実装した。", "explanation": "ここは〈完成〉の意味。完成は作品を仕上げることで、計画を使える形にする意味ではない。"}, {"text": "新しい車を実装した。", "explanation": "ここは〈購入〉の意味。購入は品物を買うことで、計画を使える形にする意味ではない。"}, {"text": "部屋を実装した。", "explanation": "ここは〈掃除〉の意味。掃除は汚れを取り除くことで、計画を使える形にする意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38342, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい検索機能の実装を、来月の初めに終わる予定です。", "corrected_sentence": "新しい検索機能の実装は、来月の初めに終わる予定です。", "error_description": "「実装が終わる」のように主語として使うので、「実装を」ではなく「実装は」が必要。誤りは「を」で、正しくは「は」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38342, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先月は画面の設計を実装する、動作確認まで終わった。", "corrected_sentence": "先月は画面の設計を実装して、動作確認まで終わった。", "error_description": "「実装する」は終止形なので、後ろに文を続けるには「実装して」（て形）が必要。誤りは「する」で、正しくは「して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38344, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "量", "is_correct": true, "explanation": "量は物の多さを表し、ものの良さを表す質と対になる。"}, {"text": "品質", "is_correct": false, "explanation": "品質は質の類義語で、反対語ではない。"}, {"text": "価値", "is_correct": false, "explanation": "価値は質に近い意味で、反対語ではない。"}, {"text": "性質", "is_correct": false, "explanation": "性質は物の特徴で、質の反対語ではない。"}], "correct_answer": "量", "explanations": {"量": "量は物の多さを表し、ものの良さを表す質と対になる。", "品質": "品質は質の類義語で、反対語ではない。", "価値": "価値は質に近い意味で、反対語ではない。", "性質": "性質は物の特徴で、質の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38344, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "量", "is_correct": true, "explanation": "量は質の反対で、質を落とさず安く作る話と対になる。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格で、質の反対語ではない。"}, {"text": "評判", "is_correct": false, "explanation": "評判は世間の評価で、質の反対語ではない。"}, {"text": "材料", "is_correct": false, "explanation": "材料は作る元の物で、質の反対語ではない。"}], "correct_answer": "量", "explanations": {"量": "量は質の反対で、質を落とさず安く作る話と対になる。", "値段": "値段は価格で、質の反対語ではない。", "評判": "評判は世間の評価で、質の反対語ではない。", "材料": "材料は作る元の物で、質の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38344, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "もののよさ。", "primary_collocate": null, "pronunciation": "しつ", "ipa": "ɕitsɯ", "syllable_count": 2, "sentences": [{"text": "質が悪い。", "target_word": "質", "complexity_tier": "T1", "furigana": "質[しつ]が悪[わる]い。", "sentence_source": "generated"}, {"text": "この靴は質がよいです。", "target_word": "質", "complexity_tier": "T2", "furigana": "この靴[くつ]は質[しつ]がよいです。", "sentence_source": "generated"}, {"text": "質の高い肉を買いました。", "target_word": "質", "complexity_tier": "T2", "furigana": "質[しつ]の高[たか]い肉[にく]を買[か]いました。", "sentence_source": "generated"}, {"text": "質は値段で決まりますか。", "target_word": "質", "complexity_tier": "T2", "furigana": "質[しつ]は値段[ねだん]で決[き]まりますか。", "sentence_source": "generated"}, {"text": "この店は、質のいい野菜を売っている。", "target_word": "質", "complexity_tier": "T3", "furigana": "この店[みせ]は、質[しつ]のいい野菜[やさい]を売[う]っている。", "sentence_source": "generated"}, {"text": "質を比べてから、どちらを買うか決めよう。", "target_word": "質", "complexity_tier": "T3", "furigana": "質[しつ]を比[くら]べてから、どちらを買[か]うか決[き]めよう。", "sentence_source": "generated"}, {"text": "値段が高いのに、質はあまりよくない。", "target_word": "質", "complexity_tier": "T3", "furigana": "値段[ねだん]が高[たか]いのに、質[しつ]はあまりよくない。", "sentence_source": "generated"}, {"text": "質のよい道具を使えば、仕事も楽になるだろう。", "target_word": "質", "complexity_tier": "T4", "furigana": "質[しつ]のよい道具[どうぐ]を使[つか]えば、仕事[しごと]も楽[らく]になるだろう。", "sentence_source": "generated"}, {"text": "古くなっても質が変わらない服が好きだ。", "target_word": "質", "complexity_tier": "T4", "furigana": "古[ふる]くなっても質[しつ]が変[か]わらない服[ふく]が好[す]きだ。", "sentence_source": "generated"}, {"text": "質を落とさずに安く作る方法を探している。", "target_word": "質", "complexity_tier": "T4", "furigana": "質[しつ]を落[お]とさずに安[やす]く作[つく]る方法[ほうほう]を探[さが]している。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | ものの良し悪しや優れた具合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35403af3-e307-4569-9687-90b6f2030bed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38344, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "質", "is_correct": true, "explanation": "見出し語。しつ。"}, {"text": "実", "is_correct": false, "explanation": "じつ。「し」が「じ」に変わった別の語。"}, {"text": "蜜", "is_correct": false, "explanation": "みつ。「し」が「み」に変わった別の語。"}, {"text": "塩", "is_correct": false, "explanation": "しお。「つ」が「お」に変わった別の語。"}, {"text": "城", "is_correct": false, "explanation": "しろ。「つ」が「ろ」に変わった別の語。"}], "explanations": {"質": "見出し語。しつ。", "実": "じつ。「し」が「じ」に変わった別の語。", "蜜": "みつ。「し」が「み」に変わった別の語。", "塩": "しお。「つ」が「お」に変わった別の語。", "城": "しろ。「つ」が「ろ」に変わった別の語。"}, "sentence_index": null, "correct_answer": "質"}, "level_3": {"options": [{"text": "質", "is_correct": true, "explanation": "「質が悪い」で、ものの良さが低いという意味になる。"}, {"text": "三月", "is_correct": false, "explanation": "形は合うが、「三月が悪い」は意味が合わない。"}, {"text": "切手", "is_correct": false, "explanation": "形は合うが、「切手が悪い」は意味が合わない。"}, {"text": "百円", "is_correct": false, "explanation": "形は合うが、「百円が悪い」は意味が合わない。"}], "explanations": {"質": "「質が悪い」で、ものの良さが低いという意味になる。", "三月": "形は合うが、「三月が悪い」は意味が合わない。", "切手": "形は合うが、「切手が悪い」は意味が合わない。", "百円": "形は合うが、「百円が悪い」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "質を開けると、中から冷たい風が出てきた。", "explanation": "「質」は良さのことで、開ける扉や箱ではない。"}, {"text": "兄は質を弾いて、みんなを楽しませた。", "explanation": "「質」は楽器ではないので、「弾く」の対象にならない。"}, {"text": "この道は質が広くて、車が通りやすい。", "explanation": "「質」は良さの程度で、道の広さを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38344, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "質", "is_correct": true, "explanation": "見出し語。しつ。"}, {"text": "式", "is_correct": false, "explanation": "しき。「つ」が「き」に変わった別の語。"}, {"text": "島", "is_correct": false, "explanation": "しま。「つ」が「ま」に変わった別の語。"}, {"text": "霜", "is_correct": false, "explanation": "しも。「つ」が「も」に変わった別の語。"}, {"text": "歯科", "is_correct": false, "explanation": "しか。「つ」が「か」に変わった別の語。"}], "explanations": {"質": "見出し語。しつ。", "式": "しき。「つ」が「き」に変わった別の語。", "島": "しま。「つ」が「ま」に変わった別の語。", "霜": "しも。「つ」が「も」に変わった別の語。", "歯科": "しか。「つ」が「か」に変わった別の語。"}, "sentence_index": null, "correct_answer": "質"}, "level_3": {"options": [{"text": "質", "is_correct": true, "explanation": "「値段が高いのに、質はあまりよくない」で、良さの程度を指す。"}, {"text": "誕生日", "is_correct": false, "explanation": "形は合うが、「誕生日はあまりよくない」は意味が合わない。"}, {"text": "電話番号", "is_correct": false, "explanation": "形は合うが、「電話番号はあまりよくない」は意味が合わない。"}, {"text": "左手", "is_correct": false, "explanation": "形は合うが、「左手はあまりよくない」は値段の話と合わない。"}], "explanations": {"質": "「値段が高いのに、質はあまりよくない」で、良さの程度を指す。", "誕生日": "形は合うが、「誕生日はあまりよくない」は意味が合わない。", "電話番号": "形は合うが、「電話番号はあまりよくない」は意味が合わない。", "左手": "形は合うが、「左手はあまりよくない」は値段の話と合わない。"}, "sentence_index": 6, "correct_answer": "質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は毎朝、質を飲んでから学校へ行く。", "explanation": "「質」は良さの程度で、飲める物ではない。"}, {"text": "質の長さを測ったら、二メートルあった。", "explanation": "「質」は良さの程度で、長さを測れる物ではない。"}, {"text": "弟は質をかぶって、野球の試合に出た。", "explanation": "「質」は帽子のようにかぶる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
