INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38345, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "量", "is_correct": true, "explanation": "量は質の反対で、水の良さに対する多さを表す。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格で、質の反対語ではない。"}, {"text": "評判", "is_correct": false, "explanation": "評判は世間の評価で、質の反対語ではない。"}, {"text": "材料", "is_correct": false, "explanation": "材料は作る元の物で、質の反対語ではない。"}], "correct_answer": "量", "explanations": {"量": "量は質の反対で、水の良さに対する多さを表す。", "値段": "値段は価格で、質の反対語ではない。", "評判": "評判は世間の評価で、質の反対語ではない。", "材料": "材料は作る元の物で、質の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38345, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物事の価値や良さの程度。品質。", "primary_collocate": null, "pronunciation": "しつ", "ipa": "ɕitsɯ", "syllable_count": 2, "sentences": [{"text": "一方で、農村経済全体を見ると、労働需要の質が変化するという社会経済的影響も無視できません。", "target_word": "質", "complexity_tier": "T6", "furigana": "一方[いっぽう]で、農村[のうそん]経済[けいざい]全体[ぜんたい]を見[み]ると、労働[ろうどう]需要[じゅよう]の質[しつ]が変化[へんか]するという社会[しゃかい]経済的[けいざいてき]影響[えいきょう]も無視[むし]できません。", "sentence_source": "mined"}, {"text": "質がいい。", "target_word": "質", "complexity_tier": "T1", "furigana": "質[しつ]がいい。", "sentence_source": "generated"}, {"text": "この布は質が高いです。", "target_word": "質", "complexity_tier": "T2", "furigana": "この布[ぬの]は質[しつ]が高[たか]いです。", "sentence_source": "generated"}, {"text": "質の悪い品物は買いません。", "target_word": "質", "complexity_tier": "T2", "furigana": "質[しつ]の悪[わる]い品物[しなもの]は買[か]いません。", "sentence_source": "generated"}, {"text": "安くても質のよい物を選びたい。", "target_word": "質", "complexity_tier": "T3", "furigana": "安[やす]くても質[しつ]のよい物[もの]を選[えら]びたい。", "sentence_source": "generated"}, {"text": "睡眠の質を上げるために、早く寝ている。", "target_word": "質", "complexity_tier": "T3", "furigana": "睡眠[すいみん]の質[しつ]を上[あ]げるために、早[はや]く寝[ね]ている。", "sentence_source": "generated"}, {"text": "サービスの質は、店によって違う。", "target_word": "質", "complexity_tier": "T3", "furigana": "サービスの質[しつ]は、店[みせ]によって違[ちが]う。", "sentence_source": "generated"}, {"text": "授業の質を保つには、先生の努力が必要だ。", "target_word": "質", "complexity_tier": "T4", "furigana": "授業[じゅぎょう]の質[しつ]を保[たも]つには、先生[せんせい]の努力[どりょく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "量を増やしすぎて、製品の質が落ちてしまった。", "target_word": "質", "complexity_tier": "T4", "furigana": "量[りょう]を増[ふ]やしすぎて、製品[せいひん]の質[しつ]が落[お]ちてしまった。", "sentence_source": "generated"}, {"text": "水の質が悪化すれば、魚が住めなくなる恐れがある。", "target_word": "質", "complexity_tier": "T5", "furigana": "水[みず]の質[しつ]が悪化[あっか]すれば、魚[さかな]が住[す]めなくなる恐[おそ]れがある。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 物事の価値や良さの程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35403af3-e307-4569-9687-90b6f2030bed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38345, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "質", "is_correct": true, "explanation": "見出し語。しつ。"}, {"text": "実", "is_correct": false, "explanation": "じつ。「し」が「じ」に変わった別の語。"}, {"text": "筆", "is_correct": false, "explanation": "ひつ。「し」が「ひ」に変わった別の語。"}, {"text": "蜜", "is_correct": false, "explanation": "みつ。「し」が「み」に変わった別の語。"}, {"text": "塩", "is_correct": false, "explanation": "しお。「つ」が「お」に変わった別の語。"}], "explanations": {"質": "見出し語。しつ。", "実": "じつ。「し」が「じ」に変わった別の語。", "筆": "ひつ。「し」が「ひ」に変わった別の語。", "蜜": "みつ。「し」が「み」に変わった別の語。", "塩": "しお。「つ」が「お」に変わった別の語。"}, "sentence_index": null, "correct_answer": "質"}, "level_3": {"options": [{"text": "質", "is_correct": true, "explanation": "「労働需要の質」で、需要の良さの程度が変わるという意味に合う。"}, {"text": "色", "is_correct": false, "explanation": "形は合うが、「労働需要の色が変化する」は意味が合わない。"}, {"text": "匂い", "is_correct": false, "explanation": "形は合うが、「労働需要の匂いが変化する」は意味が合わない。"}, {"text": "屋根", "is_correct": false, "explanation": "形は合うが、「労働需要の屋根が変化する」は意味が合わない。"}], "explanations": {"質": "「労働需要の質」で、需要の良さの程度が変わるという意味に合う。", "色": "形は合うが、「労働需要の色が変化する」は意味が合わない。", "匂い": "形は合うが、「労働需要の匂いが変化する」は意味が合わない。", "屋根": "形は合うが、「労働需要の屋根が変化する」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、駅で質に乗って学校へ行きます。", "explanation": "「質」は物の良さの程度で、乗り物ではないので「乗る」の対象にならない。"}, {"text": "質が重い荷物を、両手で運びました。", "explanation": "「質」は良さの程度で、重さを表す語ではない。"}, {"text": "この布は質が青くて、赤い服に合います。", "explanation": "「質」は良さの程度で、色を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38345, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "質", "is_correct": true, "explanation": "見出し語。しつ。"}, {"text": "式", "is_correct": false, "explanation": "しき。「つ」が「き」に変わった別の語。"}, {"text": "品", "is_correct": false, "explanation": "しな。「つ」が「な」に変わった別の語。"}, {"text": "島", "is_correct": false, "explanation": "しま。「つ」が「ま」に変わった別の語。"}, {"text": "霜", "is_correct": false, "explanation": "しも。「つ」が「も」に変わった別の語。"}], "explanations": {"質": "見出し語。しつ。", "式": "しき。「つ」が「き」に変わった別の語。", "品": "しな。「つ」が「な」に変わった別の語。", "島": "しま。「つ」が「ま」に変わった別の語。", "霜": "しも。「つ」が「も」に変わった別の語。"}, "sentence_index": null, "correct_answer": "質"}, "level_3": {"options": [{"text": "質", "is_correct": true, "explanation": "「サービスの質は店によって違う」で、良さの程度の違いを表す。"}, {"text": "年齢", "is_correct": false, "explanation": "形は合うが、「サービスの年齢は店によって違う」は意味が合わない。"}, {"text": "屋根", "is_correct": false, "explanation": "形は合うが、「サービスの屋根は店によって違う」は意味が合わない。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、「サービスの靴は店によって違う」は意味が合わない。"}], "explanations": {"質": "「サービスの質は店によって違う」で、良さの程度の違いを表す。", "年齢": "形は合うが、「サービスの年齢は店によって違う」は意味が合わない。", "屋根": "形は合うが、「サービスの屋根は店によって違う」は意味が合わない。", "靴": "形は合うが、「サービスの靴は店によって違う」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水の質を飲みすぎて、お腹が痛くなった。", "explanation": "「質」は良さの程度で、飲める物ではない。"}, {"text": "私は質を二つ買って、友達にあげた。", "explanation": "「質」は良さの程度を表す語で、買って数えられる物ではない。"}, {"text": "質が大きい山に、毎年たくさんの人が登る。", "explanation": "「質」は良さの程度で、山の大きさを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38345, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この紙は質が多いです。", "corrected_sentence": "この紙は質が高いです。", "error_description": "「質」の程度は「多い」ではなく「高い」「よい」で表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38345, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "料理の質を落ちると、客が減ってしまう。", "corrected_sentence": "料理の質が落ちると、客が減ってしまう。", "error_description": "「落ちる」は自動詞なので「質を」は誤りで、「質が落ちる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38346, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「分岐に立っている」は立つ場所を示す正しい形。"}, {"text": "が", "is_correct": false, "explanation": "「分岐が、地蔵が立つ」は分岐自体が主語になり、場所を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「分岐を」は対象を示すが、地蔵が立つ場所を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示すが、ここは立っている場所なので「に」の位置には入らない。"}], "correct_answer": "に", "explanations": {"に": "「分岐に立っている」は立つ場所を示す正しい形。", "が": "「分岐が、地蔵が立つ」は分岐自体が主語になり、場所を示せない。", "を": "「分岐を」は対象を示すが、地蔵が立つ場所を表せない。", "へ": "「へ」は移動の方向を示すが、ここは立っている場所なので「に」の位置には入らない。"}, "error_tags": {"に": "場所", "が": "主語", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38346, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「人生の分岐で迷う」は迷う場面・状況を示す正しい形。"}, {"text": "が", "is_correct": false, "explanation": "「分岐が迷った」は分岐が迷う主体になり、文脈に合わない。"}, {"text": "を", "is_correct": false, "explanation": "「迷う」は目的語を取らないため、「分岐を迷った」は誤り。"}, {"text": "の", "is_correct": false, "explanation": "「分岐の迷ったとき」と続かず、文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「人生の分岐で迷う」は迷う場面・状況を示す正しい形。", "が": "「分岐が迷った」は分岐が迷う主体になり、文脈に合わない。", "を": "「迷う」は目的語を取らないため、「分岐を迷った」は誤り。", "の": "「分岐の迷ったとき」と続かず、文が成り立たない。"}, "error_tags": {"で": "場面・状況", "が": "主語", "を": "対象", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38346, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "道が二つに分かれるところ。大事な選択をしなければならない時。", "primary_collocate": null, "pronunciation": "ぶんき", "ipa": "bɯŋki", "syllable_count": 3, "sentences": [{"text": "山道の分岐で地図を広げ、右の道へ進むことにした。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "山道(やまみち)の分岐(ぶんき)で地図(ちず)を広(ひろ)げ、右(みぎ)の道(みち)へ進(すす)むことにした。", "sentence_source": "generated"}, {"text": "川沿いの道の分岐に、小さな地蔵が立っている。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "川沿(かわぞ)いの道(みち)の分岐(ぶんき)に、小(ちい)さな地蔵(じぞう)が立(た)っている。", "sentence_source": "generated"}, {"text": "標識がない分岐で迷い、予定より一時間遅れた。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "標識(ひょうしき)がない分岐(ぶんき)で迷(まよ)い、予定(よてい)より一時間(いちじかん)遅(おく)れた。", "sentence_source": "generated"}, {"text": "次の分岐を左に曲がると、駅が見えてくる。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "次(つぎ)の分岐(ぶんき)を左(ひだり)に曲(ま)がると、駅(えき)が見(み)えてくる。", "sentence_source": "generated"}, {"text": "登山道の分岐には、行き先を示す古い看板が立っていた。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "登山道(とざんどう)の分岐(ぶんき)には、行(い)き先(さき)を示(しめ)す古(ふる)い看板(かんばん)が立(た)っていた。", "sentence_source": "generated"}, {"text": "高速道路の分岐では、案内表示をよく見ておくことが大切だ。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "高速(こうそく)道路(どうろ)の分岐(ぶんき)では、案内(あんない)表示(ひょうじ)をよく見(み)ておくことが大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "霧が深かったので、分岐を見落としてしまった。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "霧(きり)が深(ふか)かったので、分岐(ぶんき)を見落(みお)としてしまった。", "sentence_source": "generated"}, {"text": "人生の分岐で迷ったとき、祖父の言葉を思い出す。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "人生(じんせい)の分岐(ぶんき)で迷(まよ)ったとき、祖父(そふ)の言葉(ことば)を思(おも)い出(だ)す。", "sentence_source": "generated"}, {"text": "道の分岐に、古い大きな木が一本立っていた。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "道(みち)の分岐(ぶんき)に、古(ふる)い大(おお)きな木(き)が一本(いっぽん)立(た)っていた。", "sentence_source": "generated"}, {"text": "道の分岐に着いたが、どちらも同じような細い道だった。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "道(みち)の分岐(ぶんき)に着(つ)いたが、どちらも同(おな)じような細(ほそ)い道(みち)だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分岐する", "label": "dictionary form (suru verb)"}, {"form": "分岐した", "label": "past"}, {"form": "分岐して", "label": "te-form"}], "register": "neutral written", "sense_fingerprint": "道が分かれる場所、また大事な選択の時", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '448d110d-502d-4765-a516-917bc7c1e24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38346, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分岐", "is_correct": true, "explanation": "「山道の分岐で」は道が分かれる場所を示し、地図を広げる場面に合う。"}, {"text": "湧き水", "is_correct": false, "explanation": "「山道の湧き水で地図を広げ」は意味が通らず、場所も示せない。"}, {"text": "呼び鈴", "is_correct": false, "explanation": "玄関などにある装置で、山道の場面に合わない。"}, {"text": "歌声", "is_correct": false, "explanation": "人の歌声は場所を示さず、地図を広げる文脈に合わない。"}], "explanations": {"分岐": "「山道の分岐で」は道が分かれる場所を示し、地図を広げる場面に合う。", "湧き水": "「山道の湧き水で地図を広げ」は意味が通らず、場所も示せない。", "呼び鈴": "玄関などにある装置で、山道の場面に合わない。", "歌声": "人の歌声は場所を示さず、地図を広げる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "分岐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの道は駅前で分岐して、一本になっている。", "explanation": "ここは〈合流〉の意味（分かれていたものが一つになること）。分岐は一つが二つに分かれることなので、一本に戻る場面には使わない。"}, {"text": "大きな板を三つに分岐して運んだ。", "explanation": "ここは〈分割〉の意味（切って分けること）。分岐は進路が分かれる意味で、物を切り分ける作業には使わない。"}, {"text": "胃は消化を助ける液を分岐する。", "explanation": "ここは〈分泌〉の意味（体内の液を外に出すこと）。分岐は道や進路が分かれる意味で、体の液を出す働きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38346, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分岐", "is_correct": true, "explanation": "「霧が深かったので、分岐を見落とした」は道の分かれ目を指し、文脈に合う。"}, {"text": "呼吸", "is_correct": false, "explanation": "息をする行為で、見落とす対象にはならない。"}, {"text": "作曲", "is_correct": false, "explanation": "曲を作る行為で、見落とす対象として文脈に合わない。"}, {"text": "漂白", "is_correct": false, "explanation": "色を抜く作業で、見落とす対象として文脈に合わない。"}], "explanations": {"分岐": "「霧が深かったので、分岐を見落とした」は道の分かれ目を指し、文脈に合う。", "呼吸": "息をする行為で、見落とす対象にはならない。", "作曲": "曲を作る行為で、見落とす対象として文脈に合わない。", "漂白": "色を抜く作業で、見落とす対象として文脈に合わない。"}, "sentence_index": 6, "correct_answer": "分岐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古いラジオを分岐して、部品を掃除した。", "explanation": "ここは〈分解〉の意味（組み立てたものをばらすこと）。分岐は進路が分かれる意味で、機械をばらす作業には使わない。"}, {"text": "利益を社員に分岐した。", "explanation": "ここは〈分配〉の意味（分けて配ること）。分岐は進路が分かれる意味で、利益を配る場面には使わない。"}, {"text": "細胞が分岐して、二つの細胞になった。", "explanation": "ここは〈分裂〉の意味（一つのものが割れて二つになること）。分岐は方向が分かれる意味で、細胞の増え方には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38346, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "霧の中で、分岐を迷い、道を失った。", "corrected_sentence": "霧の中で、分岐で迷い、道を失った。", "error_description": "「迷う」は場所を「で」で示す。「分岐を迷い」は「を」が誤り。正しくは「分岐で迷い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38346, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山道は、途中で分岐された。", "corrected_sentence": "山道は、途中で分岐した。", "error_description": "「分岐する」は自動詞なので受け身にできない。「分岐された」は誤り。正しくは「分岐した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38347, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「分岐に立つ」は立つ場所を示す正しい形。"}, {"text": "が", "is_correct": false, "explanation": "「分岐が立った」は分岐自体が主語になり、人が立つ文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「立つ」は目的語をとらないため、「分岐を立つ」は誤り。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐだけなので、「人生の分岐の立ったとき」と続かず文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「分岐に立つ」は立つ場所を示す正しい形。", "が": "「分岐が立った」は分岐自体が主語になり、人が立つ文として成り立たない。", "を": "「立つ」は目的語をとらないため、「分岐を立つ」は誤り。", "の": "「の」は名詞をつなぐだけなので、「人生の分岐の立ったとき」と続かず文が成り立たない。"}, "error_tags": {"に": "場所・場面", "が": "主語", "を": "対象", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38347, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「分岐では」は場面を示し、「治療方針が決まる分岐では」と続く文脈に合う。"}, {"text": "も", "is_correct": false, "explanation": "「分岐もは」は「も」と「は」が重なり、取り立ての形として成り立たない。"}, {"text": "や", "is_correct": false, "explanation": "「分岐やは」は並列を示す「や」に後続がなく、文が成り立たない。"}, {"text": "ね", "is_correct": false, "explanation": "「分岐ねは」は終助詞が文中に入るため、文法的に成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「分岐では」は場面を示し、「治療方針が決まる分岐では」と続く文脈に合う。", "も": "「分岐もは」は「も」と「は」が重なり、取り立ての形として成り立たない。", "や": "「分岐やは」は並列を示す「や」に後続がなく、文が成り立たない。", "ね": "「分岐ねは」は終助詞が文中に入るため、文法的に成り立たない。"}, "error_tags": {"で": "場面・状況", "も": "取り立て", "や": "並列", "ね": "終助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38347, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が二つ以上の方向に分かれて、どちらに進むかが決まる重要な場面や点。", "primary_collocate": null, "pronunciation": "ぶんき", "ipa": "bɯŋki", "syllable_count": 3, "sentences": [{"text": "次いで、分岐や終点といった進路の重要な局面を見極める。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "次(つ)いで、分岐(ぶんき)や終点(しゅうてん)といった進路(しんろ)の重要(じゅうよう)な局面(きょくめん)を見極(みきわ)める。", "sentence_source": "generated"}, {"text": "人生の分岐に立ったとき、彼は安定より挑戦を選んだ。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "人生(じんせい)の分岐(ぶんき)に立(た)ったとき、彼(かれ)は安定(あんてい)より挑戦(ちょうせん)を選(えら)んだ。", "sentence_source": "generated"}, {"text": "この物語は、主人公の選択が分岐となって結末が二つに分かれる。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "この物語(ものがたり)は、主人公(しゅじんこう)の選択(せんたく)が分岐(ぶんき)となって結末(けつまつ)が二(ふた)つに分(わ)かれる。", "sentence_source": "generated"}, {"text": "交渉は最大の分岐を迎え、双方が譲歩するか決裂するかが決まる。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "交渉(こうしょう)は最大(さいだい)の分岐(ぶんき)を迎(むか)え、双方(そうほう)が譲歩(じょうほ)するか決裂(けつれつ)するかが決(き)まる。", "sentence_source": "generated"}, {"text": "大学進学か就職かという分岐で、彼女は何日も悩んだ。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "大学(だいがく)進学(しんがく)か就職(しゅうしょく)かという分岐(ぶんき)で、彼女(かのじょ)は何日(なんにち)も悩(なや)んだ。", "sentence_source": "generated"}, {"text": "歴史の分岐には、小さな判断が大きな結果につながる場面が多い。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "歴史(れきし)の分岐(ぶんき)には、小(ちい)さな判断(はんだん)が大(おお)きな結果(けっか)につながる場面(ばめん)が多(おお)い。", "sentence_source": "generated"}, {"text": "プロジェクトの分岐で判断を誤ると、後から修正するのは難しい。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "プロジェクトの分岐(ぶんき)で判断(はんだん)を誤(あやま)ると、後(あと)から修正(しゅうせい)するのは難(むずか)しい。", "sentence_source": "generated"}, {"text": "治療方針が決まる分岐では、医師と患者がよく話し合う。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "治療(ちりょう)方針(ほうしん)が決(き)まる分岐(ぶんき)では、医師(いし)と患者(かんじゃ)がよく話(はな)し合(あ)う。", "sentence_source": "generated"}, {"text": "ゲームでは、会話の分岐ごとに別の展開が用意されている。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "ゲームでは、会話(かいわ)の分岐(ぶんき)ごとに別(べつ)の展開(てんかい)が用意(ようい)されている。", "sentence_source": "generated"}, {"text": "転職は、彼のキャリアにとって大きな分岐だった。", "target_word": "分岐", "complexity_tier": "T3", "furigana": "転職(てんしょく)は、彼(かれ)のキャリアにとって大(おお)きな分岐(ぶんき)だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分岐する", "label": "dictionary form (suru verb)"}, {"form": "分岐した", "label": "past"}, {"form": "分岐して", "label": "te-form"}], "register": "neutral written", "sense_fingerprint": "物事の進む方向が決まる重要な分かれ目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '448d110d-502d-4765-a516-917bc7c1e24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38347, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分岐", "is_correct": true, "explanation": "進路を決める重要な局面を指し、「終点」と並べて挙げる文脈に合う。"}, {"text": "濃淡", "is_correct": false, "explanation": "明暗の度合いを表す語で、特徴点の種類として「終点」と並ばない。"}, {"text": "解像度", "is_correct": false, "explanation": "画像の細かさを表す語で、特徴点の名称にはならない。"}, {"text": "画素", "is_correct": false, "explanation": "画像を構成する一点を表す語で、特徴点の種類として並べられない。"}], "explanations": {"分岐": "進路を決める重要な局面を指し、「終点」と並べて挙げる文脈に合う。", "濃淡": "明暗の度合いを表す語で、特徴点の種類として「終点」と並ばない。", "解像度": "画像の細かさを表す語で、特徴点の名称にはならない。", "画素": "画像を構成する一点を表す語で、特徴点の種類として並べられない。"}, "sentence_index": 0, "correct_answer": "分岐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この仕事は三人で分岐し、それぞれ担当している。", "explanation": "ここは〈分業〉の意味（仕事を役割ごとに分けること）。分岐は進む方向が分かれる意味なので、仕事の分担には使わない。"}, {"text": "人口が都市部に集中せず、各地に分岐している。", "explanation": "ここは〈分散〉の意味（広く散らばること）。分岐は一つが二方向に分かれることで、人が各地に散らばる状態には使わない。"}, {"text": "油と水を分岐させて、上の層だけを取り出した。", "explanation": "ここは〈分離〉の意味（混ざったものを別々にすること）。分岐は進路が分かれる意味で、物質を分けて取り出す操作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38347, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分岐", "is_correct": true, "explanation": "「プロジェクトの分岐で」は判断の場面を示し、文脈に合う。"}, {"text": "換気", "is_correct": false, "explanation": "空気を入れ替える作業で、「プロジェクトの換気で判断を誤る」は意味が通らない。"}, {"text": "鑑賞", "is_correct": false, "explanation": "作品を味わう行為で、判断を誤る場面には合わない。"}, {"text": "発声", "is_correct": false, "explanation": "声を出す行為で、判断の場面とは結びつかない。"}], "explanations": {"分岐": "「プロジェクトの分岐で」は判断の場面を示し、文脈に合う。", "換気": "空気を入れ替える作業で、「プロジェクトの換気で判断を誤る」は意味が通らない。", "鑑賞": "作品を味わう行為で、判断を誤る場面には合わない。", "発声": "声を出す行為で、判断の場面とは結びつかない。"}, "sentence_index": 6, "correct_answer": "分岐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雑用は四人で分岐して、交代で担当した。", "explanation": "ここは〈分担〉の意味（役割を分けて受け持つこと）。分岐は進む方向が分かれる意味で、作業の役割分けには使わない。"}, {"text": "古いラジオを分岐して、部品を掃除した。", "explanation": "ここは〈分解〉の意味（組み立てたものをばらすこと）。分岐は進路が分かれる意味で、機械をばらす作業には使わない。"}, {"text": "資料を内容ごとに分岐して、棚に並べた。", "explanation": "ここは〈分類〉の意味（種類ごとに分けること）。分岐は方向が分かれる意味で、種類で整理する場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
